/// The walking-skeleton + auth in-flight net kinds: a dispatched query's
/// token maps back to one of these on the answer drain (the C++ delivers
/// through the query's promise; the skeleton parks the pair instead).
pub(crate) enum PendingNetKind {
    Auth(AuthPendingKind),
    GetMe,
    /// The editMessageText request (the EditMessageQuery answer tail):
    /// the dialog + message identify the object the tail rebuilds.
    EditMessage {
        dialog_id: crate::dialog_id::DialogId,
        message_id: crate::message_id::MessageId,
    },
    /// The PhoneNumberManager plane (the glue slice): the change-phone /
    /// verify-phone / confirm-ownership queries.
    Phone(PhonePendingKind),
}

/// The UpdatesManager in-flight query kinds (the C++
/// `GetDifferenceQuery`/`GetUpdatesStateQuery`/`ConfirmPtsQtsQuery`/
/// `GetPtsUpdateQuery`/`PingServerQuery` — UpdatesManager.cpp:126-271).
/// The completions park by kind (the engine env senders are promise-less;
/// the C++ promise lambdas route Ok/Err into `on_get_difference`/
/// `on_failed_get_difference`/`on_get_updates_state`/
/// `on_failed_get_updates_state`/`on_server_pong`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum UpdatesNetKind {
    GetDifference,
    GetUpdatesState,
    ConfirmPtsQts,
    /// the pts-short-gap repair (`GetPtsUpdateQuery`) — the C++ promise
    /// lambda captures `pts` (the repair target, `get_pts() + 1`) and
    /// rides it back into `on_get_pts_update` (cpp:360-365); the wire
    /// query itself sends `pts - 1` (cpp:367).
    GetPtsUpdate {
        pts: i32,
    },
    /// `PingServerQuery` — the C++ class sends `updates.getState` and
    /// feeds `on_server_pong` (UpdatesManager.cpp:152-166, 1927-1937).
    Ping,
}

/// The kind tag riding a per-family dispatcher callback — the completed
/// answers park under their kind and the `Td` drain routes them.
pub(crate) trait NetAnswerKind: Copy + Send + 'static {}

impl<T: Copy + Send + 'static> NetAnswerKind for T {}

/// The cloned per-kind dispatch surface the env senders use (the env is
// a view over `&mut Td`, so the trio rides as owned Arcs). The C++ shape
/// is `td_->create_handler<…>()->send(...)`: the query serializes onto
/// the main-DC auth dispatch and the answer comes back through the
/// callback into the per-kind completed queue.
#[derive(Clone)]
pub(crate) struct NetKindHandle<K: NetAnswerKind> {
    dispatcher: Arc<NetQueryDispatcher>,
    completed: Arc<Mutex<Vec<(K, NetQuery)>>>,
    /// The actor wake — `None` in the net-inert tests.
    shared: Option<Arc<NetShared>>,
}

impl<K: NetAnswerKind> NetKindHandle<K> {
    /// Serialize + dispatch one query (the session prepends the shared
    /// `MtprotoHeader`; the NetQueryCreator defaults ride like the
    /// walking-skeleton dispatch — DcId::main, the 24-hour budget).
    pub(crate) fn dispatch(&self, kind: K, function: telegram_api::Function) {
        self.dispatch_dc(kind, function, DcId::main());
    }

    /// The per-DC form — `create(function, {}, dc_id)`.
    pub(crate) fn dispatch_dc(&self, kind: K, function: telegram_api::Function, dc_id: DcId) {
        self.dispatch_query(kind, function, dc_id, AuthFlag::On);
    }

    /// The `create_with_prefix` form (NetQueryCreator.cpp:36-39) — the
    /// serialized prefix function rides the payload head (the
    /// business-connection invoke wrapper) and the inner function's
    /// constructor id carries the query; the C++ `{{"me"}}` chains of
    /// the business senders collapse onto the plain per-DC dispatch.
    pub(crate) fn dispatch_with_prefix(
        &self,
        kind: K,
        prefix: telegram_api::Function,
        function: telegram_api::Function,
        dc_id: DcId,
    ) {
        let mut bytes = Vec::new();
        prefix.store(&mut bytes);
        let mut inner = Vec::new();
        function.store(&mut inner);
        bytes.extend_from_slice(&inner);
        let tl_constructor = i32::from_le_bytes(inner[0..4].try_into().unwrap());
        let net_query = NetQuery::new(
            0,
            dc_id,
            NetQueryType::Common,
            AuthFlag::On,
            GzipFlag::Off,
            tl_constructor,
            bytes,
            u32::MAX,
            60 * 60 * 24,
        );
        self.dispatcher.dispatch_with_callback(
            net_query,
            Box::new(NetKindDispatchCallback {
                kind,
                completed: Arc::clone(&self.completed),
                shared: self.shared.clone(),
            }),
        );
    }

    /// The unauth form — the C++ `create_unauth` (the pre-auth window
    /// queries: the country/help families).
    pub(crate) fn dispatch_unauth(&self, kind: K, function: telegram_api::Function) {
        self.dispatch_query(kind, function, DcId::main(), AuthFlag::Off);
    }

    /// The shared serialize + dispatch leg.
    fn dispatch_query(
        &self,
        kind: K,
        function: telegram_api::Function,
        dc_id: DcId,
        auth_flag: AuthFlag,
    ) {
        let mut bytes = Vec::new();
        function.store(&mut bytes);
        let tl_constructor = i32::from_le_bytes(bytes[0..4].try_into().unwrap());
        let net_query = NetQuery::new(
            0,
            dc_id,
            NetQueryType::Common,
            auth_flag,
            GzipFlag::Off,
            tl_constructor,
            bytes,
            u32::MAX,
            60 * 60 * 24,
        );
        self.dispatcher.dispatch_with_callback(
            net_query,
            Box::new(NetKindDispatchCallback {
                kind,
                completed: Arc::clone(&self.completed),
                shared: self.shared.clone(),
            }),
        );
    }

    /// Complete a kind without a wire round-trip — the send-leg failure
    /// band: the C++ `ResultHandler::send` resolves the input peer and
    /// calls `on_error(Status)` inline when it can't (the "Can't access
    /// the chat" 400); this files the same error through the completed
    /// queue so the answer half runs the full `on_error` tail (the
    /// dialog-error head + the promise error).
    pub(crate) fn complete_error(&self, kind: K, code: i32, message: &str) {
        let net_query = NetQuery::new(
            0,
            DcId::main(),
            NetQueryType::Common,
            AuthFlag::On,
            GzipFlag::Off,
            0,
            Vec::new(),
            u32::MAX,
            0,
        );
        let mut net_query = net_query;
        net_query.set_error(tdutils::status::Status::error(code, message));
        self.completed.lock().push((kind, net_query));
        if let Some(shared) = &self.shared {
            shared.wake_td();
        }
    }
}

/// The dispatcher callback for the per-kind queries: files the completed
/// `NetQuery` under its kind and nudges the `Td` actor; the nudge drains
/// the answers through the per-family `dispatch_completed_*` method.
struct NetKindDispatchCallback<K: NetAnswerKind> {
    kind: K,
    completed: Arc<Mutex<Vec<(K, NetQuery)>>>,
    /// The actor wake — `None` in the net-inert tests.
    shared: Option<Arc<NetShared>>,
}

impl<K: NetAnswerKind> NetQueryCallback for NetKindDispatchCallback<K> {
    fn on_result(&mut self, query: NetQuery) {
        self.completed.lock().push((self.kind, query));
        if let Some(shared) = &self.shared {
            shared.wake_td();
        }
    }
}

