/// The parked auto-download promises (the C++ handlers' own promises).
enum PendingAutoDownloadQuery {
    /// The `GetAutoDownloadSettingsQuery` promise (cpp:35).
    GetPresets {
        promise: Promise<td_api::AutoDownloadSettingsPresets>,
    },
    /// The `SaveAutoDownloadSettingsQuery` promise (cpp:71).
    Save { promise: Promise<()> },
}

impl PendingAutoDownloadQuery {
    fn is_get_presets(&self) -> bool {
        matches!(self, Self::GetPresets { .. })
    }
    fn is_save(&self) -> bool {
        matches!(self, Self::Save { .. })
    }
}

/// The parked privacy promises (the C++ handlers' own promises) — the
/// set/global pairs; the get promises queue in the manager's
/// `PrivacyInfo` instead (the C++ shape).
enum PendingPrivacyQuery {
    /// The `SetPrivacyQuery` promise (PrivacyManager.cpp:55).
    SetPrivacy { promise: Promise<()> },
    /// The `GetGlobalPrivacySettingsQuery` promise
    /// (GlobalPrivacySettings.cpp:27).
    GetGlobal {
        promise: Promise<crate::privacy_manager::GlobalPrivacySettings>,
    },
    /// The set chain's get-leg capture (GlobalPrivacySettings.cpp:186-197)
    /// — the set slice rides the pending entry the way the C++ lambda
    /// captures it; the get answer applies the changes and dispatches
    /// the `SetGlobalPrivacySettingsQuery` tail.
    SetGlobalChain {
        set_settings: crate::privacy_manager::GlobalPrivacySettings,
        promise: Promise<()>,
    },
    /// The `SetGlobalPrivacySettingsQuery` promise
    /// (GlobalPrivacySettings.cpp:49).
    SetGlobal { promise: Promise<()> },
}

impl PendingPrivacyQuery {
    fn is_set_privacy(&self) -> bool {
        matches!(self, Self::SetPrivacy { .. })
    }
    fn is_get_global_leg(&self) -> bool {
        matches!(self, Self::GetGlobal { .. } | Self::SetGlobalChain { .. })
    }
    fn is_set_global(&self) -> bool {
        matches!(self, Self::SetGlobal { .. })
    }
}

