/// The `G()`/`td_` surface for the [`crate::story_manager::StoryManager`]
/// (the M.47 conventions): field-split borrows off `Td`, the notification
/// outbox for `send_update`, and the M.12 file manager behind its shared
/// lock. The StoryDb seam answers `None` — the story tables are implemented
/// standalone in [`crate::story_db`] over the tddb `SqliteDb` (the M.13S
/// `notification_db.rs` precedent); the TdDb story-db plumbing lands at the
/// db integration.
pub(crate) struct StoryEnv<'a> {
    pub global: &'a mut Global,
    pub options: Option<&'a mut OptionManager>,
    pub auth_is_authorized: bool,
    pub auth_is_bot: bool,
    pub user_manager: &'a mut UserManager,
    pub chat_manager: &'a mut crate::chat_manager::ChatManager,
    pub file_manager: std::sync::Arc<parking_lot::Mutex<crate::files::FileManager>>,
    pub file_load_manager: std::sync::Arc<parking_lot::Mutex<crate::files::FileLoadManager>>,
    pub documents: &'a mut crate::documents_manager::DocumentsManager,
    pub animations: &'a mut crate::animations_manager::AnimationsManager,
    pub videos: &'a mut crate::videos_manager::VideosManager,
    pub audios: &'a mut crate::audios_manager::AudiosManager,
    pub voice_notes: &'a mut crate::voice_notes_manager::VoiceNotesManager,
    pub video_notes: &'a mut crate::video_notes_manager::VideoNotesManager,
    pub updates: &'a mut Vec<td_api::Update>,
    /// The story net dispatch surface — `None` keeps the net-inert
    /// posture (the §3.5 net-drain 20 families dispatch through it).
    pub net: Option<StoryNetHandle>,
    /// The `AudiosManager::upload_audio_file_callback_` outbox bridge —
    /// the story-music upload leg registers the file-plane uploads
    /// through it.
    pub audios_upload_callback:
        std::sync::Arc<parking_lot::Mutex<dyn crate::files::UploadCallback>>,
}

impl<'a> StoryEnv<'a> {
    /// The `UserEnv` for the user-manager surfaces the story plane needs;
    /// the caller halves land with the user-manager read surface.
    #[allow(dead_code)]
    fn user_env(&mut self) -> UserEnv<'_> {
        UserEnv {
            global: self.global,
            options: self
                .options
                .as_deref_mut()
                .expect("story requests run with the initialized option manager"),
            auth_is_bot: self.auth_is_bot,
        }
    }

    /// The `td_->dialog_manager_->get_input_peer(dialog_id, rights)` leg
    /// shared by the story query sends (the same split the
    /// `have_input_peer` override reads).
    fn story_input_peer(
        &mut self,
        dialog_id: DialogId,
        need_write: bool,
    ) -> Option<telegram_api::InputPeer> {
        let access_rights = if need_write {
            crate::user_manager::AccessRights::Write
        } else {
            crate::user_manager::AccessRights::Read
        };
        match dialog_id.get_type() {
            crate::dialog_id::DialogType::User => {
                let StoryEnv {
                    global,
                    options,
                    auth_is_bot,
                    user_manager,
                    ..
                } = self;
                let user_env = UserEnv {
                    global,
                    options: options
                        .as_deref_mut()
                        .expect("story requests run with the initialized option manager"),
                    auth_is_bot: *auth_is_bot,
                };
                user_manager.get_input_peer_user(&user_env, dialog_id.get_user_id(), access_rights)
            }
            crate::dialog_id::DialogType::Chat => self
                .chat_manager
                .get_input_peer_chat(dialog_id.get_chat_id(), access_rights),
            crate::dialog_id::DialogType::Channel => {
                let StoryEnv {
                    global,
                    options,
                    auth_is_bot,
                    chat_manager,
                    ..
                } = self;
                let user_env = UserEnv {
                    global,
                    options: options
                        .as_deref_mut()
                        .expect("story requests run with the initialized option manager"),
                    auth_is_bot: *auth_is_bot,
                };
                chat_manager.get_input_peer_channel(
                    &user_env,
                    dialog_id.get_channel_id(),
                    access_rights,
                )
            }
            crate::dialog_id::DialogType::SecretChat => None,
            crate::dialog_id::DialogType::None => Some(telegram_api::InputPeer::inputPeerEmpty(
                telegram_api::inputPeerEmpty {},
            )),
        }
    }
}

