    /// Take the single query of the expected constructor from the
    /// recorder (the engine's own difference fetches share the stream).
    fn take_sent_query(rec: &std::sync::Arc<RecNetSession>, constructor: i32) -> NetQuery {
        let sent = std::mem::take(&mut *rec.sent.lock());
        let mut matches: Vec<_> = sent
            .into_iter()
            .filter(|query| query.tl_constructor() == constructor)
            .collect();
        assert_eq!(
            matches.len(),
            1,
            "expected exactly one {constructor:#x} query"
        );
        matches.pop().unwrap()
    }

    /// Take the sent queries of two constructors sharing one flush (the
    /// paired `start_up` + first-load sends), one each.
    fn take_sent_pair(
        rec: &std::sync::Arc<RecNetSession>,
        first: i32,
        second: i32,
    ) -> (NetQuery, NetQuery) {
        let sent = std::mem::take(&mut *rec.sent.lock());
        let (mut firsts, seconds): (Vec<_>, Vec<_>) = sent
            .into_iter()
            .partition(|query| query.tl_constructor() == first);
        let mut seconds: Vec<_> = seconds
            .into_iter()
            .filter(|query| query.tl_constructor() == second)
            .collect();
        assert_eq!(firsts.len(), 1, "expected exactly one {first:#x} query");
        assert_eq!(seconds.len(), 1, "expected exactly one {second:#x} query");
        (firsts.pop().unwrap(), seconds.pop().unwrap())
    }

    /// The net-drain 36 band sweep — the remaining dispatcher families
    /// round-trip their wire answers (the band ladders live beside the
    /// tails in `group_call_manager.rs`).
    #[test]
    fn group_call_band_families_round_trip() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(group_call_band_families_round_trip_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn group_call_band_families_round_trip_impl() {
        use crate::group_call_manager::{GroupCall, GroupCallEnv, GroupCallId, GroupCallManager};

        struct NettedGroupCallEnv {
            updates: Vec<td_api::Update>,
        }
        impl GroupCallEnv for NettedGroupCallEnv {
            fn is_authorized(&self) -> bool {
                true
            }
            fn is_bot(&self) -> bool {
                false
            }
            fn send_update(&mut self, update: td_api::Update) {
                self.updates.push(update);
            }
            fn get_input_peer_read(
                &mut self,
                _dialog_id: DialogId,
            ) -> Option<telegram_api::InputPeer> {
                Some(telegram_api::InputPeer::inputPeerEmpty(
                    telegram_api::inputPeerEmpty {},
                ))
            }
        }

        let (mut td, rec) = netted_td("netfix-group-call-bands");
        let mut env = NettedGroupCallEnv {
            updates: Vec::new(),
        };
        td.group_call_manager.on_get_group_call(
            &mut env,
            GroupCall {
                group_call_id: GroupCallId::new(11),
                input_group_call_id: 7100,
                input_group_call_access_hash: 43,
                chat_id: -1_000_000_000_777,
                title: "band".to_owned(),
                is_active: true,
                is_joined: true,
                can_be_managed: true,
                ..GroupCall::default()
            },
        );

        macro_rules! drive_unit {
            ($td:ident, $rec:ident, $env:ident, $call:expr, $constructor:expr, $answer:expr) => {{
                let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
                let capture = std::sync::Arc::clone(&slot);
                let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                    *capture.lock().unwrap() = Some(result);
                });
                ($call)(&mut $td.group_call_manager, &mut $env, promise);
                let sent = take_sent_query(&$rec, $constructor);
                net_complete(sent, $answer);
                $td.dispatch_completed_group_call_net();
                slot
            }};
        }

        let updates_answer = || {
            let mut answer = Vec::new();
            answer.extend_from_slice(&telegram_api::updatesCombined::ID.to_le_bytes());
            telegram_api::updatesCombined {
                updates: vec![],
                users: vec![],
                chats: vec![],
                date: 1700000000,
                seq_start: 0,
                seq: 0,
            }
            .store(&mut answer);
            answer
        };

        // SaveJoinAs (phone.saveDefaultGroupCallJoinAs → Bool)
        {
            let slot = drive_unit!(
                td,
                rec,
                env,
                |manager: &mut GroupCallManager, env: &mut NettedGroupCallEnv, promise| {
                    manager.set_group_call_default_join_as(
                        env,
                        DialogId::new(-1_000_000_000_777),
                        telegram_api::InputPeer::inputPeerEmpty(telegram_api::inputPeerEmpty {}),
                        promise,
                    );
                },
                telegram_api::phone_saveDefaultGroupCallJoinAs::ID,
                {
                    // `boolTrue#997275b5` — the bootstrap Bool has no
                    // generated struct (the parse_wire_bool note).
                    (0x9972_75b5u32).to_le_bytes().to_vec()
                }
            );
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // Each drive registers its own record — the registry is
        // stateful across the drives (the live-story band, the
        // scheduled band and the equality settles read it).
        let register = |td: &mut Td,
                        env: &mut NettedGroupCallEnv,
                        is_live_story: bool,
                        scheduled_start_date: i32| {
            td.group_call_manager.on_get_group_call(
                env,
                GroupCall {
                    group_call_id: GroupCallId::new(11),
                    input_group_call_id: 7100,
                    input_group_call_access_hash: 43,
                    chat_id: -1_000_000_000_777,
                    is_active: true,
                    is_joined: true,
                    can_be_managed: true,
                    is_live_story,
                    scheduled_start_date,
                    ..GroupCall::default()
                },
            );
        };

        // SaveSendAs (phone.saveDefaultSendAs → Bool) — the tail's
        // live-story band needs a live-story record.
        {
            register(&mut td, &mut env, true, 0);
            let slot = drive_unit!(
                td,
                rec,
                env,
                |manager: &mut GroupCallManager, env: &mut NettedGroupCallEnv, promise| {
                    manager.set_group_call_default_send_as(
                        env,
                        GroupCallId::new(11),
                        DialogId::new(-1_000_000_000_777),
                        false,
                        telegram_api::InputPeer::inputPeerEmpty(telegram_api::inputPeerEmpty {}),
                        promise,
                    );
                },
                telegram_api::phone_saveDefaultSendAs::ID,
                {
                    // `boolTrue#997275b5` — the bootstrap Bool has no
                    // generated struct (the parse_wire_bool note).
                    (0x9972_75b5u32).to_le_bytes().to_vec()
                }
            );
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // ToggleStartSubscription (→ Updates)
        {
            register(&mut td, &mut env, false, 1700000000);
            let slot = drive_unit!(
                td,
                rec,
                env,
                |manager: &mut GroupCallManager, env: &mut NettedGroupCallEnv, promise| {
                    manager.toggle_group_call_start_subscribed(
                        env,
                        GroupCallId::new(11),
                        true,
                        promise,
                    );
                },
                telegram_api::phone_toggleGroupCallStartSubscription::ID,
                updates_answer()
            );
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // ToggleSettings (the revoke form → Updates)
        {
            let slot = drive_unit!(
                td,
                rec,
                env,
                |manager: &mut GroupCallManager, _env: &mut NettedGroupCallEnv, promise| {
                    manager.revoke_group_call_invite_link(GroupCallId::new(11), promise);
                },
                telegram_api::phone_toggleGroupCallSettings::ID,
                updates_answer()
            );
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // LeavePresentation (→ Updates)
        {
            let slot = drive_unit!(
                td,
                rec,
                env,
                |manager: &mut GroupCallManager, _env: &mut NettedGroupCallEnv, promise| {
                    manager.end_group_call_screen_sharing(GroupCallId::new(11), promise);
                },
                telegram_api::phone_leaveGroupCallPresentation::ID,
                updates_answer()
            );
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // ToggleRecord (→ Updates)
        {
            let slot = drive_unit!(
                td,
                rec,
                env,
                |manager: &mut GroupCallManager, _env: &mut NettedGroupCallEnv, promise| {
                    manager.toggle_group_call_recording(
                        GroupCallId::new(11),
                        true,
                        String::new(),
                        false,
                        false,
                        promise,
                    );
                },
                telegram_api::phone_toggleGroupCallRecord::ID,
                updates_answer()
            );
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // ExportInvite (phone.exportGroupCallInvite → the link)
        {
            let slot: std::sync::Arc<std::sync::Mutex<Option<tdutils::status::Result<String>>>> =
                std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            td.group_call_manager
                .get_group_call_invite_link(GroupCallId::new(11), true, promise);
            let sent = take_sent_query(&rec, telegram_api::phone_exportGroupCallInvite::ID);
            let mut answer = Vec::new();
            telegram_api::phone_ExportedGroupCallInvite {
                link: "https://t.me/c/1".to_owned(),
            }
            .store_boxed(&mut answer);
            net_complete(sent, answer);
            td.dispatch_completed_group_call_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Ok(link)) => {
                    assert_eq!(link, "https://t.me/c/1");
                }
                other => panic!("unexpected invite-link result: {other:?}"),
            }
        }

        // GetJoinAs (phone.getGroupCallJoinAs → the peers list)
        {
            let slot: std::sync::Arc<
                std::sync::Mutex<Option<tdutils::status::Result<td_api::MessageSenders>>>,
            > = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            td.group_call_manager.get_group_call_join_as(
                &mut env,
                DialogId::new(-1_000_000_000_777),
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::phone_getGroupCallJoinAs::ID);
            let mut answer = Vec::new();
            telegram_api::phone_JoinAsPeers {
                peers: vec![],
                chats: vec![],
                users: vec![],
            }
            .store_boxed(&mut answer);
            net_complete(sent, answer);
            td.dispatch_completed_group_call_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Ok(senders)) => {
                    assert_eq!(senders.total_count, 0);
                }
                other => panic!("unexpected join-as result: {other:?}"),
            }
        }

        // GetStars (phone.getGroupCallStars → the donors total)
        {
            let slot: std::sync::Arc<
                std::sync::Mutex<Option<tdutils::status::Result<td_api::LiveStoryDonors>>>,
            > = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            register(&mut td, &mut env, true, 0);
            td.group_call_manager
                .get_group_call_stars_from_server(GroupCallId::new(11), promise);
            let sent = take_sent_query(&rec, telegram_api::phone_getGroupCallStars::ID);
            let mut answer = Vec::new();
            telegram_api::phone_GroupCallStars {
                total_stars: 5_000_000_000,
                top_donors: vec![],
                chats: vec![],
                users: vec![],
            }
            .store_boxed(&mut answer);
            net_complete(sent, answer);
            td.dispatch_completed_group_call_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Ok(donors)) => {
                    // the wire total is already in stars; the answer
                    // applies only the ±2^51 clamp (cpp:1799-1816)
                    assert_eq!(donors.total_star_count, 5_000_000_000);
                }
                other => panic!("unexpected stars result: {other:?}"),
            }
        }

        // Invite (phone.inviteToGroupCall → Updates) — the not-a-video-
        // chat band needs the non-live-story record back.
        {
            register(&mut td, &mut env, false, 0);
            let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            td.group_call_manager.invite_group_call_participants(
                GroupCallId::new(11),
                vec![telegram_api::InputUser::inputUserSelf(
                    telegram_api::inputUserSelf {},
                )],
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::phone_inviteToGroupCall::ID);
            net_complete(sent, updates_answer());
            td.dispatch_completed_group_call_net();
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // SendMessage (phone.sendGroupCallMessage → the star ledger +
        // the updates hop) and its revert band. The paid-message bands
        // ride the live-story record.
        {
            register(&mut td, &mut env, true, 0);
            let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            td.group_call_manager.send_group_call_message(
                GroupCallId::new(11),
                5,
                false,
                false,
                true,
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::phone_sendGroupCallMessage::ID);
            net_fail(sent, 400, "STARS_WITHDRAWAL_FAILED");
            td.dispatch_completed_group_call_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Err(status)) => {
                    assert_eq!(status.message(), "STARS_WITHDRAWAL_FAILED");
                }
                other => panic!("unexpected send-message result: {other:?}"),
            }
        }

        // DeleteSenderMessages (phone.deleteGroupCallParticipantMessages
        // → Updates)
        {
            let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            register(&mut td, &mut env, true, 0);
            td.group_call_manager.delete_group_call_messages_by_sender(
                &mut env,
                GroupCallId::new(11),
                DialogId::new(-1_000_000_000_777),
                false,
                promise,
            );
            let sent = take_sent_query(
                &rec,
                telegram_api::phone_deleteGroupCallParticipantMessages::ID,
            );
            net_complete(sent, updates_answer());
            td.dispatch_completed_group_call_net();
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // Leave (phone.leaveGroupCall → Updates)
        {
            let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            td.group_call_manager
                .leave_group_call(GroupCallId::new(11), promise);
            let sent = take_sent_query(&rec, telegram_api::phone_leaveGroupCall::ID);
            net_complete(sent, updates_answer());
            td.dispatch_completed_group_call_net();
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // DeclineInvite (phone.declineConferenceCallInvite → Updates)
        {
            let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            td.group_call_manager
                .decline_group_call_invitation(42, promise);
            let sent = take_sent_query(&rec, telegram_api::phone_declineConferenceCallInvite::ID);
            net_complete(sent, updates_answer());
            td.dispatch_completed_group_call_net();
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // GetStreamer (phone.getGroupCall limit 10) — the C++ band
        // (cpp:2450-2479): only a joined live story scans for the
        // streamer; the plain video chats, the rtmp streams and the
        // not-joined live stories settle before the wire query. The
        // answer side stays the signaling thin form — the C++
        // participant scan (cpp:513-520) rides the parked participants
        // plane.
        fn wire_call(id: i64) -> telegram_api::GroupCall {
            telegram_api::GroupCall::groupCall(telegram_api::groupCall {
                flags: 0,
                join_muted: false,
                can_change_join_muted: false,
                join_date_asc: false,
                schedule_start_subscribed: false,
                can_start_video: false,
                record_video_active: false,
                rtmp_stream: false,
                listeners_hidden: false,
                conference: false,
                creator: false,
                messages_enabled: false,
                can_change_messages_enabled: false,
                min: false,
                id,
                access_hash: 43,
                participants_count: 0,
                title: "band".to_owned(),
                stream_dc_id: 0,
                record_start_date: 0,
                schedule_date: 0,
                unmuted_video_count: 0,
                unmuted_video_limit: 0,
                version: 1,
                invite_link: String::new(),
                send_paid_messages_stars: 0,
                default_send_as: None,
            })
        }
        type StreamerSlot = std::sync::Arc<
            std::sync::Mutex<Option<tdutils::status::Result<Option<td_api::GroupCallParticipant>>>>,
        >;
        let streamer_slot = || {
            let slot: StreamerSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            (slot, promise)
        };

        // the plain video chat settles empty with no wire query
        {
            register(&mut td, &mut env, false, 0);
            let (slot, promise) = streamer_slot();
            td.group_call_manager
                .get_group_call_streamer(GroupCallId::new(11), promise);
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(None))
            ));
            assert!(rec.sent.lock().is_empty(), "the plain band must not send");
        }

        // the rtmp stream settles empty with no wire query
        {
            td.group_call_manager.on_get_group_call(
                &mut env,
                GroupCall {
                    group_call_id: GroupCallId::new(11),
                    input_group_call_id: 7100,
                    input_group_call_access_hash: 43,
                    chat_id: -1_000_000_000_777,
                    is_active: true,
                    is_joined: true,
                    is_rtmp_stream: true,
                    ..GroupCall::default()
                },
            );
            let (slot, promise) = streamer_slot();
            td.group_call_manager
                .get_group_call_streamer(GroupCallId::new(11), promise);
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(None))
            ));
            assert!(rec.sent.lock().is_empty(), "the rtmp band must not send");
        }

        // the not-joined live story takes the C++ else arm's error
        {
            td.group_call_manager.on_get_group_call(
                &mut env,
                GroupCall {
                    group_call_id: GroupCallId::new(11),
                    input_group_call_id: 7100,
                    input_group_call_access_hash: 43,
                    chat_id: -1_000_000_000_777,
                    is_active: true,
                    is_joined: false,
                    is_live_story: true,
                    ..GroupCall::default()
                },
            );
            let (slot, promise) = streamer_slot();
            td.group_call_manager
                .get_group_call_streamer(GroupCallId::new(11), promise);
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Err(status)) => {
                    assert_eq!(status.message(), "GROUPCALL_JOIN_MISSING");
                }
                other => panic!("unexpected streamer result: {other:?}"),
            }
            assert!(rec.sent.lock().is_empty(), "the error band must not send");
        }

        // the joined live story dispatches; the success settles the
        // thin None through the answer tail
        {
            register(&mut td, &mut env, true, 0);
            let (slot, promise) = streamer_slot();
            td.group_call_manager
                .get_group_call_streamer(GroupCallId::new(11), promise);
            let sent = take_sent_query(&rec, telegram_api::phone_getGroupCall::ID);
            let wire = telegram_api::phone_getGroupCall::parse(sent.query()).unwrap();
            assert_eq!(wire.limit, 10);
            let mut answer = Vec::new();
            telegram_api::phone_GroupCall {
                call: Some(wire_call(7100)),
                participants: vec![],
                participants_next_offset: String::new(),
                chats: vec![],
                users: vec![],
            }
            .store_boxed(&mut answer);
            net_complete(sent, answer);
            td.dispatch_completed_group_call_net();
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(None))
            ));
        }

        // the tail scope: GROUPCALL_NOT_MODIFIED collapses locally only
        // on the five C++ handlers (cpp:792, 984, 1017, 1063, 1474) —
        // ToggleRecord settles Ok; Leave errors through (cpp:1588-1590).
        // (EditTitle / ToggleStartSubscription can't drive the tail —
        // their promises settle at the request arm, cpp:5231 / 4387.)
        {
            register(&mut td, &mut env, false, 0);
            let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            td.group_call_manager.toggle_group_call_recording(
                GroupCallId::new(11),
                true,
                String::new(),
                false,
                false,
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::phone_toggleGroupCallRecord::ID);
            net_fail(sent, 400, "GROUPCALL_NOT_MODIFIED");
            td.dispatch_completed_group_call_net();
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }
        {
            let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            td.group_call_manager
                .leave_group_call(GroupCallId::new(11), promise);
            let sent = take_sent_query(&rec, telegram_api::phone_leaveGroupCall::ID);
            net_fail(sent, 400, "GROUPCALL_NOT_MODIFIED");
            td.dispatch_completed_group_call_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Err(status)) => {
                    assert_eq!(status.message(), "GROUPCALL_NOT_MODIFIED");
                }
                other => panic!("unexpected leave result: {other:?}"),
            }
        }
    }

    fn group_call_families_ride_the_dispatcher_impl() {
        use crate::group_call_manager::{GroupCall, GroupCallEnv, GroupCallId, GroupCallManager};

        /// The netted test env: the peer seam hands the empty peer (the
        /// dispatch goes through the manager's installed handle), the
        /// updates collect.
        struct NettedGroupCallEnv {
            updates: Vec<td_api::Update>,
        }
        impl GroupCallEnv for NettedGroupCallEnv {
            fn is_authorized(&self) -> bool {
                true
            }
            fn is_bot(&self) -> bool {
                false
            }
            fn send_update(&mut self, update: td_api::Update) {
                self.updates.push(update);
            }
            fn get_input_peer_read(
                &mut self,
                _dialog_id: DialogId,
            ) -> Option<telegram_api::InputPeer> {
                Some(telegram_api::InputPeer::inputPeerEmpty(
                    telegram_api::inputPeerEmpty {},
                ))
            }
        }

        fn wire_call(id: i64, title: &str) -> telegram_api::GroupCall {
            telegram_api::GroupCall::groupCall(telegram_api::groupCall {
                // the title (bit 3), schedule_date (bit 7), creator
                // (bit 15) and messages_enabled (bit 17) flag masks
                flags: (1 << 3) | (1 << 7) | (1 << 15) | (1 << 17),
                join_muted: false,
                can_change_join_muted: false,
                join_date_asc: false,
                schedule_start_subscribed: false,
                can_start_video: false,
                record_video_active: false,
                rtmp_stream: false,
                listeners_hidden: false,
                conference: false,
                creator: true,
                messages_enabled: true,
                can_change_messages_enabled: false,
                min: false,
                id,
                access_hash: 42,
                participants_count: 0,
                title: title.to_owned(),
                stream_dc_id: 0,
                record_start_date: 0,
                schedule_date: 1700000000,
                unmuted_video_count: 0,
                unmuted_video_limit: 0,
                version: 1,
                invite_link: String::new(),
                send_paid_messages_stars: 0,
                default_send_as: None,
            })
        }

        fn registered_call() -> GroupCall {
            GroupCall {
                group_call_id: GroupCallId::new(9),
                input_group_call_id: 7000,
                input_group_call_access_hash: 42,
                chat_id: -1_000_000_000_999,
                title: "old".to_owned(),
                is_active: true,
                is_joined: true,
                can_be_managed: true,
                ..GroupCall::default()
            }
        }

        fn unit_slot() -> (tdutils::promise::Promise<()>, UnitSlot) {
            let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            (promise, slot)
        }

        let (mut td, rec) = netted_td("netfix-group-call");
        let mut env = NettedGroupCallEnv {
            updates: Vec::new(),
        };
        let manager = &mut td.group_call_manager;
        manager.on_get_group_call(&mut env, registered_call());

        // 1. getGroupCall — the reload dispatch; the answer updates the
        //    registry and settles the typed promise.
        {
            let slot: std::sync::Arc<
                std::sync::Mutex<Option<tdutils::status::Result<Option<td_api::GroupCall>>>>,
            > = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            let manager = &mut td.group_call_manager;
            manager.reload_group_call(GroupCallId::new(9), promise);
            let sent = std::mem::take(&mut *rec.sent.lock());
            assert_eq!(sent.len(), 1);
            assert_eq!(
                sent[0].tl_constructor(),
                telegram_api::phone_getGroupCall::ID
            );
            let wire = telegram_api::phone_getGroupCall::parse(sent[0].query()).unwrap();
            let telegram_api::InputGroupCall::inputGroupCall(input) = wire.call.unwrap() else {
                panic!("expected the input group call");
            };
            assert_eq!(input.id, 7000);
            assert_eq!(input.access_hash, 42);
            assert_eq!(wire.limit, 3);

            let mut answer = Vec::new();
            telegram_api::phone_GroupCall {
                call: Some(wire_call(7000, "renamed")),
                participants: vec![],
                participants_next_offset: String::new(),
                chats: vec![],
                users: vec![],
            }
            .store_boxed(&mut answer);

            net_complete(sent.into_iter().next().unwrap(), answer);
            td.dispatch_completed_group_call_net();
            let settled = slot.lock().unwrap().take();
            match settled {
                Some(tdutils::status::Result::Ok(Some(object))) => {
                    assert_eq!(object.id, 9);
                    assert_eq!(object.title, "renamed");
                    assert!(object.is_active);
                    assert_eq!(object.scheduled_start_date, 1700000000);
                }
                other => panic!("unexpected getGroupCall result: {other:?}"),
            }
            assert_eq!(
                td.group_call_manager
                    .get_group_call(GroupCallId::new(9))
                    .unwrap()
                    .title,
                "renamed"
            );
        }

        // 2. startScheduledVideoChat — the dispatch; the Updates answer
        //    settles through the inline updates hop.
        {
            let (promise, slot) = unit_slot();
            let manager = &mut td.group_call_manager;
            manager.start_scheduled_group_call(GroupCallId::new(9), promise);
            let sent = take_sent_query(&rec, telegram_api::phone_startScheduledGroupCall::ID);
            let mut answer = Vec::new();
            answer.extend_from_slice(&telegram_api::updatesCombined::ID.to_le_bytes());
            telegram_api::updatesCombined {
                updates: vec![],
                users: vec![],
                chats: vec![],
                date: 1700000000,
                seq_start: 0,
                seq: 0,
            }
            .store(&mut answer);
            net_complete(sent, answer);
            td.dispatch_completed_group_call_net();
            assert!(matches!(
                *slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // 3. getVideoChatRtmpUrl — the RtmpUrl answer converts.
        {
            let slot: std::sync::Arc<
                std::sync::Mutex<Option<tdutils::status::Result<td_api::RtmpUrl>>>,
            > = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            let manager = &mut td.group_call_manager;
            manager.get_video_chat_rtmp_stream_url(
                &mut env,
                DialogId::new(-1_000_000_000_999),
                false,
                false,
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::phone_getGroupCallStreamRtmpUrl::ID);
            let mut answer = Vec::new();
            telegram_api::phone_GroupCallStreamRtmpUrl {
                url: "rtmps://url".to_owned(),
                key: "the-key".to_owned(),
            }
            .store_boxed(&mut answer);
            net_complete(sent, answer);
            td.dispatch_completed_group_call_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Ok(rtmp)) => {
                    assert_eq!(rtmp.url, "rtmps://url");
                    assert_eq!(rtmp.stream_key, "the-key");
                }
                other => panic!("unexpected rtmp result: {other:?}"),
            }
        }

        // 4. getGroupCallStreams — the channel answer converts.
        {
            let slot: std::sync::Arc<
                std::sync::Mutex<Option<tdutils::status::Result<td_api::GroupCallStreams>>>,
            > = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            let mut call = registered_call();
            call.stream_dc_id = 2;
            td.group_call_manager.on_get_group_call(&mut env, call);
            let manager = &mut td.group_call_manager;
            manager.get_group_call_streams(GroupCallId::new(9), promise);
            let sent = take_sent_query(&rec, telegram_api::phone_getGroupCallStreamChannels::ID);
            let mut answer = Vec::new();
            telegram_api::phone_GroupCallStreamChannels {
                channels: vec![telegram_api::GroupCallStreamChannel {
                    channel: 7,
                    scale: 3,
                    last_timestamp_ms: 12345,
                }],
            }
            .store_boxed(&mut answer);
            net_complete(sent, answer);
            td.dispatch_completed_group_call_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Ok(streams)) => {
                    assert_eq!(streams.streams.len(), 1);
                    assert_eq!(streams.streams[0].channel_id, 7);
                    assert_eq!(streams.streams[0].time_offset, 12345);
                }
                other => panic!("unexpected streams result: {other:?}"),
            }
        }

        // 5. discardGroupCall — the error ladder settles through the
        //    promise (the parse failures ride the same tail).
        {
            let (promise, slot) = unit_slot();
            let manager = &mut td.group_call_manager;
            manager.discard_group_call(GroupCallId::new(9), promise);
            let sent = take_sent_query(&rec, telegram_api::phone_discardGroupCall::ID);
            net_fail(sent, 400, "GROUPCALL_INVALID");
            td.dispatch_completed_group_call_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Err(status)) => {
                    assert_eq!(status.code(), 400);
                    assert_eq!(status.message(), "GROUPCALL_INVALID");
                }
                other => panic!("unexpected discard result: {other:?}"),
            }
        }

        // 6. the net-inert posture — a dispatcher-less manager logs the
        //    send and parks the promise in the lot.
        {
            let mut inert = GroupCallManager::new();
            inert.on_get_group_call(&mut env, registered_call());
            let (promise, slot) = unit_slot();
            inert.discard_group_call(GroupCallId::new(9), promise);
            assert!(slot.lock().unwrap().is_none());
            assert_eq!(inert.pending.discard.len(), 1);
        }
    }

    fn poll_families_ride_the_dispatcher_impl() {
        use crate::dialog_id::{DialogId, MessageFullId};
        use crate::messages_manager::MessageId;
        use crate::poll_manager::{Poll, PollId, PollManagerEnv, PollOption};

        /// A `Promise<T>` slot (the UnitSlot convention over any type).
        type PromiseSlot<T> = std::sync::Arc<std::sync::Mutex<Option<tdutils::status::Result<T>>>>;
        fn record_slot<T: Send + 'static>() -> (Promise<T>, PromiseSlot<T>) {
            let slot: PromiseSlot<T> = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            (promise, slot)
        }

        /// An empty `Updates` container — the same walk-safe answer the
        /// group-call round-trips use.
        fn empty_updates() -> Vec<u8> {
            let mut answer = Vec::new();
            telegram_api::Updates::updatesCombined(telegram_api::updatesCombined {
                updates: Vec::new(),
                users: Vec::new(),
                chats: Vec::new(),
                date: 1700000000,
                seq_start: 0,
                seq: 0,
            })
            .store(&mut answer);
            answer
        }

        let (mut td, rec) = netted_td("netfix-poll");
        // the self user id without the user record (inputPeerSelf
        // resolves at the send legs)
        tdactor::ActorMessage::dispatch(SeedMyId(500), &mut td);
        let my_id = td.user_manager.get_my_id();
        let dialog_id = DialogId::from_user_id(my_id);
        let message_full_id = MessageFullId::new(dialog_id, MessageId::new(1 << 20));
        let poll_id = PollId::new(31);

        // seed the poll record over the self dialog (inputPeerSelf
        // resolves at the send legs) + register the server message (the
        // GetPollResults timeout arm)
        {
            let (mut env, manager) = poll_env_split(&mut td);
            manager.polls.insert(
                poll_id,
                Poll {
                    options: vec![
                        PollOption {
                            voter_count: 1,
                            data: "a".to_owned(),
                            ..PollOption::default()
                        },
                        PollOption {
                            voter_count: 0,
                            data: "b".to_owned(),
                            ..PollOption::default()
                        },
                    ],
                    hash: 77,
                    is_anonymous: false,
                    allow_multiple_answers: true,
                    ..Poll::default()
                },
            );
            manager.register_poll(&mut env, poll_id, message_full_id);
        }

        // 1. getPollResults — the register-armed 0.0 timeout fires at the
        //    tick, the send resolves inputPeerSelf, the Updates answer
        //    feeds the engine with the empty promise.
        {
            let (mut env, manager) = poll_env_split(&mut td);
            manager.tick_timeouts(&mut env);
            let sent = take_sent_query(&rec, telegram_api::messages_getPollResults::ID);
            let wire = telegram_api::messages_getPollResults::parse(sent.query()).unwrap();
            assert!(
                matches!(
                    *wire.peer.unwrap(),
                    telegram_api::InputPeer::inputPeerSelf(_)
                ),
                "the self dialog resolves inputPeerSelf"
            );
            assert_eq!(wire.msg_id, 1);
            assert_eq!(wire.poll_hash, 77);

            net_complete(sent, empty_updates());
            td.dispatch_completed_poll_net();
            // the lot drained and the family's own deadline is gone (the
            // engine may refire its difference machinery — not ours to
            // assert here)
            assert!(td.poll_manager.pending_net.get_poll_results.is_empty());
            let (mut env, manager) = poll_env_split(&mut td);
            manager.tick_timeouts(&mut env);
            assert!(!manager.update_poll_timeout.contains_key(&poll_id.get()));
        }

        // 2. sendVote — the replay entry (`do_set_poll_answer`) parks the
        //    promise and dispatches; the Updates answer walks the engine
        //    then finishes the ladder with Unit().
        {
            let (promise, slot) = record_slot::<()>();
            let (mut env, manager) = poll_env_split(&mut td);
            manager.do_set_poll_answer(
                &mut env,
                poll_id,
                message_full_id,
                vec!["a".to_owned()],
                0,
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_sendVote::ID);
            let wire = telegram_api::messages_sendVote::parse(sent.query()).unwrap();
            assert_eq!(wire.msg_id, 1);
            assert_eq!(wire.options, vec![b"a".to_vec()]);

            net_complete(sent, empty_updates());
            td.dispatch_completed_poll_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Ok(())) => {}
                other => panic!("unexpected sendVote result: {other:?}"),
            }
            assert!(!td.poll_manager.pending_answers.contains_key(&poll_id));
        }

        // 2b. sendVote — the wire error band: the dialog-error head runs,
        //    the ladder settles the parked promise with the error.
        {
            let (promise, slot) = record_slot::<()>();
            let (mut env, manager) = poll_env_split(&mut td);
            manager.do_set_poll_answer(
                &mut env,
                poll_id,
                message_full_id,
                vec!["b".to_owned()],
                0,
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_sendVote::ID);
            net_fail(sent, 400, "VOTE_NOT_ALLOWED");
            td.dispatch_completed_poll_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Err(status)) => {
                    assert_eq!(status.code(), 400);
                    assert_eq!(status.message(), "VOTE_NOT_ALLOWED");
                }
                other => panic!("unexpected sendVote error result: {other:?}"),
            }
        }

        // 3. stopPoll — the replay entry (`do_stop_poll`) dispatches the
        //    closed-poll editMessage; the Updates answer walks the
        //    engine then runs on_stop_poll_finished (the promise + the
        //    being_closed erase).
        {
            let (promise, slot) = record_slot::<()>();
            let (mut env, manager) = poll_env_split(&mut td);
            manager.do_stop_poll(&mut env, poll_id, message_full_id, None, 0, promise);
            let sent = take_sent_query(&rec, telegram_api::messages_editMessage::ID);
            let wire = telegram_api::messages_editMessage::parse(sent.query()).unwrap();
            // MEDIA_MASK without REPLY_MARKUP_MASK (the null markup)
            assert_eq!(wire.flags & (1 << 14), 1 << 14);
            assert_eq!(wire.flags & (1 << 2), 0);
            assert_eq!(wire.id, 1);
            let telegram_api::InputMedia::inputMediaPoll(input) = *wire.media.unwrap() else {
                panic!("expected the inputMediaPoll close stub");
            };
            let poll = input.poll.unwrap();
            assert_eq!(poll.id, 31);
            assert!(poll.closed);
            assert!(poll.creator);
            assert!(!poll.multiple_choice);

            assert!(td.poll_manager.being_closed_polls.contains(&poll_id));
            net_complete(sent, empty_updates());
            td.dispatch_completed_poll_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Ok(())) => {}
                other => panic!("unexpected stopPoll result: {other:?}"),
            }
            assert!(!td.poll_manager.being_closed_polls.contains(&poll_id));
        }

        // 3b. stopPoll — the MESSAGE_NOT_MODIFIED band settles Ok
        //     (non-bot) through on_stop_poll_finished.
        {
            let (promise, slot) = record_slot::<()>();
            let (mut env, manager) = poll_env_split(&mut td);
            manager.do_stop_poll(&mut env, poll_id, message_full_id, None, 0, promise);
            let sent = take_sent_query(&rec, telegram_api::messages_editMessage::ID);
            net_fail(sent, 400, "MESSAGE_NOT_MODIFIED");
            td.dispatch_completed_poll_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Ok(())) => {}
                other => panic!("unexpected stopPoll not-modified result: {other:?}"),
            }
            assert!(!td.poll_manager.being_closed_polls.contains(&poll_id));
        }

        // 4. getPollVoters — the entry point rides the M.10 seam, so the
        //    parked lot + promise drive the send arm; the votesList
        //    answer runs the intake (the unknown self voter drops from
        //    the object, the wire count carries).
        {
            let (promise, slot) = record_slot::<td_api::PollVoters>();
            {
                let (_, manager) = poll_env_split(&mut td);
                manager
                    .poll_voters
                    .entry(poll_id)
                    .or_default()
                    .resize_with(2, Default::default);
                manager.poll_voters.get_mut(&poll_id).unwrap()[0]
                    .pending_queries
                    .push(promise);
                manager.pending_net.get_poll_voters.push((
                    poll_id,
                    0,
                    String::new(),
                    10,
                    dialog_id,
                ));
            }
            let (mut env, _) = poll_env_split(&mut td);
            env.send_get_poll_voters_query(&message_full_id, poll_id, 0, b"a".to_vec(), "", 10)
                .unwrap();
            let sent = take_sent_query(&rec, telegram_api::messages_getPollVotes::ID);
            let wire = telegram_api::messages_getPollVotes::parse(sent.query()).unwrap();
            // OPTION_MASK without OFFSET_MASK; the wire limit is
            // max(limit, 10)
            assert_eq!(wire.flags, 1);
            assert_eq!(wire.id, 1);
            assert_eq!(wire.option, b"a".to_vec());
            assert_eq!(wire.limit, 10);

            let mut answer = Vec::new();
            telegram_api::messages_VotesList {
                flags: 0,
                count: 1,
                votes: vec![telegram_api::MessagePeerVote::messagePeerVoteInputOption(
                    telegram_api::messagePeerVoteInputOption {
                        peer: Some(telegram_api::Peer::peerUser(telegram_api::peerUser {
                            user_id: my_id.get(),
                        })),
                        date: 1700000000,
                    },
                )],
                chats: Vec::new(),
                users: Vec::new(),
                next_offset: String::new(),
            }
            .store_boxed(&mut answer);
            net_complete(sent, answer);
            td.dispatch_completed_poll_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Ok(object)) => {
                    assert_eq!(object.total_count, 1);
                    // the not-yet-received self voter drops from the
                    // object (the min-sender gate)
                    assert!(object.voters.is_empty());
                }
                other => panic!("unexpected getPollVoters result: {other:?}"),
            }
            // the voter landed in the cache and the next page answers
            // from it
            assert_eq!(
                td.poll_manager.poll_voters.get(&poll_id).unwrap()[0]
                    .voters
                    .len(),
                1
            );
        }

        // 5. deletePollAnswer — the entry point rides the M.10 seam, so
        //    the parked promise drives the send arm; the Updates answer
        //    walks the engine with the promise.
        {
            let (promise, slot) = record_slot::<()>();
            {
                let (_, manager) = poll_env_split(&mut td);
                manager
                    .pending_net
                    .delete_poll_answer
                    .push((dialog_id, promise));
            }
            let (mut env, _) = poll_env_split(&mut td);
            env.send_delete_poll_answer_query(&message_full_id, b"b".to_vec())
                .unwrap();
            let sent = take_sent_query(&rec, telegram_api::messages_deletePollAnswer::ID);
            let wire = telegram_api::messages_deletePollAnswer::parse(sent.query()).unwrap();
            assert_eq!(wire.msg_id, 1);
            assert_eq!(wire.option, b"b".to_vec());

            net_complete(sent, empty_updates());
            td.dispatch_completed_poll_net();
            match slot.lock().unwrap().take() {
                Some(tdutils::status::Result::Ok(())) => {}
                other => panic!("unexpected deletePollAnswer result: {other:?}"),
            }
            assert!(td.poll_manager.pending_net.delete_poll_answer.is_empty());
        }
    }

    fn account_queries_ride_the_dispatcher_impl() {
        let (mut td, rec) = netted_td("netfix-account");

        // 1. getUserLink — the plain form (remove_messages_fee =
        //    false) with the empty first username parks at the
        //    phone-number privacy (AccountManager.cpp:1401-1420); the
        //    pump drives account.getPrivacy, and without a
        //    my_phone_number option the chain falls through to the
        //    contacts_exportContactToken query — the answer clamps the
        //    expiry against the td clock.
        let (promise, slot) = record_account_user_link();
        with_account_manager(&mut td, |manager, env| {
            manager.get_user_link(env, false, false, false, promise);
        });
        assert!(
            rec.sent.lock().is_empty(),
            "the phone arm waits for the privacy drive"
        );
        td.dispatch_completed_walking();
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::account_getPrivacy::ID
        );
        net_complete(
            sent.into_iter().next().unwrap(),
            wire_privacy_rules_answer(vec![telegram_api::PrivacyRule::privacyValueAllowAll(
                telegram_api::privacyValueAllowAll,
            )]),
        );
        td.dispatch_completed_walking();
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::contacts_exportContactToken::ID
        );
        let expires = td.global.unix_time() + 100;
        let mut answer = Vec::new();
        telegram_api::ExportedContactToken {
            url: "https://t.me/contact".to_owned(),
            expires,
        }
        .store_boxed(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_account_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(link)) => {
                assert_eq!(link.url, "https://t.me/contact");
                assert_eq!(link.expires_in, 100);
            }
            other => panic!("unexpected user link result: {other:?}"),
        }

        // 2. setInactiveSessionTtlDays — the SetAuthorizationTtlQuery
        //    dispatch; boolTrue answers ok.
        let (promise, slot) = record_ton_unit();
        with_account_manager(&mut td, |manager, env| {
            manager.set_inactive_session_ttl_days(env, 90, promise);
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::account_setAuthorizationTTL::ID
        );
        net_complete(sent.into_iter().next().unwrap(), bool_answer(true));
        td.dispatch_completed_account_net();
        assert!(matches!(
            *slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 3. setAccountTtl — the boolFalse 500 band.
        let (promise, slot) = record_ton_unit();
        with_account_manager(&mut td, |manager, env| {
            manager.set_account_ttl(env, 180, promise);
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::account_setAccountTTL::ID
        );
        net_complete(sent.into_iter().next().unwrap(), bool_answer(false));
        td.dispatch_completed_account_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.code(), 500);
                assert_eq!(
                    status.message(),
                    "Internal Server Error: failed to set account TTL"
                );
            }
            other => panic!("unexpected ttl result: {other:?}"),
        }

        // 4. getAccountTtl — the days answer converts.
        let (promise, slot) = record_account_ttl();
        with_account_manager(&mut td, |manager, env| {
            manager.get_account_ttl(env, promise);
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::account_getAccountTTL::ID
        );
        let mut answer = Vec::new();
        telegram_api::AccountDaysTTL { days: 30 }.store_boxed(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_account_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(ttl)) => assert_eq!(ttl.days, 30),
            other => panic!("unexpected ttl result: {other:?}"),
        }

        // 5. confirmQrCodeAuthentication — the AcceptLoginTokenQuery
        //    dispatch; the Authorization answer converts to the Session.
        let (promise, slot) = record_account_session();
        with_account_manager(&mut td, |manager, env| {
            manager.confirm_qr_code_authentication(env, "tg://login?token=QUJD", promise);
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::auth_acceptLoginToken::ID
        );
        let mut answer = Vec::new();
        wire_authorization(5, true, 42).store_boxed(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_account_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(session)) => {
                assert_eq!(session.id, 5);
                assert!(session.is_current);
            }
            other => panic!("unexpected session result: {other:?}"),
        }

        // 6. getActiveSessions — the ttl clamp (9999 → 180) and the
        //    current-first sort.
        let (promise, slot) = record_account_sessions();
        with_account_manager(&mut td, |manager, env| {
            manager.get_active_sessions(env, promise);
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::account_getAuthorizations::ID
        );
        let mut answer = Vec::new();
        telegram_api::account_Authorizations {
            authorization_ttl_days: 9999,
            authorizations: vec![
                wire_authorization(2, false, 10),
                wire_authorization(1, true, 20),
            ],
        }
        .store_boxed(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_account_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(sessions)) => {
                assert_eq!(sessions.inactive_session_ttl_days, 180);
                assert_eq!(sessions.sessions.len(), 2);
                assert_eq!(sessions.sessions[0].id, 1);
                assert!(sessions.sessions[0].is_current);
                assert_eq!(sessions.sessions[1].id, 2);
            }
            other => panic!("unexpected sessions result: {other:?}"),
        }

        // 7. getConnectedWebsites — the websites conversion over the
        //    users intake.
        let (promise, slot) = record_account_websites();
        with_account_manager(&mut td, |manager, env| {
            manager.get_connected_websites(env, promise);
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::account_getWebAuthorizations::ID
        );
        let mut answer = Vec::new();
        telegram_api::account_WebAuthorizations {
            authorizations: vec![telegram_api::WebAuthorization {
                hash: 3,
                bot_id: 7,
                domain: "example.com".to_owned(),
                browser: "Firefox".to_owned(),
                platform: "Linux".to_owned(),
                date_created: 1,
                date_active: 2,
                ip: "127.0.0.1".to_owned(),
                region: "Region".to_owned(),
            }],
            users: vec![],
        }
        .store_boxed(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_account_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(websites)) => {
                assert_eq!(websites.websites.len(), 1);
                let website = websites.websites.into_iter().next().unwrap();
                assert_eq!(website.id, 3);
                assert_eq!(website.domain_name, "example.com");
                assert_eq!(website.bot_user_id, 7);
            }
            other => panic!("unexpected websites result: {other:?}"),
        }

        assert!(td.account_net_completed.lock().is_empty(), "drained");
    }

    // ---- the net-drain 51 terms-of-service slice: the poll + accept
    // families ride the account dispatch plane (the
    // TermsOfServiceManager.cpp handler halves). ----

    /// The net-drain 51 terms-of-service round-trips — the §3.9
    /// families ride the dispatcher through the [`AccountEnv`] send
    /// arms (GetTermsOfServiceUpdateQuery/AcceptTermsOfServiceQuery,
    /// TermsOfServiceManager.cpp:23-92): the auth-success poll with the
    /// full terms object in the update, the accept through the live
    /// td_api arm with the schedule(0) re-poll, and the
    /// false-Bool/error/parse bands.
    #[test]
    fn terms_of_service_families_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(terms_of_service_families_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    // ---- the net-drain 52 suggested-action slice (the promo family):
    // the login-email check rides the account dispatch plane (the
    // SuggestedActionManager.cpp CheckPromoDataQuery handler half). ----

    /// The net-drain 52 promo round-trip — the §3.9 family rides the
    /// dispatcher through the [`AccountEnv`] send arm
    /// (CheckPromoDataQuery, SuggestedActionManager.cpp:65-105): the
    /// live `isLoginEmailAddressRequired` arm dispatches
    /// `help.getPromoData`, the matching SETUP_LOGIN_EMAIL answer
    /// settles ok (cpp:87-93), the unmatched and empty promo bands
    /// answer 404 "Not Found" (cpp:94-99), errors forward verbatim
    /// (cpp:102-104) and parse failures ride the 500 convention.

    #[test]
    fn suggested_action_promo_bands_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(suggested_action_promo_bands_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn suggested_action_promo_bands_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-suggested-actions");

        fn promo_answer(suggestions: &[&str]) -> Vec<u8> {
            let mut out = Vec::new();
            telegram_api::help_PromoData::help_promoData(telegram_api::help_promoData {
                flags: 0,
                proxy: false,
                expires: 1_700_003_600,
                peer: None,
                psa_type: String::new(),
                psa_message: String::new(),
                pending_suggestions: suggestions.iter().map(|s| s.to_string()).collect(),
                dismissed_suggestions: Vec::new(),
                custom_pending_suggestion: None,
                chats: Vec::new(),
                users: Vec::new(),
            })
            .store(&mut out);
            out
        }

        fn promo_empty_answer() -> Vec<u8> {
            let mut out = Vec::new();
            telegram_api::help_PromoData::help_promoDataEmpty(telegram_api::help_promoDataEmpty {
                expires: 1_700_003_600,
            })
            .store(&mut out);
            out
        }

        td.request(
            310,
            Function::isLoginEmailAddressRequired(td_api::isLoginEmailAddressRequired),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::help_getPromoData::ID,
        );
        net_complete(sent, promo_answer(&["SETUP_LOGIN_EMAIL"]));
        td.dispatch_completed_account_net();
        td.flush_deferred_results();
        assert!(
            responses_of(&callback, 310)
                .iter()
                .any(|object| matches!(object, Object::ok(_))),
            "the matching promo settles ok"
        );

        td.request(
            311,
            Function::isLoginEmailAddressRequired(td_api::isLoginEmailAddressRequired),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::help_getPromoData::ID,
        );
        net_complete(sent, promo_answer(&["VALIDATE_PASSWORD"]));
        td.dispatch_completed_account_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 311);
        assert_eq!(error.code, 404);
        assert_eq!(error.message, "Not Found");

        td.request(
            312,
            Function::isLoginEmailAddressRequired(td_api::isLoginEmailAddressRequired),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::help_getPromoData::ID,
        );
        net_complete(sent, promo_empty_answer());
        td.dispatch_completed_account_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 312);
        assert_eq!(error.code, 404);
        assert_eq!(error.message, "Not Found");

        td.request(
            313,
            Function::isLoginEmailAddressRequired(td_api::isLoginEmailAddressRequired),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::help_getPromoData::ID,
        );
        net_fail(sent, 420, "SLOWMODE_WAIT");
        td.dispatch_completed_account_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 313);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "SLOWMODE_WAIT");

        td.request(
            314,
            Function::isLoginEmailAddressRequired(td_api::isLoginEmailAddressRequired),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::help_getPromoData::ID,
        );
        net_complete(sent, vec![0x00, 0x00, 0x00, 0x00]);
        td.dispatch_completed_account_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 314);
        assert_eq!(error.code, 500);
        assert_eq!(
            error.message,
            "Failed to parse the help.getPromoData answer"
        );
    }

    // ---- the net-drain 52 suggested-action slice (the dismiss
    // family): the hideSuggestedAction arm rides the account dispatch
    // plane (the SuggestedAction.cpp free ladder + the manager flow, the
    // DismissSuggestionQuery handler half). ----

    /// The net-drain 52 dismiss round-trips — the §3.9 family rides the
    /// dispatcher through the [`AccountEnv`] send arm
    /// (DismissSuggestionQuery, SuggestedActionManager.cpp:26-63): the
    /// live `hideSuggestedAction` arm through the free ladder
    /// (SuggestedAction.cpp:312-355) into the manager flow (cpp:156-193)
    /// and the wire query — the wire form (inputPeerEmpty + the action
    /// string), the head-only send + fan-out, the ladder bands, the
    /// error forward, the dialog-access band — and the Bool answer
    /// settling the deferred ok with the reload tail (cpp:195-220); the
    /// premium dismiss-park flip (the assignStoreTransaction trio,
    /// Premium.cpp:1454-1465).
    #[test]
    fn suggested_action_dismiss_bands_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(suggested_action_dismiss_bands_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn suggested_action_dismiss_bands_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-suggested-actions-dismiss");

        // Load the persistent actions through the real manager intake
        // (the dismiss entry sends only for present actions) — the env
        // exactly as the production call sites build it (the take-out
        // convention).
        fn load_actions(td: &mut Td, strs: &[&str]) {
            let mut manager = std::mem::take(&mut td.suggested_action_manager);
            let net = td.account_net();
            let mut env = AccountEnv {
                global: &mut td.global,
                options: td.option_manager.as_mut(),
                user_manager: &mut td.user_manager,
                chat_manager: &mut td.chat_manager,
                device_token_manager: &mut td.device_token_manager,
                auth_is_bot: td.auth_manager.is_bot(),
                updates: &mut td.account_updates,
                net,
            };
            manager.update_suggested_actions(
                &mut env,
                strs.iter()
                    .map(|str| crate::suggested_action::SuggestedAction::from_action_str(str))
                    .collect(),
            );
            td.suggested_action_manager = manager;
        }

        fn dismiss_wire(query: &NetQuery) -> telegram_api::help_dismissSuggestion {
            telegram_api::help_dismissSuggestion::parse(query.query()).unwrap()
        }

        // 1. The live hideSuggestedAction arm — the loaded action rides
        //    the free ladder into the manager flow (Requests.cpp:8144-
        //    8148 → SuggestedAction.cpp:312-355 → 156-193): the wire form
        //    carries inputPeerEmpty + the action string; boolTrue settles
        //    the deferred ok (cpp:48-55), the removal update emits and the
        //    no-dialog ok branch runs the reload tail (cpp:216) — the
        //    follow-up help.getAppConfig dispatches.
        {
            load_actions(&mut td, &["PREMIUM_UPGRADE"]);
            td.request(
                301,
                Function::hideSuggestedAction(td_api::hideSuggestedAction {
                    action: Some(td_api::SuggestedAction::suggestedActionUpgradePremium(
                        td_api::suggestedActionUpgradePremium,
                    )),
                }),
            );
            let sent = take_sent(
                std::mem::take(&mut *rec.sent.lock()),
                telegram_api::help_dismissSuggestion::ID,
            );
            let wire = dismiss_wire(&sent);
            assert!(matches!(
                wire.peer.as_ref().map(|peer| peer.as_ref()),
                Some(telegram_api::InputPeer::inputPeerEmpty(_))
            ));
            assert_eq!(wire.suggestion, "PREMIUM_UPGRADE");
            net_complete(sent, bool_answer(true));
            td.dispatch_completed_account_net();
            td.flush_deferred_results();
            assert!(
                responses_of(&callback, 301)
                    .iter()
                    .any(|object| matches!(object, Object::ok(_))),
                "the dismiss settles ok"
            );
            let removed = td
                .account_updates
                .iter()
                .filter(|update| matches!(update, td_api::Update::updateSuggestedActions(_)))
                .count();
            assert_eq!(removed, 2, "the intake load + the removal update");
            // cpp:216 — the reload tail: the follow-up app-config query
            // dispatches (the in-flight coalescing keeps it at one).
            let config_queries = std::mem::take(&mut *rec.sent.lock())
                .into_iter()
                .filter(|query| query.tl_constructor() == telegram_api::help_getAppConfig::ID)
                .count();
            assert_eq!(config_queries, 1, "the reload tail dispatches");
        }

        // 2. The fan-out band — a second dismiss of the same in-flight
        //    action parks without a second query (cpp:185-192); one
        //    answer settles both promises.
        {
            load_actions(&mut td, &["PREMIUM_RESTORE"]);
            td.request(
                302,
                Function::hideSuggestedAction(td_api::hideSuggestedAction {
                    action: Some(td_api::SuggestedAction::suggestedActionRestorePremium(
                        td_api::suggestedActionRestorePremium,
                    )),
                }),
            );
            td.request(
                303,
                Function::hideSuggestedAction(td_api::hideSuggestedAction {
                    action: Some(td_api::SuggestedAction::suggestedActionRestorePremium(
                        td_api::suggestedActionRestorePremium,
                    )),
                }),
            );
            let dismissals = std::mem::take(&mut *rec.sent.lock())
                .into_iter()
                .filter(|query| query.tl_constructor() == telegram_api::help_dismissSuggestion::ID)
                .collect::<Vec<_>>();
            assert_eq!(dismissals.len(), 1, "the head-only send");
            net_complete(dismissals.into_iter().next().unwrap(), bool_answer(true));
            td.dispatch_completed_account_net();
            td.flush_deferred_results();
            for id in [302, 303] {
                assert!(
                    responses_of(&callback, id)
                        .iter()
                        .any(|object| matches!(object, Object::ok(_))),
                    "the fan-out settles {id}"
                );
            }
            let _ = std::mem::take(&mut *rec.sent.lock());
        }

        // 3. The absent-action band — a dismiss of an action the manager
        //    does not hold settles ok inline with no wire query
        //    (cpp:179-181).
        {
            td.request(
                304,
                Function::hideSuggestedAction(td_api::hideSuggestedAction {
                    action: Some(td_api::SuggestedAction::suggestedActionCheckPhoneNumber(
                        td_api::suggestedActionCheckPhoneNumber,
                    )),
                }),
            );
            td.flush_deferred_results();
            assert!(
                responses_of(&callback, 304)
                    .iter()
                    .any(|object| matches!(object, Object::ok(_))),
                "the absent action settles ok"
            );
            let sent = std::mem::take(&mut *rec.sent.lock());
            assert!(sent.is_empty(), "no wire query for an absent action");
        }

        // 4. The ladder bands through the live arm — the noskip 400
        //    (SuggestedAction.cpp:317-318), the invalid delay 400
        //    (cpp:333-334) and the matching-days ok band (cpp:339-346:
        //    the removal update + the cleared option, no wire query).
        {
            td.request(
                305,
                Function::hideSuggestedAction(td_api::hideSuggestedAction {
                    action: Some(
                        td_api::SuggestedAction::suggestedActionSetLoginEmailAddress(
                            td_api::suggestedActionSetLoginEmailAddress {
                                can_be_hidden: false,
                            },
                        ),
                    ),
                }),
            );
            td.flush_deferred_results();
            let error = error_of(&callback, 305);
            assert_eq!(error.code, 400);
            assert_eq!(error.message, "The action can't be hidden");

            td.request(
                306,
                Function::hideSuggestedAction(td_api::hideSuggestedAction {
                    action: Some(td_api::SuggestedAction::suggestedActionSetPassword(
                        td_api::suggestedActionSetPassword {
                            authorization_delay: -1,
                        },
                    )),
                }),
            );
            td.flush_deferred_results();
            let error = error_of(&callback, 306);
            assert_eq!(error.code, 400);
            assert_eq!(error.message, "Invalid authorization_delay specified");

            if let Some(options) = td.option_manager.as_mut() {
                options.set_option_integer("otherwise_relogin_days", 7);
            }
            let updates_before = td
                .account_updates
                .iter()
                .filter(|update| matches!(update, td_api::Update::updateSuggestedActions(_)))
                .count();
            td.request(
                307,
                Function::hideSuggestedAction(td_api::hideSuggestedAction {
                    action: Some(td_api::SuggestedAction::suggestedActionSetPassword(
                        td_api::suggestedActionSetPassword {
                            authorization_delay: 7,
                        },
                    )),
                }),
            );
            td.flush_deferred_results();
            assert!(
                responses_of(&callback, 307)
                    .iter()
                    .any(|object| matches!(object, Object::ok(_))),
                "the days band settles ok"
            );
            let updates_after = td
                .account_updates
                .iter()
                .filter(|update| matches!(update, td_api::Update::updateSuggestedActions(_)))
                .count();
            assert_eq!(updates_after, updates_before + 1, "the removal update");
            assert_eq!(
                td.option_manager
                    .as_ref()
                    .map(|options| options.get_option_integer("otherwise_relogin_days", 0)),
                Some(0),
                "the option cleared"
            );
            let sent = std::mem::take(&mut *rec.sent.lock());
            assert!(sent.is_empty(), "the days band sends nothing");
        }

        // 5. The error band — the wire error forwards to the deferred
        //    promise (cpp:57-62 → 206-208).
        {
            load_actions(&mut td, &["BIRTHDAY_SETUP"]);
            td.request(
                308,
                Function::hideSuggestedAction(td_api::hideSuggestedAction {
                    action: Some(td_api::SuggestedAction::suggestedActionSetBirthdate(
                        td_api::suggestedActionSetBirthdate,
                    )),
                }),
            );
            let sent = take_sent(
                std::mem::take(&mut *rec.sent.lock()),
                telegram_api::help_dismissSuggestion::ID,
            );
            net_fail(sent, 400, "SUGGESTION_INVALID");
            td.dispatch_completed_account_net();
            td.flush_deferred_results();
            let error = error_of(&callback, 308);
            assert_eq!(error.code, 400);
            assert_eq!(error.message, "SUGGESTION_INVALID");
        }

        // 6. The dialog-form band — the unregistered channel fails the
        //    access gate before any dispatch (cpp:163-165).
        {
            td.request(
                309,
                Function::hideSuggestedAction(td_api::hideSuggestedAction {
                    action: Some(
                        td_api::SuggestedAction::suggestedActionConvertToBroadcastGroup(
                            td_api::suggestedActionConvertToBroadcastGroup {
                                supergroup_id: 1099,
                            },
                        ),
                    ),
                }),
            );
            td.flush_deferred_results();
            let error = error_of(&callback, 309);
            assert_eq!(error.code, 400);
            assert_eq!(error.message, "Chat not found");
            let sent = std::mem::take(&mut *rec.sent.lock());
            assert!(sent.is_empty());
        }

        // 8. The premium dismiss-park flip (§6) — the
        //    assignStoreTransaction PremiumSubscription purpose dismisses
        //    the three suggested actions (Premium.cpp:1454-1456): with the
        //    actions loaded the trio rides the wire (the §6 parks flip),
        //    the answers drain through the account plane and the reload
        //    tail parks behind the in-flight app-config query (the
        //    coalescing).
        {
            load_actions(
                &mut td,
                &["PREMIUM_UPGRADE", "PREMIUM_ANNUAL", "PREMIUM_RESTORE"],
            );
            let (promise, slot) = record_translation_unit();
            with_premium_manager(&mut td, |manager, env| {
                manager.assign_store_transaction(
                    env,
                    Some(td_api::StoreTransaction::storeTransactionGooglePlay(
                        td_api::storeTransactionGooglePlay {
                            package_name: "org.telegram.plus".to_string(),
                            store_product_id: "product/12".to_string(),
                            purchase_token: "tok".to_string(),
                        },
                    )),
                    Some(
                        td_api::StorePaymentPurpose::storePaymentPurposePremiumSubscription(
                            td_api::storePaymentPurposePremiumSubscription {
                                is_restore: true,
                                is_upgrade: false,
                            },
                        ),
                    ),
                    promise,
                );
            });
            let sent = std::mem::take(&mut *rec.sent.lock());
            let mut dismiss_queries = Vec::new();
            let mut rest = Vec::new();
            for query in sent {
                if query.tl_constructor() == telegram_api::help_dismissSuggestion::ID {
                    dismiss_queries.push(query);
                } else {
                    rest.push(query);
                }
            }
            let dismissals = dismiss_queries
                .iter()
                .map(dismiss_wire)
                .map(|wire| wire.suggestion.clone())
                .collect::<Vec<_>>();
            assert_eq!(
                dismissals,
                ["PREMIUM_UPGRADE", "PREMIUM_ANNUAL", "PREMIUM_RESTORE"],
                "the §6 trio rides the wire"
            );
            let assign_query = rest
                .into_iter()
                .find(|query| {
                    query.tl_constructor() == telegram_api::payments_assignPlayMarketTransaction::ID
                })
                .expect("the assign query dispatches");
            let mut answer = Vec::new();
            telegram_api::Updates::updates(telegram_api::updates {
                updates: Vec::new(),
                users: Vec::new(),
                chats: Vec::new(),
                date: 0,
                seq: 0,
            })
            .store(&mut answer);
            net_complete(assign_query, answer);
            td.dispatch_completed_premium_net();
            assert!(matches!(
                slot.lock().unwrap().take(),
                Some(tdutils::status::Result::Ok(()))
            ));
            // the trio's Bool answers drain through the account plane:
            // the lots pop, the promise-less internal dismisses settle,
            // and each no-dialog ok branch queues an app-config reload —
            // all coalesced behind the in-flight query from case 1 (no
            // new dispatch).
            for query in dismiss_queries {
                net_complete(query, bool_answer(true));
                td.dispatch_completed_account_net();
            }
            assert!(
                td.suggested_action_manager
                    .dismiss_suggested_action_queries
                    .is_empty(),
                "the dismisses drain"
            );
            let config_queries = std::mem::take(&mut *rec.sent.lock())
                .into_iter()
                .filter(|query| query.tl_constructor() == telegram_api::help_getAppConfig::ID)
                .count();
            assert_eq!(
                config_queries, 0,
                "the reloads coalesce behind the in-flight config"
            );
        }

        assert!(td.account_net_completed.lock().is_empty(), "drained");
    }

    fn terms_of_service_families_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-terms");

        // The env exactly as the production call sites build it —
        // expanded at the call site so the field borrows stay disjoint.
        macro_rules! terms_env {
            () => {{
                let net = td.account_net();
                AccountEnv {
                    global: &mut td.global,
                    options: td.option_manager.as_mut(),
                    user_manager: &mut td.user_manager,
                    chat_manager: &mut td.chat_manager,
                    device_token_manager: &mut td.device_token_manager,
                    auth_is_bot: td.auth_manager.is_bot(),
                    updates: &mut td.account_updates,
                    net,
                }
            }};
        }

        fn terms_answer(expires: i32, id: &str, text: &str) -> Vec<u8> {
            let mut out = Vec::new();
            telegram_api::help_termsOfServiceUpdate {
                expires,
                terms_of_service: Some(telegram_api::help_TermsOfService {
                    // bit 1 — min_age_confirm rides the wire
                    flags: 1 << 1,
                    popup: true,
                    id: Some(telegram_api::DataJSON {
                        data: id.to_owned(),
                    }),
                    text: text.to_owned(),
                    entities: Vec::new(),
                    min_age_confirm: 16,
                }),
            }
            .store_boxed(&mut out);
            out
        }

        fn empty_terms_answer(expires: i32) -> Vec<u8> {
            let mut out = Vec::new();
            telegram_api::help_termsOfServiceUpdateEmpty { expires }.store_boxed(&mut out);
            out
        }

        fn count_terms_updates(td: &Td) -> usize {
            td.account_updates
                .iter()
                .filter(|update| matches!(update, td_api::Update::updateTermsOfService(_)))
                .count()
        }

        fn account_terms_update(td: &Td) -> Option<&td_api::updateTermsOfService> {
            td.account_updates.iter().find_map(|update| match update {
                td_api::Update::updateTermsOfService(update) => Some(update),
                _ => None,
            })
        }

        // 1. The auth-success poll — help.getTermsOfServiceUpdate
        //    dispatches once (the is_inited_ gate, cpp:105-115); the
        //    answer converts the Empty/Update halves (cpp:36-57) and
        //    routes on_get_terms_of_service (cpp:145-167) — the update
        //    carries the full terms object (cpp:136-143).
        {
            let mut env = terms_env!();
            td.terms_of_service_manager.init(&mut env);
            let mut env = terms_env!();
            td.terms_of_service_manager.init(&mut env);
            let sent = std::mem::take(&mut *rec.sent.lock());
            assert_eq!(sent.len(), 1);
            assert_eq!(
                sent[0].tl_constructor(),
                telegram_api::help_getTermsOfServiceUpdate::ID
            );
            net_complete(
                sent.into_iter().next().unwrap(),
                terms_answer(1_700_003_600, "tos-1", "Please accept"),
            );
            td.dispatch_completed_account_net();
            let update = account_terms_update(&td).expect("the terms update emits");
            assert_eq!(update.terms_of_service_id, "tos-1");
            let terms = update.terms_of_service.as_ref().unwrap();
            assert_eq!(terms.min_user_age, 16);
            assert!(terms.show_popup);
            assert_eq!(terms.text.as_ref().unwrap().text, "Please accept");
        }

        // 2. acceptTermsOfService through the live td_api arm — the
        //    dataJSON wire form (cpp:71-74); boolTrue settles ok
        //    (cpp:76-87), the pending clears with no update on the
        //    accept itself (cpp:184-188), and the schedule(0) re-poll
        //    dispatches again (the collapsed timer) — the empty-update
        //    re-poll answer keeps the pending clear.
        {
            let updates_before = count_terms_updates(&td);
            td.request(
                201,
                Function::acceptTermsOfService(td_api::acceptTermsOfService {
                    terms_of_service_id: "tos-1".to_owned(),
                }),
            );
            let sent = std::mem::take(&mut *rec.sent.lock());
            assert_eq!(sent.len(), 1);
            assert_eq!(
                sent[0].tl_constructor(),
                telegram_api::help_acceptTermsOfService::ID
            );
            let wire = telegram_api::help_acceptTermsOfService::parse(sent[0].query()).unwrap();
            assert_eq!(wire.id.unwrap().data, "tos-1");
            net_complete(sent.into_iter().next().unwrap(), bool_answer(true));
            td.dispatch_completed_account_net();
            td.flush_deferred_results();
            assert!(
                responses_of(&callback, 201)
                    .iter()
                    .any(|object| matches!(object, Object::ok(_))),
                "the accept settles ok"
            );
            assert_eq!(
                count_terms_updates(&td),
                updates_before,
                "the accept itself emits no update"
            );
            let sent = std::mem::take(&mut *rec.sent.lock());
            assert_eq!(sent.len(), 1);
            assert_eq!(
                sent[0].tl_constructor(),
                telegram_api::help_getTermsOfServiceUpdate::ID
            );
            net_complete(
                sent.into_iter().next().unwrap(),
                empty_terms_answer(1_700_003_600),
            );
            td.dispatch_completed_account_net();
            assert_eq!(
                count_terms_updates(&td),
                updates_before,
                "the empty re-poll answer emits nothing"
            );
        }

        // 3. The false-Bool band — the LOG(ERROR) leg still settles ok
        //    (cpp:80-87); the re-poll's terms answer re-emits the update
        //    even though the id is unchanged (cpp:157-161 — the
        //    reference sends on every non-empty poll, no id compare).
        {
            td.request(
                202,
                Function::acceptTermsOfService(td_api::acceptTermsOfService {
                    terms_of_service_id: "tos-1".to_owned(),
                }),
            );
            let sent = std::mem::take(&mut *rec.sent.lock());
            net_complete(sent.into_iter().next().unwrap(), bool_answer(false));
            td.dispatch_completed_account_net();
            td.flush_deferred_results();
            assert!(
                responses_of(&callback, 202)
                    .iter()
                    .any(|object| matches!(object, Object::ok(_))),
                "the false Bool still settles ok"
            );
            let sent = std::mem::take(&mut *rec.sent.lock());
            assert_eq!(sent.len(), 1);
            net_complete(
                sent.into_iter().next().unwrap(),
                terms_answer(1_700_003_600, "tos-1", "Please accept"),
            );
            td.dispatch_completed_account_net();
            assert_eq!(
                count_terms_updates(&td),
                2,
                "the re-poll answer re-emits the update"
            );
        }

        // 4. The error forward (cpp:89-91 → 176-178) and the
        //    parse-failure 500 band.
        {
            td.request(
                203,
                Function::acceptTermsOfService(td_api::acceptTermsOfService {
                    terms_of_service_id: "tos-1".to_owned(),
                }),
            );
            let sent = std::mem::take(&mut *rec.sent.lock());
            net_fail(
                sent.into_iter().next().unwrap(),
                400,
                "TERMS_OF_SERVICE_INVALID",
            );
            td.dispatch_completed_account_net();
            td.flush_deferred_results();
            let error = error_of(&callback, 203);
            assert_eq!(error.code, 400);
            assert_eq!(error.message, "TERMS_OF_SERVICE_INVALID");

            td.request(
                204,
                Function::acceptTermsOfService(td_api::acceptTermsOfService {
                    terms_of_service_id: "tos-1".to_owned(),
                }),
            );
            let sent = std::mem::take(&mut *rec.sent.lock());
            net_complete(
                sent.into_iter().next().unwrap(),
                vec![0x00, 0x00, 0x00, 0x00],
            );
            td.dispatch_completed_account_net();
            td.flush_deferred_results();
            let error = error_of(&callback, 204);
            assert_eq!(error.code, 500);
            assert_eq!(
                error.message,
                "Failed to parse the help.acceptTermsOfService answer"
            );
        }

        // 5. The poll error band — the failed answer routes the error
        //    half of on_get_terms_of_service (logged + dropped; the C++
        //    reschedules at Random::fast(10, 60), the collapsed timer
        //    plane; cpp:59-61 → 151-153).
        {
            let updates_before = count_terms_updates(&td);
            td.request(
                205,
                Function::acceptTermsOfService(td_api::acceptTermsOfService {
                    terms_of_service_id: "tos-1".to_owned(),
                }),
            );
            let sent = std::mem::take(&mut *rec.sent.lock());
            net_complete(sent.into_iter().next().unwrap(), bool_answer(true));
            td.dispatch_completed_account_net();
            let sent = std::mem::take(&mut *rec.sent.lock());
            assert_eq!(sent.len(), 1);
            net_fail(sent.into_iter().next().unwrap(), 500, "FLOOD_WAIT");
            td.dispatch_completed_account_net();
            assert_eq!(
                count_terms_updates(&td),
                updates_before,
                "the failed poll emits nothing"
            );
        }

        assert!(td.account_net_completed.lock().is_empty(), "drained");
    }

    // ---- the star net slice: the option/subscription/revenue families
    // ride the dispatcher and their answers drain through the real Td
    // routing (the StarManager.cpp handler halves). ----

    /// The production-shaped star split for the tests (the take-out
    /// convention).
    fn with_star_manager(
        td: &mut Td,
        f: impl FnOnce(&mut crate::star_manager::StarManager, &mut TdStarEnv<'_>),
    ) {
        let (mut manager, mut env) = crate::td::star_env_split(td);
        f(&mut manager, &mut env);
        td.star_manager = manager;
    }

    type StarOptionsSlot = std::sync::Arc<
        std::sync::Mutex<Option<tdutils::status::Result<td_api::StarPaymentOptions>>>,
    >;

    fn record_star_options() -> (Promise<td_api::StarPaymentOptions>, StarOptionsSlot) {
        struct Rec(StarOptionsSlot);
        impl tdutils::promise::PromiseInterface<td_api::StarPaymentOptions> for Rec {
            fn set_value(&mut self, value: td_api::StarPaymentOptions) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
            }
            fn set_error(&mut self, error: Status) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
            }
        }
        let slot: StarOptionsSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
        (Promise::from_interface(Rec(slot.clone())), slot)
    }

    type StarSubscriptionsSlot = std::sync::Arc<
        std::sync::Mutex<Option<tdutils::status::Result<td_api::StarSubscriptions>>>,
    >;

    fn record_star_subscriptions() -> (Promise<td_api::StarSubscriptions>, StarSubscriptionsSlot) {
        struct Rec(StarSubscriptionsSlot);
        impl tdutils::promise::PromiseInterface<td_api::StarSubscriptions> for Rec {
            fn set_value(&mut self, value: td_api::StarSubscriptions) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
            }
            fn set_error(&mut self, error: Status) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
            }
        }
        let slot: StarSubscriptionsSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
        (Promise::from_interface(Rec(slot.clone())), slot)
    }

    type UrlSlot = std::sync::Arc<std::sync::Mutex<Option<tdutils::status::Result<String>>>>;

    fn record_star_url() -> (Promise<String>, UrlSlot) {
        struct Rec(UrlSlot);
        impl tdutils::promise::PromiseInterface<String> for Rec {
            fn set_value(&mut self, value: String) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
            }
            fn set_error(&mut self, error: Status) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
            }
        }
        let slot: UrlSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
        (Promise::from_interface(Rec(slot.clone())), slot)
    }

    /// The net-drain 41 forum-topic round-trips — the send families'
    /// legs dispatch through the installed handle and the wire answers
    /// settle the parked promises (the band ladders live in
    /// `forum_topic_manager.rs`; these cover the dispatcher plumbing, the
    /// updates-walk tails and the read conversions).
    #[test]
    fn forum_topic_families_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(forum_topic_families_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    /// The net-drain 46 web-page round-trips — the GetWebPageQuery
    /// family's send legs dispatch through the installed handle (the
    /// by-URL reloads and the instant-view heads) and the wire answers
    /// settle the parked promise tails (the band ladders live in
    /// `web_pages_manager.rs`; these cover the dispatcher plumbing, the
    /// ladder continuations and the null-object 404 rewrite).
    #[test]
    fn web_page_families_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(web_page_families_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn web_page_families_ride_the_dispatcher_impl() {
        use crate::web_pages_manager::{WebPageIdTail, WebPageInstantView, WebPagesManager};
        use crate::webpage::WebPageId;

        let (mut td, rec, callback) = netted_td_with_callback("netfix-web-pages");

        /// A wire `webPage` answer body (no cached_page — the instant
        /// view content plane rides the M.17 seam).
        fn wire_page(id: i64, url: &str) -> telegram_api::WebPage {
            telegram_api::WebPage::webPage(telegram_api::webPage {
                id,
                flags: 0,
                url: url.to_owned(),
                display_url: url.to_owned(),
                hash: 0,
                r#type: "article".to_owned(),
                site_name: String::new(),
                title: "Title".to_owned(),
                description: String::new(),
                photo: None,
                embed_url: String::new(),
                embed_type: String::new(),
                embed_width: 0,
                embed_height: 0,
                duration: 0,
                author: String::new(),
                document: None,
                cached_page: None,
                attributes: Vec::new(),
                has_large_media: false,
                video_cover_photo: false,
            })
        }

        /// The `messages.webPage` answer envelope.
        fn web_page_answer(page: telegram_api::WebPage, users: Vec<telegram_api::User>) -> Vec<u8> {
            let mut out = Vec::new();
            out.extend_from_slice(&telegram_api::messages_WebPage::ID.to_le_bytes());
            telegram_api::messages_WebPage {
                webpage: Some(Box::new(page)),
                chats: Vec::new(),
                users,
            }
            .store(&mut out);
            out
        }

        /// The `webPageNotModified` answer envelope.
        fn not_modified_answer(cached_page_views: i32) -> Vec<u8> {
            let mut out = Vec::new();
            out.extend_from_slice(&telegram_api::messages_WebPage::ID.to_le_bytes());
            telegram_api::messages_WebPage {
                webpage: Some(Box::new(telegram_api::WebPage::webPageNotModified(
                    telegram_api::webPageNotModified {
                        flags: 1, // CACHED_PAGE_VIEWS
                        cached_page_views,
                    },
                ))),
                chats: Vec::new(),
                users: Vec::new(),
            }
            .store(&mut out);
            out
        }

        /// Seed a cached page with a loaded instant view (the
        /// instant-view reload head's precondition, cpp:1331-1332).
        fn seed_page_with_instant_view(td: &mut Td, id: i64, url: &str, hash: i32, is_full: bool) {
            let (mut env, manager) = crate::td::web_pages_env_split(td);
            let web_page_id = WebPageId::new(id);
            manager
                .url_to_web_page_id
                .insert(url.to_owned(), (web_page_id, false));
            manager.web_pages.insert(
                web_page_id,
                crate::web_pages_manager::WebPage {
                    url: url.to_owned(),
                    display_url: url.to_owned(),
                    type_: "article".to_owned(),
                    title: "Title".to_owned(),
                    ..crate::web_pages_manager::WebPage::default()
                },
            );
            if let Some(page) = manager.web_pages.get_mut(&web_page_id) {
                page.instant_view = WebPageInstantView {
                    hash,
                    is_full,
                    is_loaded: true,
                    is_empty: false,
                    ..WebPageInstantView::default()
                };
            }
            let _ = &mut env;
        }

        // 1. getWebPageInstantView over the live td_api arm — the cold
        //    URL reload sends messages.getWebPage(url, 0); the full-page
        //    answer lands the record + the url map, and the empty
        //    instant view settles the actor tail through the null-object
        //    rewrite (404 "Not Found", Td.cpp:1405-1409).
        {
            td.request(
                1,
                Function::getWebPageInstantView(td_api::getWebPageInstantView {
                    url: "https://example.com/page".to_owned(),
                    only_local: false,
                }),
            );
            let sent = take_sent_query(&rec, telegram_api::messages_getWebPage::ID);
            let body = telegram_api::messages_getWebPage::parse(sent.query()).expect("the body");
            assert_eq!(body.url, "https://example.com/page");
            assert_eq!(body.hash, 0, "the cold by-URL hash");
            net_complete(
                sent,
                web_page_answer(wire_page(5, "https://example.com/page"), Vec::new()),
            );
            td.dispatch_completed_web_pages_net();
            td.flush_deferred_results();
            let error = error_of(&callback, 1);
            assert_eq!((error.code, error.message.as_str()), (404, "Not Found"));
            // the landed record: the second, only-local request answers
            // from the negative-cache ladder without any new query
            td.request(
                2,
                Function::getWebPageInstantView(td_api::getWebPageInstantView {
                    url: "https://example.com/page".to_owned(),
                    only_local: true,
                }),
            );
            td.flush_deferred_results();
            let error = error_of(&callback, 2);
            assert_eq!((error.code, error.message.as_str()), (404, "Not Found"));
            assert!(
                rec.sent.lock().is_empty(),
                "the cached-url request dispatches nothing"
            );
        }

        // 2. the wire error band — the by-URL send's error rides to the
        //    request answer (the GetWebPageQuery::on_error half,
        //    cpp:162-165).
        {
            td.request(
                3,
                Function::getWebPageInstantView(td_api::getWebPageInstantView {
                    url: "https://example.com/gone".to_owned(),
                    only_local: false,
                }),
            );
            let sent = take_sent_query(&rec, telegram_api::messages_getWebPage::ID);
            net_fail(sent, 400, "WEBPAGE_NOT_EXIST");
            td.dispatch_completed_web_pages_net();
            td.flush_deferred_results();
            let error = error_of(&callback, 3);
            assert_eq!(
                (error.code, error.message.as_str()),
                (400, "WEBPAGE_NOT_EXIST")
            );
        }

        // 3. the instant-view reload head — the cached page re-requests
        //    with is_full ? hash : 0 (cpp:1329-1330); the
        //    webPageNotModified answer runs the view-count intake
        //    (cpp:141-146) and settles the parked actor tail with the
        //    captured id, which builds the instant-view object.
        {
            seed_page_with_instant_view(&mut td, 7, "https://example.com/iv", 42, true);
            td.request(
                4,
                Function::getWebPageInstantView(td_api::getWebPageInstantView {
                    url: "https://example.com/iv".to_owned(),
                    only_local: false,
                }),
            );
            let sent = take_sent_query(&rec, telegram_api::messages_getWebPage::ID);
            let body = telegram_api::messages_getWebPage::parse(sent.query()).expect("the body");
            assert_eq!(body.hash, 42, "the is_full hash re-request");
            net_complete(sent, not_modified_answer(99));
            td.dispatch_completed_web_pages_net();
            td.flush_deferred_results();
            let responses = responses_of(&callback, 4);
            assert_eq!(responses.len(), 1, "the not-modified settle");
            let Object::webPageInstantView(object) = &responses[0] else {
                panic!("the instant-view object answer: {:?}", responses[0]);
            };
            assert_eq!(object.view_count, 99, "the view-count intake");
            // the view count persisted on the record
            let (_, manager) = crate::td::web_pages_env_split(&mut td);
            assert_eq!(
                manager
                    .web_pages
                    .get(&WebPageId::new(7))
                    .expect("the cached page")
                    .instant_view
                    .view_count,
                99
            );
        }

        // 4. the server-lot error band — the reload head's error fails
        //    every parked tail of the lot (cpp:1439-1441).
        {
            seed_page_with_instant_view(&mut td, 8, "https://example.com/iv-err", 0, false);
            td.request(
                5,
                Function::getWebPageInstantView(td_api::getWebPageInstantView {
                    url: "https://example.com/iv-err".to_owned(),
                    only_local: false,
                }),
            );
            let sent = take_sent_query(&rec, telegram_api::messages_getWebPage::ID);
            let body = telegram_api::messages_getWebPage::parse(sent.query()).expect("the body");
            assert_eq!(body.hash, 0, "the !is_full hash re-request");
            net_fail(sent, 500, "Internal Server Error");
            td.dispatch_completed_web_pages_net();
            td.flush_deferred_results();
            let error = error_of(&callback, 5);
            assert_eq!(
                (error.code, error.message.as_str()),
                (500, "Internal Server Error")
            );
        }

        // 5. the webPagePending band — the pending page arms the
        //    timeout (the re-fetch keeps the URL) and the ladder
        //    settles the empty-instant-view 404 (cpp:630-641).
        {
            td.request(
                6,
                Function::getWebPageInstantView(td_api::getWebPageInstantView {
                    url: "https://example.com/pending".to_owned(),
                    only_local: false,
                }),
            );
            let sent = take_sent_query(&rec, telegram_api::messages_getWebPage::ID);
            net_complete(
                sent,
                web_page_answer(
                    telegram_api::WebPage::webPagePending(telegram_api::webPagePending {
                        flags: 1, // URL
                        id: 9,
                        date: 100,
                        url: "https://example.com/pending".to_owned(),
                    }),
                    Vec::new(),
                ),
            );
            td.dispatch_completed_web_pages_net();
            td.flush_deferred_results();
            let error = error_of(&callback, 6);
            assert_eq!((error.code, error.message.as_str()), (404, "Not Found"));
            assert!(
                td.web_pages_timeouts.contains_key(&9),
                "the pending-page timeout armed"
            );
            assert_eq!(
                td.web_pages_manager
                    .pending_web_page_urls
                    .get(&WebPageId::new(9))
                    .map(String::as_str),
                Some("https://example.com/pending")
            );
        }

        // 6. the loaded-instant-view only_local band — the cached answer
        //    settles without any query (cpp:1297-1299).
        {
            td.request(
                7,
                Function::getWebPageInstantView(td_api::getWebPageInstantView {
                    url: "https://example.com/iv".to_owned(),
                    only_local: true,
                }),
            );
            td.flush_deferred_results();
            let responses = responses_of(&callback, 7);
            assert_eq!(responses.len(), 1, "the only-local settle");
            assert!(
                rec.sent.lock().is_empty(),
                "the loaded-instant-view only-local request dispatches nothing"
            );
        }

        // 7. the net-inert posture — the plain WebPageId tail parks in
        //    the family lot when the handle is absent (the None arm
        //    logs net-inert, §0.2).
        {
            td.web_pages_manager.net = None;
            let slot: std::sync::Arc<std::sync::Mutex<Option<tdutils::status::Result<WebPageId>>>> =
                std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            let (mut env, manager) = crate::td::web_pages_env_split(&mut td);
            WebPagesManager::fetch_web_page_by_url(
                manager,
                &mut env,
                "https://example.com/inert",
                WebPageIdTail::Promise { promise },
            );
            assert!(
                slot.lock().unwrap().is_none(),
                "the net-inert send parks the tail"
            );
            let (_, manager) = crate::td::web_pages_env_split(&mut td);
            assert_eq!(manager.pending_web_page_queries.len(), 1);
        }
    }

    fn forum_topic_families_ride_the_dispatcher_impl() {
        use crate::forum_topic_manager::ForumTopicManager;

        let (mut td, rec) = netted_td("netfix-forum-topics");
        seed_my_user(&mut td); // my id 42 — the create-topic creator id
        // the creator forum megagroup (the permission reads + the Write
        // peer resolve off the record)
        seed_dialog_channel_with_flags(&mut td, 703, true, true, true);
        let dialog = crate::dialog_id::DialogId::new(-1_000_000_000_703);

        fn unit_slot() -> (tdutils::promise::Promise<()>, UnitSlot) {
            let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            (promise, slot)
        }

        /// The CreateForumTopicQuery answer — the service message found
        /// by its random id (cpp:104-125).
        fn create_topic_answer(random_id: i64, channel_id: i64, topic_id: i32) -> Vec<u8> {
            let service = telegram_api::Message::messageService(telegram_api::messageService {
                flags: 0,
                out: true,
                mentioned: false,
                media_unread: false,
                reactions_are_possible: false,
                silent: false,
                post: false,
                legacy: false,
                id: topic_id,
                from_id: Some(telegram_api::Peer::peerUser(telegram_api::peerUser {
                    user_id: 42,
                })),
                peer_id: Some(telegram_api::Peer::peerChannel(telegram_api::peerChannel {
                    channel_id,
                })),
                saved_peer_id: None,
                reply_to: None,
                date: 1700000000,
                action: Some(telegram_api::MessageAction::messageActionTopicCreate(
                    telegram_api::messageActionTopicCreate {
                        flags: 0,
                        title_missing: true,
                        title: "Hello".to_owned(),
                        icon_color: 0x7E_39C2,
                        icon_emoji_id: 0,
                    },
                )),
                reactions: None,
                ttl_period: 0,
            });
            let mut out = Vec::new();
            out.extend_from_slice(&telegram_api::updatesCombined::ID.to_le_bytes());
            telegram_api::updatesCombined {
                updates: vec![
                    telegram_api::Update::updateMessageID(telegram_api::updateMessageID {
                        id: topic_id,
                        random_id,
                    }),
                    telegram_api::Update::updateNewChannelMessage(
                        telegram_api::updateNewChannelMessage {
                            message: Some(service),
                            pts: 0,
                            pts_count: 0,
                        },
                    ),
                ],
                users: Vec::new(),
                chats: Vec::new(),
                date: 1700000000,
                seq_start: 0,
                seq: 0,
            }
            .store(&mut out);
            out
        }

        fn updates_answer() -> Vec<u8> {
            let mut answer = Vec::new();
            answer.extend_from_slice(&telegram_api::updatesCombined::ID.to_le_bytes());
            telegram_api::updatesCombined {
                updates: vec![],
                users: vec![],
                chats: vec![],
                date: 1700000000,
                seq_start: 0,
                seq: 0,
            }
            .store(&mut answer);
            answer
        }

        // 1. createForumTopic — the flags/peer/random-id wire form; the
        //    answer's service message builds the info and the updates
        //    walk completes the request promise.
        {
            let (promise, slot) = {
                type InfoSlot = std::sync::Arc<
                    std::sync::Mutex<
                        Option<tdutils::status::Result<Option<td_api::ForumTopicInfo>>>,
                    >,
                >;
                struct Rec(InfoSlot);
                impl tdutils::promise::PromiseInterface<Option<td_api::ForumTopicInfo>> for Rec {
                    fn set_value(&mut self, value: Option<td_api::ForumTopicInfo>) {
                        *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
                    }
                    fn set_error(&mut self, error: Status) {
                        *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
                    }
                }
                let slot: InfoSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
                (
                    tdutils::promise::Promise::from_interface(Rec(slot.clone())),
                    slot,
                )
            };
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            ForumTopicManager::create_forum_topic(
                manager,
                &mut env,
                dialog,
                "Hello",
                true,
                Some(td_api::ForumTopicIcon {
                    color: 0x7E_39C2,
                    custom_emoji_id: 0,
                }),
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_createForumTopic::ID);
            let body = telegram_api::messages_createForumTopic::parse(sent.query())
                .expect("the create body");
            assert_eq!(body.title, "Hello");
            assert!(body.title_missing, "the TITLE_MISSING flag");
            assert_eq!(body.flags & 1, 1, "the ICON_COLOR flag");
            assert_ne!(body.random_id, 0, "the random id");
            let peer_channel = match body.peer.as_deref() {
                Some(telegram_api::InputPeer::inputPeerChannel(p)) => Some(p.channel_id),
                _ => None,
            };
            assert_eq!(peer_channel, Some(703), "the Write peer");
            net_complete(sent, create_topic_answer(body.random_id, 703, 7));
            td.dispatch_completed_forum_topic_net();
            let info = match slot.lock().unwrap().take().unwrap() {
                tdutils::status::Result::Ok(Some(info)) => info,
                other => panic!("the create answer: {other:?}"),
            };
            assert_eq!(info.forum_topic_id, 7);
            assert_eq!(info.name, "Hello");
            assert!(info.is_outgoing, "the create-topic info is outgoing");
            assert!(info.is_name_implicit, "the TITLE_MISSING flag rides");
            assert!(manager_has_topic(&td, dialog, 7), "the registry intake");
        }

        // 2. editForumTopic — the TITLE wire form; the Updates walk
        //    settles the promise, the TOPIC_NOT_MODIFIED band settles ok.
        {
            let (promise, slot) = unit_slot();
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            ForumTopicManager::edit_forum_topic(
                manager,
                &mut env,
                dialog,
                crate::forum_topic::ForumTopicId::new(7),
                "New",
                false,
                crate::emoji_status::CustomEmojiId::default(),
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_editForumTopic::ID);
            let body =
                telegram_api::messages_editForumTopic::parse(sent.query()).expect("the edit body");
            assert_eq!(body.flags & 1, 1, "the TITLE flag");
            assert_eq!(body.topic_id, 7);
            net_complete(sent, updates_answer());
            td.dispatch_completed_forum_topic_net();
            assert!(matches!(
                &*slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));

            // the not-modified band (cpp:213-215)
            let (promise, slot) = unit_slot();
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            ForumTopicManager::edit_forum_topic(
                manager,
                &mut env,
                dialog,
                crate::forum_topic::ForumTopicId::new(7),
                "Newer",
                false,
                crate::emoji_status::CustomEmojiId::default(),
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_editForumTopic::ID);
            net_fail(sent, 400, "TOPIC_NOT_MODIFIED");
            td.dispatch_completed_forum_topic_net();
            assert!(matches!(
                &*slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // 3. toggleForumTopicIsClosed — the CLOSED wire form (cpp:169-186).
        {
            let (promise, _slot) = unit_slot();
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            ForumTopicManager::toggle_forum_topic_is_closed(
                manager,
                &mut env,
                dialog,
                crate::forum_topic::ForumTopicId::new(7),
                true,
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_editForumTopic::ID);
            let body =
                telegram_api::messages_editForumTopic::parse(sent.query()).expect("the body");
            assert_eq!(body.flags, 1 << 2, "the CLOSED flag only");
            assert!(body.closed);
        }

        // 4. toggleGeneralForumTopicIsHidden — the HIDDEN wire form over
        //    the general topic id 1 (cpp:188-205).
        {
            let (promise, _slot) = unit_slot();
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            ForumTopicManager::toggle_forum_topic_is_hidden(
                manager, &mut env, dialog, true, promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_editForumTopic::ID);
            let body =
                telegram_api::messages_editForumTopic::parse(sent.query()).expect("the body");
            assert_eq!(body.flags, 1 << 3, "the HIDDEN flag only");
            assert_eq!(body.topic_id, 1, "the general topic id");
            assert!(body.hidden);
        }

        // 5. toggleForumTopicIsPinned — messages.updatePinnedForumTopic;
        //    the PINNED_TOPIC_NOT_MODIFIED band settles ok (cpp:251-253).
        {
            let (promise, slot) = unit_slot();
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            ForumTopicManager::toggle_forum_topic_is_pinned(
                manager,
                &mut env,
                dialog,
                crate::forum_topic::ForumTopicId::new(7),
                true,
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_updatePinnedForumTopic::ID);
            let body = telegram_api::messages_updatePinnedForumTopic::parse(sent.query())
                .expect("the pin body");
            assert_eq!(body.topic_id, 7);
            assert!(body.pinned);
            net_fail(sent, 400, "PINNED_TOPIC_NOT_MODIFIED");
            td.dispatch_completed_forum_topic_net();
            assert!(matches!(
                &*slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // 6. setPinnedForumTopics — messages.reorderPinnedForumTopics
        //    with the request order (cpp:283); the not-modified band.
        {
            let (promise, slot) = unit_slot();
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            ForumTopicManager::set_pinned_forum_topics(
                manager,
                &mut env,
                dialog,
                vec![
                    crate::forum_topic::ForumTopicId::new(7),
                    crate::forum_topic::ForumTopicId::new(9),
                ],
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_reorderPinnedForumTopics::ID);
            let body = telegram_api::messages_reorderPinnedForumTopics::parse(sent.query())
                .expect("the reorder body");
            assert_eq!(body.order, vec![7, 9]);
            assert!(body.force);
            net_fail(sent, 400, "PINNED_TOPICS_NOT_MODIFIED");
            td.dispatch_completed_forum_topic_net();
            assert!(matches!(
                &*slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }
    }

    /// The net-drain 41 read families — `getForumTopic` answers the
    /// single-topic band and the null form, `getForumTopics` walks the
    /// topics with the next-offset computation.
    #[test]
    fn forum_topic_reads_round_trip() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(forum_topic_reads_round_trip_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn forum_topic_reads_round_trip_impl() {
        use crate::forum_topic_manager::ForumTopicManager;

        let (mut td, rec) = netted_td("netfix-forum-topic-reads");
        seed_dialog_channel_with_flags(&mut td, 704, true, true, true);
        let dialog = crate::dialog_id::DialogId::new(-1_000_000_000_704);

        /// A live wire forumTopic in the read answers.
        fn wire_forum_topic(id: i32, date: i32, channel_id: i64) -> telegram_api::ForumTopic {
            telegram_api::ForumTopic::forumTopic(telegram_api::forumTopic {
                flags: 0,
                my: true,
                closed: false,
                pinned: true,
                short: false,
                hidden: false,
                title_missing: false,
                id,
                date,
                peer: Some(telegram_api::Peer::peerChannel(telegram_api::peerChannel {
                    channel_id,
                })),
                title: format!("Topic {id}"),
                icon_color: 0,
                icon_emoji_id: 0,
                top_message: 0,
                read_inbox_max_id: 0,
                read_outbox_max_id: 0,
                unread_count: 0,
                unread_mentions_count: 0,
                unread_reactions_count: 0,
                unread_poll_votes_count: 0,
                from_id: Some(telegram_api::Peer::peerUser(telegram_api::peerUser {
                    user_id: 42,
                })),
                notify_settings: None,
                draft: None,
            })
        }

        fn forum_topics_answer(
            topics: Vec<telegram_api::ForumTopic>,
            count: i32,
            order_by_create_date: bool,
        ) -> Vec<u8> {
            let mut out = Vec::new();
            telegram_api::messages_ForumTopics {
                flags: 0,
                order_by_create_date,
                count,
                topics,
                messages: Vec::new(),
                chats: Vec::new(),
                users: Vec::new(),
                pts: 0,
            }
            .store_boxed(&mut out);
            out
        }

        // 1. getForumTopic — messages.getForumTopicsByID; the
        //    single-topic answer walks the intake and answers the object.
        {
            type TopicSlot = std::sync::Arc<
                std::sync::Mutex<Option<tdutils::status::Result<Option<td_api::ForumTopic>>>>,
            >;
            struct Rec(TopicSlot);
            impl tdutils::promise::PromiseInterface<Option<td_api::ForumTopic>> for Rec {
                fn set_value(&mut self, value: Option<td_api::ForumTopic>) {
                    *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
                }
                fn set_error(&mut self, error: Status) {
                    *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
                }
            }
            let slot: TopicSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let promise = tdutils::promise::Promise::from_interface(Rec(slot.clone()));
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            ForumTopicManager::get_forum_topic(
                manager,
                &mut env,
                dialog,
                crate::forum_topic::ForumTopicId::new(5),
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_getForumTopicsByID::ID);
            let body = telegram_api::messages_getForumTopicsByID::parse(sent.query())
                .expect("the by-id body");
            assert_eq!(body.topics, vec![5]);
            net_complete(
                sent,
                forum_topics_answer(vec![wire_forum_topic(5, 1000, 704)], 1, false),
            );
            td.dispatch_completed_forum_topic_net();
            let topic = match slot.lock().unwrap().take().unwrap() {
                tdutils::status::Result::Ok(Some(topic)) => topic,
                other => panic!("the by-id answer: {other:?}"),
            };
            let info = topic.info.expect("the topic info");
            assert_eq!(info.forum_topic_id, 5);
            assert_eq!(info.chat_id, dialog.get());
            assert!(topic.is_pinned, "the wire pinned flag rides the object");
            assert!(
                td.forum_topic_manager
                    .has_topic_for_test(dialog, crate::forum_topic::ForumTopicId::new(5)),
                "the registry intake"
            );
        }

        // 2. getForumTopic — the zero-topic null band (cpp:349-351).
        {
            type TopicSlot = std::sync::Arc<
                std::sync::Mutex<Option<tdutils::status::Result<Option<td_api::ForumTopic>>>>,
            >;
            struct Rec(TopicSlot);
            impl tdutils::promise::PromiseInterface<Option<td_api::ForumTopic>> for Rec {
                fn set_value(&mut self, value: Option<td_api::ForumTopic>) {
                    *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
                }
                fn set_error(&mut self, error: Status) {
                    *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
                }
            }
            let slot: TopicSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let promise = tdutils::promise::Promise::from_interface(Rec(slot.clone()));
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            ForumTopicManager::get_forum_topic(
                manager,
                &mut env,
                dialog,
                crate::forum_topic::ForumTopicId::new(6),
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_getForumTopicsByID::ID);
            net_complete(sent, forum_topics_answer(Vec::new(), 0, false));
            td.dispatch_completed_forum_topic_net();
            assert!(matches!(
                slot.lock().unwrap().take().unwrap(),
                tdutils::status::Result::Ok(None)
            ));
        }

        // 3. getForumTopics — the Q flag, the walk and the next offsets.
        {
            type TopicsSlot = std::sync::Arc<
                std::sync::Mutex<Option<tdutils::status::Result<td_api::ForumTopics>>>,
            >;
            struct Rec(TopicsSlot);
            impl tdutils::promise::PromiseInterface<td_api::ForumTopics> for Rec {
                fn set_value(&mut self, value: td_api::ForumTopics) {
                    *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
                }
                fn set_error(&mut self, error: Status) {
                    *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
                }
            }
            let slot: TopicsSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let promise = tdutils::promise::Promise::from_interface(Rec(slot.clone()));
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            ForumTopicManager::get_forum_topics(
                manager,
                &mut env,
                dialog,
                "search".to_owned(),
                0,
                crate::message_id::MessageId::default(),
                crate::forum_topic::ForumTopicId::default(),
                10,
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_getForumTopics::ID);
            let body =
                telegram_api::messages_getForumTopics::parse(sent.query()).expect("the list body");
            assert_eq!(body.flags & 1, 1, "the Q flag");
            assert_eq!(body.q, "search");
            assert_eq!(body.limit, 10);
            net_complete(
                sent,
                forum_topics_answer(
                    vec![
                        wire_forum_topic(5, 1000, 704),
                        wire_forum_topic(6, 2000, 704),
                    ],
                    42,
                    false,
                ),
            );
            td.dispatch_completed_forum_topic_net();
            let topics = match slot.lock().unwrap().take().unwrap() {
                tdutils::status::Result::Ok(topics) => topics,
                other => panic!("the list answer: {other:?}"),
            };
            assert_eq!(topics.total_count, 42);
            assert_eq!(topics.topics.len(), 2);
            assert_eq!(topics.next_offset_date, 2000, "the last creation date");
            assert_eq!(topics.next_offset_message_id, 0);
            assert_eq!(topics.next_offset_forum_topic_id, 6);
        }
    }

    /// The delete family — the wire tail rides the message-query
    /// affected-history plane: the partial answer refills the loop, the
    /// final answer runs `on_delete_forum_topic` (the registry erase +
    /// the deleted-id mark) and settles the request promise.
    #[test]
    fn delete_forum_topic_rides_the_affected_history_plane() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(delete_forum_topic_rides_the_affected_history_plane_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn delete_forum_topic_rides_the_affected_history_plane_impl() {
        use crate::forum_topic_manager::ForumTopicManager;

        let (mut td, rec) = netted_td("netfix-forum-topic-delete");
        seed_dialog_channel_with_flags(&mut td, 705, true, true, true);
        let dialog = crate::dialog_id::DialogId::new(-1_000_000_000_705);

        // seed a live topic (the delete tail erases it)
        {
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            manager.on_get_forum_topic_impl(
                &mut env,
                dialog,
                telegram_api::ForumTopic::forumTopic(telegram_api::forumTopic {
                    flags: 0,
                    my: true,
                    closed: false,
                    pinned: false,
                    short: false,
                    hidden: false,
                    title_missing: false,
                    id: 8,
                    date: 1000,
                    peer: Some(telegram_api::Peer::peerChannel(telegram_api::peerChannel {
                        channel_id: 705,
                    })),
                    title: "Doomed".to_owned(),
                    icon_color: 0,
                    icon_emoji_id: 0,
                    top_message: 0,
                    read_inbox_max_id: 0,
                    read_outbox_max_id: 0,
                    unread_count: 0,
                    unread_mentions_count: 0,
                    unread_reactions_count: 0,
                    unread_poll_votes_count: 0,
                    from_id: Some(telegram_api::Peer::peerUser(telegram_api::peerUser {
                        user_id: 42,
                    })),
                    notify_settings: None,
                    draft: None,
                }),
            );
        }
        assert!(
            td.forum_topic_manager
                .has_topic_for_test(dialog, crate::forum_topic::ForumTopicId::new(8))
        );

        let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
        let capture = std::sync::Arc::clone(&slot);
        let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
            *capture.lock().unwrap() = Some(result);
        });
        {
            let (mut env, manager) = crate::td::forum_topic_env_split(&mut td);
            ForumTopicManager::delete_forum_topic(
                manager,
                &mut env,
                dialog,
                crate::forum_topic::ForumTopicId::new(8),
                promise,
            );
        }
        td.run_forum_topic_delete_tails();
        let sent = take_sent_query(&rec, telegram_api::messages_deleteTopicHistory::ID);
        let body = telegram_api::messages_deleteTopicHistory::parse(sent.query())
            .expect("the delete body");
        assert_eq!(body.top_msg_id, 8);

        // the partial answer (offset > 0) refills the loop
        let mut partial = Vec::new();
        telegram_api::messages_AffectedHistory {
            pts: 10,
            pts_count: 5,
            offset: 100,
        }
        .store_boxed(&mut partial);
        net_complete(sent, partial);
        td.dispatch_completed_message_query_net();
        let refill = take_sent_query(&rec, telegram_api::messages_deleteTopicHistory::ID);
        assert!(
            slot.lock().unwrap().is_none(),
            "the partial answer does not settle the promise"
        );

        // the final answer runs the delete tail and settles the promise
        let mut final_answer = Vec::new();
        telegram_api::messages_AffectedHistory {
            pts: 20,
            pts_count: 0,
            offset: 0,
        }
        .store_boxed(&mut final_answer);
        net_complete(refill, final_answer);
        td.dispatch_completed_message_query_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));
        assert!(
            !td.forum_topic_manager
                .has_topic_for_test(dialog, crate::forum_topic::ForumTopicId::new(8)),
            "the registry erase"
        );
        assert!(
            td.forum_topic_manager
                .is_deleted_for_test(dialog, crate::forum_topic::ForumTopicId::new(8)),
            "the deleted-id mark"
        );
    }

    fn manager_has_topic(
        td: &Td,
        dialog_id: crate::dialog_id::DialogId,
        forum_topic_id: i32,
    ) -> bool {
        td.forum_topic_manager.has_topic_for_test(
            dialog_id,
            crate::forum_topic::ForumTopicId::new(forum_topic_id),
        )
    }

    /// The net-drain 42 attach-menu round-trips — the three families'
    /// send legs dispatch through the installed handle and the wire
    /// answers settle the parked promises (the band ladders live in
    /// `attach_menu_manager.rs`; these cover the dispatcher plumbing, the
    /// toggle chains and the read conversions).
    #[test]
    fn attach_menu_families_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(attach_menu_families_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn attach_menu_families_ride_the_dispatcher_impl() {
        use crate::user_manager::UserId;

        let (mut td, rec) = netted_td("netfix-attach-menu");
        // the addable attach-menu bot (the request legs resolve + gate on
        // it; the answer's users intake re-lands the same record)
        {
            let crate::td::Td {
                global,
                option_manager,
                auth_manager,
                user_manager,
                ..
            } = &mut td;
            let mut env = crate::user_manager::UserEnv {
                global,
                options: option_manager.as_mut().expect("option manager set"),
                auth_is_bot: auth_manager.is_bot(),
            };
            user_manager.on_get_user(
                &mut env,
                telegram_api::User::user(telegram_api::user {
                    flags: 1 | (1 << 1) | (1 << 3), // ACCESS_HASH | FIRST_NAME | USERNAME
                    access_hash: 77,
                    first_name: "Attach".to_owned(),
                    username: "attach_bot".to_owned(),
                    bot: true,
                    bot_attach_menu: true,
                    ..telegram_api::user::default()
                }),
                "test",
            );
        }

        fn unit_slot() -> (tdutils::promise::Promise<()>, UnitSlot) {
            let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let capture = std::sync::Arc::clone(&slot);
            let promise = tdutils::promise::PromiseCreator::lambda_result(move |result| {
                *capture.lock().unwrap() = Some(result);
            });
            (promise, slot)
        }

        /// A wire `attachMenuBot` with a valid default_static icon.
        fn wire_bot(user_id: i64) -> telegram_api::AttachMenuBot {
            telegram_api::AttachMenuBot {
                flags: 0,
                inactive: false,
                has_settings: false,
                request_write_access: true,
                show_in_attach_menu: true,
                show_in_side_menu: false,
                side_menu_disclaimer_needed: false,
                bot_id: user_id,
                short_name: "attach_bot".to_owned(),
                peer_types: vec![telegram_api::AttachMenuPeerType::attachMenuPeerTypePM(
                    telegram_api::attachMenuPeerTypePM,
                )],
                icons: vec![telegram_api::AttachMenuBotIcon {
                    flags: 0,
                    name: "default_static".to_owned(),
                    icon: Some(telegram_api::Document::document(telegram_api::document {
                        flags: 0,
                        id: 100,
                        access_hash: 7,
                        file_reference: b"ref".to_vec(),
                        date: 0,
                        mime_type: "image/png".to_owned(),
                        size: 123,
                        thumbs: Vec::new(),
                        video_thumbs: Vec::new(),
                        dc_id: 2,
                        attributes: Vec::new(),
                    })),
                    colors: Vec::new(),
                }],
            }
        }

        /// The wire `user` record that lands the bot into the cache.
        fn wire_bot_user(user_id: i64) -> telegram_api::User {
            telegram_api::User::user(telegram_api::user {
                flags: 1 | (1 << 1) | (1 << 3), // ACCESS_HASH | FIRST_NAME | USERNAME
                id: user_id,
                access_hash: 77,
                first_name: "Attach".to_owned(),
                username: "attach_bot".to_owned(),
                bot: true,
                bot_attach_menu: true,
                ..telegram_api::user::default()
            })
        }

        /// The bootstrap `Bool` answer — the generator emits no structs
        /// for the type (the `parse_wire_bool` doc); the ids are the
        /// wire constants (telegram_api.tl:11-12).
        fn bool_answer(value: bool) -> Vec<u8> {
            const BOOL_TRUE_ID: i32 = 0x9972_75b5u32 as i32;
            const BOOL_FALSE_ID: i32 = 0xbc79_9737u32 as i32;
            let mut out = Vec::new();
            out.extend_from_slice(
                &(if value { BOOL_TRUE_ID } else { BOOL_FALSE_ID }).to_le_bytes(),
            );
            out
        }

        // 1. getAttachMenuBots — the cold-hash send; the answer runs the
        //    users intake + the cache/save/update walk and settles the
        //    parked promise Unit.
        {
            let (promise, slot) = unit_slot();
            let (mut env, manager) = crate::td::attach_menu_env_split(&mut td);
            manager.reload_attach_menu_bots(&mut env, promise);
            let sent = take_sent_query(&rec, telegram_api::messages_getAttachMenuBots::ID);
            let body = telegram_api::messages_getAttachMenuBots::parse(sent.query())
                .expect("the getAttachMenuBots body");
            assert_eq!(body.hash, 0, "the cold hash");
            let mut answer = Vec::new();
            telegram_api::AttachMenuBots::attachMenuBots(telegram_api::attachMenuBots {
                hash: 1234,
                bots: vec![wire_bot(901)],
                users: vec![wire_bot_user(901)],
            })
            .store(&mut answer);
            net_complete(sent, answer);
            td.dispatch_completed_attach_menu_net();
            assert!(matches!(
                &*slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
            assert_eq!(td.attach_menu_manager.cache_for_test(), (1234, 1));
            assert!(
                td.attach_menu_updates
                    .iter()
                    .any(|u| matches!(u, td_api::Update::updateAttachmentMenuBots(_)))
            );
        }

        // 2. the reload error band — the C++ `set_promises` settles the
        //    parked promise Unit (the toggle chain answers Ok) and the
        //    short retry arms (cpp:615-618).
        {
            let (promise, slot) = unit_slot();
            let (mut env, manager) = crate::td::attach_menu_env_split(&mut td);
            manager.reload_attach_menu_bots(&mut env, promise);
            let sent = take_sent_query(&rec, telegram_api::messages_getAttachMenuBots::ID);
            net_fail(sent, 429, "FLOOD_WAIT_1");
            td.dispatch_completed_attach_menu_net();
            assert!(
                matches!(
                    &*slot.lock().unwrap(),
                    Some(tdutils::status::Result::Ok(()))
                ),
                "the C++ set_promises settles the reload promise Ok"
            );
            let deadline = td
                .attach_menu_manager
                .next_deadline()
                .expect("the short retry armed");
            assert!(
                deadline - tdutils::time::now() >= 59.0 && deadline - tdutils::time::now() <= 120.0
            );
        }

        // 3. getAttachMenuBot — the input user resolves with the seeded
        //    access hash; the answer converts and the added bot's cache
        //    entry updates in place (no hash reset, no new broadcast).
        {
            type BotSlot = std::sync::Arc<
                std::sync::Mutex<Option<tdutils::status::Result<td_api::AttachmentMenuBot>>>,
            >;
            struct Rec(BotSlot);
            impl tdutils::promise::PromiseInterface<td_api::AttachmentMenuBot> for Rec {
                fn set_value(&mut self, value: td_api::AttachmentMenuBot) {
                    *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
                }
                fn set_error(&mut self, error: Status) {
                    *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
                }
            }
            let slot: BotSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let promise = tdutils::promise::Promise::from_interface(Rec(slot.clone()));
            let (mut env, manager) = crate::td::attach_menu_env_split(&mut td);
            manager.get_attach_menu_bot_request(&mut env, UserId::new(901), promise);
            let sent = take_sent_query(&rec, telegram_api::messages_getAttachMenuBot::ID);
            let body = telegram_api::messages_getAttachMenuBot::parse(sent.query())
                .expect("the getAttachMenuBot body");
            match body.bot.as_ref() {
                Some(telegram_api::InputUser::inputUser(u)) => {
                    assert_eq!(u.user_id, 901);
                    assert_eq!(u.access_hash, 77, "the seeded access hash");
                }
                other => panic!("the resolved input user: {other:?}"),
            }
            let updates_before = td.attach_menu_updates.len();
            let mut answer = Vec::new();
            telegram_api::AttachMenuBotsBot {
                bot: Some(wire_bot(901)),
                users: vec![wire_bot_user(901)],
            }
            .store_boxed(&mut answer);
            net_complete(sent, answer);
            td.dispatch_completed_attach_menu_net();
            let object = match &*slot.lock().unwrap() {
                Some(tdutils::status::Result::Ok(bot)) => bot.clone(),
                other => panic!("the single-bot answer: {other:?}"),
            };
            assert_eq!(object.bot_user_id, 901);
            assert!(object.is_added && object.request_write_access);
            assert!(object.default_icon.is_some(), "the registered icon file");
            assert_eq!(object.name, "attach_bot");
            assert_eq!(
                td.attach_menu_manager.cache_for_test(),
                (1234, 1),
                "the same-content walk leaves the hash alone"
            );
            assert_eq!(
                td.attach_menu_updates.len(),
                updates_before,
                "no new broadcast for the same-content walk"
            );
        }

        // 4. the wrong-bot band — the answer carries a different bot id
        //    (cpp:739-741, the C++ lambda capture checks it).
        {
            type BotSlot = std::sync::Arc<
                std::sync::Mutex<Option<tdutils::status::Result<td_api::AttachmentMenuBot>>>,
            >;
            struct Rec(BotSlot);
            impl tdutils::promise::PromiseInterface<td_api::AttachmentMenuBot> for Rec {
                fn set_value(&mut self, _value: td_api::AttachmentMenuBot) {}
                fn set_error(&mut self, error: Status) {
                    *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
                }
            }
            let slot: BotSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
            let promise = tdutils::promise::Promise::from_interface(Rec(slot.clone()));
            let (mut env, manager) = crate::td::attach_menu_env_split(&mut td);
            manager.get_attach_menu_bot_request(&mut env, UserId::new(901), promise);
            let sent = take_sent_query(&rec, telegram_api::messages_getAttachMenuBot::ID);
            let mut answer = Vec::new();
            telegram_api::AttachMenuBotsBot {
                bot: Some(wire_bot(777)),
                users: Vec::new(),
            }
            .store_boxed(&mut answer);
            net_complete(sent, answer);
            td.dispatch_completed_attach_menu_net();
            assert!(matches!(
                &*slot.lock().unwrap(),
                Some(tdutils::status::Result::Err(error)) if error.code() == 500
            ));
        }

        // 5. toggleBotInAttachMenu — the WRITE_ALLOWED/enabled wire form;
        //    the boolTrue answer success-chains into the reload query and
        //    the reload's NotModified settles the toggle promise.
        {
            let (promise, slot) = unit_slot();
            let (mut env, manager) = crate::td::attach_menu_env_split(&mut td);
            manager.toggle_bot_is_added_to_attach_menu(
                &mut env,
                UserId::new(901),
                true,
                true,
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_toggleBotInAttachMenu::ID);
            let body = telegram_api::messages_toggleBotInAttachMenu::parse(sent.query())
                .expect("the toggle body");
            assert!(body.write_allowed, "is_added && allow_write_access");
            assert!(body.enabled);
            net_complete(sent, bool_answer(true));
            td.dispatch_completed_attach_menu_net();
            // the success chain fired the reload query
            let reload = take_sent_query(&rec, telegram_api::messages_getAttachMenuBots::ID);
            let body = telegram_api::messages_getAttachMenuBots::parse(reload.query())
                .expect("the chained reload body");
            assert_eq!(body.hash, 1234, "the current hash rides the chain");
            let mut answer = Vec::new();
            telegram_api::AttachMenuBots::attachMenuBotsNotModified(
                telegram_api::attachMenuBotsNotModified,
            )
            .store(&mut answer);
            net_complete(reload, answer);
            td.dispatch_completed_attach_menu_net();
            assert!(
                matches!(
                    &*slot.lock().unwrap(),
                    Some(tdutils::status::Result::Ok(()))
                ),
                "the chained reload settles the toggle promise"
            );
        }

        // 6. the toggle boolFalse band — the C++ LOG(ERROR) + the Unit
        //    answer still success-chains (cpp:103-114).
        {
            let (promise, slot) = unit_slot();
            let (mut env, manager) = crate::td::attach_menu_env_split(&mut td);
            manager.toggle_bot_is_added_to_attach_menu(
                &mut env,
                UserId::new(901),
                true,
                false,
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_toggleBotInAttachMenu::ID);
            let body = telegram_api::messages_toggleBotInAttachMenu::parse(sent.query())
                .expect("the toggle body");
            assert!(!body.write_allowed, "allow_write_access = false");
            assert!(body.enabled);
            net_complete(sent, bool_answer(false));
            td.dispatch_completed_attach_menu_net();
            let reload = take_sent_query(&rec, telegram_api::messages_getAttachMenuBots::ID);
            let mut answer = Vec::new();
            telegram_api::AttachMenuBots::attachMenuBotsNotModified(
                telegram_api::attachMenuBotsNotModified,
            )
            .store(&mut answer);
            net_complete(reload, answer);
            td.dispatch_completed_attach_menu_net();
            assert!(matches!(
                &*slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ));
        }

        // 7. the toggle error band — the C++ `on_error` fires the
        //    promise-less reload first, then fails the toggle promise
        //    (cpp:116-119).
        {
            let (promise, slot) = unit_slot();
            let (mut env, manager) = crate::td::attach_menu_env_split(&mut td);
            manager.toggle_bot_is_added_to_attach_menu(
                &mut env,
                UserId::new(901),
                true,
                true,
                promise,
            );
            let sent = take_sent_query(&rec, telegram_api::messages_toggleBotInAttachMenu::ID);
            net_fail(sent, 400, "BOT_INACTIVE");
            td.dispatch_completed_attach_menu_net();
            assert!(matches!(
                &*slot.lock().unwrap(),
                Some(tdutils::status::Result::Err(error)) if error.code() == 400
            ));
            // the promise-less reload rode the same answer
            let reload = take_sent_query(&rec, telegram_api::messages_getAttachMenuBots::ID);
            let mut answer = Vec::new();
            telegram_api::AttachMenuBots::attachMenuBotsNotModified(
                telegram_api::attachMenuBotsNotModified,
            )
            .store(&mut answer);
            net_complete(reload, answer);
            td.dispatch_completed_attach_menu_net();
        }
    }

    #[test]
    fn bot_recommendation_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(bot_recommendation_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    /// The net-drain 53 family — `bots.getBotRecommendations` through the
    /// live td_api arms (getBotSimilarBots/getBotSimilarBotCount,
    /// Requests.cpp:3209-3222): the outgoing input user resolves at the
    /// send leg (BotRecommendationManager.cpp:42-47), the answers run the
    /// users intake + the cache walk (cpp:299-352) and settle the parked
    /// family promises.
    fn bot_recommendation_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-bot-recommendations");

        /// The wire `user` record that lands a bot into the cache (the
        /// seeded bot resolves with its access hash at the send leg).
        fn wire_user(user_id: i64, is_bot: bool) -> telegram_api::User {
            telegram_api::User::user(telegram_api::user {
                flags: 1 | (1 << 1), // ACCESS_HASH | FIRST_NAME
                id: user_id,
                access_hash: 700 + user_id,
                first_name: "Bot".to_owned(),
                bot: is_bot,
                ..telegram_api::user::default()
            })
        }

        fn seed_user(td: &mut Td, user_id: i64, is_bot: bool) {
            let crate::td::Td {
                global,
                option_manager,
                auth_manager,
                user_manager,
                ..
            } = td;
            let mut env = crate::user_manager::UserEnv {
                global,
                options: option_manager.as_mut().expect("option manager set"),
                auth_is_bot: auth_manager.is_bot(),
            };
            user_manager.on_get_user(&mut env, wire_user(user_id, is_bot), "test");
        }

        /// A boxed `users.usersSlice` answer.
        fn slice_answer(count: i32, users: Vec<telegram_api::User>) -> Vec<u8> {
            let mut out = Vec::new();
            telegram_api::users_Users::users_usersSlice(telegram_api::users_usersSlice {
                count,
                users,
            })
            .store(&mut out);
            out
        }

        // 1. getBotSimilarBots — the live arm parks the request promise,
        //    the query rides the dispatcher with the resolved input user
        //    (cpp:42-47), and the slice answer runs the users intake +
        //    the non-bot filter (cpp:308-340: the total count decrements
        //    per dropped user).
        seed_user(&mut td, 901, true);
        td.request(
            301,
            Function::getBotSimilarBots(td_api::getBotSimilarBots { bot_user_id: 901 }),
        );
        let sent = take_sent_query(&rec, telegram_api::bots_getBotRecommendations::ID);
        let body = telegram_api::bots_getBotRecommendations::parse(sent.query())
            .expect("the getBotRecommendations body");
        match body.bot.as_ref() {
            Some(telegram_api::InputUser::inputUser(user)) => {
                assert_eq!(user.user_id, 901);
                assert_eq!(user.access_hash, 1601, "the seeded access hash");
            }
            other => panic!("the resolved input user: {other:?}"),
        }
        net_complete(
            sent,
            slice_answer(
                3,
                vec![
                    wire_user(911, true),
                    wire_user(912, false),
                    wire_user(913, true),
                ],
            ),
        );
        td.dispatch_completed_bot_recommendation_net();
        td.flush_deferred_results();
        let responses = responses_of(&callback, 301);
        let users = match responses.first() {
            Some(Object::users(users)) => users.clone(),
            other => panic!("the getBotSimilarBots answer: {other:?}"),
        };
        assert_eq!(users.total_count, 2, "the non-bot drops the count");
        assert_eq!(users.user_ids, vec![911, 913]);

        // 2. the fresh cache answers without a wire query (cpp:152-164).
        td.request(
            302,
            Function::getBotSimilarBots(td_api::getBotSimilarBots { bot_user_id: 901 }),
        );
        td.flush_deferred_results();
        assert!(rec.sent.lock().is_empty(), "the cache hit sends nothing");
        let responses = responses_of(&callback, 302);
        assert!(
            responses.iter().any(
                |object| matches!(object, Object::users(users) if users.user_ids == vec![911, 913])
            ),
            "the cached answer: {responses:?}"
        );

        // 3. getBotSimilarBotCount — the cached total count (the same
        //    family queue, cpp:158-161).
        td.request(
            303,
            Function::getBotSimilarBotCount(td_api::getBotSimilarBotCount {
                bot_user_id: 901,
                return_local: false,
            }),
        );
        td.flush_deferred_results();
        assert!(
            responses_of(&callback, 303)
                .iter()
                .any(|object| matches!(object, Object::count(count) if count.count == 2)),
            "the cached count"
        );

        // 4. the return_local count answers -1 before the send
        //    (cpp:283-291); the wire query still fires for the reload.
        seed_user(&mut td, 902, true);
        td.request(
            304,
            Function::getBotSimilarBotCount(td_api::getBotSimilarBotCount {
                bot_user_id: 902,
                return_local: true,
            }),
        );
        td.flush_deferred_results();
        assert!(
            responses_of(&callback, 304)
                .iter()
                .any(|object| matches!(object, Object::count(count) if count.count == -1)),
            "the local count band"
        );
        let sent = take_sent_query(&rec, telegram_api::bots_getBotRecommendations::ID);
        net_complete(sent, slice_answer(0, Vec::new()));
        td.dispatch_completed_bot_recommendation_net();

        // 5. the error band — the codes forward verbatim through
        //    fail_load_bot_recommendations_queries (cpp:61-63 → :205-221).
        seed_user(&mut td, 903, true);
        td.request(
            305,
            Function::getBotSimilarBots(td_api::getBotSimilarBots { bot_user_id: 903 }),
        );
        let sent = take_sent_query(&rec, telegram_api::bots_getBotRecommendations::ID);
        net_fail(sent, 420, "BOT_INVALID");
        td.dispatch_completed_bot_recommendation_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 305);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "BOT_INVALID");

        // 6. the parse-failure band — the fetch_result failure rides the
        //    same Err path as the C++ on_error chain (the §5 convention).
        seed_user(&mut td, 904, true);
        td.request(
            306,
            Function::getBotSimilarBots(td_api::getBotSimilarBots { bot_user_id: 904 }),
        );
        let sent = take_sent_query(&rec, telegram_api::bots_getBotRecommendations::ID);
        net_complete(sent, b"garbage".to_vec());
        td.dispatch_completed_bot_recommendation_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 306);
        assert_eq!(error.code, 500);
        assert_eq!(
            error.message,
            "Failed to parse the bots.getBotRecommendations answer"
        );

        // 7. the total-count clamp band — a slice count below the vector
        //    length LOG(ERROR)s and clamps (cpp:321-325).
        seed_user(&mut td, 905, true);
        td.request(
            307,
            Function::getBotSimilarBots(td_api::getBotSimilarBots { bot_user_id: 905 }),
        );
        let sent = take_sent_query(&rec, telegram_api::bots_getBotRecommendations::ID);
        net_complete(
            sent,
            slice_answer(1, vec![wire_user(906, true), wire_user(907, true)]),
        );
        td.dispatch_completed_bot_recommendation_net();
        td.flush_deferred_results();
        assert!(
            responses_of(&callback, 307).iter().any(
                |object| matches!(object, Object::users(users) if users.total_count == 2
                    && users.user_ids == vec![906, 907])
            ),
            "the clamped total count"
        );

        assert!(
            td.bot_recommendation_net_completed.lock().is_empty(),
            "drained"
        );
    }

    #[test]
    fn custom_emoji_documents_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(custom_emoji_documents_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    /// The net-drain 59 custom-emoji family —
    /// `messages.getCustomEmojiDocuments` through the live td_api arm
    /// (getCustomEmojiStickers, Requests.cpp:7745-7749): the outgoing
    /// query carries the deduped unknown ids
    /// (StickersManager.cpp:6583-6579), the answer runs the sticker-record
    /// intake (`on_get_sticker_document` → `create_sticker` →
    /// `on_get_sticker`, cpp:2972-3067/:3376-3435/:2845-2950) and the
    /// parked request promise settles from the family lot.
    fn custom_emoji_documents_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-stickers-custom-emoji");

        /// A wire custom-emoji sticker document: the id is the custom
        /// emoji id, the `documentAttributeCustomEmoji` carries the alt
        /// and the set.
        fn custom_emoji_document(
            custom_emoji_id: i64,
            alt: &str,
            set_id: i64,
        ) -> telegram_api::Document {
            telegram_api::Document::document(telegram_api::document {
                id: custom_emoji_id,
                access_hash: 0x5100_0000_0000 + custom_emoji_id,
                file_reference: b"ref".to_vec(),
                mime_type: "application/x-tgsticker".to_string(),
                size: 4096,
                thumbs: Vec::new(),
                video_thumbs: Vec::new(),
                dc_id: 2,
                attributes: vec![
                    telegram_api::DocumentAttribute::documentAttributeImageSize(
                        telegram_api::documentAttributeImageSize { w: 100, h: 100 },
                    ),
                    telegram_api::DocumentAttribute::documentAttributeCustomEmoji(
                        telegram_api::documentAttributeCustomEmoji {
                            flags: 0,
                            free: true,
                            text_color: false,
                            alt: alt.to_owned(),
                            stickerset: Some(telegram_api::InputStickerSet::inputStickerSetID(
                                telegram_api::inputStickerSetID {
                                    id: set_id,
                                    access_hash: 0x6600_0000_0000 + set_id,
                                },
                            )),
                        },
                    ),
                ],
                ..telegram_api::document::default()
            })
        }

        /// A boxed bare `Vector<Document>` answer.
        fn documents_answer(documents: Vec<telegram_api::Document>) -> Vec<u8> {
            let mut out = Vec::new();
            telegram_api::tl::__i32(&mut out, telegram_api::tl::VECTOR_ID);
            telegram_api::tl::__i32(&mut out, documents.len() as i32);
            for document in documents {
                document.store(&mut out);
            }
            out
        }

        // 1. the live arm parks the request promise and the query rides
        //    the dispatcher with the deduped unknown ids (cpp:6570-6579).
        let first_id = 5_000_001;
        let second_id = 5_000_002;
        td.request(
            401,
            Function::getCustomEmojiStickers(td_api::getCustomEmojiStickers {
                custom_emoji_ids: vec![first_id, second_id, first_id],
            }),
        );
        let sent = take_sent_query(&rec, telegram_api::messages_getCustomEmojiDocuments::ID);
        let body = telegram_api::messages_getCustomEmojiDocuments::parse(sent.query())
            .expect("the getCustomEmojiDocuments body");
        assert_eq!(body.document_id, vec![first_id, second_id]);

        // 2. the answer builds the sticker records (the set record + the
        //    custom-emoji id map) and answers the per-id object vector —
        //    the still-unknown second id contributes nothing
        //    (cpp:6473-6493).
        net_complete(
            sent,
            documents_answer(vec![custom_emoji_document(first_id, "\u{1f389}", 4242)]),
        );
        td.dispatch_completed_stickers_net();
        td.flush_deferred_results();
        let responses = responses_of(&callback, 401);
        let stickers = match responses.first() {
            Some(Object::stickers(stickers)) => stickers.clone(),
            other => panic!("the getCustomEmojiStickers answer: {other:?}"),
        };
        assert_eq!(stickers.stickers.len(), 1, "the unknown id drops");
        let sticker = stickers.stickers[0].clone();
        assert_eq!(sticker.id, first_id);
        assert_eq!(sticker.set_id, 4242);
        assert_eq!(sticker.width, 100);
        assert_eq!(sticker.height, 100);
        assert_eq!(sticker.emoji, "\u{1f389}");
        assert!(matches!(
            sticker.format,
            Some(td_api::StickerFormat::stickerFormatTgs(_))
        ));
        match sticker.full_type {
            Some(td_api::StickerFullType::stickerFullTypeCustomEmoji(custom)) => {
                assert_eq!(custom.custom_emoji_id, first_id);
                assert!(!custom.needs_repainting);
            }
            other => panic!("the custom-emoji full type: {other:?}"),
        }
        assert!(sticker.sticker.is_some(), "the registered file object");

        // 3. the id-map cache hit answers without a wire query
        //    (cpp:6486-6493: both ids resolve after the second load).
        td.request(
            402,
            Function::getCustomEmojiStickers(td_api::getCustomEmojiStickers {
                custom_emoji_ids: vec![first_id],
            }),
        );
        td.flush_deferred_results();
        assert!(rec.sent.lock().is_empty(), "the cache hit sends nothing");
        assert!(
            responses_of(&callback, 402)
                .iter()
                .any(|object| matches!(object, Object::stickers(value)
                    if value.stickers.len() == 1))
        );

        // 4. the error band — the codes forward verbatim through the
        //    promise (cpp:6593-6594).
        td.request(
            403,
            Function::getCustomEmojiStickers(td_api::getCustomEmojiStickers {
                custom_emoji_ids: vec![5_000_003],
            }),
        );
        let sent = take_sent_query(&rec, telegram_api::messages_getCustomEmojiDocuments::ID);
        net_fail(sent, 420, "EMOJI_INVALID");
        td.dispatch_completed_stickers_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 403);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "EMOJI_INVALID");

        // 5. the parse-failure band — the fetch_result failure rides the
        //    same Err path as the C++ on_error chain (§5 convention).
        td.request(
            404,
            Function::getCustomEmojiStickers(td_api::getCustomEmojiStickers {
                custom_emoji_ids: vec![5_000_004],
            }),
        );
        let sent = take_sent_query(&rec, telegram_api::messages_getCustomEmojiDocuments::ID);
        net_complete(sent, b"garbage".to_vec());
        td.dispatch_completed_stickers_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 404);
        assert_eq!(error.code, 500);
        assert_eq!(
            error.message,
            "Failed to parse the messages.getCustomEmojiDocuments answer"
        );

        // 6. the no-attribute band — a document without the sticker or
        //    custom-emoji attribute LOG(ERROR)s and drops
        //    (cpp:3022-3030); the answer is the empty sticker vector.
        td.request(
            405,
            Function::getCustomEmojiStickers(td_api::getCustomEmojiStickers {
                custom_emoji_ids: vec![5_000_005],
            }),
        );
        let sent = take_sent_query(&rec, telegram_api::messages_getCustomEmojiDocuments::ID);
        net_complete(
            sent,
            documents_answer(vec![telegram_api::Document::document(
                telegram_api::document {
                    id: 5_000_005,
                    mime_type: "image/webp".to_string(),
                    dc_id: 2,
                    ..telegram_api::document::default()
                },
            )]),
        );
        td.dispatch_completed_stickers_net();
        td.flush_deferred_results();
        assert!(
            responses_of(&callback, 405)
                .iter()
                .any(|object| matches!(object, Object::stickers(value)
                    if value.stickers.is_empty()))
        );

        // 7. the unknown-mime band — the format guard drops the document
        //    (cpp:3031-3037: `image/png` is not a sticker mime).
        td.request(
            406,
            Function::getCustomEmojiStickers(td_api::getCustomEmojiStickers {
                custom_emoji_ids: vec![5_000_006],
            }),
        );
        let sent = take_sent_query(&rec, telegram_api::messages_getCustomEmojiDocuments::ID);
        net_complete(
            sent,
            documents_answer(vec![telegram_api::Document::document(
                telegram_api::document {
                    id: 5_000_006,
                    mime_type: "image/png".to_string(),
                    dc_id: 2,
                    attributes: vec![
                        telegram_api::DocumentAttribute::documentAttributeCustomEmoji(
                            telegram_api::documentAttributeCustomEmoji {
                                alt: String::new(),
                                ..telegram_api::documentAttributeCustomEmoji::default()
                            },
                        ),
                    ],
                    ..telegram_api::document::default()
                },
            )]),
        );
        td.dispatch_completed_stickers_net();
        td.flush_deferred_results();
        assert!(
            responses_of(&callback, 406)
                .iter()
                .any(|object| matches!(object, Object::stickers(value)
                    if value.stickers.is_empty()))
        );

        assert!(td.stickers_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn stickers_special_sets_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(stickers_special_sets_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    /// The net-drain 59 special-sticker-set family —
    /// `messages.getStickerSet` over the special wire inputs
    /// (`ReloadSpecialStickerSetQuery`, StickersManager.cpp:794-832) and
    /// the §6 premium gift-options sticker leg: the premium arm's
    /// `get_premium_gift_sticker_object` (Premium.cpp:446) triggers the
    /// premium-gift set load on the first miss, the set record lands from
    /// the `messages_stickerSet` answer (cpp:3797-3948), and the next
    /// premium answer carries the live sticker.
    fn stickers_special_sets_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-stickers-special-sets");

        /// A wire premium-gift sticker document: the id doubles as the
        /// custom emoji id over the custom-emoji attribute.
        fn gift_document(document_id: i64, alt: &str) -> telegram_api::Document {
            telegram_api::Document::document(telegram_api::document {
                id: document_id,
                access_hash: 0x3100_0000_0000 + document_id,
                file_reference: b"ref".to_vec(),
                mime_type: "application/x-tgsticker".to_string(),
                size: 4096,
                thumbs: Vec::new(),
                video_thumbs: Vec::new(),
                dc_id: 2,
                attributes: vec![
                    telegram_api::DocumentAttribute::documentAttributeImageSize(
                        telegram_api::documentAttributeImageSize { w: 512, h: 512 },
                    ),
                    telegram_api::DocumentAttribute::documentAttributeCustomEmoji(
                        telegram_api::documentAttributeCustomEmoji {
                            flags: 0,
                            free: true,
                            text_color: false,
                            alt: alt.to_owned(),
                            stickerset: Some(telegram_api::InputStickerSet::inputStickerSetID(
                                telegram_api::inputStickerSetID {
                                    id: 6106107694985,
                                    access_hash: 12345,
                                },
                            )),
                        },
                    ),
                ],
                ..telegram_api::document::default()
            })
        }

        /// A boxed `messages_stickerSet` answer for the premium-gift set —
        /// five keycap-emoji stickers (the `1..5` month ladder of
        /// cpp:2579-2591).
        fn gift_set_answer() -> Vec<u8> {
            const SET_ID: i64 = 6106107694985;
            let mut documents = Vec::new();
            let mut packs = Vec::new();
            for number in 1i64..=5 {
                // the ids double as custom emoji ids, which the C++
                // validity band floors at 1 << 20 (CustomEmojiId.h:29-31)
                let document_id = 0x10_0000 + number;
                documents.push(gift_document(
                    document_id,
                    &format!("{}\u{20e3}", char::from(b'0' + number as u8)),
                ));
                packs.push(telegram_api::StickerPack {
                    emoticon: format!("{}\u{20e3}", char::from(b'0' + number as u8)),
                    documents: vec![document_id],
                });
            }
            let mut out = Vec::new();
            let set = telegram_api::messages_StickerSet::messages_stickerSet(
                telegram_api::messages_stickerSet {
                    set: Some(telegram_api::StickerSet {
                        flags: 0,
                        archived: false,
                        official: true,
                        masks: false,
                        emojis: true,
                        text_color: false,
                        channel_emoji_status: false,
                        creator: false,
                        installed_date: 0,
                        id: SET_ID,
                        access_hash: 12345,
                        title: "Premium Gifts".to_owned(),
                        short_name: "premium_gifts".to_owned(),
                        thumbs: Vec::new(),
                        thumb_dc_id: 0,
                        thumb_version: 0,
                        thumb_document_id: 0,
                        count: 5,
                        hash: 7,
                    }),
                    packs,
                    keywords: Vec::new(),
                    documents,
                },
            );
            set.store(&mut out);
            out
        }

        /// The boxed bare `Vector<PremiumGiftCodeOption>` answer.
        fn gift_options_answer() -> Vec<u8> {
            let mut answer = Vec::new();
            answer.extend_from_slice(&telegram_api::tl::VECTOR_ID.to_le_bytes());
            answer.extend_from_slice(&2i32.to_le_bytes());
            for (months, amount) in [(3, 500), (12, 2000)] {
                telegram_api::PremiumGiftCodeOption {
                    flags: 0,
                    users: 1,
                    months,
                    store_product: String::new(),
                    store_quantity: 0,
                    currency: "USD".to_owned(),
                    amount,
                }
                .store_boxed(&mut answer);
            }
            answer
        }

        // 1. getPremiumGiftPaymentOptions through the live td_api arm —
        //    the premium answer's sticker leg misses
        //    (`get_premium_gift_sticker_set` → null, cpp:2528-2546), so
        //    the first answer carries no sticker and the premium-gift
        //    special set load rides the dispatcher.
        td.request(
            501,
            Function::getPremiumGiftPaymentOptions(td_api::getPremiumGiftPaymentOptions {}),
        );
        let premium_sent =
            take_sent_query(&rec, telegram_api::payments_getPremiumGiftCodeOptions::ID);
        net_complete(premium_sent, gift_options_answer());
        td.dispatch_completed_premium_net();
        td.flush_deferred_results();
        match responses_of(&callback, 501).first() {
            Some(Object::premiumGiftPaymentOptions(options)) => {
                assert!(
                    options
                        .options
                        .iter()
                        .all(|option| option.sticker.is_none()),
                    "the pre-flip band answers no sticker"
                );
            }
            other => panic!("the first gift-options answer: {other:?}"),
        }

        // 2. the miss triggered the special-set load — the
        //    `inputStickerSetPremiumGifts` wire input with hash 0
        //    (cpp:802-804).
        let sticker_sent = take_sent_query(&rec, telegram_api::messages_getStickerSet::ID);
        let body = telegram_api::messages_getStickerSet::parse(sticker_sent.query()).expect("body");
        assert!(matches!(
            body.stickerset,
            Some(telegram_api::InputStickerSet::inputStickerSetPremiumGifts(
                _
            ))
        ));
        assert_eq!(body.hash, 0);

        // 3. the set answer lands the record (the document walk, the packs
        //    walk into `sticker_emojis_map_`, the set record) and settles
        //    the premium-gift pending lot.
        net_complete(sticker_sent, gift_set_answer());
        td.dispatch_completed_stickers_net();
        td.flush_deferred_results();

        // 4. the second premium answer carries the live sticker leg — the
        //    §6 flip, verified through the live td_api arm.
        td.request(
            502,
            Function::getPremiumGiftPaymentOptions(td_api::getPremiumGiftPaymentOptions {}),
        );
        let premium_sent =
            take_sent_query(&rec, telegram_api::payments_getPremiumGiftCodeOptions::ID);
        assert!(
            rec.sent.lock().is_empty(),
            "the loaded special set re-sends no sticker query"
        );
        net_complete(premium_sent, gift_options_answer());
        td.dispatch_completed_premium_net();
        td.flush_deferred_results();
        let options = match responses_of(&callback, 502).first() {
            Some(Object::premiumGiftPaymentOptions(options)) => options.clone(),
            other => panic!("the second gift-options answer: {other:?}"),
        };
        assert_eq!(options.options.len(), 2);
        for option in &options.options {
            let sticker = option
                .sticker
                .as_ref()
                .expect("the §6 gift-options sticker leg is live");
            // cpp:2579-2591 — 3 months → the "2" keycap, 12 months → the
            // "4" keycap
            let expected_alt = match option.month_count {
                3 => "2\u{20e3}",
                12 => "4\u{20e3}",
                other => panic!("unexpected month count {other}"),
            };
            assert_eq!(sticker.emoji, expected_alt);
            assert_eq!(sticker.set_id, 6106107694985);
            match &sticker.full_type {
                Some(td_api::StickerFullType::stickerFullTypeCustomEmoji(custom)) => {
                    assert_eq!(
                        custom.custom_emoji_id,
                        i64::from(sticker.emoji.as_bytes()[0] - b'0') + 0x10_0000
                    );
                }
                other => panic!("the gift sticker full type: {other:?}"),
            }
        }

        // 5. getPremiumInfoSticker through the live td_api arm — the
        //    loaded set answers immediately (cpp:2648-2651).
        td.request(
            503,
            Function::getPremiumInfoSticker(td_api::getPremiumInfoSticker { month_count: 6 }),
        );
        td.flush_deferred_results();
        match responses_of(&callback, 503).first() {
            Some(Object::sticker(sticker)) => assert_eq!(sticker.emoji, "3\u{20e3}"),
            other => panic!("the premium info sticker: {other:?}"),
        }

        // 6. getThemedEmojiStatuses through the live td_api arm
        //    (Requests.cpp:6815-6819 — the themed reader; the bare
        //    getDefaultEmojiStatuses arm is the EmojiStatus.cpp plane) —
        //    the default-statuses set load parks the promise, the answer
        //    settles it with the first 8 custom emoji ids (cpp:6294-6305).
        td.request(
            504,
            Function::getThemedEmojiStatuses(td_api::getThemedEmojiStatuses {}),
        );
        let sent = take_sent_query(&rec, telegram_api::messages_getStickerSet::ID);
        let body = telegram_api::messages_getStickerSet::parse(sent.query()).expect("body");
        assert!(matches!(
            body.stickerset,
            Some(telegram_api::InputStickerSet::inputStickerSetEmojiDefaultStatuses(_))
        ));
        net_complete(
            sent,
            gift_set_answer(), // any loaded set settles the lot
        );
        td.dispatch_completed_stickers_net();
        td.flush_deferred_results();
        match responses_of(&callback, 504).first() {
            Some(Object::emojiStatusCustomEmojis(statuses)) => {
                assert_eq!(statuses.custom_emoji_ids.len(), 5);
            }
            other => panic!("the default emoji statuses answer: {other:?}"),
        }

        // 7. the error band — a failed special-set load keeps the parked
        //    reader promises parked (cpp:1988-2005: only the premium-gift
        //    lot settles, over the OK arm; the rest wait for the 300-600s
        //    retry, which parks at the timer plane). The channel twin
        //    drives the wire error; a second request joins the parked lot
        //    without a new wire query (the is_being_loaded guard).
        td.request(
            505,
            Function::getThemedChatEmojiStatuses(td_api::getThemedChatEmojiStatuses {}),
        );
        let sent = take_sent_query(&rec, telegram_api::messages_getStickerSet::ID);
        let body = telegram_api::messages_getStickerSet::parse(sent.query()).expect("body");
        assert!(matches!(
            body.stickerset,
            Some(telegram_api::InputStickerSet::inputStickerSetEmojiChannelDefaultStatuses(_))
        ));
        net_fail(sent, 420, "STICKERSET_INVALID");
        td.dispatch_completed_stickers_net();
        td.flush_deferred_results();
        assert!(
            responses_of(&callback, 505).is_empty(),
            "the parked promise stays parked on the failed load"
        );
        td.request(
            507,
            Function::getThemedChatEmojiStatuses(td_api::getThemedChatEmojiStatuses {}),
        );
        td.flush_deferred_results();
        assert!(
            rec.sent.lock().is_empty(),
            "the in-flight load keeps the second reader parked"
        );
        assert!(responses_of(&callback, 507).is_empty());

        // 8. the parse-failure band — the fetch_result failure rides the
        //    same Err path (§5 convention) and parks the same way.
        td.request(
            506,
            Function::getForumTopicDefaultIcons(td_api::getForumTopicDefaultIcons {}),
        );
        let sent = take_sent_query(&rec, telegram_api::messages_getStickerSet::ID);
        net_complete(sent, b"garbage".to_vec());
        td.dispatch_completed_stickers_net();
        td.flush_deferred_results();
        assert!(responses_of(&callback, 506).is_empty());

        assert!(td.stickers_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn star_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(star_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn star_queries_ride_the_dispatcher_impl() {
        let (mut td, rec) = netted_td("netfix-star");

        // 1. getStarPaymentOptions — the topup vector converts over
        //    get_star_count (the >2^51 band clamps).
        let (promise, slot) = record_star_options();
        with_star_manager(&mut td, |manager, env| {
            manager.get_star_payment_options(env, promise);
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::payments_getStarsTopupOptions::ID
        );
        let mut answer = Vec::new();
        answer.extend_from_slice(&telegram_api::tl::VECTOR_ID.to_le_bytes());
        answer.extend_from_slice(&1i32.to_le_bytes());
        telegram_api::StarsTopupOption {
            flags: 1, // the STORE_PRODUCT bit (flags.0)
            extended: false,
            stars: 100,
            store_product: "product".to_owned(),
            currency: "USD".to_owned(),
            amount: 199,
        }
        .store_boxed(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_star_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(options)) => {
                assert_eq!(options.options.len(), 1);
                let option = &options.options[0];
                assert_eq!(option.currency, "USD");
                assert_eq!(option.amount, 199);
                assert_eq!(option.star_count, 100);
                assert_eq!(option.store_product_id, "product");
            }
            other => panic!("unexpected option result: {other:?}"),
        }

        // 2. getStarSubscriptions — the balance gate, the channel
        //    subscription conversion and the owned-balance update.
        let (promise, slot) = record_star_subscriptions();
        with_star_manager(&mut td, |manager, env| {
            manager.get_star_subscriptions(env, false, String::new(), promise);
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::payments_getStarsSubscriptions::ID
        );
        let mut answer = Vec::new();
        telegram_api::payments_StarsStatus {
            flags: (1 << 1) | (1 << 2) | (1 << 4), // subscriptions + next_offset + missing_balance
            balance: Some(telegram_api::StarsAmount::starsAmount(
                telegram_api::starsAmount {
                    amount: 42,
                    nanos: 0,
                },
            )),
            subscriptions: vec![telegram_api::StarsSubscription {
                flags: 1 << 3, // the CHAT_INVITE_HASH bit (flags.3)
                canceled: false,
                can_refulfill: true,
                missing_balance: false,
                bot_canceled: false,
                id: "sub1".to_owned(),
                peer: Some(telegram_api::Peer::peerChannel(telegram_api::peerChannel {
                    channel_id: 9000,
                })),
                until_date: 1000,
                pricing: Some(telegram_api::StarsSubscriptionPricing {
                    period: 30,
                    amount: 50,
                }),
                chat_invite_hash: "abc123".to_owned(),
                title: String::new(),
                photo: None,
                invoice_slug: String::new(),
            }],
            subscriptions_next_offset: "offset2".to_owned(),
            subscriptions_missing_balance: 7,
            history: vec![],
            next_offset: String::new(),
            chats: vec![],
            users: vec![],
        }
        .store_boxed(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_star_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(subscriptions)) => {
                assert_eq!(subscriptions.star_amount.as_ref().unwrap().star_count, 42);
                assert_eq!(subscriptions.subscriptions.len(), 1);
                let subscription = &subscriptions.subscriptions[0];
                assert_eq!(subscription.id, "sub1");
                assert_eq!(subscription.chat_id, -1000000009000);
                assert!(subscription.expiration_date == 1000);
                match &subscription.r#type {
                    Some(td_api::StarSubscriptionType::starSubscriptionTypeChannel(channel)) => {
                        assert!(channel.can_reuse);
                        assert!(channel.invite_link.ends_with("+abc123"));
                    }
                    other => panic!("unexpected subscription type: {other:?}"),
                }
                assert_eq!(subscriptions.required_star_count, 7);
                assert_eq!(subscriptions.next_offset, "offset2");
            }
            other => panic!("unexpected subscriptions result: {other:?}"),
        }

        // 3. getStarWithdrawalUrl — the my-dialog input peer rides the
        //    query (seed the own id like the community test); the url
        //    answers (the SRP seam stays the parked PasswordManager
        //    collapse — the empty-SRP send leg).
        td.user_manager.set_my_id(
            &mut crate::user_manager::UserEnv {
                global: &mut td.global,
                options: td
                    .option_manager
                    .as_mut()
                    .expect("the option manager exists after init"),
                auth_is_bot: td.auth_manager.is_bot(),
            },
            crate::user_manager::UserId::new(700000001),
        );
        let my_dialog_id = crate::dialog_id::DialogId::from_user_id(td.user_manager.get_my_id());
        let (promise, slot) = record_star_url();
        with_star_manager(&mut td, |manager, env| {
            manager.get_star_withdrawal_url(env, my_dialog_id, 100, "password".to_owned(), promise);
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::payments_getStarsRevenueWithdrawalUrl::ID
        );
        let mut answer = Vec::new();
        telegram_api::payments_StarsRevenueWithdrawalUrl {
            url: "https://example.com/withdraw".to_owned(),
        }
        .store_boxed(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_star_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(url)) => {
                assert_eq!(url, "https://example.com/withdraw")
            }
            other => panic!("unexpected url result: {other:?}"),
        }

        assert!(td.star_net_completed.lock().is_empty(), "drained");
    }

    type StarTransactionsSlot =
        std::sync::Arc<std::sync::Mutex<Option<tdutils::status::Result<td_api::StarTransactions>>>>;

    fn record_star_transactions() -> (Promise<td_api::StarTransactions>, StarTransactionsSlot) {
        struct Rec(StarTransactionsSlot);
        impl tdutils::promise::PromiseInterface<td_api::StarTransactions> for Rec {
            fn set_value(&mut self, value: td_api::StarTransactions) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
            }
            fn set_error(&mut self, error: Status) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
            }
        }
        let slot: StarTransactionsSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
        (Promise::from_interface(Rec(slot.clone())), slot)
    }

    type TonTransactionsSlot =
        std::sync::Arc<std::sync::Mutex<Option<tdutils::status::Result<td_api::TonTransactions>>>>;

    fn record_ton_transactions() -> (Promise<td_api::TonTransactions>, TonTransactionsSlot) {
        struct Rec(TonTransactionsSlot);
        impl tdutils::promise::PromiseInterface<td_api::TonTransactions> for Rec {
            fn set_value(&mut self, value: td_api::TonTransactions) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
            }
            fn set_error(&mut self, error: Status) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
            }
        }
        let slot: TonTransactionsSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
        (Promise::from_interface(Rec(slot.clone())), slot)
    }

    #[test]
    fn star_transactions_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(star_transactions_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn star_transactions_queries_ride_the_dispatcher_impl() {
        let (mut td, rec) = netted_td("netfix-star-tx");
        td.user_manager.set_my_id(
            &mut crate::user_manager::UserEnv {
                global: &mut td.global,
                options: td
                    .option_manager
                    .as_mut()
                    .expect("the option manager exists after init"),
                auth_is_bot: td.auth_manager.is_bot(),
            },
            crate::user_manager::UserId::new(700000001),
        );
        let my_dialog_id = crate::dialog_id::DialogId::from_user_id(td.user_manager.get_my_id());

        // 1. getStarTransactions over the own dialog — the
        //    subscription-id + inbound flags ride the wire, the partner
        //    ladder converts and the own-dialog balance update fires.
        let (promise, slot) = record_star_transactions();
        with_star_manager(&mut td, |manager, env| {
            manager.get_star_transactions(
                env,
                my_dialog_id,
                "sub".to_owned(),
                String::new(),
                10,
                Some(td_api::TransactionDirection::transactionDirectionIncoming(
                    td_api::transactionDirectionIncoming {},
                )),
                promise,
            );
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::payments_getStarsTransactions::ID
        );
        let wire = telegram_api::payments_getStarsTransactions::parse(sent[0].query()).unwrap();
        assert!(wire.flags & 1 << 3 != 0, "the subscription-id flag");
        assert!(wire.inbound && !wire.outbound);
        assert!(!wire.ascending, "a user client sends descending");
        assert!(!wire.ton);
        assert_eq!(wire.subscription_id, "sub");
        assert_eq!(wire.limit, 10);

        let mut answer = Vec::new();
        telegram_api::payments_StarsStatus {
            flags: (1 << 0) | (1 << 3), // next_offset + history
            balance: Some(telegram_api::StarsAmount::starsAmount(
                telegram_api::starsAmount {
                    amount: 42,
                    nanos: 0,
                },
            )),
            subscriptions: vec![],
            subscriptions_next_offset: String::new(),
            subscriptions_missing_balance: 0,
            history: vec![
                // a premium-bot deposit over the user band
                telegram_api::StarsTransaction {
                    flags: 0,
                    refund: false,
                    pending: false,
                    failed: false,
                    gift: false,
                    reaction: false,
                    stargift_upgrade: false,
                    business_transfer: false,
                    stargift_resale: false,
                    posts_search: false,
                    stargift_prepaid_upgrade: false,
                    stargift_drop_original_details: false,
                    phonegroup_message: false,
                    stargift_auction_bid: false,
                    offer: false,
                    id: "tx1".to_owned(),
                    amount: Some(telegram_api::StarsAmount::starsAmount(
                        telegram_api::starsAmount {
                            amount: 75,
                            nanos: 0,
                        },
                    )),
                    date: 100,
                    peer: Some(
                        telegram_api::StarsTransactionPeer::starsTransactionPeerPremiumBot(
                            telegram_api::starsTransactionPeerPremiumBot,
                        ),
                    ),
                    title: String::new(),
                    description: String::new(),
                    photo: None,
                    transaction_date: 0,
                    transaction_url: String::new(),
                    bot_payload: vec![],
                    msg_id: 0,
                    extended_media: vec![],
                    subscription_period: 0,
                    giveaway_post_id: 0,
                    stargift: None,
                    floodskip_number: 0,
                    starref_commission_permille: 0,
                    starref_peer: None,
                    starref_amount: None,
                    paid_messages: 0,
                    premium_gift_months: 0,
                    ads_proceeds_from_date: 0,
                    ads_proceeds_to_date: 0,
                },
                // a succeeded Fragment withdrawal
                {
                    let mut transaction = star_test_transaction(
                        "tx2",
                        Some(telegram_api::StarsAmount::starsAmount(
                            telegram_api::starsAmount {
                                amount: -10,
                                nanos: 0,
                            },
                        )),
                        telegram_api::StarsTransactionPeer::starsTransactionPeerFragment(
                            telegram_api::starsTransactionPeerFragment,
                        ),
                    );
                    transaction.flags |= 1 << 5; // transaction_date + transaction_url
                    transaction.transaction_date = 200;
                    transaction.transaction_url = "https://fragment.example".to_owned();
                    transaction
                },
                // a bot-subscription purchase (a refunded expense
                // records as a purchase, cpp:316) over a user peer
                {
                    let mut transaction = star_test_transaction(
                        "tx3",
                        Some(telegram_api::StarsAmount::starsAmount(
                            telegram_api::starsAmount {
                                amount: 100,
                                nanos: 0,
                            },
                        )),
                        telegram_api::StarsTransactionPeer::starsTransactionPeer(
                            telegram_api::starsTransactionPeer {
                                peer: Some(telegram_api::Peer::peerUser(telegram_api::peerUser {
                                    user_id: 500,
                                })),
                            },
                        ),
                    );
                    transaction.refund = true;
                    transaction.flags |= (1 << 0) | (1 << 12); // title + subscription_period
                    transaction.title = "Bot Subscription".to_owned();
                    transaction.subscription_period = 30;
                    transaction
                },
                // an invalid amount skips the transaction (cpp:240-242)
                star_test_transaction(
                    "tx4",
                    Some(telegram_api::StarsAmount::starsTonAmount(
                        telegram_api::starsTonAmount { amount: 5 },
                    )),
                    telegram_api::StarsTransactionPeer::starsTransactionPeerPremiumBot(
                        telegram_api::starsTransactionPeerPremiumBot,
                    ),
                ),
                // a bare user peer falls to the unsupported fallback
                // (cpp:777-782)
                star_test_transaction(
                    "tx5",
                    Some(telegram_api::StarsAmount::starsAmount(
                        telegram_api::starsAmount {
                            amount: 1,
                            nanos: 0,
                        },
                    )),
                    telegram_api::StarsTransactionPeer::starsTransactionPeer(
                        telegram_api::starsTransactionPeer {
                            peer: Some(telegram_api::Peer::peerUser(telegram_api::peerUser {
                                user_id: 501,
                            })),
                        },
                    ),
                ),
            ],
            next_offset: "off2".to_owned(),
            chats: vec![],
            users: vec![],
        }
        .store_boxed(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_star_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(transactions)) => {
                assert_eq!(transactions.star_amount.as_ref().unwrap().star_count, 42);
                assert_eq!(transactions.next_offset, "off2");
                assert_eq!(transactions.transactions.len(), 4, "the invalid one skips");
                match &transactions.transactions[0].r#type {
                    Some(td_api::StarTransactionType::starTransactionTypePremiumBotDeposit(_)) => {}
                    other => panic!("unexpected tx1 type: {other:?}"),
                }
                match &transactions.transactions[1].r#type {
                    Some(td_api::StarTransactionType::starTransactionTypeFragmentWithdrawal(
                        withdrawal,
                    )) => match &withdrawal.withdrawal_state {
                        Some(td_api::RevenueWithdrawalState::revenueWithdrawalStateSucceeded(
                            succeeded,
                        )) => {
                            assert_eq!(succeeded.date, 200);
                            assert_eq!(succeeded.url, "https://fragment.example");
                        }
                        other => panic!("unexpected withdrawal state: {other:?}"),
                    },
                    other => panic!("unexpected tx2 type: {other:?}"),
                }
                match &transactions.transactions[2].r#type {
                    Some(
                        td_api::StarTransactionType::starTransactionTypeBotSubscriptionPurchase(
                            subscription,
                        ),
                    ) => {
                        assert_eq!(subscription.user_id, 500);
                        assert_eq!(subscription.subscription_period, 30);
                        assert_eq!(
                            subscription.product_info.as_ref().unwrap().title,
                            "Bot Subscription"
                        );
                    }
                    other => panic!("unexpected tx3 type: {other:?}"),
                }
                assert!(transactions.transactions[2].is_refund);
                assert!(matches!(
                    &transactions.transactions[3].r#type,
                    Some(td_api::StarTransactionType::starTransactionTypeUnsupported(
                        _
                    ))
                ));
            }
            other => panic!("unexpected transactions result: {other:?}"),
        }
        // the own-dialog balance update went out (cpp:804-806)
        assert!(
            td.star_updates
                .iter()
                .any(|update| matches!(update, td_api::Update::updateOwnedStarCount(_)))
        );

        // 2. the by-id reload — payments.getStarsTransactionsByID with
        //    the refund bit; the Unit promise rides the answer.
        let (promise, slot) = record_ton_unit();
        with_star_manager(&mut td, |manager, env| {
            manager.reload_star_transaction(env, my_dialog_id, "tx1".to_owned(), true, promise);
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::payments_getStarsTransactionsByID::ID
        );
        let wire = telegram_api::payments_getStarsTransactionsByID::parse(sent[0].query()).unwrap();
        assert!(!wire.ton);
        assert_eq!(wire.id.len(), 1);
        assert_eq!(wire.id[0].id, "tx1");
        assert!(wire.id[0].refund);
        let mut answer = Vec::new();
        telegram_api::payments_StarsStatus {
            flags: 0,
            balance: Some(telegram_api::StarsAmount::starsAmount(
                telegram_api::starsAmount {
                    amount: 42,
                    nanos: 0,
                },
            )),
            subscriptions: vec![],
            subscriptions_next_offset: String::new(),
            subscriptions_missing_balance: 0,
            history: vec![],
            next_offset: String::new(),
            chats: vec![],
            users: vec![],
        }
        .store_boxed(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_star_net();
        assert!(matches!(
            slot.lock().unwrap().take(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 3. the send-leg no-peer band — an unknown channel resolves no
        //    write peer; the C++ on_error 400 answers the promise
        //    (StarManager.cpp:174-176).
        let unknown_channel = crate::dialog_id::DialogId::new(-1_000_000_999_999);
        let (promise, slot) = record_star_transactions();
        with_star_manager(&mut td, |manager, env| {
            manager.get_star_transactions(
                env,
                unknown_channel,
                String::new(),
                String::new(),
                10,
                None,
                promise,
            );
        });
        td.dispatch_completed_star_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.code(), 400);
                assert_eq!(status.message(), "Have no access to the chat");
            }
            other => panic!("unexpected no-peer result: {other:?}"),
        }

        // 4. getTonTransactions — the ton flag over the self peer, the
        //    TON ladder and the unconditional owned-ton update.
        let (promise, slot) = record_ton_transactions();
        with_star_manager(&mut td, |manager, env| {
            manager.get_ton_transactions(env, String::new(), 5, None, promise);
        });
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::payments_getStarsTransactions::ID
        );
        let wire = telegram_api::payments_getStarsTransactions::parse(sent[0].query()).unwrap();
        assert!(wire.ton);
        assert!(!wire.ascending);
        assert!(!wire.inbound && !wire.outbound);
        assert_eq!(wire.limit, 5);

        let mut answer = Vec::new();
        telegram_api::payments_StarsStatus {
            flags: 1 << 3, // history
            balance: Some(telegram_api::StarsAmount::starsTonAmount(
                telegram_api::starsTonAmount {
                    amount: 90_000_000_000,
                },
            )),
            subscriptions: vec![],
            subscriptions_next_offset: String::new(),
            subscriptions_missing_balance: 0,
            history: vec![
                // a gifted Fragment deposit (no withdrawal state)
                {
                    let mut transaction = star_test_transaction(
                        "ton1",
                        Some(telegram_api::StarsAmount::starsTonAmount(
                            telegram_api::starsTonAmount { amount: 100 },
                        )),
                        telegram_api::StarsTransactionPeer::starsTransactionPeerFragment(
                            telegram_api::starsTransactionPeerFragment,
                        ),
                    );
                    transaction.gift = true;
                    transaction
                },
                // a stake-dice stake (the prod-DC id, an expense)
                star_test_transaction(
                    "ton2",
                    Some(telegram_api::StarsAmount::starsTonAmount(
                        telegram_api::starsTonAmount { amount: -500 },
                    )),
                    telegram_api::StarsTransactionPeer::starsTransactionPeer(
                        telegram_api::starsTransactionPeer {
                            peer: Some(telegram_api::Peer::peerUser(telegram_api::peerUser {
                                user_id: 8353936423,
                            })),
                        },
                    ),
                ),
                // an invalid amount skips (the stars band)
                star_test_transaction(
                    "ton3",
                    Some(telegram_api::StarsAmount::starsAmount(
                        telegram_api::starsAmount {
                            amount: 5,
                            nanos: 0,
                        },
                    )),
                    telegram_api::StarsTransactionPeer::starsTransactionPeerFragment(
                        telegram_api::starsTransactionPeerFragment,
                    ),
                ),
            ],
            next_offset: String::new(),
            chats: vec![],
            users: vec![],
        }
        .store_boxed(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_star_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(transactions)) => {
                assert_eq!(transactions.gram_amount, 90_000_000_000);
                assert_eq!(transactions.transactions.len(), 2);
                match &transactions.transactions[0].r#type {
                    Some(td_api::TonTransactionType::tonTransactionTypeFragmentDeposit(
                        deposit,
                    )) => {
                        assert!(deposit.is_gift);
                        assert!(deposit.sticker.is_none(), "the ton-gift sticker seam parks");
                    }
                    other => panic!("unexpected ton1 type: {other:?}"),
                }
                assert!(matches!(
                    &transactions.transactions[1].r#type,
                    Some(td_api::TonTransactionType::tonTransactionTypeStakeDiceStake(_))
                ));
            }
            other => panic!("unexpected ton transactions result: {other:?}"),
        }
        // the TON balance always refreshes the owned count (cpp:1001)
        assert!(
            td.star_updates
                .iter()
                .any(|update| matches!(update, td_api::Update::updateOwnedGramCount(_)))
        );

        assert!(td.star_net_completed.lock().is_empty(), "drained");
    }

