    fn user_emoji_status_queries_ride_the_dispatcher_impl() {
        let (mut td, rec) = netted_td("netfix-user-emoji-statuses");

        // 1. getDefaultEmojiStatuses — no cache: the query rides the
        //    dispatcher (the fresh-record hash is -1), the answer saves
        //    the record and flushes the queue.
        let (promise, slot) = record_custom_emoji_list();
        with_user_manager(&mut td, |manager, env| {
            manager.get_default_emoji_statuses(env, promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_getDefaultEmojiStatuses::ID,
        );
        net_complete(sent, emoji_status_answer(7, 42));
        td.dispatch_completed_user_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Ok(list)) => {
                assert_eq!(list.custom_emoji_ids, vec![42]);
            }
            other => panic!("the default list: {other:?}"),
        }

        // 2. the cached record answers without a query (the C++
        //    set_value-then-send band).
        let (promise, slot) = record_custom_emoji_list();
        with_user_manager(&mut td, |manager, env| {
            manager.get_default_emoji_statuses(env, promise);
        });
        assert!(rec.sent.lock().is_empty(), "the cache answers locally");
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Ok(list)) => {
                assert_eq!(list.custom_emoji_ids, vec![42]);
            }
            other => panic!("the cached list: {other:?}"),
        }

        // 3. getDefaultChatEmojiStatuses — the channel family rides its
        //    own constructor and queue.
        let (promise, slot) = record_custom_emoji_list();
        with_user_manager(&mut td, |manager, env| {
            manager.get_default_channel_emoji_statuses(env, promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_getChannelDefaultEmojiStatuses::ID,
        );
        net_complete(sent, emoji_status_answer(9, 100));
        td.dispatch_completed_user_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Ok(list)) => {
                assert_eq!(list.custom_emoji_ids, vec![100]);
            }
            other => panic!("the channel list: {other:?}"),
        }

        // 4. the error band forwards — the query tail's on_error.
        let (promise, slot) = record_statuses_list();
        with_user_manager(&mut td, |manager, env| {
            manager.get_recent_emoji_statuses(env, promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_getRecentEmojiStatuses::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_7");
        td.dispatch_completed_user_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.code(), 420);
                assert_eq!(status.message(), "FLOOD_WAIT_7");
            }
            other => panic!("the error band: {other:?}"),
        }

        // 5. getRecentEmojiStatuses — the notModified band answers the
        //    C++ 500 (the error band saved no record).
        let (promise, slot) = record_statuses_list();
        with_user_manager(&mut td, |manager, env| {
            manager.get_recent_emoji_statuses(env, promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_getRecentEmojiStatuses::ID,
        );
        let mut answer = Vec::new();
        telegram_api::account_EmojiStatuses::account_emojiStatusesNotModified(
            telegram_api::account_emojiStatusesNotModified,
        )
        .store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_user_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.code(), 500);
                assert_eq!(status.message(), "Receive wrong server response");
            }
            other => panic!("the notModified band: {other:?}"),
        }

        // 6. getUpgradedGiftEmojiStatuses — the collectible family.
        let (promise, slot) = record_statuses_list();
        with_user_manager(&mut td, |manager, env| {
            manager.get_upgraded_gift_emoji_statuses(env, promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_getCollectibleEmojiStatuses::ID,
        );
        net_complete(sent, emoji_status_answer(3, 5));
        td.dispatch_completed_user_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Ok(statuses)) => {
                assert_eq!(statuses.emoji_statuses.len(), 1);
            }
            other => panic!("the collectible list: {other:?}"),
        }

        // 7. clearRecentEmojiStatuses — the Bool answer resolves the ok
        //    (and writes the recent record's empty form).
        let slot: UnitSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
        let promise = {
            struct Rec(UnitSlot);
            impl tdutils::promise::PromiseInterface<()> for Rec {
                fn set_value(&mut self, value: ()) {
                    *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
                }
                fn set_error(&mut self, error: Status) {
                    *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
                }
            }
            Promise::from_interface(Rec(slot.clone()))
        };
        with_user_manager(&mut td, |manager, env| {
            manager.clear_recent_emoji_statuses(env, promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_clearRecentEmojiStatuses::ID,
        );
        net_complete(sent, 0x9972_75b5u32.to_le_bytes().to_vec());
        td.dispatch_completed_user_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    // ---- the users-core net slice (§3.1 #1-#3): the GetUserMerger and
    // the premium-required merger ride the dispatcher through their Td
    // merge-function messages, the GetUserFullCombiner through its send
    // leg. The merger/combiner actors need the scheduler context, so the
    // netted harness drives the exact message code the actors run. ----

    /// One wire user record with a full access hash and a first name
    /// (the `on_get_users` intake accepts it as received).
    fn wire_user(id: i64, first_name: &str) -> telegram_api::User {
        telegram_api::User::user(telegram_api::user {
            flags: 1 | (1 << 1), // access_hash present + first_name, not min
            access_hash: 42,
            id,
            first_name: first_name.to_owned(),
            ..telegram_api::user::default()
        })
    }

    /// A boxed `Vector<User>` answer (the users.getUsers result shape).
    fn users_vector_answer(user: telegram_api::User) -> Vec<u8> {
        let mut answer = Vec::new();
        answer.extend_from_slice(&telegram_api::tl::VECTOR_ID.to_le_bytes());
        answer.extend_from_slice(&1i32.to_le_bytes());
        user.store(&mut answer);
        answer
    }

    /// A boxed `Vector<RequirementToContact>` answer (the
    /// users.getRequirementsToContact result shape).
    fn requirements_vector_answer(requirement: telegram_api::RequirementToContact) -> Vec<u8> {
        let mut answer = Vec::new();
        answer.extend_from_slice(&telegram_api::tl::VECTOR_ID.to_le_bytes());
        answer.extend_from_slice(&1i32.to_le_bytes());
        requirement.store(&mut answer);
        answer
    }

    /// The sent payload of a query, parsed back into the function.
    fn sent_function(query: &NetQuery) -> telegram_api::Function {
        telegram_api::Function::parse(query.query()).expect("the sent payload parses")
    }

    #[test]
    fn user_get_users_merger_round_trips() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(user_get_users_merger_round_trips_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn user_get_users_merger_round_trips_impl() {
        let (mut td, rec) = netted_td("netfix-user-get-users");

        // 1. the merge-function half (cpp:2798-2802): the merged batch
        //    dispatches users.getUsers with the force input users (the
        //    unknown id takes the zero access-hash form).
        let (promise, slot) = record_ton_unit();
        tdactor::ActorMessage::dispatch(
            MergeGetUserQueries {
                user_ids: vec![5],
                promise,
            },
            &mut td,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_getUsers::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::users_getUsers(payload) => match &payload.id[..] {
                [telegram_api::InputUser::inputUser(input_user)] => {
                    assert_eq!((input_user.user_id, input_user.access_hash), (5, 0));
                }
                other => panic!("the merged payload: {other:?}"),
            },
            other => panic!("the sent function: {other:?}"),
        }

        // 2. the happy-path answer: on_get_users caches the record and
        //    the merger's result promise flushes (cpp:1427-1438).
        net_complete(sent, users_vector_answer(wire_user(5, "Alice")));
        td.dispatch_completed_user_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));
        assert!(
            td.user_manager
                .have_min_user(crate::user_manager::UserId::new(5))
        );

        // 3. the error band forwards to the promise (the handler's
        //    on_error, cpp:1440-1444)
        let (promise, slot) = record_ton_unit();
        tdactor::ActorMessage::dispatch(
            MergeGetUserQueries {
                user_ids: vec![5],
                promise,
            },
            &mut td,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_getUsers::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_5");
        td.dispatch_completed_user_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!((status.code(), status.message()), (420, "FLOOD_WAIT_5"));
            }
            other => panic!("the error band: {other:?}"),
        }

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn user_get_full_user_round_trips() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(user_get_full_user_round_trips_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn user_get_full_user_round_trips_impl() {
        let (mut td, rec) = netted_td("netfix-user-get-full");

        // 1. the combiner's send leg (`GetFullUserQuery::send`, the
        //    send_query lambda resolution of cpp:8963-8970): the query
        //    goes out with the parked result promise.
        let (promise, slot) = record_ton_unit();
        let input_user = telegram_api::InputUser::inputUser(telegram_api::inputUser {
            user_id: 5,
            access_hash: 42,
        });
        td.user_manager
            .send_get_full_user_query(input_user, promise);
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_getFullUser::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::users_getFullUser(payload) => {
                let telegram_api::InputUser::inputUser(input_user) =
                    payload.id.expect("the input user rides the query")
                else {
                    panic!("the full-user query rides a concrete input user");
                };
                assert_eq!((input_user.user_id, input_user.access_hash), (5, 42));
            }
            other => panic!("the sent function: {other:?}"),
        }

        // 2. the happy-path answer (cpp:1469-1476): the users pre-apply,
        //    the full record caches, the promise flushes. The chats
        //    vector carries the community family + a channel: the arm
        //    funnels through the shared chats intake, so the community
        //    rides the community-first hop to the community cache and
        //    the channel remainder reaches ChatManager (#143; the
        //    users → chats → full order of UserManager.cpp:1485-1487)
        let mut answer = Vec::new();
        telegram_api::users_UserFull {
            full_user: Some(telegram_api::UserFull {
                id: 5,
                ..telegram_api::UserFull::default()
            }),
            chats: vec![
                telegram_api::Chat::community(telegram_api::community {
                    // creator (flags.0) + the access-hash presence bit
                    // (flags.13): the answer round-trips through
                    // store/parse, so the hash needs its TL presence bit
                    // or the intake's non-min gate drops the community
                    flags: 1 | (1 << 13),
                    creator: true,
                    left: false,
                    min: false,
                    flags2: 0,
                    collapsed_in_dialogs: true,
                    id: 7,
                    access_hash: 11,
                    title: "My community".to_owned(),
                    photo: None,
                    date: 10,
                    admin_rights: None,
                    default_banned_rights: None,
                }),
                telegram_api::Chat::channel(wire_channel(3, "the personal chat")),
            ],
            users: vec![wire_user(5, "Alice")],
        }
        .store_boxed(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_user_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));
        assert!(
            td.user_manager
                .get_user_full(crate::user_manager::UserId::new(5))
                .is_some()
        );
        with_community_manager(&mut td, |manager, _| {
            assert!(
                manager
                    .get_community_object(crate::community_id::CommunityId::new(7))
                    .expect("the answer's community chat reaches the community cache")
                    .are_chats_collapsed
            );
        });
        assert!(
            td.chat_manager
                .have_channel(crate::chat_manager::ChannelId::new(3)),
            "the channel remainder reaches ChatManager"
        );

        // 3. the error band forwards to the promise (cpp:1478-1481)
        let (promise, slot) = record_ton_unit();
        td.user_manager.send_get_full_user_query(
            telegram_api::InputUser::inputUser(telegram_api::inputUser {
                user_id: 5,
                access_hash: 42,
            }),
            promise,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_getFullUser::ID,
        );
        net_fail(sent, 400, "USER_ID_INVALID");
        td.dispatch_completed_user_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!((status.code(), status.message()), (400, "USER_ID_INVALID"));
            }
            other => panic!("the error band: {other:?}"),
        }

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn user_requirements_to_contact_round_trips() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(user_requirements_to_contact_round_trips_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn user_requirements_to_contact_round_trips_impl() {
        let (mut td, rec) = netted_td("netfix-user-requirements");

        // seed a received user so the input-user build rides its access
        // hash (the merge function's transform, cpp:2803-2811)
        with_user_manager(&mut td, |manager, env| {
            manager.on_get_users(env, vec![wire_user(7, "Bob")], "t");
        });

        // 1. the merge-function half: the merged query dispatches with
        //    the user's access hash.
        let (promise, slot) = record_ton_unit();
        tdactor::ActorMessage::dispatch(
            MergePremiumRequiredContactQueries {
                user_ids: vec![7],
                promise,
            },
            &mut td,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_getRequirementsToContact::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::users_getRequirementsToContact(payload) => {
                match &payload.id[..] {
                    [telegram_api::InputUser::inputUser(input_user)] => {
                        assert_eq!((input_user.user_id, input_user.access_hash), (7, 42));
                    }
                    other => panic!("the merged payload: {other:?}"),
                }
            }
            other => panic!("the sent function: {other:?}"),
        }

        // 2. the premium-required answer caches the price and flushes
        //    the promise (cpp:1788-1798 + the intake cpp:7854-7882)
        net_complete(
            sent,
            requirements_vector_answer(
                telegram_api::RequirementToContact::requirementToContactPremium(
                    telegram_api::requirementToContactPremium,
                ),
            ),
        );
        td.dispatch_completed_user_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));
        assert!(
            td.user_manager
                .get_user_full(crate::user_manager::UserId::new(7))
                .is_none()
        );

        // 3. the length-mismatch band answers the C++ 500 (the intake's
        //    error, cpp:7860-7863)
        let (promise, slot) = record_ton_unit();
        tdactor::ActorMessage::dispatch(
            MergePremiumRequiredContactQueries {
                user_ids: vec![7, 8],
                promise,
            },
            &mut td,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_getRequirementsToContact::ID,
        );
        net_complete(
            sent,
            requirements_vector_answer(
                telegram_api::RequirementToContact::requirementToContactEmpty(
                    telegram_api::requirementToContactEmpty,
                ),
            ),
        );
        td.dispatch_completed_user_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(
                    (status.code(), status.message()),
                    (500, "Receive invalid response")
                );
            }
            other => panic!("the mismatch band: {other:?}"),
        }

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    // ---- the user acks & setters net slice (§3.1 #4-#6, #8, #29): the
    // note/tab/birthday setters, the support-user query and the emoji
    // status ride the dispatcher through their live td_api arms. ----

    #[test]
    fn user_acks_and_setters_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(user_acks_and_setters_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn user_acks_and_setters_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-user-setters");

        // me, a contact, a plain peer, and my full record (the
        // main-profile-tab write target)
        let wire_flags_user =
            |id: i64, name: &str, extra_flags: i32, contact: bool, support: bool| {
                telegram_api::User::user(telegram_api::user {
                    flags: 1 | (1 << 1) | extra_flags,
                    access_hash: 42,
                    id,
                    first_name: name.to_owned(),
                    contact,
                    support,
                    ..telegram_api::user::default()
                })
            };
        with_user_manager(&mut td, |manager, env| {
            manager.set_my_id(env, crate::user_manager::UserId::new(700000001));
            manager.on_get_user(env, wire_flags_user(700000001, "Me", 0, false, false), "t");
            manager.on_get_user(env, wire_flags_user(5, "Alice", 1 << 11, true, false), "t");
            manager.on_get_user(env, wire_flags_user(6, "Bob", 0, false, false), "t");
            manager.on_get_user_full(
                env,
                telegram_api::UserFull {
                    id: 700000001,
                    ..telegram_api::UserFull::default()
                },
            );
        });

        // 1. setUserNote — the contact/self gates and the text
        //    normalization pass; the query rides the concrete input user
        //    and the wire note, the ok ack resolves the request.
        td.request(
            1,
            Function::setUserNote(td_api::setUserNote {
                user_id: 5,
                note: Some(td_api::FormattedText {
                    text: "the note".to_owned(),
                    entities: Vec::new(),
                }),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_updateContactNote::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::contacts_updateContactNote(payload) => {
                let telegram_api::InputUser::inputUser(input_user) =
                    payload.id.expect("the input user rides the query")
                else {
                    panic!("the note peer must be a concrete input user");
                };
                assert_eq!((input_user.user_id, input_user.access_hash), (5, 42));
                let note = payload.note.expect("the note rides the query");
                assert_eq!(note.text, "the note");
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. the query error band forwards to the request promise
        td.request(
            2,
            Function::setUserNote(td_api::setUserNote {
                user_id: 5,
                note: Some(td_api::FormattedText {
                    text: "again".to_owned(),
                    entities: Vec::new(),
                }),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_updateContactNote::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_9");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 2) {
            Some((_, error)) => {
                assert_eq!(error.code, 420);
                assert_eq!(error.message, "FLOOD_WAIT_9");
            }
            None => panic!("the note error band never fired"),
        }

        // 3. setMainProfileTab — the Gifts tab rides the query, the ok
        //    ack writes my user_full record
        td.request(
            3,
            Function::setMainProfileTab(td_api::setMainProfileTab {
                main_profile_tab: Some(td_api::ProfileTab::profileTabGifts(
                    td_api::profileTabGifts {},
                )),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_setMainProfileTab::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::account_setMainProfileTab(payload) => {
                assert!(matches!(
                    payload.tab,
                    Some(telegram_api::ProfileTab::profileTabGifts(_))
                ));
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 3).first(),
            Some(Object::ok(_))
        ));
        assert_eq!(
            td.user_manager
                .get_user_full(crate::user_manager::UserId::new(700000001))
                .unwrap()
                .main_profile_tab,
            crate::chat_manager::ProfileTab::Gifts
        );

        // 4. the false band answers the C++ 400
        td.request(
            4,
            Function::setMainProfileTab(td_api::setMainProfileTab {
                main_profile_tab: Some(td_api::ProfileTab::profileTabPosts(
                    td_api::profileTabPosts {},
                )),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_setMainProfileTab::ID,
        );
        net_complete(sent, bool_answer(false));
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 4) {
            Some((_, error)) => {
                assert_eq!(error.code, 400);
                assert_eq!(error.message, "Failed to change main profile tab");
            }
            None => panic!("the tab false band never fired"),
        }

        // 5. suggestUserBirthdate — the birthday rides the query, the
        //    Updates answer re-enters on_get_updates and resolves ok
        td.request(
            5,
            Function::suggestUserBirthdate(td_api::suggestUserBirthdate {
                user_id: 6,
                birthdate: Some(td_api::Birthdate {
                    day: 10,
                    month: 6,
                    year: 1990,
                }),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_suggestBirthday::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::users_suggestBirthday(payload) => {
                let telegram_api::InputUser::inputUser(input_user) =
                    payload.id.expect("the input user rides the query")
                else {
                    panic!("the birthday peer must be a concrete input user");
                };
                assert_eq!((input_user.user_id, input_user.access_hash), (6, 42));
                let birthday = payload.birthday.expect("the birthday rides the query");
                assert_eq!(birthday.flags, 1, "the year bit");
                assert_eq!((birthday.day, birthday.month, birthday.year), (10, 6, 1990));
            }
            other => panic!("the sent function: {other:?}"),
        }
        let mut answer = Vec::new();
        telegram_api::Updates::updates(telegram_api::updates {
            updates: Vec::new(),
            users: Vec::new(),
            chats: Vec::new(),
            date: 0,
            seq: 0,
        })
        .store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 5).first(),
            Some(Object::ok(_))
        ));

        // 6. getSupportUser — the query error band fails the parked
        //    promises first (cpp:1766-1769 + the manager's lambda)
        td.request(11, Function::getSupportUser(td_api::getSupportUser));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::help_getSupport::ID,
        );
        net_fail(sent, 400, "SUPPORT_UNAVAILABLE");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 11) {
            Some((_, error)) => {
                assert_eq!(error.code, 400);
                assert_eq!(error.message, "SUPPORT_UNAVAILABLE");
            }
            None => panic!("the support error band never fired"),
        }

        // 7. the ok leg — the answer registers the support user and
        //    resolves the object; the cached id answers without a query
        td.request(6, Function::getSupportUser(td_api::getSupportUser));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::help_getSupport::ID,
        );
        let mut answer = Vec::new();
        telegram_api::help_Support {
            phone_number: String::new(),
            user: Some(wire_flags_user(777, "Support", 1 << 23, false, true)),
        }
        .store_boxed(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        match responses_of(&callback, 6).first() {
            Some(Object::user(user)) => {
                assert_eq!(user.id, 777);
                assert!(user.is_support);
            }
            other => panic!("the support user object: {other:?}"),
        }
        td.request(7, Function::getSupportUser(td_api::getSupportUser));
        assert!(rec.sent.lock().is_empty(), "the cached id answers locally");
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 7).first(),
            Some(Object::user(user)) if user.id == 777
        ));

        // 8. setEmojiStatus without premium answers the 400 gate
        td.request(
            8,
            Function::setEmojiStatus(td_api::setEmojiStatus { emoji_status: None }),
        );
        assert!(
            rec.sent.lock().is_empty(),
            "the gate answers before the send"
        );
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 8) {
            Some((_, error)) => {
                assert_eq!(error.code, 400);
                assert_eq!(
                    error.message,
                    "The method is available only to Telegram Premium users"
                );
            }
            None => panic!("the premium gate never fired"),
        }

        // 9. the query error band refetches the recent list before
        //    failing the promise (cpp:1399-1401) — the empty-promise
        //    refire rides the GetRecentEmojiStatuses family
        td.option_manager
            .as_mut()
            .expect("the option manager")
            .set_option_boolean("is_premium", true);
        td.request(
            9,
            Function::setEmojiStatus(td_api::setEmojiStatus { emoji_status: None }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_updateEmojiStatus::ID,
        );
        net_fail(sent, 500, "TESTERR");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 9) {
            Some((_, error)) => {
                assert_eq!(error.code, 500);
                assert_eq!(error.message, "TESTERR");
            }
            None => panic!("the emoji-status error band never fired"),
        }
        let recent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_getRecentEmojiStatuses::ID,
        );
        net_complete(recent, emoji_status_answer(7, 42));
        td.dispatch_completed_user_net();

        // 10. the happy path — the status rides the wire form, the ok
        //    ack applies my user, the recent registry gains the entry
        td.request(
            10,
            Function::setEmojiStatus(td_api::setEmojiStatus {
                emoji_status: Some(td_api::EmojiStatus {
                    r#type: Some(td_api::EmojiStatusType::emojiStatusTypeCustomEmoji(
                        td_api::emojiStatusTypeCustomEmoji {
                            custom_emoji_id: 77,
                        },
                    )),
                    expiration_date: 0,
                }),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_updateEmojiStatus::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::account_updateEmojiStatus(payload) => {
                match payload.emoji_status {
                    Some(telegram_api::EmojiStatus::emojiStatus(status)) => {
                        assert_eq!(status.document_id, 77);
                    }
                    other => panic!("the sent status: {other:?}"),
                }
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 10).first(),
            Some(Object::ok(_))
        ));
        assert!(matches!(
            td.user_manager
                .get_user(crate::user_manager::UserId::new(700000001))
                .unwrap()
                .emoji_status,
            Some(ref status) if status.get_custom_emoji_id().get() == 77
        ));
        let statuses = crate::emoji_status::load_emoji_statuses(
            td.global.binlog_pmc(),
            crate::emoji_status::RECENT_EMOJI_STATUSES_DATABASE_KEY,
        );
        assert_eq!(statuses.hash, 0);
        assert_eq!(statuses.emoji_statuses.len(), 2);
        assert_eq!(statuses.emoji_statuses[0].get_custom_emoji_id().get(), 77);

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    // ---- the profile-photo plane net slice (§3.1 #9, #11-#14): the
    // getUserPhotos listing/reload queries, the prev-photo
    // UpdateProfilePhoto, the contact-photo delete and the
    // DeleteProfilePhoto arms ride the dispatcher; the intakes
    // (on_get_user_photos, on_set_profile_photo,
    // on_delete_profile_photo) run in the drain. ----

    /// One wire photo record with the 'a'/'c' size pair
    /// (`as_profile_photo`'s selection).
    fn wire_photo(id: i64) -> telegram_api::Photo {
        let size = |r#type: &str, dim: i32| {
            telegram_api::PhotoSize::photoSize(telegram_api::photoSize {
                r#type: r#type.to_owned(),
                w: dim,
                h: dim,
                size: dim * dim,
            })
        };
        telegram_api::Photo::photo(telegram_api::photo {
            flags: 0,
            has_stickers: false,
            id,
            access_hash: 5,
            file_reference: b"fr".to_vec(),
            date: 1234,
            sizes: vec![size("a", 5), size("c", 9)],
            video_sizes: Vec::new(),
            dc_id: 2,
        })
    }

    /// A `wire_user` with the contact flag set (the
    /// setUserPersonalProfilePhoto contact gate).
    fn wire_contact_user(id: i64, first_name: &str) -> telegram_api::User {
        let telegram_api::User::user(user) = wire_user(id, first_name) else {
            unreachable!()
        };
        telegram_api::User::user(telegram_api::user {
            flags: user.flags | (1 << 11),
            contact: true,
            ..user
        })
    }

    /// A boxed `photos.photosSlice` answer (the photos.getUserPhotos
    /// result shape).
    fn photos_slice_answer(
        count: i32,
        photos: Vec<telegram_api::Photo>,
        users: Vec<telegram_api::User>,
    ) -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::photos_Photos::photos_photosSlice(telegram_api::photos_photosSlice {
            count,
            photos,
            users,
        })
        .store(&mut answer);
        answer
    }

    /// A boxed `photos.photos` answer (the count-less listing shape).
    fn photos_photos_answer(
        photos: Vec<telegram_api::Photo>,
        users: Vec<telegram_api::User>,
    ) -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::photos_Photos::photos_photos(telegram_api::photos_photos { photos, users })
            .store(&mut answer);
        answer
    }

    /// A boxed `photos.photo` answer (the updateProfilePhoto/
    /// uploadContactProfilePhoto result shape).
    fn photos_photo_answer(
        photo: Option<telegram_api::Photo>,
        users: Vec<telegram_api::User>,
    ) -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::photos_Photo { photo, users }.store_boxed(&mut answer);
        answer
    }

    /// A boxed `Vector<long>` answer (the photos.deletePhotos result
    /// shape).
    fn long_vector_answer(ids: &[i64]) -> Vec<u8> {
        let mut answer = Vec::new();
        answer.extend_from_slice(&telegram_api::tl::VECTOR_ID.to_le_bytes());
        answer.extend_from_slice(&(ids.len() as i32).to_le_bytes());
        for id in ids {
            answer.extend_from_slice(&id.to_le_bytes());
        }
        answer
    }

    /// Register the photo's remote file node under the id the manager's
    /// photo registration parked — the placeholder photo file ids are
    /// all the invalid `FileId(0, 0)` (the Files step makes them real),
    /// so the node stands in for the C++ `get_photo_size` registration
    /// `send_update_profile_photo_query` reads through the file view
    /// (cpp:6094-6107).
    fn seed_profile_photo_file_node(td: &mut Td, photo_id: i64, access_hash: i64) {
        use crate::files::{
            FileEncryptionKey, FileLocationSource, FileNode, FullRemoteFileLocation,
            LocalFileLocation, NewRemoteFileLocation, PhotoSizeSource,
        };
        let full = FullRemoteFileLocation::from_photo(
            PhotoSizeSource::thumbnail(crate::files::FileType::Photo, b'a' as i32),
            photo_id,
            access_hash,
            ChatDcId::internal(2),
            "ref7".to_owned(),
        );
        let node = FileNode::new(
            LocalFileLocation::Empty,
            NewRemoteFileLocation {
                partial: None,
                full: Some(full),
                is_full_alive: true,
                full_source: FileLocationSource::FromServer,
            },
            None,
            0,
            0,
            String::new(),
            String::new(),
            crate::messages_manager::DialogId::default(),
            FileEncryptionKey::default(),
            crate::files::FileId::new(0, 0),
            0,
        );
        td.file_manager
            .lock()
            .register_file_node(crate::files::FileId::new(0, 0), 0, node);
    }

    #[test]
    fn user_get_user_photos_round_trips() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(user_get_user_photos_round_trips_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn user_get_user_photos_round_trips_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-user-get-photos");
        with_user_manager(&mut td, |manager, env| {
            manager.on_get_users(env, vec![wire_user(5, "Alice")], "t");
        });

        // 1. the live getUserProfilePhotos arm: the cache miss parks the
        //    request and the query rides the input user with the raised
        //    limit (cpp:6890-6911 — max(limit, MAX_GET_PROFILE_PHOTOS/5))
        td.request(
            1,
            Function::getUserProfilePhotos(td_api::getUserProfilePhotos {
                user_id: 5,
                offset: 0,
                limit: 10,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_getUserPhotos::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::photos_getUserPhotos(payload) => {
                let telegram_api::InputUser::inputUser(input_user) =
                    payload.user_id.expect("the input user rides the query")
                else {
                    panic!("the photos query rides a concrete input user");
                };
                assert_eq!((input_user.user_id, input_user.access_hash), (5, 42));
                assert_eq!((payload.offset, payload.max_id, payload.limit), (0, 0, 20));
            }
            other => panic!("the sent function: {other:?}"),
        }

        // 2. the answer: the users intake, the photos cache fill and the
        //    retry machine answer the request from the fresh cache
        //    (cpp:1494-1531)
        net_complete(
            sent,
            photos_slice_answer(1, vec![wire_photo(31)], vec![wire_user(5, "Alice")]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let responses = responses_of(&callback, 1);
        let Object::chatPhotos(photos) = &responses[0] else {
            panic!("getUserProfilePhotos answers chatPhotos, got {responses:?}");
        };
        assert_eq!(photos.total_count, 1);
        assert_eq!(photos.photos.len(), 1);
        assert!(
            td.user_manager
                .get_user(crate::user_manager::UserId::new(5))
                .expect("the user record")
                .photo_ids
                .contains(&31)
        );

        // 3. the cached window answers without a query
        td.request(
            2,
            Function::getUserProfilePhotos(td_api::getUserProfilePhotos {
                user_id: 5,
                offset: 0,
                limit: 1,
            }),
        );
        td.flush_deferred_results();
        assert!(rec.sent.lock().is_empty(), "the cache answers locally");
        let responses = responses_of(&callback, 2);
        let Object::chatPhotos(photos) = &responses[0] else {
            panic!("the cached window answers chatPhotos, got {responses:?}");
        };
        assert_eq!(photos.total_count, 1);

        // 4. the error band forwards to the parked request (the
        //    handler's on_error → the retry machine error arm)
        with_user_manager(&mut td, |manager, env| {
            manager.on_get_users(env, vec![wire_user(6, "Bob")], "t");
        });
        td.request(
            3,
            Function::getUserProfilePhotos(td_api::getUserProfilePhotos {
                user_id: 6,
                offset: 0,
                limit: 10,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_getUserPhotos::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_7");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "FLOOD_WAIT_7");

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn user_profile_photo_reload_round_trips() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(user_profile_photo_reload_round_trips_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn user_profile_photo_reload_round_trips_impl() {
        let (mut td, rec) = netted_td("netfix-user-photo-reload");
        with_user_manager(&mut td, |manager, env| {
            manager.on_get_users(env, vec![wire_user(5, "Alice")], "t");
        });

        // 1. the offset -1 reload: the query carries the photo id and
        //    the caller promise rides the query (cpp:6988-6992 — the §5
        //    fidelity restore)
        let (promise, slot) = record_ton_unit();
        with_user_manager(&mut td, |manager, env| {
            manager.reload_user_profile_photo(
                env,
                crate::user_manager::UserId::new(5),
                31,
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_getUserPhotos::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::photos_getUserPhotos(payload) => {
                let telegram_api::InputUser::inputUser(input_user) =
                    payload.user_id.expect("the input user rides the query")
                else {
                    panic!("the reload query rides a concrete input user");
                };
                assert_eq!(input_user.user_id, 5);
                assert_eq!((payload.offset, payload.max_id, payload.limit), (-1, 31, 1));
            }
            other => panic!("the sent function: {other:?}"),
        }

        // 2. the answer: the offset -1 intake registers the photo and
        //    the query-carried promise resolves (cpp:7044-7064)
        net_complete(sent, photos_photos_answer(vec![wire_photo(31)], Vec::new()));
        td.dispatch_completed_user_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));
        assert!(
            td.user_manager
                .get_user(crate::user_manager::UserId::new(5))
                .expect("the user record")
                .photo_ids
                .contains(&31)
        );

        // 3. the error band fails the query-carried promise
        let (promise, slot) = record_ton_unit();
        with_user_manager(&mut td, |manager, env| {
            manager.reload_user_profile_photo(
                env,
                crate::user_manager::UserId::new(5),
                99,
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_getUserPhotos::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_3");
        td.dispatch_completed_user_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!((status.code(), status.message()), (420, "FLOOD_WAIT_3"));
            }
            other => panic!("the error band: {other:?}"),
        }

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn user_prev_profile_photo_round_trips() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(user_prev_profile_photo_round_trips_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn user_prev_profile_photo_round_trips_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-user-prev-photo");
        tdactor::ActorMessage::dispatch(SeedMyId(500), &mut td);
        with_user_manager(&mut td, |manager, env| {
            manager.on_get_users(env, vec![wire_user(500, "Me")], "t");
        });

        // seed my photo registration through the getUserPhotos flow (the
        // natural intake — register_user_photo's my_photo_file_id row)
        td.request(
            1,
            Function::getUserProfilePhotos(td_api::getUserProfilePhotos {
                user_id: 500,
                offset: 0,
                limit: 10,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_getUserPhotos::ID,
        );
        net_complete(
            sent,
            photos_slice_answer(1, vec![wire_photo(7)], vec![wire_user(500, "Me")]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert_eq!(responses_of(&callback, 1).len(), 1);

        // 1. the registered photo without a file node is the C++ 500
        //    (the file-view gate of send_update_profile_photo_query,
        //    cpp:6100-6103 — the registration the Files step provides)
        td.request(
            2,
            Function::setProfilePhoto(td_api::setProfilePhoto {
                photo: Some(td_api::InputChatPhoto::inputChatPhotoPrevious(
                    td_api::inputChatPhotoPrevious { chat_photo_id: 7 },
                )),
                is_public: false,
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 2);
        assert_eq!(error.code, 500);
        assert_eq!(error.message, "Failed to upload the file");

        // 2. with the node the prev-photo arm sends
        //    photos.updateProfilePhoto with the file view's input photo
        //    (cpp:6027-6030 + 671-691)
        seed_profile_photo_file_node(&mut td, 7, 77);
        td.request(
            3,
            Function::setProfilePhoto(td_api::setProfilePhoto {
                photo: Some(td_api::InputChatPhoto::inputChatPhotoPrevious(
                    td_api::inputChatPhotoPrevious { chat_photo_id: 7 },
                )),
                is_public: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_updateProfilePhoto::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::photos_updateProfilePhoto(payload) => {
                assert!(!payload.fallback, "the own-photo arm carries no bot");
                assert!(payload.bot.is_none());
                match payload.id {
                    Some(telegram_api::InputPhoto::inputPhoto(photo)) => {
                        assert_eq!((photo.id, photo.access_hash), (7, 77));
                        assert_eq!(photo.file_reference, b"ref7".to_vec());
                    }
                    other => panic!("the input photo: {other:?}"),
                }
            }
            other => panic!("the sent function: {other:?}"),
        }

        // 3. the answer: on_set_profile_photo deletes the replaced
        //    photo from the cache, re-adds the new one and completes
        //    the promise with the user riding the answer (cpp:6190-6214)
        net_complete(
            sent,
            photos_photo_answer(Some(wire_photo(7)), vec![wire_user(500, "Me")]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 3).first(),
            Some(Object::ok(_))
        ));

        // 4. the unknown photo id band answers the C++ 400 with no query
        td.request(
            4,
            Function::setProfilePhoto(td_api::setProfilePhoto {
                photo: Some(td_api::InputChatPhoto::inputChatPhotoPrevious(
                    td_api::inputChatPhotoPrevious { chat_photo_id: 99 },
                )),
                is_public: false,
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Unknown profile photo ID specified");
        assert!(rec.sent.lock().is_empty(), "no query went out");

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn user_contact_profile_photo_delete_round_trips() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(user_contact_profile_photo_delete_round_trips_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn user_contact_profile_photo_delete_round_trips_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-user-contact-photo-del");
        with_user_manager(&mut td, |manager, env| {
            manager.on_get_users(env, vec![wire_contact_user(5, "Alice")], "t");
            manager.on_get_user_full(
                env,
                telegram_api::UserFull {
                    id: 5,
                    flags: 1 << 21, // personal_photo present
                    personal_photo: Some(wire_photo(31)),
                    ..telegram_api::UserFull::default()
                },
            );
        });

        // 1. the null-photo arm of setUserPersonalProfilePhoto sends
        //    photos.uploadContactProfilePhoto with save=true
        //    (cpp:766-786)
        td.request(
            1,
            Function::setUserPersonalProfilePhoto(td_api::setUserPersonalProfilePhoto {
                user_id: 5,
                photo: None,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_uploadContactProfilePhoto::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::photos_uploadContactProfilePhoto(payload) => {
                assert!(!payload.suggest);
                assert!(payload.save, "the delete arm is the save-only form");
                assert!(payload.file.is_none() && payload.video.is_none());
                let telegram_api::InputUser::inputUser(input_user) =
                    payload.user_id.expect("the input user rides the query")
                else {
                    panic!("the delete query rides a concrete input user");
                };
                assert_eq!((input_user.user_id, input_user.access_hash), (5, 42));
            }
            other => panic!("the sent function: {other:?}"),
        }

        // 2. the answer: the photo is nulled before the
        //    on_set_profile_photo tail (cpp:789-793) — the empty photo
        //    always applies to the personal slot (cpp:6246-6249)
        net_complete(
            sent,
            photos_photo_answer(Some(wire_photo(31)), vec![wire_contact_user(5, "Alice")]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));
        let user_full = td
            .user_manager
            .get_user_full(crate::user_manager::UserId::new(5))
            .expect("the seeded user full");
        assert!(
            user_full.personal_photo.is_empty(),
            "the personal photo resets"
        );

        // 3. the error band forwards (cpp:795-797)
        td.request(
            2,
            Function::setUserPersonalProfilePhoto(td_api::setUserPersonalProfilePhoto {
                user_id: 5,
                photo: None,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_uploadContactProfilePhoto::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_5");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 2);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "FLOOD_WAIT_5");

        // 4. a non-contact user answers the C++ 400
        with_user_manager(&mut td, |manager, env| {
            manager.on_get_users(env, vec![wire_user(6, "Bob")], "t");
        });
        td.request(
            3,
            Function::setUserPersonalProfilePhoto(td_api::setUserPersonalProfilePhoto {
                user_id: 6,
                photo: None,
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "User isn't a contact");

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn user_delete_profile_photo_round_trips() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(user_delete_profile_photo_round_trips_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn user_delete_profile_photo_round_trips_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-user-del-photo");
        tdactor::ActorMessage::dispatch(SeedMyId(500), &mut td);
        with_user_manager(&mut td, |manager, env| {
            manager.on_get_users(env, vec![wire_user(500, "Me")], "t");
        });

        // 1. the unloaded UserFull without the Td-actor hop answers the
        //    net-inert 500 (the uncached-consumer convention — the
        //    reload ladder's combiner ride needs the scheduler context)
        td.request(
            1,
            Function::deleteProfilePhoto(td_api::deleteProfilePhoto {
                profile_photo_id: 7,
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 1);
        assert_eq!(error.code, 500);
        assert_eq!(error.message, "Request aborted");

        // seed the photos cache through the listing flow and the full
        // record with the main photo (in that order — a photo-less user
        // intake would drop the full photos, the C++ drop path)
        td.request(
            2,
            Function::getUserProfilePhotos(td_api::getUserProfilePhotos {
                user_id: 500,
                offset: 0,
                limit: 10,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_getUserPhotos::ID,
        );
        net_complete(
            sent,
            photos_slice_answer(1, vec![wire_photo(7)], vec![wire_user(500, "Me")]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert_eq!(responses_of(&callback, 2).len(), 1);
        with_user_manager(&mut td, |manager, env| {
            manager.on_get_user_full(
                env,
                telegram_api::UserFull {
                    id: 500,
                    flags: 1 << 2, // profile_photo present
                    profile_photo: Some(wire_photo(7)),
                    ..telegram_api::UserFull::default()
                },
            );
        });

        // 2. the reset arm: deleting the main photo refires the
        //    UpdateProfilePhotoQuery with inputPhotoEmpty (cpp:6418-6422
        //    — the #9 machinery)
        td.request(
            3,
            Function::deleteProfilePhoto(td_api::deleteProfilePhoto {
                profile_photo_id: 7,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_updateProfilePhoto::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::photos_updateProfilePhoto(payload) => {
                assert!(
                    !payload.fallback,
                    "the main photo resets the non-fallback form"
                );
                assert!(payload.bot.is_none());
                assert!(
                    matches!(
                        payload.id,
                        Some(telegram_api::InputPhoto::inputPhotoEmpty(_))
                    ),
                    "the reset arm carries the empty input photo"
                );
            }
            other => panic!("the sent function: {other:?}"),
        }

        // 3. the answer: the cache delete empties the list (count 0 →
        //    the User record keeps the empty photo, no re-get needed)
        //    and the re-add restores the photo at the head (cpp:6190+
        //    6216+)
        net_complete(
            sent,
            photos_photo_answer(Some(wire_photo(7)), vec![wire_user(500, "Me")]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 3).first(),
            Some(Object::ok(_))
        ));

        // 4. the plain arm: photos.deletePhotos over the one-element id
        //    list (cpp:799-816)
        td.request(
            4,
            Function::deleteProfilePhoto(td_api::deleteProfilePhoto {
                profile_photo_id: 9,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_deletePhotos::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::photos_deletePhotos(payload) => match &payload.id[..] {
                [telegram_api::InputPhoto::inputPhoto(photo)] => {
                    assert_eq!(photo.id, 9);
                    assert_eq!(photo.access_hash, 0);
                }
                other => panic!("the delete payload: {other:?}"),
            },
            other => panic!("the sent function: {other:?}"),
        }

        // 5. the one-element Vector<long> answer runs the cache delete
        //    (the unknown id drops the photos cache — cpp:6300-6310)
        net_complete(sent, long_vector_answer(&[9]));
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 4).first(),
            Some(Object::ok(_))
        ));

        // 6. the length-mismatch band answers the C++ 400 (cpp:808-814)
        td.request(
            5,
            Function::deleteProfilePhoto(td_api::deleteProfilePhoto {
                profile_photo_id: 11,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_deletePhotos::ID,
        );
        net_complete(sent, long_vector_answer(&[11, 12]));
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 5);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Photo can't be deleted");

        // 7. the error band forwards (cpp:816-819)
        td.request(
            6,
            Function::deleteProfilePhoto(td_api::deleteProfilePhoto {
                profile_photo_id: 13,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_deletePhotos::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_9");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 6);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "FLOOD_WAIT_9");

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    /// Test-only Td message: swap the net dispatcher for the recorder
    /// (the netted_td field assignments, delivered inside the actor).
    struct InstallRecordingNet(Arc<RecNetSession>);

    impl tdactor::ActorMessage for InstallRecordingNet {
        type Actor = Td;

        fn dispatch(self, td: &mut Td) {
            let dispatcher = NetQueryDispatcher::new(
                Box::new(RecNetSessionHandle(self.0)),
                Box::new(NullConfigSink),
                Box::new(AcceptingDcInitSink),
            );
            dispatcher.mark_dc_inited(1);
            td.net_query_dispatcher = Some(Arc::new(dispatcher));
            td.user_manager.net = td.user_net();
        }
    }

    /// Test-only Td message: set `my_id` without the user record — the
    /// merger-park band of `get_user` (the C++ `get_me` shape: the self
    /// input user exists, the record does not).
    struct SeedMyId(i64);

    impl tdactor::ActorMessage for SeedMyId {
        type Actor = Td;

        fn dispatch(self, td: &mut Td) {
            td.auth_manager.force_authorized_for_test();
            let mut env = UserEnv {
                global: &mut td.global,
                options: td
                    .option_manager
                    .as_mut()
                    .expect("the option manager exists after init"),
                auth_is_bot: td.auth_manager.is_bot(),
            };
            td.user_manager
                .set_my_id(&mut env, crate::user_manager::UserId::new(self.0));
        }
    }

    #[test]
    fn get_user_and_full_info_round_trip_the_live_arms() {
        let callback = CollectCallback::default();
        run_actor_with(&callback, |actor, callback, scheduler| {
            let dir = temp_db_dir("netfix-user-live-arm");
            send(actor, scheduler, 1, set_tdlib_parameters(dir, false));
            let rec = Arc::new(RecNetSession {
                sent: parking_lot::Mutex::new(Vec::new()),
            });
            {
                let send_ptr = scheduler.send_scheduler();
                let _guard = send_ptr.guard(false);
                tdactor::send_closure(actor, InstallRecordingNet(rec.clone()));
                tdactor::send_closure(actor, SeedMyId(500));
            }
            scheduler.run_main(0.01);

            // 1. the live getUser arm: the miss parks on the GetUserMerger
            //    (the self input user resolves, the record does not), the
            //    merged users.getUsers rides the dispatcher, the answer
            //    caches the record and the re-run completes the request.
            send(
                actor,
                scheduler,
                2,
                Function::getUser(td_api::getUser { user_id: 500 }),
            );
            let sent = take_sent(
                std::mem::take(&mut *rec.sent.lock()),
                telegram_api::users_getUsers::ID,
            );
            assert!(rec.sent.lock().is_empty(), "one merged query only");
            match sent_function(&sent) {
                telegram_api::Function::users_getUsers(payload) => match &payload.id[..] {
                    [telegram_api::InputUser::inputUserSelf(_)] => {}
                    other => panic!("the merged payload: {other:?}"),
                },
                other => panic!("the sent function: {other:?}"),
            }
            net_complete(sent, users_vector_answer(wire_user(500, "Eve")));
            scheduler.run_main(0.05);
            let responses = responses_of(callback, 2);
            assert_eq!(responses.len(), 1, "getUser answers exactly once");
            let Object::user(user) = &responses[0] else {
                panic!("getUser answers the user object, got {:?}", responses[0]);
            };
            assert_eq!(user.id, 500);
            assert_eq!(user.first_name, "Eve");

            // 2. the live getUserFullInfo arm over the same user: the
            //    missing full parks on the GetUserFullCombiner, the
            //    combined users.getFullUser rides the dispatcher, the
            //    answer caches the record and completes the request.
            send(
                actor,
                scheduler,
                3,
                Function::getUserFullInfo(td_api::getUserFullInfo { user_id: 500 }),
            );
            let sent = take_sent(
                std::mem::take(&mut *rec.sent.lock()),
                telegram_api::users_getFullUser::ID,
            );
            let mut answer = Vec::new();
            telegram_api::users_UserFull {
                full_user: Some(telegram_api::UserFull {
                    id: 500,
                    ..telegram_api::UserFull::default()
                }),
                chats: Vec::new(),
                users: vec![wire_user(500, "Eve")],
            }
            .store_boxed(&mut answer);
            net_complete(sent, answer);
            scheduler.run_main(0.05);
            let responses = responses_of(callback, 3);
            assert_eq!(responses.len(), 1, "getUserFullInfo answers exactly once");
            let Object::userFullInfo(user_full_info) = &responses[0] else {
                panic!(
                    "getUserFullInfo answers the full-info object, got {:?}",
                    responses[0]
                );
            };
            let _ = user_full_info;
            assert!(callback.errors.lock().iter().all(|(id, _)| *id != 3));
        });
    }

    // ---- net-drain 09 (§3.1 #15-#19): the saved-music five ride the
    // dispatcher — the four live td_api arms round-trip (the
    // setProfileAudioPosition / removeProfileAudio / getUserProfileAudios
    // / isProfileAudio request arms) and the by-id reload (the
    // Files-plane repair caller) rides the manager seam with the
    // carried promise restored (the C++ query carrier; ours is the §5
    // FIFO shape). ----

    /// One wire audio document (the `users_savedMusic` answer member).
    fn wire_audio_document(id: i64, access_hash: i64) -> telegram_api::Document {
        telegram_api::Document::document(telegram_api::document {
            flags: 0,
            id,
            access_hash,
            file_reference: Vec::new(),
            date: 1234,
            mime_type: "audio/mpeg".to_owned(),
            size: 100_000,
            thumbs: Vec::new(),
            video_thumbs: Vec::new(),
            dc_id: 2,
            attributes: vec![telegram_api::DocumentAttribute::documentAttributeAudio(
                telegram_api::documentAttributeAudio {
                    flags: 0,
                    voice: false,
                    duration: 180,
                    title: "Song".to_owned(),
                    performer: "Artist".to_owned(),
                    waveform: Vec::new(),
                },
            )],
        })
    }

    /// A boxed `users_savedMusic` answer.
    fn saved_music_answer(count: i32, documents: Vec<telegram_api::Document>) -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::users_SavedMusic::users_savedMusic(telegram_api::users_savedMusic {
            count,
            documents,
        })
        .store(&mut answer);
        answer
    }

    #[test]
    fn saved_music_families_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(saved_music_families_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn saved_music_families_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-user-saved-music");
        const BOOL_TRUE: i32 = 0x9972_75b5u32 as i32;
        with_user_manager(&mut td, |manager, env| {
            manager.set_my_id(env, crate::user_manager::UserId::new(900));
        });
        seed_dialog_user(&mut td);
        // the location-registry seeds — the client got these audios from
        // a profile listing in the C++ (the parse registers the pair the
        // inputDocument builders read back)
        let file_id = with_user_manager(&mut td, |manager, _env| {
            manager.parse_saved_music_document(wire_audio_document(202, 22))
        })
        .expect("the audio parses");
        let after_file_id = with_user_manager(&mut td, |manager, _env| {
            manager.parse_saved_music_document(wire_audio_document(204, 24))
        })
        .expect("the anchor audio parses");
        let stranger_file_id = with_user_manager(&mut td, |manager, _env| {
            manager.parse_saved_music_document(wire_audio_document(206, 26))
        })
        .expect("the stranger audio parses");

        // 1. isProfileAudio — the not-inited list parks the check and
        //    dispatches account.getSavedMusicIds (the vector hash over
        //    the empty set is 0), the answer replaces the set and the
        //    collapsed lambda hop re-runs the check.
        td.request(
            1,
            Function::isProfileAudio(td_api::isProfileAudio {
                file_id: file_id.get(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_getSavedMusicIds::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::account_getSavedMusicIds(payload) => {
                assert_eq!(payload.hash, 0, "the empty set hashes to 0");
            }
            other => panic!("the sent function: {other:?}"),
        }
        let mut ids_answer = Vec::new();
        telegram_api::account_SavedMusicIds::account_savedMusicIds(
            telegram_api::account_savedMusicIds { ids: vec![202] },
        )
        .store(&mut ids_answer);
        net_complete(sent, ids_answer);
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. the isProfileAudio bands — the loaded set answers the
        //    member locally (no query) and 404s the stranger.
        td.request(
            2,
            Function::isProfileAudio(td_api::isProfileAudio {
                file_id: file_id.get(),
            }),
        );
        assert!(rec.sent.lock().is_empty(), "the loaded set answers locally");
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::ok(_))
        ));

        td.request(
            3,
            Function::isProfileAudio(td_api::isProfileAudio {
                file_id: stranger_file_id.get(),
            }),
        );
        assert!(rec.sent.lock().is_empty());
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!((error.code, error.message.as_str()), (404, "Not Found"));

        // 4. setProfileAudioPosition — the live arm validates locally,
        //    dispatches account.saveMusic with the anchor flag and the
        //    inputDocument pair, and the Bool answer runs
        //    on_add_saved_music (the save cache-side).
        td.request(
            4,
            Function::setProfileAudioPosition(td_api::setProfileAudioPosition {
                file_id: file_id.get(),
                after_file_id: after_file_id.get(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_saveMusic::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::account_saveMusic(payload) => {
                assert_eq!(payload.flags & (1 << 1), 1 << 1, "the anchor flag");
                assert!(!payload.unsave);
                match payload.id {
                    Some(telegram_api::InputDocument::inputDocument(document)) => {
                        assert_eq!(document.id, 202);
                        assert_eq!(document.access_hash, 22);
                    }
                    other => panic!("the document: {other:?}"),
                }
                match payload.after_id {
                    Some(telegram_api::InputDocument::inputDocument(document)) => {
                        assert_eq!(document.id, 204);
                        assert_eq!(document.access_hash, 24);
                    }
                    other => panic!("the anchor document: {other:?}"),
                }
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 4).first(),
            Some(Object::ok(_))
        ));

        // 5. the save error band — the plain error fails the promise (the
        //    file-reference repair leg rides the Files plane).
        td.request(
            5,
            Function::setProfileAudioPosition(td_api::setProfileAudioPosition {
                file_id: file_id.get(),
                after_file_id: 0,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_saveMusic::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::account_saveMusic(payload) => {
                assert_eq!(payload.flags & (1 << 1), 0, "no anchor");
                assert!(!payload.unsave);
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_fail(sent, 420, "FLOOD_WAIT_3");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 5);
        assert_eq!((error.code, error.message.as_str()), (420, "FLOOD_WAIT_3"));

        // 6. removeProfileAudio — the unsave form of the same query, and
        //    the on_remove_saved_music tail runs on the Bool answer.
        td.request(
            6,
            Function::removeProfileAudio(td_api::removeProfileAudio {
                file_id: file_id.get(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_saveMusic::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::account_saveMusic(payload) => {
                assert!(payload.unsave);
                match payload.id {
                    Some(telegram_api::InputDocument::inputDocument(document)) => {
                        assert_eq!(document.id, 202);
                    }
                    other => panic!("the document: {other:?}"),
                }
                assert!(payload.after_id.is_none());
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 6).first(),
            Some(Object::ok(_))
        ));

        // 7. getUserProfileAudios — the cache miss parks the request,
        //    users.getSavedMusic rides the dispatcher (the limit bumps to
        //    MAX_GET_SAVED_MUSIC / 5), the answer feeds the intake and
        //    finish_get_user_saved_music completes the parked request.
        td.request(
            7,
            Function::getUserProfileAudios(td_api::getUserProfileAudios {
                user_id: 700000001,
                offset: 0,
                limit: 1,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_getSavedMusic::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::users_getSavedMusic(payload) => {
                match payload.id {
                    Some(telegram_api::InputUser::inputUser(user)) => {
                        assert_eq!(user.user_id, 700000001);
                        assert_eq!(user.access_hash, 5);
                    }
                    other => panic!("the input user: {other:?}"),
                }
                assert_eq!(payload.offset, 0);
                assert_eq!(payload.limit, crate::user_manager::MAX_GET_SAVED_MUSIC / 5);
                assert_eq!(payload.hash, 0);
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(
            sent,
            saved_music_answer(30, vec![wire_audio_document(301, 33)]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let responses = responses_of(&callback, 7);
        let Object::audios(audios) = responses.first().unwrap() else {
            panic!("the audios object, got {:?}", responses.first());
        };
        assert_eq!(audios.total_count, 30);
        assert_eq!(audios.audios.len(), 1);

        // 8. the getSavedMusic band — a cache-window miss (offset 20
        //    with the cache covering [0, 1) of 30) parks the request,
        //    the notModified answer breaks the constructor gate and the
        //    parked request fails with the C++ 500.
        td.request(
            8,
            Function::getUserProfileAudios(td_api::getUserProfileAudios {
                user_id: 700000001,
                offset: 20,
                limit: 10,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_getSavedMusic::ID,
        );
        let mut not_modified = Vec::new();
        telegram_api::users_SavedMusic::users_savedMusicNotModified(
            telegram_api::users_savedMusicNotModified { count: 0 },
        )
        .store(&mut not_modified);
        net_complete(sent, not_modified.clone());
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 8);
        assert_eq!(
            (error.code, error.message.as_str()),
            (500, "Receive invalid response")
        );

        // 9. the beyond-total band — offset >= the known count answers
        //    the empty audios locally (cpp:7449-7453), no query.
        td.request(
            9,
            Function::getUserProfileAudios(td_api::getUserProfileAudios {
                user_id: 700000001,
                offset: 30,
                limit: 10,
            }),
        );
        assert!(rec.sent.lock().is_empty(), "beyond-total answers locally");
        td.flush_deferred_results();
        let responses = responses_of(&callback, 9);
        let Object::audios(audios) = responses.first().unwrap() else {
            panic!("the empty audios object");
        };
        assert_eq!((audios.total_count, audios.audios.len()), (30, 0));

        // 10. reload_user_saved_music — the manager seam (the caller is
        //     the FileReferenceManager repair leg), users.getSavedMusicByID
        //     with the one-element document vector, and the caller
        //     promise completes from the answer (the §5 item).
        let (promise, slot) = record_ton_unit();
        with_user_manager(&mut td, |manager, env| {
            manager.reload_user_saved_music(
                env,
                crate::user_manager::UserId::new(700000001),
                305,
                35,
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_getSavedMusicByID::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::users_getSavedMusicByID(payload) => match payload.id {
                Some(telegram_api::InputUser::inputUser(user)) => {
                    assert_eq!(user.user_id, 700000001);
                    assert_eq!(user.access_hash, 5);
                }
                other => panic!("the input user: {other:?}"),
            },
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(
            sent,
            saved_music_answer(1, vec![wire_audio_document(305, 35)]),
        );
        td.dispatch_completed_user_net();
        assert!(
            matches!(
                &*slot.lock().unwrap(),
                Some(tdutils::status::Result::Ok(()))
            ),
            "the carried promise completes"
        );

        // 11. the by-id band — the wrong constructor and the query error
        //     both fail the carried promise.
        let (promise, slot) = record_ton_unit();
        with_user_manager(&mut td, |manager, env| {
            manager.reload_user_saved_music(
                env,
                crate::user_manager::UserId::new(700000001),
                306,
                36,
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_getSavedMusicByID::ID,
        );
        net_complete(sent, not_modified);
        td.dispatch_completed_user_net();
        let failure = slot.lock().unwrap().clone().unwrap();
        match failure {
            tdutils::status::Result::Err(status) => {
                assert_eq!(status.message(), "Receive invalid response");
            }
            tdutils::status::Result::Ok(()) => panic!("the carried promise fails"),
        }

        let (promise, slot) = record_ton_unit();
        with_user_manager(&mut td, |manager, env| {
            manager.reload_user_saved_music(
                env,
                crate::user_manager::UserId::new(700000001),
                307,
                37,
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::users_getSavedMusicByID::ID,
        );
        net_fail(sent, 400, "DOCUMENT_INVALID");
        td.dispatch_completed_user_net();
        let failure = slot.lock().unwrap().clone().unwrap();
        match failure {
            tdutils::status::Result::Err(status) => {
                assert_eq!(status.message(), "DOCUMENT_INVALID");
            }
            tdutils::status::Result::Ok(()) => panic!("the carried promise fails"),
        }

        // 12. the unsave error band — the Err arm of case 6's family
        //     (UnsaveMusicQuery::on_error, cpp:1613-1628): the plain
        //     error fails the promise (the file-reference repair leg
        //     rides the Files plane).
        td.request(
            12,
            Function::removeProfileAudio(td_api::removeProfileAudio {
                file_id: file_id.get(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_saveMusic::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::account_saveMusic(payload) => {
                assert!(payload.unsave, "the unsave form");
                match payload.id {
                    Some(telegram_api::InputDocument::inputDocument(document)) => {
                        assert_eq!(document.id, 202);
                    }
                    other => panic!("the document: {other:?}"),
                }
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_fail(sent, 420, "FLOOD_WAIT_4");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 12);
        assert_eq!((error.code, error.message.as_str()), (420, "FLOOD_WAIT_4"));

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    // ---- net-drain 10 (§3.1 #20-#28): the contacts nine ride the
    // dispatcher — the live td_api arms round-trip (getContacts /
    // addContact / removeContacts / clearImportedContacts /
    // hideContactCloseBirthdays / setCloseFriends /
    // searchUserByPhoneNumber / sharePhoneNumber / importContacts) with
    // the §5 query-carried promises restored over the family queues. ----

    /// The wire `user` form of the contacts seed — access hash 42, a
    /// first name and the contact flag (the answer builders reuse it).
    fn contacts_wire_user(id: i64, name: &str, contact: bool) -> telegram_api::User {
        telegram_api::User::user(telegram_api::user {
            flags: 1 | (1 << 1), // access_hash + first_name
            access_hash: 42,
            id,
            first_name: name.to_owned(),
            contact,
            ..telegram_api::user::default()
        })
    }

    /// The me + Alice + Bob seed — Alice is a contact (the delete/close-
    /// friends rounds read her flag), Bob a plain peer (the addContact /
    /// acceptContact targets).
    fn seed_contacts_users(td: &mut Td) {
        with_user_manager(&mut *td, |manager, env| {
            manager.set_my_id(env, crate::user_manager::UserId::new(700000001));
            manager.on_get_user(env, contacts_wire_user(700000001, "Me", false), "t");
            manager.on_get_user(env, contacts_wire_user(5, "Alice", true), "t");
            manager.on_get_user(env, contacts_wire_user(6, "Bob", false), "t");
        });
    }

    /// A boxed `contacts_contacts` answer.
    fn contacts_list_answer(saved_count: i32, users: Vec<telegram_api::User>) -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::contacts_Contacts::contacts_contacts(telegram_api::contacts_contacts {
            contacts: Vec::new(),
            saved_count,
            users,
        })
        .store(&mut answer);
        answer
    }

    /// A boxed `contacts_contactsNotModified` answer.
    fn contacts_not_modified_answer() -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::contacts_Contacts::contacts_contactsNotModified(
            telegram_api::contacts_contactsNotModified,
        )
        .store(&mut answer);
        answer
    }

    /// A boxed empty `updates` answer (the Updates-typed acks).
    fn empty_updates_answer() -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::Updates::updates(telegram_api::updates {
            updates: Vec::new(),
            users: Vec::new(),
            chats: Vec::new(),
            date: 0,
            seq: 0,
        })
        .store(&mut answer);
        answer
    }

    /// A boxed `Vector<contactStatus>` answer.
    fn contact_statuses_answer(statuses: Vec<telegram_api::ContactStatus>) -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::tl::__i32(&mut answer, telegram_api::tl::VECTOR_ID);
        telegram_api::tl::__i32(&mut answer, statuses.len() as i32);
        for status in statuses {
            status.store_boxed(&mut answer);
        }
        answer
    }

    /// A boxed `contacts_resolvedPhone` answer.
    fn resolved_phone_answer(user_id: i64, users: Vec<telegram_api::User>) -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::contacts_ResolvedPeer {
            peer: Some(telegram_api::Peer::peerUser(telegram_api::peerUser {
                user_id,
            })),
            chats: Vec::new(),
            users,
        }
        .store_boxed(&mut answer);
        answer
    }

    /// A boxed `contacts_importedContacts` answer.
    fn imported_contacts_answer(
        imported: Vec<telegram_api::ImportedContact>,
        popular_invites: Vec<telegram_api::PopularContact>,
        retry_contacts: Vec<i64>,
    ) -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::contacts_ImportedContacts {
            imported,
            popular_invites,
            retry_contacts,
            users: Vec::new(),
        }
        .store_boxed(&mut answer);
        answer
    }

    #[test]
    fn contacts_families_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(contacts_families_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn contacts_families_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-user-contacts");
        seed_contacts_users(&mut td);

        // 1. getContacts — the request parks behind the load, the load
        //    dispatches contacts.getContacts (hash 0 while unloaded), the
        //    answer finishes the load and resolves the parked users result
        td.request(1, Function::getContacts(td_api::getContacts));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getContacts::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::contacts_getContacts(payload) => {
                assert_eq!(payload.hash, 0, "the unloaded hash");
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(
            sent,
            contacts_list_answer(1, vec![contacts_wire_user(5, "Alice", true)]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        match responses_of(&callback, 1).first() {
            Some(Object::users(users)) => {
                assert_eq!(users.total_count, 1);
                assert_eq!(users.user_ids, vec![5]);
            }
            other => panic!("the contacts result, got {other:?}"),
        }

        // 2. addContact — the share bit + the contact fields ride the
        //    query, the Updates answer resolves ok
        td.request(
            2,
            Function::addContact(td_api::addContact {
                user_id: 6,
                contact: Some(td_api::ImportedContact {
                    phone_number: "+15551234".to_owned(),
                    first_name: "Bobby".to_owned(),
                    last_name: String::new(),
                    note: None,
                }),
                share_phone_number: true,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_addContact::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::contacts_addContact(payload) => {
                assert!(payload.add_phone_privacy_exception, "the share bit");
                assert!(
                    payload.note.is_none(),
                    "the note branch is the formatted-text plane"
                );
                assert_eq!(payload.first_name, "Bobby");
                assert_eq!(payload.last_name, "");
                assert_eq!(payload.phone, "+15551234");
                let telegram_api::InputUser::inputUser(input_user) =
                    payload.id.expect("the concrete input user")
                else {
                    panic!("the add-contact peer must be a concrete input user");
                };
                assert_eq!((input_user.user_id, input_user.access_hash), (6, 42));
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, empty_updates_answer());
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::ok(_))
        ));

        // 3. the addContact error band — the promise fails and the
        //    reload refire re-sends the sync query; its notModified
        //    answer chains the fire-and-forget statuses query (#21)
        td.request(
            3,
            Function::addContact(td_api::addContact {
                user_id: 6,
                contact: Some(td_api::ImportedContact {
                    phone_number: "+15551234".to_owned(),
                    first_name: "Bobby".to_owned(),
                    last_name: String::new(),
                    note: None,
                }),
                share_phone_number: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_addContact::ID,
        );
        net_fail(sent, 500, "INTERNAL");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!((error.code, error.message.as_str()), (500, "INTERNAL"));
        let refire = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getContacts::ID,
        );
        net_complete(refire, contacts_not_modified_answer());
        td.dispatch_completed_user_net();
        let statuses = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getStatuses::ID,
        );
        net_complete(
            statuses,
            contact_statuses_answer(vec![telegram_api::ContactStatus {
                user_id: 5,
                status: Some(telegram_api::UserStatus::userStatusOffline(
                    telegram_api::userStatusOffline { was_online: 12345 },
                )),
            }]),
        );
        td.dispatch_completed_user_net();

        // the second statuses site — the online-status-privacy update
        with_user_manager(&mut td, |manager, env| {
            manager.on_update_online_status_privacy(env)
        });
        take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getStatuses::ID,
        );

        // 4. removeContacts — the contact's input user rides the query
        td.request(
            4,
            Function::removeContacts(td_api::removeContacts { user_ids: vec![5] }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_deleteContacts::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::contacts_deleteContacts(payload) => {
                assert_eq!(payload.id.len(), 1, "only the contact rides");
                let telegram_api::InputUser::inputUser(input_user) = &payload.id[0] else {
                    panic!("the delete peer must be a concrete input user");
                };
                assert_eq!((input_user.user_id, input_user.access_hash), (5, 42));
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, empty_updates_answer());
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 4).first(),
            Some(Object::ok(_))
        ));

        // 4b. the empty band — no contact among the ids answers ok with
        //     no query out
        td.request(
            5,
            Function::removeContacts(td_api::removeContacts { user_ids: vec![6] }),
        );
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 5).first(),
            Some(Object::ok(_))
        ));
        assert_not_sent(
            &rec,
            telegram_api::contacts_deleteContacts::ID,
            "the empty delete",
        );

        // 5. clearImportedContacts — the false band logs + refetches but
        //    still resolves; the true band resets the store
        td.request(
            6,
            Function::clearImportedContacts(td_api::clearImportedContacts),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_resetSaved::ID,
        );
        net_complete(sent, bool_answer(false));
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 6).first(),
            Some(Object::ok(_))
        ));
        assert_eq!(
            td.user_manager.saved_contact_count_for_test(),
            1,
            "the false band keeps the store"
        );
        // the false band's reload refire
        let refire = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getContacts::ID,
        );
        net_complete(
            refire,
            contacts_list_answer(1, vec![contacts_wire_user(5, "Alice", true)]),
        );
        td.dispatch_completed_user_net();

        td.request(
            7,
            Function::clearImportedContacts(td_api::clearImportedContacts),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_resetSaved::ID,
        );
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 7).first(),
            Some(Object::ok(_))
        ));
        assert_eq!(
            td.user_manager.saved_contact_count_for_test(),
            0,
            "on_update_contacts_reset ran"
        );
        // on_update_contacts_reset's own reload refire — answer it so
        // the sync date re-arms (the later error tails refire through it)
        let refire = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getContacts::ID,
        );
        net_complete(
            refire,
            contacts_list_answer(1, vec![contacts_wire_user(5, "Alice", true)]),
        );
        td.dispatch_completed_user_net();

        // 6. hideContactCloseBirthdays — the dismiss form rides the
        //    inputPeerEmpty + action pair
        td.request(
            8,
            Function::hideContactCloseBirthdays(td_api::hideContactCloseBirthdays),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::help_dismissSuggestion::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::help_dismissSuggestion(payload) => {
                assert!(matches!(
                    payload.peer.as_deref(),
                    Some(telegram_api::InputPeer::inputPeerEmpty(_))
                ));
                assert_eq!(payload.suggestion, "BIRTHDAY_CONTACTS_TODAY");
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 8).first(),
            Some(Object::ok(_))
        ));

        // 7. setCloseFriends — the ids ride the query; the ok band runs
        //    the close-friends flip
        td.request(
            9,
            Function::setCloseFriends(td_api::setCloseFriends { user_ids: vec![5] }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_editCloseFriends::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::contacts_editCloseFriends(payload) => {
                assert_eq!(payload.id, vec![5]);
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 9).first(),
            Some(Object::ok(_))
        ));
        assert!(
            td.user_manager
                .get_user(crate::user_manager::UserId::new(5))
                .is_some_and(|u| u.is_close_friend)
        );

        // 7b. the gate band — an unknown user answers the C++ 400
        td.request(
            10,
            Function::setCloseFriends(td_api::setCloseFriends {
                user_ids: vec![999],
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 10);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "User not found")
        );
        assert_not_sent(
            &rec,
            telegram_api::contacts_editCloseFriends::ID,
            "the gate band",
        );

        // 8. searchUserByPhoneNumber — the cleaned digits ride the
        //    query, the resolved peer answers the fresh user object
        td.request(
            11,
            Function::searchUserByPhoneNumber(td_api::searchUserByPhoneNumber {
                phone_number: "+9 (999)".to_owned(),
                only_local: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_resolvePhone::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::contacts_resolvePhone(payload) => {
                assert_eq!(payload.phone, "9999", "the digits-only cleaning");
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(
            sent,
            resolved_phone_answer(5, vec![contacts_wire_user(5, "Alice", true)]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        match responses_of(&callback, 11).first() {
            Some(Object::user(user)) => assert_eq!(user.id, 5),
            other => panic!("the resolved user, got {other:?}"),
        }

        // 8b. the PHONE_NOT_OCCUPIED band — the negative cache answers
        //     the 404
        td.request(
            12,
            Function::searchUserByPhoneNumber(td_api::searchUserByPhoneNumber {
                phone_number: "888".to_owned(),
                only_local: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_resolvePhone::ID,
        );
        net_fail(sent, 400, "PHONE_NOT_OCCUPIED");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        match responses_of(&callback, 12).first() {
            Some(Object::error(error)) => {
                assert_eq!((error.code, error.message.as_str()), (404, "Not Found"))
            }
            other => panic!("the negative-cache 404, got {other:?}"),
        }

        // 8c. the error band surfaces the status
        td.request(
            13,
            Function::searchUserByPhoneNumber(td_api::searchUserByPhoneNumber {
                phone_number: "777".to_owned(),
                only_local: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_resolvePhone::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_7");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 13);
        assert_eq!((error.code, error.message.as_str()), (420, "FLOOD_WAIT_7"));

        // 8d. the non-user-peer band fails the parked request with the
        //     C++ 500 (the on_error re-entry — do_send_error)
        td.request(
            20,
            Function::searchUserByPhoneNumber(td_api::searchUserByPhoneNumber {
                phone_number: "666".to_owned(),
                only_local: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_resolvePhone::ID,
        );
        let mut answer = Vec::new();
        telegram_api::contacts_ResolvedPeer {
            peer: Some(telegram_api::Peer::peerChannel(telegram_api::peerChannel {
                channel_id: 9,
            })),
            chats: Vec::new(),
            users: Vec::new(),
        }
        .store_boxed(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 20);
        assert_eq!(
            (error.code, error.message.as_str()),
            (500, "Receive invalid response")
        );

        // 8e. the parse-failure band fails the parked request too
        td.request(
            21,
            Function::searchUserByPhoneNumber(td_api::searchUserByPhoneNumber {
                phone_number: "555".to_owned(),
                only_local: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_resolvePhone::ID,
        );
        net_complete(sent, vec![0xde, 0xad, 0xbe, 0xef]);
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 21);
        assert_eq!(error.code, 500, "the parse-failure 500");

        // 9. sharePhoneNumber — the accept-contact form
        td.request(
            14,
            Function::sharePhoneNumber(td_api::sharePhoneNumber { user_id: 6 }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_acceptContact::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::contacts_acceptContact(payload) => {
                let telegram_api::InputUser::inputUser(input_user) =
                    payload.id.expect("the concrete input user")
                else {
                    panic!("the accept peer must be a concrete input user");
                };
                assert_eq!((input_user.user_id, input_user.access_hash), (6, 42));
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, empty_updates_answer());
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 14).first(),
            Some(Object::ok(_))
        ));

        // 10. importContacts — the inputPhoneContact payload rides the
        //     query, the answer resolves the parked request with the
        //     imported ids
        td.request(
            15,
            Function::importContacts(td_api::importContacts {
                contacts: vec![td_api::ImportedContact {
                    phone_number: "+15550001".to_owned(),
                    first_name: "Carol".to_owned(),
                    last_name: String::new(),
                    note: None,
                }],
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_importContacts::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::contacts_importContacts(payload) => {
                assert_eq!(payload.contacts.len(), 1);
                assert_eq!(payload.contacts[0].client_id, 0, "the position id");
                assert_eq!(
                    (
                        payload.contacts[0].phone.as_str(),
                        payload.contacts[0].first_name.as_str(),
                        payload.contacts[0].last_name.as_str()
                    ),
                    ("+15550001", "Carol", "")
                );
                assert_eq!(
                    payload.contacts[0].flags, 0,
                    "the note branch is the formatted-text plane"
                );
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(
            sent,
            imported_contacts_answer(
                vec![telegram_api::ImportedContact {
                    user_id: 5,
                    client_id: 0,
                }],
                vec![telegram_api::PopularContact {
                    client_id: 0,
                    importers: 3,
                }],
                Vec::new(),
            ),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        match responses_of(&callback, 15).first() {
            Some(Object::importedContacts(imported)) => {
                assert_eq!(imported.user_ids, vec![5]);
                assert_eq!(imported.importer_count, vec![3]);
            }
            other => panic!("the imported result, got {other:?}"),
        }

        // 10b. the all-retry band — the C++ 429
        td.request(
            16,
            Function::importContacts(td_api::importContacts {
                contacts: vec![td_api::ImportedContact {
                    phone_number: "+15550002".to_owned(),
                    first_name: "Dan".to_owned(),
                    last_name: String::new(),
                    note: None,
                }],
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_importContacts::ID,
        );
        net_complete(
            sent,
            imported_contacts_answer(
                Vec::new(),
                Vec::new(),
                vec![0], // the full retry — sent_size == retry len
            ),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 16);
        assert_eq!(
            (error.code, error.message.as_str()),
            (429, "Too Many Requests: retry after 3600")
        );

        // 10c. the partial retry — the re-send carries the retry client
        //      ids with the same random id, the final answer resolves
        td.request(
            17,
            Function::importContacts(td_api::importContacts {
                contacts: vec![
                    td_api::ImportedContact {
                        phone_number: "+15550003".to_owned(),
                        first_name: "Eve".to_owned(),
                        last_name: String::new(),
                        note: None,
                    },
                    td_api::ImportedContact {
                        phone_number: "+15550004".to_owned(),
                        first_name: "Frank".to_owned(),
                        last_name: String::new(),
                        note: None,
                    },
                ],
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_importContacts::ID,
        );
        net_complete(
            sent,
            imported_contacts_answer(
                vec![telegram_api::ImportedContact {
                    user_id: 5,
                    client_id: 0,
                }],
                Vec::new(),
                vec![1], // the partial retry
            ),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(
            responses_of(&callback, 17).is_empty(),
            "the task stays in flight"
        );
        let retry = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_importContacts::ID,
        );
        match sent_function(&retry) {
            telegram_api::Function::contacts_importContacts(payload) => {
                assert_eq!(payload.contacts.len(), 1, "only the retried contact");
                assert_eq!(payload.contacts[0].client_id, 1, "the server's client id");
                assert_eq!(payload.contacts[0].phone, "+15550004");
            }
            other => panic!("the retry function: {other:?}"),
        }
        net_complete(
            retry,
            imported_contacts_answer(
                vec![telegram_api::ImportedContact {
                    user_id: 6,
                    client_id: 1,
                }],
                Vec::new(),
                Vec::new(),
            ),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        match responses_of(&callback, 17).first() {
            Some(Object::importedContacts(imported)) => {
                assert_eq!(imported.user_ids, vec![5, 6]);
                assert_eq!(imported.importer_count, vec![0, 0]);
            }
            other => panic!("the retry result, got {other:?}"),
        }

        // 11. the birthdays reload — the internal send + the None error
        //     band (the sync flag re-arms). The dismiss option of step 6
        //     suppresses the reload (the faithful dismiss branch) — reset
        //     it first.
        if let Some(option_manager) = td.option_manager.as_mut() {
            option_manager.set_option_boolean("dismiss_birthday_contact_today", false);
        }
        with_user_manager(&mut td, |manager, env| {
            manager.reload_contact_birthdates(env, true)
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getBirthdays::ID,
        );
        let mut answer = Vec::new();
        telegram_api::contacts_ContactBirthdays {
            contacts: Vec::new(),
            users: Vec::new(),
        }
        .store_boxed(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_user_net();
        with_user_manager(&mut td, |manager, env| {
            manager.reload_contact_birthdates(env, true)
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getBirthdays::ID,
        );
        net_fail(sent, 500, "INTERNAL");
        td.dispatch_completed_user_net();
        // the None intake re-armed the flag — a further reload sends again
        with_user_manager(&mut td, |manager, env| {
            manager.reload_contact_birthdates(env, true)
        });
        take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getBirthdays::ID,
        );

        // 12. the deleteContacts error band — the promise fails and the
        //     reload refire re-sends the sync query
        td.request(
            18,
            Function::removeContacts(td_api::removeContacts { user_ids: vec![5] }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_deleteContacts::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_3");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 18);
        assert_eq!((error.code, error.message.as_str()), (420, "FLOOD_WAIT_3"));
        let refire = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getContacts::ID,
        );
        net_complete(refire, contacts_not_modified_answer());
        td.dispatch_completed_user_net();

        // 13. the dismiss error band forwards to the request promise
        td.request(
            19,
            Function::hideContactCloseBirthdays(td_api::hideContactCloseBirthdays),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::help_dismissSuggestion::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_8");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 19);
        assert_eq!((error.code, error.message.as_str()), (420, "FLOOD_WAIT_8"));

        // 14. remove_contacts_by_phone_number over the manager seam —
        //     the Bool true band runs on_deleted_contacts (the contact
        //     drops from the tree and the hints)
        with_user_manager(&mut td, |manager, env| {
            manager.remove_contacts_by_phone_number(
                env,
                vec!["+15551234".to_owned()],
                vec![crate::user_manager::UserId::new(5)],
                Promise::default(),
            )
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_deleteByPhones::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::contacts_deleteByPhones(payload) => {
                assert_eq!(payload.phones, vec!["+15551234".to_owned()]);
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_user_net();
        assert!(
            !td.user_manager
                .get_user(crate::user_manager::UserId::new(5))
                .is_some_and(|u| u.is_contact),
            "on_deleted_contacts dropped the flag"
        );

        // 14b. the false band answers the C++ 500 + refetches
        with_user_manager(&mut td, |manager, env| {
            manager.remove_contacts_by_phone_number(
                env,
                vec!["+15559999".to_owned()],
                Vec::new(),
                Promise::default(),
            )
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_deleteByPhones::ID,
        );
        net_complete(sent, bool_answer(false));
        td.dispatch_completed_user_net();
        take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getContacts::ID,
        );

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn contacts_load_failure_errors_the_parked_requests() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(contacts_load_failure_errors_the_parked_requests_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn contacts_load_failure_errors_the_parked_requests_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-user-contacts-fail");
        seed_contacts_users(&mut td);

        // the unloaded getContacts parks the request behind the load; the
        // load query's error band runs on_get_contacts_failed — the load
        // promises fail and the parked td_api requests error out (the
        // C++ request actors' do_send_error)
        td.request(1, Function::getContacts(td_api::getContacts));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getContacts::ID,
        );
        net_fail(sent, 500, "INTERNAL");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 1);
        assert_eq!((error.code, error.message.as_str()), (500, "INTERNAL"));
        assert!(!td.user_manager.are_contacts_loaded());
        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    // ---- net-drain 11 (§3.1 #7, #10): the Files-gated user upload
    // tails — uploadProfilePhoto's three arms and addProfileAudio's
    // upload tail ride the dispatcher over the real file plane. The
    // offline round-trip swaps the all-ok upload factory (the wire
    // saveBigFilePart bytes are the M.12.6 gate, the live transfer the
    // T.9 gate). ----

    /// The all-ok upload factory — every part save answers true.
    struct TestOkUploadNetFactory;

    impl crate::files::FileLoadNetFactory for TestOkUploadNetFactory {
        fn download_net(&mut self) -> Box<dyn crate::files::FileDownloaderNet> {
            unimplemented!("the upload round-trips start no downloads")
        }
        fn upload_net(&mut self) -> Box<dyn crate::files::FileUploaderNet> {
            Box::new(TestOkUploadNet)
        }
        fn hash_net(&mut self) -> Box<dyn crate::files::FileHashUploaderNet> {
            unimplemented!("the upload round-trips start no hash uploads")
        }
        fn utils_net(&mut self) -> Box<dyn crate::files::FileDownloaderNet> {
            unimplemented!("the upload round-trips touch no file io")
        }
    }

    struct TestOkUploadNet;

    impl crate::files::FileUploaderNet for TestOkUploadNet {
        fn upload_part(&mut self, _query: crate::files::UploadPartQuery) -> Result<bool, Status> {
            Ok(true)
        }
    }

    /// A boxed `messageMediaDocument` answer (the messages.uploadMedia
    /// result shape).
    fn uploaded_media_document_answer(document: Option<telegram_api::Document>) -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::MessageMedia::messageMediaDocument(telegram_api::messageMediaDocument {
            // `document:flags.0?Document` — the answer carries the bit
            flags: if document.is_some() { 1 } else { 0 },
            document,
            ..telegram_api::messageMediaDocument::default()
        })
        .store(&mut answer);
        answer
    }

    #[test]
    fn upload_saved_music_round_trips_messages_upload_media() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(upload_saved_music_round_trips_messages_upload_media_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn upload_saved_music_round_trips_messages_upload_media_impl() {
        let (mut td, rec, callback) = netted_td_with_files("netfix-user-upload-music");
        const BOOL_TRUE: i32 = 0x9972_75b5u32 as i32;
        td.file_load_manager
            .lock()
            .set_factory(Box::new(TestOkUploadNetFactory));
        with_user_manager(&mut td, |manager, env| {
            manager.set_my_id(env, crate::user_manager::UserId::new(900));
        });
        seed_dialog_user(&mut td);

        // a real local audio file — the upload reads it from disk
        let dir = temp_db_dir("netfix-user-upload-music-src");
        let path = std::path::Path::new(&dir).join("song.mp3");
        std::fs::write(&path, vec![7u8; 1024]).unwrap();

        // 1. the happy path — the request's own drive pumps the upload
        //    (the loader events, the callback outbox, the drain's
        //    do_upload hop) and the query rides the dispatcher
        td.request(
            1,
            Function::addProfileAudio(td_api::addProfileAudio {
                audio: Some(td_api::InputAudio {
                    audio: Some(td_api::InputFile::inputFileLocal(td_api::inputFileLocal {
                        path: path.to_string_lossy().into_owned(),
                    })),
                    album_cover_thumbnail: None,
                    duration: 10,
                    title: "Title".to_owned(),
                    performer: "Performer".to_owned(),
                }),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_uploadMedia::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::messages_uploadMedia(payload) => {
                assert!(
                    matches!(
                        payload.peer.as_deref(),
                        Some(telegram_api::InputPeer::inputPeerSelf(_))
                    ),
                    "the upload rides inputPeerSelf"
                );
                match payload.media.as_deref() {
                    Some(telegram_api::InputMedia::inputMediaUploadedDocument(media)) => {
                        assert_eq!(media.mime_type, "audio/mpeg");
                        assert!(
                            media.attributes.iter().any(|attribute| matches!(
                                attribute,
                                telegram_api::DocumentAttribute::documentAttributeAudio(audio)
                                    if !audio.voice && audio.duration == 10
                            )),
                            "the created audio rides the upload"
                        );
                        match media.file.as_ref() {
                            Some(telegram_api::InputFile::inputFile(file)) => {
                                assert_eq!(file.parts, 1, "one small-file part");
                            }
                            other => panic!("the uploaded file: {other:?}"),
                        }
                    }
                    other => panic!("the uploaded media: {other:?}"),
                }
            }
            other => panic!("the sent function: {other:?}"),
        }

        // the answer runs the documents intake, cancels the upload and
        // refires add_saved_music (the PromiseCreator lambda hop)
        net_complete(
            sent,
            uploaded_media_document_answer(Some(wire_audio_document(202, 22))),
        );
        td.dispatch_completed_user_net();
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_saveMusic::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::account_saveMusic(payload) => {
                assert!(!payload.unsave);
                match payload.id {
                    Some(telegram_api::InputDocument::inputDocument(document)) => {
                        // the registry-stand-in read of the uploaded pair
                        assert_eq!((document.id, document.access_hash), (202, 22));
                    }
                    other => panic!("the document: {other:?}"),
                }
                assert!(payload.after_id.is_none());
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. the wrong-type band — a non-document media answers the
        //    C++ 400
        td.request(
            2,
            Function::addProfileAudio(td_api::addProfileAudio {
                audio: Some(td_api::InputAudio {
                    audio: Some(td_api::InputFile::inputFileLocal(td_api::inputFileLocal {
                        path: path.to_string_lossy().into_owned(),
                    })),
                    album_cover_thumbnail: None,
                    duration: 10,
                    title: "Title".to_owned(),
                    performer: "Performer".to_owned(),
                }),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_uploadMedia::ID,
        );
        let mut empty_media = Vec::new();
        telegram_api::MessageMedia::messageMediaEmpty(telegram_api::messageMediaEmpty)
            .store(&mut empty_media);
        net_complete(sent, empty_media);
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 2);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Can't upload profile audio file: wrong file type")
        );

        // 3. the empty-document band
        td.request(
            3,
            Function::addProfileAudio(td_api::addProfileAudio {
                audio: Some(td_api::InputAudio {
                    audio: Some(td_api::InputFile::inputFileLocal(td_api::inputFileLocal {
                        path: path.to_string_lossy().into_owned(),
                    })),
                    album_cover_thumbnail: None,
                    duration: 10,
                    title: "Title".to_owned(),
                    performer: "Performer".to_owned(),
                }),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_uploadMedia::ID,
        );
        net_complete(
            sent,
            uploaded_media_document_answer(Some(telegram_api::Document::documentEmpty(
                telegram_api::documentEmpty { id: 0 },
            ))),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Can't upload profile audio file: empty file")
        );

        // 4. the non-audio document band
        td.request(
            4,
            Function::addProfileAudio(td_api::addProfileAudio {
                audio: Some(td_api::InputAudio {
                    audio: Some(td_api::InputFile::inputFileLocal(td_api::inputFileLocal {
                        path: path.to_string_lossy().into_owned(),
                    })),
                    album_cover_thumbnail: None,
                    duration: 10,
                    title: "Title".to_owned(),
                    performer: "Performer".to_owned(),
                }),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_uploadMedia::ID,
        );
        let mut non_audio = wire_audio_document(303, 33);
        let telegram_api::Document::document(ref mut document) = non_audio else {
            unreachable!()
        };
        document.attributes.clear();
        net_complete(sent, uploaded_media_document_answer(Some(non_audio)));
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 4);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Wrong file type")
        );

        // 5. the query error band — the was_uploaded legs run the
        //    delete_partial/cancel hops and fail the promise
        td.request(
            5,
            Function::addProfileAudio(td_api::addProfileAudio {
                audio: Some(td_api::InputAudio {
                    audio: Some(td_api::InputFile::inputFileLocal(td_api::inputFileLocal {
                        path: path.to_string_lossy().into_owned(),
                    })),
                    album_cover_thumbnail: None,
                    duration: 10,
                    title: "Title".to_owned(),
                    performer: "Performer".to_owned(),
                }),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_uploadMedia::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_5");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 5);
        assert_eq!((error.code, error.message.as_str()), (420, "FLOOD_WAIT_5"));

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn upload_profile_photo_round_trips_photos_upload_profile_photo() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(upload_profile_photo_round_trips_photos_upload_profile_photo_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn upload_profile_photo_round_trips_photos_upload_profile_photo_impl() {
        let (mut td, rec, callback) = netted_td_with_files("netfix-user-upload-photo");
        td.file_load_manager
            .lock()
            .set_factory(Box::new(TestOkUploadNetFactory));
        with_user_manager(&mut td, |manager, env| {
            manager.set_my_id(env, crate::user_manager::UserId::new(900));
        });
        let dir = temp_db_dir("netfix-user-upload-photo-src");
        let path = std::path::Path::new(&dir).join("photo.jpg");
        std::fs::write(&path, vec![9u8; 2048]).unwrap();

        // 1. the static arm — the FILE flag, no bot user (is_me), and
        //    the ok answer runs the on_set_profile_photo intake
        td.request(
            1,
            Function::setProfilePhoto(td_api::setProfilePhoto {
                photo: Some(td_api::InputChatPhoto::inputChatPhotoStatic(
                    td_api::inputChatPhotoStatic {
                        photo: Some(td_api::InputFile::inputFileLocal(td_api::inputFileLocal {
                            path: path.to_string_lossy().into_owned(),
                        })),
                    },
                )),
                is_public: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_uploadProfilePhoto::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::photos_uploadProfilePhoto(payload) => {
                assert_eq!(payload.flags & 1, 1, "the FILE flag");
                assert_eq!(payload.flags & (1 << 1), 0, "no VIDEO flag");
                assert_eq!(payload.flags & (1 << 5), 0, "no BOT flag for is_me");
                assert!(payload.bot.is_none());
                assert!(
                    matches!(
                        payload.file.as_ref(),
                        Some(telegram_api::InputFile::inputFile(_))
                    ),
                    "the static arm uploads the file"
                );
                assert!(payload.video.is_none());
                assert!(payload.video_emoji_markup.is_none());
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(
            sent,
            photos_photo_answer(Some(wire_photo(7)), vec![wire_user(900, "Me")]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. the animation arm — the VIDEO + VIDEO_START_TS flag pair
        //    over the second upload
        let path = std::path::Path::new(&dir).join("clip.mp4");
        std::fs::write(&path, vec![5u8; 2048]).unwrap();
        td.request(
            2,
            Function::setProfilePhoto(td_api::setProfilePhoto {
                photo: Some(td_api::InputChatPhoto::inputChatPhotoAnimation(
                    td_api::inputChatPhotoAnimation {
                        animation: Some(td_api::InputFile::inputFileLocal(
                            td_api::inputFileLocal {
                                path: path.to_string_lossy().into_owned(),
                            },
                        )),
                        main_frame_timestamp: 1.5,
                    },
                )),
                is_public: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_uploadProfilePhoto::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::photos_uploadProfilePhoto(payload) => {
                assert_eq!(payload.flags & 1, 0, "no FILE flag");
                assert_eq!(payload.flags & (1 << 1), 1 << 1, "the VIDEO flag");
                assert_eq!(payload.flags & (1 << 2), 1 << 2, "the START_TS flag");
                assert_eq!(payload.video_start_ts, 1.5);
                assert!(matches!(
                    payload.video.as_ref(),
                    Some(telegram_api::InputFile::inputFile(_))
                ));
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(
            sent,
            photos_photo_answer(Some(wire_photo(8)), vec![wire_user(900, "Me")]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::ok(_))
        ));

        // 3. the query error band — the promise fails (the partial
        //    remote drop runs before)
        td.request(
            3,
            Function::setProfilePhoto(td_api::setProfilePhoto {
                photo: Some(td_api::InputChatPhoto::inputChatPhotoStatic(
                    td_api::inputChatPhotoStatic {
                        photo: Some(td_api::InputFile::inputFileLocal(td_api::inputFileLocal {
                            path: path.to_string_lossy().into_owned(),
                        })),
                    },
                )),
                is_public: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_uploadProfilePhoto::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_9");
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!((error.code, error.message.as_str()), (420, "FLOOD_WAIT_9"));

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn upload_sticker_profile_photo_rides_the_emoji_markup() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(upload_sticker_profile_photo_rides_the_emoji_markup_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn upload_sticker_profile_photo_rides_the_emoji_markup_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-user-upload-sticker-photo");
        with_user_manager(&mut td, |manager, env| {
            manager.set_my_id(env, crate::user_manager::UserId::new(900));
        });
        // the custom emoji must be known (the have_custom_emoji read)
        td.stickers_manager.custom_emoji_to_sticker_id.insert(
            crate::stickers_manager::CustomEmojiId::new(777),
            crate::files::FileId::new(1, 1),
        );

        let sticker_photo =
            |_custom_emoji_id: i64,
             background_fill: Option<td_api::BackgroundFill>,
             sticker_type: Option<td_api::ChatPhotoStickerType>| {
                td_api::InputChatPhoto::inputChatPhotoSticker(td_api::inputChatPhotoSticker {
                    sticker: Some(td_api::ChatPhotoSticker {
                        r#type: sticker_type,
                        background_fill,
                    }),
                })
            };
        let custom_emoji_type = |custom_emoji_id: i64| {
            Some(
                td_api::ChatPhotoStickerType::chatPhotoStickerTypeCustomEmoji(
                    td_api::chatPhotoStickerTypeCustomEmoji { custom_emoji_id },
                ),
            )
        };
        let solid_fill = |color: i32| {
            Some(td_api::BackgroundFill::backgroundFillSolid(
                td_api::backgroundFillSolid { color },
            ))
        };

        // 1. the happy path — no upload, the query carries the
        //    VIDEO_EMOJI_MARKUP pair over the resolved StickerPhotoSize
        td.request(
            1,
            Function::setProfilePhoto(td_api::setProfilePhoto {
                photo: Some(sticker_photo(
                    777,
                    solid_fill(0x112233),
                    custom_emoji_type(777),
                )),
                is_public: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::photos_uploadProfilePhoto::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::photos_uploadProfilePhoto(payload) => {
                assert_eq!(payload.flags & (1 << 4), 1 << 4, "the EMOJI_MARKUP flag");
                assert!(payload.file.is_none());
                assert!(payload.video.is_none());
                match payload.video_emoji_markup.as_ref() {
                    Some(telegram_api::VideoSize::videoSizeEmojiMarkup(markup)) => {
                        assert_eq!(markup.emoji_id, 777);
                        assert_eq!(markup.background_colors, vec![0x112233]);
                    }
                    other => panic!("the markup: {other:?}"),
                }
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(
            sent,
            photos_photo_answer(Some(wire_photo(9)), vec![wire_user(900, "Me")]),
        );
        td.dispatch_completed_user_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. the unknown custom emoji answers the C++ 400, no query
        td.request(
            2,
            Function::setProfilePhoto(td_api::setProfilePhoto {
                photo: Some(sticker_photo(999, solid_fill(0), custom_emoji_type(999))),
                is_public: false,
            }),
        );
        assert!(
            rec.sent.lock().is_empty(),
            "the unknown emoji answers locally"
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 2);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Custom emoji not found")
        );

        // 3. the regular-or-mask band — the set-record seam answers the
        //    C++ "Sticker not found" (have_sticker over no records)
        td.request(
            3,
            Function::setProfilePhoto(td_api::setProfilePhoto {
                photo: Some(sticker_photo(
                    0,
                    solid_fill(0),
                    Some(
                        td_api::ChatPhotoStickerType::chatPhotoStickerTypeRegularOrMask(
                            td_api::chatPhotoStickerTypeRegularOrMask {
                                sticker_set_id: 5,
                                sticker_id: 6,
                            },
                        ),
                    ),
                )),
                is_public: false,
            }),
        );
        assert!(rec.sent.lock().is_empty());
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Sticker not found")
        );

        // 4. the null-type band
        td.request(
            4,
            Function::setProfilePhoto(td_api::setProfilePhoto {
                photo: Some(sticker_photo(777, solid_fill(0), None)),
                is_public: false,
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 4);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Type must be non-null")
        );

        // 5. the null-fill band
        td.request(
            5,
            Function::setProfilePhoto(td_api::setProfilePhoto {
                photo: Some(sticker_photo(777, None, custom_emoji_type(777))),
                is_public: false,
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 5);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Background must be non-null")
        );

        assert!(td.user_net_completed.lock().is_empty(), "drained");
    }

    // ---- the §2 flip slice: the ported-but-intercepted td_api arms ride
    // their manager flows and the queries ride the dispatcher — every
    // round-trip goes through the LIVE td_api request arm. ----

    /// Seed one wire chat + channel pair through the real intakes (the
    /// `on_get_chat`/`on_get_channel` half) — the group creator, the
    /// broadcast creator and the member channel for the rights bands.
    fn seed_dialog_chats(td: &mut Td) {
        seed_dialog_basic_group(td, 701, true);
        seed_dialog_channel(td, 702, true, false);
        seed_dialog_channel(td, 703, false, false);
        // a creator megagroup — the §2 permissions/toggle bands
        seed_dialog_channel(td, 704, true, true);
    }

    /// Seed one basic group via the chat intake (the §2 flip bands'
    /// group dialogs); `creator` drives the participant status the
    /// rights gates read.
    fn seed_dialog_basic_group(td: &mut Td, id: i64, creator: bool) {
        let crate::td::Td {
            global,
            option_manager,
            auth_manager,
            user_manager,
            chat_manager,
            ..
        } = td;
        let mut env = crate::user_manager::UserEnv {
            global,
            options: option_manager
                .as_mut()
                .expect("option manager exists after init"),
            auth_is_bot: auth_manager.is_bot(),
        };
        chat_manager.on_get_chat(
            &mut *user_manager,
            &mut env,
            telegram_api::Chat::chat(telegram_api::chat {
                creator,
                id,
                title: "group".to_owned(),
                ..telegram_api::chat::default()
            }),
            "test",
        );
    }

    /// Seed one channel via the chat intake; `megagroup` flips the
    /// broadcast/megagroup kind (the permissions gate reads it) and
    /// `creator` the participant status. The access hash follows the
    /// seed_dialog_chats ladder (702/703 → 777, 704 → 778, …) so the
    /// per-test channels stay distinct and the existing assertions hold.
    fn seed_dialog_channel(td: &mut Td, id: i64, creator: bool, megagroup: bool) {
        seed_dialog_channel_with_flags(td, id, creator, megagroup, false)
    }

    /// The [`seed_dialog_channel`] form with the forum flags — the
    /// equal-state early-OK band reads them off the record.
    fn seed_dialog_channel_with_flags(
        td: &mut Td,
        id: i64,
        creator: bool,
        megagroup: bool,
        forum: bool,
    ) {
        let crate::td::Td {
            global,
            option_manager,
            auth_manager,
            user_manager,
            chat_manager,
            ..
        } = td;
        let mut env = crate::user_manager::UserEnv {
            global,
            options: option_manager
                .as_mut()
                .expect("option manager exists after init"),
            auth_is_bot: auth_manager.is_bot(),
        };
        chat_manager.on_get_chat(
            &mut *user_manager,
            &mut env,
            telegram_api::Chat::channel(telegram_api::channel {
                creator,
                broadcast: !megagroup,
                megagroup,
                forum,
                forum_tabs: forum,
                id,
                access_hash: 777 + (id - 703).max(0),
                title: if megagroup { "megagroup" } else { "channel" }.to_owned(),
                ..telegram_api::channel::default()
            }),
            "test",
        );
    }

    /// Seed one accessible user (the §2 flip bands' user dialogs).
    fn seed_dialog_user(td: &mut Td) {
        let crate::td::Td {
            global,
            option_manager,
            auth_manager,
            user_manager,
            ..
        } = td;
        let mut env = crate::user_manager::UserEnv {
            global,
            options: option_manager
                .as_mut()
                .expect("option manager exists after init"),
            auth_is_bot: auth_manager.is_bot(),
        };
        user_manager.on_get_user(
            &mut env,
            telegram_api::User::user(telegram_api::user {
                id: 700000001,
                flags: 1, // USER_ACCESS_HASH_MASK
                access_hash: 5,
                first_name: "User".to_owned(),
                ..telegram_api::user::default()
            }),
            "test",
        );
    }

    /// The M.10.19 ladder over the netted dispatcher: the schedule/tick
    /// fire, the pts round-trip, the `!final` re-entry, the error bands
    /// and the too-long resync (the design note's two mechanisms).
    #[test]
    fn channel_difference_ladder_rides_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(channel_difference_ladder_rides_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn channel_difference_ladder_rides_the_dispatcher_impl() {
        use crate::messages_manager::{
            DialogId, MessageId, ServerMessageId, get_channel_difference,
            schedule_get_channel_difference, tick_channel_difference_timeouts,
        };
        let (mut td, rec) = netted_td("netfix-channel-difference");
        seed_dialog_channel(&mut td, 1_000_000_000, false, true);
        let dialog_id =
            DialogId::from_channel_id(crate::chat_manager::ChannelId::new(1_000_000_000));
        // the channel dialog with pts 10 — the ladder's read point; the
        // updateNewChat announcement flag matches the seeded chat object
        // (the chat-manager receive slice owns the real emission)
        let seeded_dialog = td.messages_manager.add_dialog_for_new_message(dialog_id);
        seeded_dialog.pts = 10;
        seeded_dialog.is_update_new_chat_sent = true;

        // 1. the gap-timeout fire: schedule + the due tick dispatches
        //    updates.getChannelDifference (the virtual-clock MultiTimeout
        //    pair joined into the shared alarm slot).
        {
            let manager = &mut td.messages_manager;
            schedule_get_channel_difference(
                manager,
                dialog_id,
                0,
                MessageId::default(),
                0.001,
                tdutils::time::now(),
                "test",
            );
        }
        // SAFETY: the alias pair derives from `td_ptr`; the ladder uses
        // the contexts strictly one at a time.
        {
            let td_ptr = std::ptr::from_mut(&mut td);
            let manager: &mut crate::messages_manager::MessagesManager =
                unsafe { &mut (*td_ptr).messages_manager };
            let global: &mut crate::global::Global = unsafe { &mut (*td_ptr).global };
            let msgctx: &mut dyn crate::messages_manager::MessageObjectContext =
                unsafe { &mut *td_ptr };
            let sendctx: &dyn crate::messages_manager::SendMessageContext = unsafe { &*td_ptr };
            let state: &mut dyn crate::messages_manager::ReadStateContext =
                unsafe { crate::td::split_context_alias(td_ptr) };
            let cdctx: &mut dyn crate::messages_manager::ChannelDifferenceContext =
                unsafe { &mut *td_ptr };
            tick_channel_difference_timeouts(
                global,
                manager,
                msgctx,
                sendctx,
                state,
                cdctx,
                tdutils::time::now() + 0.002,
            );
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1, "one ladder round dispatched");
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::updates_getChannelDifference::ID
        );
        // the constructor + the request shape: force from the d->pts
        // (on_channel_get_difference_timeout's true), pts 10, limit 100
        let request = telegram_api::updates_getChannelDifference::parse(sent[0].query()).unwrap();
        assert!(request.force);
        assert_eq!(request.pts, 10);
        assert_eq!(request.limit, 100);

        // 2. the happy path: the paged difference lands the message and
        //    advances the pts (the gap closes)
        let mut answer = Vec::new();
        telegram_api::updates_ChannelDifference::updates_channelDifference(
            telegram_api::updates_channelDifference {
                flags: 1 << 10, // FINAL_MASK
                r#final: true,
                pts: 12,
                timeout: 0,
                new_messages: vec![telegram_api::Message::message(telegram_api::message {
                    id: 100,
                    peer_id: Some(telegram_api::Peer::peerChannel(telegram_api::peerChannel {
                        channel_id: 1_000_000_000,
                    })),
                    date: 1_700_000_000,
                    message: "difference".to_string(),
                    ..telegram_api::message::default()
                })],
                other_updates: Vec::new(),
                chats: Vec::new(),
                users: Vec::new(),
            },
        )
        .store(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_messages_net();
        assert_eq!(
            td.messages_manager.get_dialog(dialog_id).map(|d| d.pts),
            Some(12),
            "the difference answer advances the pts"
        );
        let message_landed = td.messages_manager.get_dialog(dialog_id).is_some_and(|d| {
            crate::messages_manager::have_message_in_dialog_memory(
                d,
                MessageId::from_server_message_id(ServerMessageId::new(100)),
            )
        });
        assert!(message_landed, "the difference message landed");
        assert!(
            !td.messages_manager
                .active_get_channel_differences
                .contains_key(&dialog_id),
            "the round closed"
        );
        assert_eq!(td.messages_manager.get_channel_difference_count, 0);

        // 3. the `!final` re-entry: a non-final answer re-runs the ladder
        //    force-first without any timeout (the pagination loop)
        {
            let manager = &mut td.messages_manager;
            schedule_get_channel_difference(
                manager,
                dialog_id,
                0,
                MessageId::default(),
                0.001,
                tdutils::time::now(),
                "test",
            );
        }
        {
            let td_ptr = std::ptr::from_mut(&mut td);
            let manager: &mut crate::messages_manager::MessagesManager =
                unsafe { &mut (*td_ptr).messages_manager };
            let global: &mut crate::global::Global = unsafe { &mut (*td_ptr).global };
            let msgctx: &mut dyn crate::messages_manager::MessageObjectContext =
                unsafe { &mut *td_ptr };
            let sendctx: &dyn crate::messages_manager::SendMessageContext = unsafe { &*td_ptr };
            let state: &mut dyn crate::messages_manager::ReadStateContext =
                unsafe { crate::td::split_context_alias(td_ptr) };
            let cdctx: &mut dyn crate::messages_manager::ChannelDifferenceContext =
                unsafe { &mut *td_ptr };
            tick_channel_difference_timeouts(
                global,
                manager,
                msgctx,
                sendctx,
                state,
                cdctx,
                tdutils::time::now() + 0.002,
            );
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        let mut answer = Vec::new();
        telegram_api::updates_ChannelDifference::updates_channelDifference(
            telegram_api::updates_channelDifference {
                flags: 0,
                r#final: false,
                pts: 14,
                timeout: 0,
                new_messages: vec![telegram_api::Message::message(telegram_api::message {
                    id: 101,
                    peer_id: Some(telegram_api::Peer::peerChannel(telegram_api::peerChannel {
                        channel_id: 1_000_000_000,
                    })),
                    date: 1_700_000_001,
                    message: "page".to_string(),
                    ..telegram_api::message::default()
                })],
                other_updates: Vec::new(),
                chats: Vec::new(),
                users: Vec::new(),
            },
        )
        .store(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_messages_net();
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(
            sent.len(),
            1,
            "the non-final answer re-entered the ladder immediately"
        );
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::updates_getChannelDifference::ID
        );
        let request = telegram_api::updates_getChannelDifference::parse(sent[0].query()).unwrap();
        assert_eq!(request.pts, 14, "the re-entry runs from the new pts");
        assert!(request.force);
        assert_eq!(
            td.messages_manager.get_dialog(dialog_id).map(|d| d.pts),
            Some(14)
        );
        // close the open round with a final empty difference
        let mut answer = Vec::new();
        telegram_api::updates_ChannelDifference::updates_channelDifferenceEmpty(
            telegram_api::updates_channelDifferenceEmpty {
                flags: 1 << 10,
                r#final: true,
                pts: 14,
                timeout: 0,
            },
        )
        .store(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_messages_net();
        assert!(
            td.messages_manager
                .active_get_channel_differences
                .is_empty()
        );

        // 4. the error bands: CHANNEL_INVALID drops without a retry; a
        //    plain error re-schedules through the backoff ladder
        {
            let td_ptr = std::ptr::from_mut(&mut td);
            let manager: &mut crate::messages_manager::MessagesManager =
                unsafe { &mut (*td_ptr).messages_manager };
            let global: &mut crate::global::Global = unsafe { &mut (*td_ptr).global };
            let msgctx: &mut dyn crate::messages_manager::MessageObjectContext =
                unsafe { &mut *td_ptr };
            let sendctx: &dyn crate::messages_manager::SendMessageContext = unsafe { &*td_ptr };
            let state: &mut dyn crate::messages_manager::ReadStateContext =
                unsafe { crate::td::split_context_alias(td_ptr) };
            let cdctx: &mut dyn crate::messages_manager::ChannelDifferenceContext =
                unsafe { &mut *td_ptr };
            get_channel_difference(
                global,
                manager,
                msgctx,
                sendctx,
                state,
                cdctx,
                dialog_id,
                14,
                0,
                MessageId::default(),
                true,
                "test error band",
                false,
            );
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        net_fail(sent.into_iter().next().unwrap(), 400, "CHANNEL_INVALID");
        td.dispatch_completed_messages_net();
        assert!(
            !td.messages_manager
                .channel_get_difference_retry_deadlines
                .contains_key(&dialog_id),
            "CHANNEL_INVALID drops the round without a retry"
        );

        {
            let td_ptr = std::ptr::from_mut(&mut td);
            let manager: &mut crate::messages_manager::MessagesManager =
                unsafe { &mut (*td_ptr).messages_manager };
            let global: &mut crate::global::Global = unsafe { &mut (*td_ptr).global };
            let msgctx: &mut dyn crate::messages_manager::MessageObjectContext =
                unsafe { &mut *td_ptr };
            let sendctx: &dyn crate::messages_manager::SendMessageContext = unsafe { &*td_ptr };
            let state: &mut dyn crate::messages_manager::ReadStateContext =
                unsafe { crate::td::split_context_alias(td_ptr) };
            let cdctx: &mut dyn crate::messages_manager::ChannelDifferenceContext =
                unsafe { &mut *td_ptr };
            get_channel_difference(
                global,
                manager,
                msgctx,
                sendctx,
                state,
                cdctx,
                dialog_id,
                14,
                0,
                MessageId::default(),
                true,
                "test error band",
                false,
            );
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        net_fail(sent.into_iter().next().unwrap(), 500, "TIMEOUT");
        td.dispatch_completed_messages_net();
        assert_eq!(
            td.messages_manager
                .channel_get_difference_retry_timeouts
                .get(&dialog_id),
            Some(&2),
            "the error band armed the doubled backoff (1 -> 2)"
        );
        assert!(
            td.messages_manager
                .channel_get_difference_retry_deadlines
                .contains_key(&dialog_id)
        );
        // clear the armed retry so the too-long round runs now
        td.messages_manager
            .channel_get_difference_retry_deadlines
            .remove(&dialog_id);
        td.messages_manager.get_channel_difference_count = 0;

        // 5. the too-long resync: the dialog answer resets the last
        //    message window and adopts the server pts
        {
            let td_ptr = std::ptr::from_mut(&mut td);
            let manager: &mut crate::messages_manager::MessagesManager =
                unsafe { &mut (*td_ptr).messages_manager };
            let global: &mut crate::global::Global = unsafe { &mut (*td_ptr).global };
            let msgctx: &mut dyn crate::messages_manager::MessageObjectContext =
                unsafe { &mut *td_ptr };
            let sendctx: &dyn crate::messages_manager::SendMessageContext = unsafe { &*td_ptr };
            let state: &mut dyn crate::messages_manager::ReadStateContext =
                unsafe { crate::td::split_context_alias(td_ptr) };
            let cdctx: &mut dyn crate::messages_manager::ChannelDifferenceContext =
                unsafe { &mut *td_ptr };
            get_channel_difference(
                global,
                manager,
                msgctx,
                sendctx,
                state,
                cdctx,
                dialog_id,
                14,
                0,
                MessageId::default(),
                true,
                "test too long",
                false,
            );
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        let mut answer = Vec::new();
        telegram_api::updates_ChannelDifference::updates_channelDifferenceTooLong(
            telegram_api::updates_channelDifferenceTooLong {
                flags: 1 << 10,
                r#final: true,
                timeout: 0,
                dialog: Some(telegram_api::Dialog::dialog(telegram_api::dialog {
                    flags: 1, // PTS_MASK — the pts field rides flags.0
                    pinned: false,
                    unread_mark: false,
                    view_forum_as_messages: false,
                    peer: Some(telegram_api::Peer::peerChannel(telegram_api::peerChannel {
                        channel_id: 1_000_000_000,
                    })),
                    top_message: 300,
                    read_inbox_max_id: 250,
                    read_outbox_max_id: 240,
                    unread_count: 7,
                    unread_mentions_count: 0,
                    unread_reactions_count: 0,
                    unread_poll_votes_count: 0,
                    notify_settings: None,
                    pts: 1000,
                    draft: None,
                    folder_id: 0,
                    ttl_period: 0,
                })),
                messages: vec![telegram_api::Message::message(telegram_api::message {
                    id: 300,
                    peer_id: Some(telegram_api::Peer::peerChannel(telegram_api::peerChannel {
                        channel_id: 1_000_000_000,
                    })),
                    date: 1_700_000_002,
                    message: "too long top".to_string(),
                    ..telegram_api::message::default()
                })],
                chats: Vec::new(),
                users: Vec::new(),
            },
        )
        .store(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_messages_net();
        assert_eq!(
            td.messages_manager.get_dialog(dialog_id).map(|d| d.pts),
            Some(1000),
            "the too-long answer adopts the server pts"
        );
        let last_new = td
            .messages_manager
            .get_dialog(dialog_id)
            .map(|d| d.last_new_message_id);
        assert_eq!(
            last_new,
            Some(MessageId::from_server_message_id(ServerMessageId::new(300))),
            "the too-long resync re-adds the top message as the last new"
        );
        assert!(
            td.messages_manager
                .get_dialog(dialog_id)
                .is_some_and(|d| d.is_channel_difference_finished),
            "the finished flag lands"
        );
    }

    #[test]
    fn chat_description_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(chat_description_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn chat_description_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-chat-about");
        seed_dialog_chats(&mut td);
        seed_dialog_user(&mut td);
        let group_dialog =
            crate::messages_manager::DialogId::from_chat_id(crate::chat_manager::ChatId::new(701))
                .get();
        let channel_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(702),
        )
        .get();
        let member_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(703),
        )
        .get();
        const BOOL_TRUE: i32 = 0x9972_75b5u32 as i32;
        const BOOL_FALSE: i32 = 0xbc79_9737u32 as i32;

        // 1. setChatDescription on the basic group — the live arm runs
        //    the manager flow and dispatches messages.editChatAbout with
        //    the Write peer and the stripped about.
        td.request(
            1,
            Function::setChatDescription(td_api::setChatDescription {
                chat_id: group_dialog,
                description: "  About the group  ".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_editChatAbout::ID,
        );
        let body =
            telegram_api::messages_editChatAbout::parse(sent.query()).expect("the sent body");
        match body.peer.as_deref() {
            Some(telegram_api::InputPeer::inputPeerChat(peer)) => {
                assert_eq!(peer.chat_id, 701);
            }
            other => panic!("the group peer: {other:?}"),
        }
        assert_eq!(body.about, "About the group");
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. the channel twin — inputPeerChannel with the access hash
        td.request(
            2,
            Function::setChatDescription(td_api::setChatDescription {
                chat_id: channel_dialog,
                description: "About the channel".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_editChatAbout::ID,
        );
        let body =
            telegram_api::messages_editChatAbout::parse(sent.query()).expect("the sent body");
        match body.peer.as_deref() {
            Some(telegram_api::InputPeer::inputPeerChannel(peer)) => {
                assert_eq!(peer.channel_id, 702);
                assert_eq!(peer.access_hash, 777);
            }
            other => panic!("the channel peer: {other:?}"),
        }
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::ok(_))
        ));

        // 3. the CHAT_NOT_MODIFIED band — the !bot value answer (the
        //    on_success intake runs for the loaded fulls only)
        td.request(
            3,
            Function::setChatDescription(td_api::setChatDescription {
                chat_id: group_dialog,
                description: "About the group".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_editChatAbout::ID,
        );
        net_fail(sent, 400, "CHAT_NOT_MODIFIED");
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 3).first(),
            Some(Object::ok(_))
        ));

        // 4. a hard error forwards through the dialog-error tail
        td.request(
            4,
            Function::setChatDescription(td_api::setChatDescription {
                chat_id: group_dialog,
                description: "About the group".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_editChatAbout::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_7");
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "FLOOD_WAIT_7");

        // 5. the false Bool answer is the C++ 500 band
        td.request(
            5,
            Function::setChatDescription(td_api::setChatDescription {
                chat_id: group_dialog,
                description: "About the group".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_editChatAbout::ID,
        );
        net_complete(sent, BOOL_FALSE.to_le_bytes().to_vec());
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 5);
        assert_eq!(error.code, 500);
        assert_eq!(error.message, "Chat description is not updated");

        // 6. the rights band — a member channel answers the C++ 400 and
        //    dispatches nothing
        td.request(
            6,
            Function::setChatDescription(td_api::setChatDescription {
                chat_id: member_dialog,
                description: "About the channel".to_owned(),
            }),
        );
        let error = error_of(&callback, 6);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Not enough rights to set chat description");
        assert!(rec.sent.lock().is_empty(), "no query on the rights band");

        // 7. the unknown dialog answers the dialog gate's 400
        td.request(
            7,
            Function::setChatDescription(td_api::setChatDescription {
                chat_id: crate::messages_manager::DialogId::from_chat_id(
                    crate::chat_manager::ChatId::new(799),
                )
                .get(),
                description: "About".to_owned(),
            }),
        );
        let error = error_of(&callback, 7);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Chat not found");

        // 8. the user dialog keeps the C++ 400
        td.request(
            8,
            Function::setChatDescription(td_api::setChatDescription {
                chat_id: 700000001,
                description: "About".to_owned(),
            }),
        );
        let error = error_of(&callback, 8);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Can't change private chat description");

        assert!(td.chat_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn channel_color_and_emoji_status_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(channel_color_and_emoji_status_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn channel_color_and_emoji_status_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-channel-color");
        seed_dialog_chats(&mut td);
        let channel_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(702),
        )
        .get();
        let member_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(703),
        )
        .get();
        let updates_answer = || {
            let mut answer = Vec::new();
            telegram_api::Updates::updates(telegram_api::updates {
                updates: Vec::new(),
                users: Vec::new(),
                chats: Vec::new(),
                date: 0,
                seq: 0,
            })
            .store(&mut answer);
            answer
        };

        // 1. setChatAccentColor — the live arm runs the flow and
        //    dispatches channels.updateColor with the COLOR flag and the
        //    input channel; the Updates answer resolves the ok
        td.request(
            1,
            Function::setChatAccentColor(td_api::setChatAccentColor {
                chat_id: channel_dialog,
                accent_color_id: 5,
                background_custom_emoji_id: 0,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_updateColor::ID,
        );
        let body = telegram_api::channels_updateColor::parse(sent.query()).expect("the sent body");
        assert_eq!(body.flags & 4, 4, "COLOR_MASK for the valid accent id");
        assert_eq!(body.flags & 1, 0, "no BACKGROUND_EMOJI_ID_MASK");
        assert!(!body.for_profile);
        assert_eq!(body.color, 5);
        match body.channel.as_ref() {
            Some(telegram_api::InputChannel::inputChannel(channel)) => {
                assert_eq!(channel.channel_id, 702);
                assert_eq!(channel.access_hash, 777);
            }
            other => panic!("the input channel: {other:?}"),
        }
        net_complete(sent, updates_answer());
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. setChatProfileAccentColor — the for_profile variant
        td.request(
            2,
            Function::setChatProfileAccentColor(td_api::setChatProfileAccentColor {
                chat_id: channel_dialog,
                profile_accent_color_id: 3,
                profile_background_custom_emoji_id: 42,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_updateColor::ID,
        );
        let body = telegram_api::channels_updateColor::parse(sent.query()).expect("the sent body");
        assert!(body.for_profile);
        assert_eq!(body.flags & 4, 4);
        assert_eq!(body.flags & 1, 1, "BACKGROUND_EMOJI_ID_MASK for 42");
        assert_eq!(body.background_emoji_id, 42);
        net_fail(sent, 400, "CHAT_NOT_MODIFIED");
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        // the !bot CHAT_NOT_MODIFIED band answers the value
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::ok(_))
        ));

        // 3. setChatEmojiStatus — the emojiStatusEmpty input form for a
        //    null status
        td.request(
            3,
            Function::setChatEmojiStatus(td_api::setChatEmojiStatus {
                chat_id: channel_dialog,
                emoji_status: None,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_updateEmojiStatus::ID,
        );
        let body =
            telegram_api::channels_updateEmojiStatus::parse(sent.query()).expect("the sent body");
        assert!(matches!(
            body.emoji_status,
            Some(telegram_api::EmojiStatus::emojiStatusEmpty(_))
        ));
        net_complete(sent, updates_answer());
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 3).first(),
            Some(Object::ok(_))
        ));

        // 4. the custom-emoji input form
        td.request(
            4,
            Function::setChatEmojiStatus(td_api::setChatEmojiStatus {
                chat_id: channel_dialog,
                emoji_status: Some(td_api::EmojiStatus {
                    expiration_date: 0,
                    r#type: Some(td_api::EmojiStatusType::emojiStatusTypeCustomEmoji(
                        td_api::emojiStatusTypeCustomEmoji {
                            custom_emoji_id: 5005,
                        },
                    )),
                }),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_updateEmojiStatus::ID,
        );
        let body =
            telegram_api::channels_updateEmojiStatus::parse(sent.query()).expect("the sent body");
        match body.emoji_status {
            Some(telegram_api::EmojiStatus::emojiStatus(status)) => {
                assert_eq!(status.document_id, 5005);
                assert_eq!(status.until, 0);
            }
            other => panic!("the custom-emoji status: {other:?}"),
        }
        net_complete(sent, updates_answer());
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 4).first(),
            Some(Object::ok(_))
        ));

        // 5. the hard error forwards through the channel-error tail and
        //    refires get_recent_emoji_statuses
        td.request(
            5,
            Function::setChatEmojiStatus(td_api::setChatEmojiStatus {
                chat_id: channel_dialog,
                emoji_status: None,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_updateEmojiStatus::ID,
        );
        net_fail(sent, 400, "CHANNEL_PRIVATE");
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 5);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "CHANNEL_PRIVATE");
        // the EmojiStatus.cpp:590 refire — the recent-statuses query rides
        // the user plane
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1, "the get_recent_emoji_statuses refire");
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::account_getRecentEmojiStatuses::ID
        );

        // 6. the rights band — the member channel answers the C++ 400
        //    and dispatches nothing
        td.request(
            6,
            Function::setChatAccentColor(td_api::setChatAccentColor {
                chat_id: member_dialog,
                accent_color_id: 5,
                background_custom_emoji_id: 0,
            }),
        );
        let error = error_of(&callback, 6);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Not enough rights in the channel");

        // 7. the invalid accent id band (the default -1 id)
        td.request(
            7,
            Function::setChatAccentColor(td_api::setChatAccentColor {
                chat_id: channel_dialog,
                accent_color_id: -1,
                background_custom_emoji_id: 0,
            }),
        );
        let error = error_of(&callback, 7);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Invalid accent color identifier specified");
        // 8. the megagroup band — accent colors are broadcast-only
        let megagroup_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(704),
        )
        .get();
        td.request(
            8,
            Function::setChatAccentColor(td_api::setChatAccentColor {
                chat_id: megagroup_dialog,
                accent_color_id: 5,
                background_custom_emoji_id: 0,
            }),
        );
        let error = error_of(&callback, 8);
        assert_eq!(error.code, 400);
        assert_eq!(
            error.message,
            "Accent color can be changed only in channel chats"
        );

        assert!(rec.sent.lock().is_empty(), "no query on the bands");
        assert!(td.chat_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn delete_chat_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(delete_chat_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn delete_chat_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-delete-chat");
        seed_dialog_chats(&mut td);
        let group_dialog =
            crate::messages_manager::DialogId::from_chat_id(crate::chat_manager::ChatId::new(701))
                .get();
        let channel_id = crate::chat_manager::ChannelId::new(702);
        let channel_dialog = crate::messages_manager::DialogId::from_channel_id(channel_id).get();
        // the can_be_deleted flag arrives with the channel full
        // (ChatManager.cpp:6170-6171) — the GetFullChannelQuery family is
        // its own net slice, so the test seeds the synced state
        td.chat_manager
            .get_channel_mut(channel_id)
            .expect("the seeded channel")
            .can_be_deleted = true;
        const BOOL_TRUE: i32 = 0x9972_75b5u32 as i32;
        let updates_answer = || {
            let mut answer = Vec::new();
            telegram_api::Updates::updates(telegram_api::updates {
                updates: Vec::new(),
                users: Vec::new(),
                chats: Vec::new(),
                date: 0,
                seq: 0,
            })
            .store(&mut answer);
            answer
        };

        // 1. deleteChat on the basic group — the bare chat id rides the
        //    query; the Bool answer refires get_difference (the engine's
        //    unknown pts dispatches getState) and the empty updates
        //    container resolves the ok
        td.request(
            1,
            Function::deleteChat(td_api::deleteChat {
                chat_id: group_dialog,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_deleteChat::ID,
        );
        let body = telegram_api::messages_deleteChat::parse(sent.query()).expect("the sent body");
        assert_eq!(body.chat_id, 701);
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1, "the get_difference getState refire");
        assert_eq!(sent[0].tl_constructor(), telegram_api::updates_getState::ID);
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. deleteChat on the channel — the input channel rides the
        //    query and the Updates answer resolves the ok
        td.request(
            2,
            Function::deleteChat(td_api::deleteChat {
                chat_id: channel_dialog,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_deleteChannel::ID,
        );
        let body =
            telegram_api::channels_deleteChannel::parse(sent.query()).expect("the sent body");
        match body.channel.as_ref() {
            Some(telegram_api::InputChannel::inputChannel(channel)) => {
                assert_eq!(channel.channel_id, 702);
                assert_eq!(channel.access_hash, 777);
            }
            other => panic!("the input channel: {other:?}"),
        }
        net_complete(sent, updates_answer());
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::ok(_))
        ));

        // 3. the error band forwards through the channel-error tail
        td.request(
            3,
            Function::deleteChat(td_api::deleteChat {
                chat_id: channel_dialog,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_deleteChannel::ID,
        );
        net_fail(sent, 400, "CHANNEL_PRIVATE");
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "CHANNEL_PRIVATE");

        // 4. the unknown chat answers the dialog gate's 400
        td.request(
            4,
            Function::deleteChat(td_api::deleteChat {
                chat_id: crate::messages_manager::DialogId::from_chat_id(
                    crate::chat_manager::ChatId::new(799),
                )
                .get(),
            }),
        );
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Chat not found");

        // 5. the full-less channel keeps the C++ "can't be deleted" band
        //    (can_be_deleted arrives with the channel full)
        td.request(
            5,
            Function::deleteChat(td_api::deleteChat {
                chat_id: crate::messages_manager::DialogId::from_channel_id(
                    crate::chat_manager::ChannelId::new(703),
                )
                .get(),
            }),
        );
        let error = error_of(&callback, 5);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "The chat can't be deleted");

        assert!(rec.sent.lock().is_empty(), "no query on the bands");
        assert!(td.chat_net_completed.lock().is_empty(), "drained");
    }

    /// Seed one file node with a full remote location — the photo form
    /// (FileType::Photo + the `Photo` variant) or the document twin for
    /// the type band; `with_remote: false` keeps the node local-only
    /// (a full local photo location, so the type gate passes and the
    /// missing-remote band fires).
    fn seed_remote_file(td: &mut Td, file_id: i32, photo: bool, with_remote: bool) {
        use crate::files::{
            FileEncryptionKey, FileLocationSource, FullRemoteFileLocation, LocalFileLocation,
            NewRemoteFileLocation, PhotoSizeSource,
        };
        let full = if photo {
            FullRemoteFileLocation::from_photo(
                PhotoSizeSource::thumbnail(FileType::Photo, b'a' as i32),
                8,
                9,
                ChatDcId::internal(2),
                "ref".to_owned(),
            )
        } else {
            FullRemoteFileLocation::from_document(
                FileType::Document,
                10,
                11,
                ChatDcId::internal(2),
                String::new(),
            )
        };
        let remote = if with_remote {
            NewRemoteFileLocation {
                partial: None,
                full: Some(full),
                is_full_alive: true,
                full_source: FileLocationSource::FromServer,
            }
        } else {
            NewRemoteFileLocation::default()
        };
        let local = if with_remote {
            LocalFileLocation::Empty
        } else {
            // the photo-typed local location keeps get_type() == Photo
            LocalFileLocation::new(FileType::Photo, String::from("/tmp/x.jpg"), 0)
        };
        let node = FileNode::new(
            local,
            remote,
            None,
            0,
            0,
            String::new(),
            String::new(),
            crate::messages_manager::DialogId::default(),
            FileEncryptionKey::default(),
            FileId::new(file_id, 0),
            0,
        );
        td.file_manager
            .lock()
            .register_file_node(FileId::new(file_id, 0), 0, node);
    }

    #[test]
    fn report_chat_photo_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(report_chat_photo_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn report_chat_photo_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-report-photo");
        seed_dialog_chats(&mut td);
        let channel_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(702),
        )
        .get();
        let group_dialog =
            crate::messages_manager::DialogId::from_chat_id(crate::chat_manager::ChatId::new(701))
                .get();
        const BOOL_TRUE: i32 = 0x9972_75b5u32 as i32;
        const BOOL_FALSE: i32 = 0xbc79_9737u32 as i32;

        // 1. the happy path — the photo node rides the query with the
        //    Read peer and the input report reason
        seed_remote_file(&mut td, 10, true, true);
        td.request(
            1,
            Function::reportChatPhoto(td_api::reportChatPhoto {
                chat_id: channel_dialog,
                file_id: 10,
                reason: Some(td_api::ReportReason::reportReasonSpam(
                    td_api::reportReasonSpam,
                )),
                text: "it is spam".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_reportProfilePhoto::ID,
        );
        let body =
            telegram_api::account_reportProfilePhoto::parse(sent.query()).expect("the sent body");
        match body.peer.as_deref() {
            Some(telegram_api::InputPeer::inputPeerChannel(peer)) => {
                assert_eq!(peer.channel_id, 702);
                assert_eq!(peer.access_hash, 777);
            }
            other => panic!("the read peer: {other:?}"),
        }
        match body.photo_id {
            Some(telegram_api::InputPhoto::inputPhoto(photo)) => {
                assert_eq!(photo.id, 8);
                assert_eq!(photo.access_hash, 9);
                assert_eq!(photo.file_reference, b"ref".to_vec());
            }
            other => panic!("the input photo: {other:?}"),
        }
        assert!(matches!(
            body.reason,
            Some(telegram_api::ReportReason::inputReportReasonSpam(_))
        ));
        assert_eq!(body.message, "it is spam");
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. the false Bool answer is the C++ 400
        td.request(
            2,
            Function::reportChatPhoto(td_api::reportChatPhoto {
                chat_id: channel_dialog,
                file_id: 10,
                reason: Some(td_api::ReportReason::reportReasonFake(
                    td_api::reportReasonFake,
                )),
                text: String::new(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_reportProfilePhoto::ID,
        );
        net_complete(sent, BOOL_FALSE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 2);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Receive false as result");

        // 3. the error band forwards (the file-reference repair chain is
        //    the Files plane)
        td.request(
            3,
            Function::reportChatPhoto(td_api::reportChatPhoto {
                chat_id: channel_dialog,
                file_id: 10,
                reason: Some(td_api::ReportReason::reportReasonFake(
                    td_api::reportReasonFake,
                )),
                text: String::new(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::account_reportProfilePhoto::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_9");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "FLOOD_WAIT_9");

        // 4. the file-view gates — the unknown id, the document type and
        //    the local-only node
        td.request(
            4,
            Function::reportChatPhoto(td_api::reportChatPhoto {
                chat_id: channel_dialog,
                file_id: 99,
                reason: Some(td_api::ReportReason::reportReasonSpam(
                    td_api::reportReasonSpam,
                )),
                text: String::new(),
            }),
        );
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Unknown file identifier");

        seed_remote_file(&mut td, 11, false, true);
        td.request(
            5,
            Function::reportChatPhoto(td_api::reportChatPhoto {
                chat_id: channel_dialog,
                file_id: 11,
                reason: Some(td_api::ReportReason::reportReasonSpam(
                    td_api::reportReasonSpam,
                )),
                text: String::new(),
            }),
        );
        let error = error_of(&callback, 5);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Only full chat photos can be reported");

        seed_remote_file(&mut td, 12, true, false);
        td.request(
            6,
            Function::reportChatPhoto(td_api::reportChatPhoto {
                chat_id: channel_dialog,
                file_id: 12,
                reason: Some(td_api::ReportReason::reportReasonSpam(
                    td_api::reportReasonSpam,
                )),
                text: String::new(),
            }),
        );
        let error = error_of(&callback, 6);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Invalid photo identifier specified");

        // 5. the non-reportable basic group (can_report_dialog is false)
        td.request(
            7,
            Function::reportChatPhoto(td_api::reportChatPhoto {
                chat_id: group_dialog,
                file_id: 10,
                reason: Some(td_api::ReportReason::reportReasonSpam(
                    td_api::reportReasonSpam,
                )),
                text: String::new(),
            }),
        );
        let error = error_of(&callback, 7);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Chat photo can't be reported");

        // 6. the arm-level null-reason band
        td.request(
            8,
            Function::reportChatPhoto(td_api::reportChatPhoto {
                chat_id: channel_dialog,
                file_id: 10,
                reason: None,
                text: String::new(),
            }),
        );
        let error = error_of(&callback, 8);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Chat report reason must be non-empty");

        assert!(rec.sent.lock().is_empty(), "no query on the bands");
        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn set_chat_available_reactions_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(set_chat_available_reactions_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn set_chat_available_reactions_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-available-reactions");
        seed_dialog_chats(&mut td);
        seed_dialog_user(&mut td);
        // the messages-manager dialog records — the flow's local half
        // mutates them; the send-update LOG_CHECK precondition is set
        for dialog_id in [
            crate::messages_manager::DialogId::from_channel_id(
                crate::chat_manager::ChannelId::new(702),
            ),
            crate::messages_manager::DialogId::from_channel_id(
                crate::chat_manager::ChannelId::new(703),
            ),
            crate::messages_manager::DialogId::from_channel_id(
                crate::chat_manager::ChannelId::new(704),
            ),
            crate::messages_manager::DialogId::from_user_id(crate::user_manager::UserId::new(
                700000001,
            )),
        ] {
            let mut d = Box::new(crate::messages_manager::Dialog::default());
            d.dialog_id = dialog_id;
            d.is_update_new_chat_sent = true;
            td.messages_manager.dialogs.insert(dialog_id, d);
        }
        let channel_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(702),
        )
        .get();
        let member_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(703),
        )
        .get();
        // the megagroup — the local half keeps the All form (the
        // broadcast twin fix_broadcast_reactions the stored copy)
        let megagroup_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(704),
        )
        .get();
        let user_dialog = crate::messages_manager::DialogId::from_user_id(
            crate::user_manager::UserId::new(700000001),
        )
        .get();
        let updates_answer = || {
            let mut answer = Vec::new();
            telegram_api::Updates::updates(telegram_api::updates {
                updates: Vec::new(),
                users: Vec::new(),
                chats: Vec::new(),
                date: 0,
                seq: 0,
            })
            .store(&mut answer);
            answer
        };

        // 1. the happy path — the All form dispatches
        //    messages.setChatAvailableReactions with the Write peer, the
        //    chatReactionsAll wire form and the PAID_ENABLED flag; the
        //    Updates answer resolves the ok and the local half mutated
        td.request(
            1,
            Function::setChatAvailableReactions(td_api::setChatAvailableReactions {
                chat_id: megagroup_dialog,
                available_reactions: Some(
                    td_api::ChatAvailableReactions::chatAvailableReactionsAll(
                        td_api::chatAvailableReactionsAll {
                            max_reaction_count: 0,
                        },
                    ),
                ),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_setChatAvailableReactions::ID,
        );
        let body = telegram_api::messages_setChatAvailableReactions::parse(sent.query())
            .expect("the sent body");
        assert_eq!(body.flags, 2, "PAID_ENABLED_MASK only (no limit)");
        match body.peer.as_deref() {
            Some(telegram_api::InputPeer::inputPeerChannel(peer)) => {
                assert_eq!(peer.channel_id, 704);
                assert_eq!(peer.access_hash, 778);
            }
            other => panic!("the write peer: {other:?}"),
        }
        assert!(matches!(
            body.available_reactions,
            Some(telegram_api::ChatReactions::chatReactionsAll(_))
        ));
        assert!(!body.paid_enabled);
        net_complete(sent, updates_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));
        // the local half — the megagroup dialog's available reactions
        // keep the All form (the broadcast twin would fix it against the
        // active set)
        let d =
            &td.messages_manager.dialogs[&crate::messages_manager::DialogId::new(megagroup_dialog)];
        assert!(d.available_reactions.allow_all_regular);
        assert!(d.is_available_reactions_inited);

        // 2. the CHAT_NOT_MODIFIED band — the !bot value answer
        td.request(
            2,
            Function::setChatAvailableReactions(td_api::setChatAvailableReactions {
                chat_id: channel_dialog,
                available_reactions: Some(
                    td_api::ChatAvailableReactions::chatAvailableReactionsAll(
                        td_api::chatAvailableReactionsAll {
                            max_reaction_count: 3,
                        },
                    ),
                ),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_setChatAvailableReactions::ID,
        );
        net_fail(sent, 400, "CHAT_NOT_MODIFIED");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::ok(_))
        ));

        // 3. the error band forwards through the dialog-error tail
        td.request(
            3,
            Function::setChatAvailableReactions(td_api::setChatAvailableReactions {
                chat_id: channel_dialog,
                available_reactions: Some(
                    td_api::ChatAvailableReactions::chatAvailableReactionsAll(
                        td_api::chatAvailableReactionsAll {
                            max_reaction_count: 3,
                        },
                    ),
                ),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_setChatAvailableReactions::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_3");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "FLOOD_WAIT_3");

        // 4. the rights band — the member channel answers the C++ 400
        td.request(
            4,
            Function::setChatAvailableReactions(td_api::setChatAvailableReactions {
                chat_id: member_dialog,
                available_reactions: Some(
                    td_api::ChatAvailableReactions::chatAvailableReactionsAll(
                        td_api::chatAvailableReactionsAll {
                            max_reaction_count: 0,
                        },
                    ),
                ),
            }),
        );
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 400);
        assert_eq!(
            error.message,
            "Not enough rights to change chat available reactions"
        );

        // 5. the private-chat band
        td.request(
            5,
            Function::setChatAvailableReactions(td_api::setChatAvailableReactions {
                chat_id: user_dialog,
                available_reactions: Some(
                    td_api::ChatAvailableReactions::chatAvailableReactionsAll(
                        td_api::chatAvailableReactionsAll {
                            max_reaction_count: 0,
                        },
                    ),
                ),
            }),
        );
        let error = error_of(&callback, 5);
        assert_eq!(error.code, 400);
        assert_eq!(
            error.message,
            "Can't change private chat available reactions"
        );

        // 6. the unknown dialog answers the access band's 400
        td.request(
            6,
            Function::setChatAvailableReactions(td_api::setChatAvailableReactions {
                chat_id: crate::messages_manager::DialogId::from_channel_id(
                    crate::chat_manager::ChannelId::new(799),
                )
                .get(),
                available_reactions: Some(
                    td_api::ChatAvailableReactions::chatAvailableReactionsAll(
                        td_api::chatAvailableReactionsAll {
                            max_reaction_count: 0,
                        },
                    ),
                ),
            }),
        );
        let error = error_of(&callback, 6);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Chat not found");

        assert!(rec.sent.lock().is_empty(), "no query on the bands");
        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn chat_title_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(chat_title_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn chat_title_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-edit-dialog-title");
        seed_dialog_chats(&mut td);
        seed_dialog_user(&mut td);
        let group_dialog =
            crate::messages_manager::DialogId::from_chat_id(crate::chat_manager::ChatId::new(701))
                .get();
        let channel_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(702),
        )
        .get();
        let member_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(703),
        )
        .get();
        let user_dialog = crate::messages_manager::DialogId::from_user_id(
            crate::user_manager::UserId::new(700000001),
        )
        .get();
        let updates_answer = || {
            let mut answer = Vec::new();
            telegram_api::Updates::updates(telegram_api::updates {
                updates: Vec::new(),
                users: Vec::new(),
                chats: Vec::new(),
                date: 0,
                seq: 0,
            })
            .store(&mut answer);
            answer
        };

        // 1. the basic group — messages.editChatTitle with the id and the
        //    cleaned title; the Updates answer resolves the ok
        td.request(
            1,
            Function::setChatTitle(td_api::setChatTitle {
                chat_id: group_dialog,
                title: "  New Title  ".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_editChatTitle::ID,
        );
        let body =
            telegram_api::messages_editChatTitle::parse(sent.query()).expect("the sent body");
        assert_eq!(body.chat_id, 701);
        assert_eq!(body.title, "New Title");
        net_complete(sent, updates_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. the equal-title no-op — the record still carries the seeded
        //    title (the empty Updates answer carries no title change), so
        //    the same title completes the value without a query
        td.request(
            2,
            Function::setChatTitle(td_api::setChatTitle {
                chat_id: group_dialog,
                title: "group".to_owned(),
            }),
        );
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::ok(_))
        ));
        assert_not_sent(&rec, telegram_api::messages_editChatTitle::ID, "the no-op");

        // 3. the channel twin — inputChannel with the access hash
        td.request(
            3,
            Function::setChatTitle(td_api::setChatTitle {
                chat_id: channel_dialog,
                title: "New Chan".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_editTitle::ID,
        );
        let body = telegram_api::channels_editTitle::parse(sent.query()).expect("the sent body");
        match body.channel {
            Some(telegram_api::InputChannel::inputChannel(channel)) => {
                assert_eq!(channel.channel_id, 702);
                assert_eq!(channel.access_hash, 777);
            }
            other => panic!("the input channel: {other:?}"),
        }
        assert_eq!(body.title, "New Chan");
        net_complete(sent, updates_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 3).first(),
            Some(Object::ok(_))
        ));

        // 4. the rights band — a member channel answers the 400 BEFORE
        //    the park (no query out)
        td.request(
            4,
            Function::setChatTitle(td_api::setChatTitle {
                chat_id: member_dialog,
                title: "Nope".to_owned(),
            }),
        );
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Not enough rights to change chat title");
        assert_not_sent(
            &rec,
            telegram_api::messages_editChatTitle::ID,
            "the rights band",
        );
        assert_not_sent(
            &rec,
            telegram_api::channels_editTitle::ID,
            "the rights band",
        );

        // 5. the CHAT_NOT_MODIFIED band — the !bot value answer
        td.request(
            5,
            Function::setChatTitle(td_api::setChatTitle {
                chat_id: group_dialog,
                title: "Another Title".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_editChatTitle::ID,
        );
        net_fail(sent, 400, "CHAT_NOT_MODIFIED");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 5).first(),
            Some(Object::ok(_))
        ));

        // 6. a hard error forwards through the dialog-error tail
        td.request(
            6,
            Function::setChatTitle(td_api::setChatTitle {
                chat_id: group_dialog,
                title: "Third Title".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_editChatTitle::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_7");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 6);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "FLOOD_WAIT_7");

        // 7. the private-chat band
        td.request(
            7,
            Function::setChatTitle(td_api::setChatTitle {
                chat_id: user_dialog,
                title: "Nope".to_owned(),
            }),
        );
        let error = error_of(&callback, 7);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Can't change private chat title");

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn chat_permissions_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(chat_permissions_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn chat_permissions_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-edit-default-banned");
        seed_dialog_chats(&mut td);
        let broadcast_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(702),
        )
        .get();
        let megagroup_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(704),
        )
        .get();
        // a member megagroup — the rights band
        seed_dialog_channel(&mut td, 705, false, true);
        let member_megagroup_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(705),
        )
        .get();
        // a megagroup seeded with the nothing-banned wire rights — its
        // record default matches the all-true td_api permissions (the
        // no-op band)
        seed_dialog_channel(&mut td, 707, true, true);
        {
            let c = td
                .chat_manager
                .get_channel_mut(crate::chat_manager::ChannelId::new(707))
                .expect("the seeded channel");
            c.default_permissions = crate::chat_manager::RestrictedRights::from_chat_banned_rights(
                Some(&telegram_api::ChatBannedRights {
                    until_date: i32::MAX,
                    ..telegram_api::ChatBannedRights::default()
                }),
                crate::chat_manager::ChannelType::Megagroup,
            );
        }
        let no_op_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(707),
        )
        .get();
        let updates_answer = || {
            let mut answer = Vec::new();
            telegram_api::Updates::updates(telegram_api::updates {
                updates: Vec::new(),
                users: Vec::new(),
                chats: Vec::new(),
                date: 0,
                seq: 0,
            })
            .store(&mut answer);
            answer
        };
        let open_permissions = td_api::ChatPermissions {
            can_send_basic_messages: true,
            can_send_audios: true,
            can_send_documents: true,
            can_send_photos: true,
            can_send_videos: true,
            can_send_video_notes: true,
            can_send_voice_notes: true,
            can_send_polls: true,
            can_send_other_messages: true,
            can_add_link_previews: true,
            can_change_info: true,
            can_invite_users: true,
            can_pin_messages: true,
            can_create_topics: true,
            can_edit_tag: true,
            can_react_to_messages: true,
        };

        // 1. the megagroup — messages.editChatDefaultBannedRights with the
        //    Write peer and the inverted wire banned rights
        td.request(
            1,
            Function::setChatPermissions(td_api::setChatPermissions {
                chat_id: megagroup_dialog,
                permissions: Some(open_permissions.clone()),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_editChatDefaultBannedRights::ID,
        );
        let body = telegram_api::messages_editChatDefaultBannedRights::parse(sent.query())
            .expect("the sent body");
        match body.peer.as_deref() {
            Some(telegram_api::InputPeer::inputPeerChannel(peer)) => {
                assert_eq!(peer.channel_id, 704);
                assert_eq!(peer.access_hash, 778);
            }
            other => panic!("the write peer: {other:?}"),
        }
        let banned = body.banned_rights.expect("the banned rights");
        assert!(!banned.send_plain);
        assert!(!banned.change_info);
        assert!(!banned.manage_topics, "the request opens topics too");
        net_complete(sent, updates_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. the broadcast band — channels reject the request outright
        td.request(
            2,
            Function::setChatPermissions(td_api::setChatPermissions {
                chat_id: broadcast_dialog,
                permissions: Some(open_permissions.clone()),
            }),
        );
        let error = error_of(&callback, 2);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Can't change channel chat permissions");
        assert_not_sent(
            &rec,
            telegram_api::messages_editChatDefaultBannedRights::ID,
            "the broadcast band",
        );

        // 3. the rights band — a member megagroup answers the 400 BEFORE
        //    the park
        td.request(
            3,
            Function::setChatPermissions(td_api::setChatPermissions {
                chat_id: member_megagroup_dialog,
                permissions: Some(open_permissions.clone()),
            }),
        );
        let error = error_of(&callback, 3);
        assert_eq!(error.code, 400);
        assert_eq!(
            error.message,
            "Not enough rights to change chat permissions"
        );
        assert_not_sent(
            &rec,
            telegram_api::messages_editChatDefaultBannedRights::ID,
            "the rights band",
        );

        // 4. the equal-permissions no-op — the 707 record carries the
        //    nothing-banned default and the all-true request maps to it;
        //    the value completes without a query
        td.request(
            4,
            Function::setChatPermissions(td_api::setChatPermissions {
                chat_id: no_op_dialog,
                permissions: Some(open_permissions.clone()),
            }),
        );
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 4).first(),
            Some(Object::ok(_))
        ));
        assert_not_sent(
            &rec,
            telegram_api::messages_editChatDefaultBannedRights::ID,
            "the no-op",
        );

        // 5. the CHAT_NOT_MODIFIED band — the !bot value answer
        td.request(
            5,
            Function::setChatPermissions(td_api::setChatPermissions {
                chat_id: megagroup_dialog,
                permissions: Some(open_permissions.clone()),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_editChatDefaultBannedRights::ID,
        );
        net_fail(sent, 400, "CHAT_NOT_MODIFIED");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 5).first(),
            Some(Object::ok(_))
        ));

        // 6. a hard error forwards through the dialog-error tail
        td.request(
            6,
            Function::setChatPermissions(td_api::setChatPermissions {
                chat_id: megagroup_dialog,
                permissions: Some(open_permissions),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_editChatDefaultBannedRights::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_7");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 6);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "FLOOD_WAIT_7");

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn protected_content_toggle_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(protected_content_toggle_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn protected_content_toggle_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-toggle-no-forwards");
        seed_dialog_chats(&mut td);
        seed_dialog_user(&mut td);
        let group_dialog =
            crate::messages_manager::DialogId::from_chat_id(crate::chat_manager::ChatId::new(701))
                .get();
        let channel_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(702),
        )
        .get();
        let member_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(703),
        )
        .get();
        let user_dialog = crate::messages_manager::DialogId::from_user_id(
            crate::user_manager::UserId::new(700000001),
        )
        .get();
        let updates_answer = || {
            let mut answer = Vec::new();
            telegram_api::Updates::updates(telegram_api::updates {
                updates: Vec::new(),
                users: Vec::new(),
                chats: Vec::new(),
                date: 0,
                seq: 0,
            })
            .store(&mut answer);
            answer
        };

        // 1. the user dialog — messages.toggleNoForwards with the Read
        //    peer, no REQUEST_MSG_ID flag
        td.request(
            1,
            Function::toggleChatHasProtectedContent(td_api::toggleChatHasProtectedContent {
                chat_id: user_dialog,
                has_protected_content: true,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_toggleNoForwards::ID,
        );
        let body =
            telegram_api::messages_toggleNoForwards::parse(sent.query()).expect("the sent body");
        assert_eq!(body.flags, 0);
        assert_eq!(body.request_msg_id, 0);
        assert!(body.enabled);
        match body.peer.as_deref() {
            Some(telegram_api::InputPeer::inputPeerUser(peer)) => {
                assert_eq!(peer.user_id, 700000001);
                assert_eq!(peer.access_hash, 5);
            }
            other => panic!("the read peer: {other:?}"),
        }
        net_complete(sent, updates_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. the creator channel twin — inputPeerChannel
        td.request(
            2,
            Function::toggleChatHasProtectedContent(td_api::toggleChatHasProtectedContent {
                chat_id: channel_dialog,
                has_protected_content: true,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_toggleNoForwards::ID,
        );
        let body =
            telegram_api::messages_toggleNoForwards::parse(sent.query()).expect("the sent body");
        match body.peer.as_deref() {
            Some(telegram_api::InputPeer::inputPeerChannel(peer)) => {
                assert_eq!(peer.channel_id, 702);
                assert_eq!(peer.access_hash, 777);
            }
            other => panic!("the read peer: {other:?}"),
        }
        net_complete(sent, updates_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::ok(_))
        ));

        // 3. the basic-group creator twin — inputPeerChat
        td.request(
            3,
            Function::toggleChatHasProtectedContent(td_api::toggleChatHasProtectedContent {
                chat_id: group_dialog,
                has_protected_content: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_toggleNoForwards::ID,
        );
        let body =
            telegram_api::messages_toggleNoForwards::parse(sent.query()).expect("the sent body");
        match body.peer.as_deref() {
            Some(telegram_api::InputPeer::inputPeerChat(peer)) => {
                assert_eq!(peer.chat_id, 701);
            }
            other => panic!("the read peer: {other:?}"),
        }
        assert!(!body.enabled);
        net_complete(sent, updates_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 3).first(),
            Some(Object::ok(_))
        ));

        // 4. the creator gate — a member channel answers the 400 BEFORE
        //    the park
        td.request(
            4,
            Function::toggleChatHasProtectedContent(td_api::toggleChatHasProtectedContent {
                chat_id: member_dialog,
                has_protected_content: true,
            }),
        );
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Only owner can restrict saving content");
        assert_not_sent(
            &rec,
            telegram_api::messages_toggleNoForwards::ID,
            "the creator band",
        );

        // 5. the request form — REQUEST_MSG_ID carries the server id
        td.request(
            5,
            Function::processChatHasProtectedContentDisableRequest(
                td_api::processChatHasProtectedContentDisableRequest {
                    chat_id: channel_dialog,
                    request_message_id: 12345 << 20,
                    approve: false,
                },
            ),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_toggleNoForwards::ID,
        );
        let body =
            telegram_api::messages_toggleNoForwards::parse(sent.query()).expect("the sent body");
        assert_eq!(body.flags, 1, "REQUEST_MSG_ID_MASK");
        assert_eq!(body.request_msg_id, 12345);
        assert!(body.enabled, "!approve");
        net_complete(sent, updates_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 5).first(),
            Some(Object::ok(_))
        ));

        // 6. the invalid request id band
        td.request(
            6,
            Function::processChatHasProtectedContentDisableRequest(
                td_api::processChatHasProtectedContentDisableRequest {
                    chat_id: channel_dialog,
                    request_message_id: 0,
                    approve: true,
                },
            ),
        );
        let error = error_of(&callback, 6);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Invalid message identifier specified");

        // 7. the CHAT_NOT_MODIFIED band — the value answer with NO bot
        //    check (cpp:439-442)
        td.request(
            7,
            Function::toggleChatHasProtectedContent(td_api::toggleChatHasProtectedContent {
                chat_id: channel_dialog,
                has_protected_content: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_toggleNoForwards::ID,
        );
        net_fail(sent, 400, "CHAT_NOT_MODIFIED");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 7).first(),
            Some(Object::ok(_))
        ));

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn chat_username_checks_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(chat_username_checks_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn chat_username_checks_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-check-username");
        seed_dialog_chats(&mut td);
        // a creator channel with an editable username — the fast path
        seed_dialog_channel(&mut td, 706, true, true);
        {
            let c = td
                .chat_manager
                .get_channel_mut(crate::chat_manager::ChannelId::new(706))
                .expect("the seeded channel");
            c.usernames =
                crate::usernames::Usernames::from_telegram("myownname".to_owned(), Vec::new());
        }
        let channel_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(702),
        )
        .get();
        let member_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(703),
        )
        .get();
        let username_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(706),
        )
        .get();
        let group_dialog =
            crate::messages_manager::DialogId::from_chat_id(crate::chat_manager::ChatId::new(701))
                .get();
        const BOOL_TRUE: i32 = 0x9972_75b5u32 as i32;
        const BOOL_FALSE: i32 = 0xbc79_9737u32 as i32;

        // 1. the creator channel — channels.checkUsername with the input
        //    channel; the true Bool answer maps to checkChatUsernameResultOk
        td.request(
            1,
            Function::checkChatUsername(td_api::checkChatUsername {
                chat_id: channel_dialog,
                username: "somechannel".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_checkUsername::ID,
        );
        let body =
            telegram_api::channels_checkUsername::parse(sent.query()).expect("the sent body");
        match body.channel {
            Some(telegram_api::InputChannel::inputChannel(channel)) => {
                assert_eq!(channel.channel_id, 702);
                assert_eq!(channel.access_hash, 777);
            }
            other => panic!("the input channel: {other:?}"),
        }
        assert_eq!(body.username, "somechannel");
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::checkChatUsernameResultOk(_))
        ));

        // 2. the false Bool band — Occupied
        td.request(
            2,
            Function::checkChatUsername(td_api::checkChatUsername {
                chat_id: channel_dialog,
                username: "taken".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_checkUsername::ID,
        );
        net_complete(sent, BOOL_FALSE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::checkChatUsernameResultUsernameOccupied(_))
        ));

        // 3. the error→result mapping bands — every mapped name answers
        //    its result variant
        type ObjectMatcher = fn(&Object) -> bool;
        let mapped: &[(u64, &str, ObjectMatcher)] = &[
            (3, "USERNAME_OCCUPIED", |o| {
                matches!(o, Object::checkChatUsernameResultUsernameOccupied(_))
            }),
            (4, "USERNAME_INVALID", |o| {
                matches!(o, Object::checkChatUsernameResultUsernameInvalid(_))
            }),
            (5, "CHANNELS_ADMIN_PUBLIC_TOO_MUCH", |o| {
                matches!(o, Object::checkChatUsernameResultPublicChatsTooMany(_))
            }),
            (6, "CHANNEL_PUBLIC_GROUP_NA", |o| {
                matches!(o, Object::checkChatUsernameResultPublicGroupsUnavailable(_))
            }),
            (7, "USERNAME_PURCHASE_AVAILABLE", |o| {
                matches!(o, Object::checkChatUsernameResultUsernamePurchasable(_))
            }),
        ];
        for (n, name, is_expected) in mapped {
            td.request(
                *n,
                Function::checkChatUsername(td_api::checkChatUsername {
                    chat_id: channel_dialog,
                    username: "checked".to_owned(),
                }),
            );
            let sent = take_sent(
                std::mem::take(&mut *rec.sent.lock()),
                telegram_api::channels_checkUsername::ID,
            );
            net_fail(sent, 400, name);
            td.dispatch_completed_dialog_net();
            td.flush_deferred_results();
            let responses = responses_of(&callback, *n);
            let Some(response) = responses.first() else {
                panic!("case {n} ({name}): no response");
            };
            assert!(
                is_expected(response),
                "case {n} ({name}): wrong response variant"
            );
        }
        // the unmapped error forwards
        td.request(
            8,
            Function::checkChatUsername(td_api::checkChatUsername {
                chat_id: channel_dialog,
                username: "checked".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_checkUsername::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_9");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 8);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "FLOOD_WAIT_9");

        // 4. the creator gate — a member channel answers the 400 BEFORE
        //    the park
        td.request(
            9,
            Function::checkChatUsername(td_api::checkChatUsername {
                chat_id: member_dialog,
                username: "somechannel".to_owned(),
            }),
        );
        let error = error_of(&callback, 9);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Not enough rights to change username");
        assert_not_sent(
            &rec,
            telegram_api::channels_checkUsername::ID,
            "the creator band",
        );

        // 5. the editable-username fast path — the own username answers
        //    Ok without a query
        td.request(
            10,
            Function::checkChatUsername(td_api::checkChatUsername {
                chat_id: username_dialog,
                username: "myownname".to_owned(),
            }),
        );
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 10).first(),
            Some(Object::checkChatUsernameResultOk(_))
        ));
        assert_not_sent(
            &rec,
            telegram_api::channels_checkUsername::ID,
            "the fast path",
        );

        // 6. the bot leg — checkBotUsername rides bots.checkUsername
        //    (the None dialog + the is_bot flag)
        td.request(
            11,
            Function::checkBotUsername(td_api::checkBotUsername {
                username: "somebot".to_owned(),
                is_secondary: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_checkUsername::ID,
        );
        let body = telegram_api::bots_checkUsername::parse(sent.query()).expect("the sent body");
        assert_eq!(body.flags, 0);
        assert!(!body.additional);
        assert_eq!(body.username, "somebot");
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 11).first(),
            Some(Object::checkChatUsernameResultOk(_))
        ));

        // 7. the basic-group band — a chat can't have a username
        td.request(
            12,
            Function::checkChatUsername(td_api::checkChatUsername {
                chat_id: group_dialog,
                username: "nope".to_owned(),
            }),
        );
        let error = error_of(&callback, 12);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "The chat can't have a username");

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn resolve_username_rides_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(resolve_username_rides_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn resolve_username_rides_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-resolve-username");
        let resolved_answer = |user_id: i64| {
            let mut answer = Vec::new();
            telegram_api::contacts_ResolvedPeer {
                peer: Some(telegram_api::Peer::peerUser(telegram_api::peerUser {
                    user_id,
                })),
                chats: Vec::new(),
                users: vec![telegram_api::User::user(telegram_api::user {
                    id: user_id,
                    flags: 1, // USER_ACCESS_HASH_MASK
                    access_hash: 55,
                    first_name: "Gif".to_owned(),
                    ..telegram_api::user::default()
                })],
            }
            .store_boxed(&mut answer);
            answer
        };

        // 1. the short-prefix search parks on the resolve family queue —
        //    "gi" is a prefix of the valid short username "gif"; one
        //    contacts.resolveUsername owns the in-flight query
        td.request(
            1,
            Function::searchPublicChats(td_api::searchPublicChats {
                query: "gi".to_owned(),
                type_filter: None,
            }),
        );
        td.request(
            2,
            Function::searchPublicChats(td_api::searchPublicChats {
                query: "gi".to_owned(),
                type_filter: None,
            }),
        );
        assert!(responses_of(&callback, 1).is_empty(), "the request parks");
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_resolveUsername::ID,
        );
        let body =
            telegram_api::contacts_resolveUsername::parse(sent.query()).expect("the sent body");
        assert_eq!(body.username, "gif");

        // 2. the answer resolves the user (the users intake lands the
        //    access hash) and BOTH parked requests answer the chats object
        net_complete(sent, resolved_answer(43));
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let gif_dialog =
            crate::messages_manager::DialogId::from_user_id(crate::user_manager::UserId::new(43))
                .get();
        for n in [1, 2] {
            match responses_of(&callback, n).first() {
                Some(Object::chats(chats)) => {
                    assert_eq!(chats.total_count, 1);
                    assert_eq!(chats.chat_ids, vec![gif_dialog]);
                }
                other => panic!("request {n}: wrong answer {other:?}"),
            }
        }
        assert_eq!(
            td.dialog_manager.inaccessible_resolved_usernames.get("gif"),
            Some(&crate::messages_manager::DialogId::from_user_id(
                crate::user_manager::UserId::new(43),
            ))
        );

        // 3. the cached resolve answers without a new query
        td.request(
            3,
            Function::searchPublicChats(td_api::searchPublicChats {
                query: "gi".to_owned(),
                type_filter: None,
            }),
        );
        td.flush_deferred_results();
        match responses_of(&callback, 3).first() {
            Some(Object::chats(chats)) => assert_eq!(chats.chat_ids, vec![gif_dialog]),
            other => panic!("request 3: wrong answer {other:?}"),
        }
        assert_not_sent(
            &rec,
            telegram_api::contacts_resolveUsername::ID,
            "the cached resolve",
        );

        // 4. the resolve error band — USERNAME_NOT_OCCUPIED fails the
        //    parked request and drops the cached username
        td.request(
            4,
            Function::searchPublicChats(td_api::searchPublicChats {
                query: "nf".to_owned(), // the prefix of "nft"
                type_filter: None,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_resolveUsername::ID,
        );
        net_fail(sent, 400, "USERNAME_NOT_OCCUPIED");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "USERNAME_NOT_OCCUPIED");
        assert!(
            !td.dialog_manager
                .inaccessible_resolved_usernames
                .contains_key("nft")
        );

        // 5. the video-chat reload arm (cpp:3276-3281) — a resolved
        //    channel tagged by reload_video_chat_on_search rides
        //    reload_channel_full's GetFullChannelQuery instead of
        //    creating the dialog (the promise parks on that query)
        seed_dialog_channel(&mut td, 710, true, true);
        let reload_channel_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(710),
        );
        td.dialog_manager
            .inaccessible_resolved_usernames
            .insert("vid".to_string(), reload_channel_dialog);
        crate::dialog_manager::reload_video_chat_on_search(&mut td, "vid");
        let reload_slot = Arc::new(std::sync::Mutex::new(None));
        let reload_capture = Arc::clone(&reload_slot);
        let reload_promise = tdutils::promise::PromiseCreator::lambda_result(
            move |result: tdutils::status::Result<()>| {
                *reload_capture.lock().unwrap() = Some(result);
            },
        );
        let found_dialog =
            crate::dialog_manager::search_public_dialog(&mut td, "@vid", false, reload_promise);
        assert_eq!(found_dialog, crate::messages_manager::DialogId::default());
        assert!(
            reload_slot.lock().unwrap().is_none(),
            "the promise rides the full reload"
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_getFullChannel::ID,
        );
        let body =
            telegram_api::channels_getFullChannel::parse(sent.query()).expect("the sent body");
        assert!(
            matches!(&body.channel, Some(telegram_api::InputChannel::inputChannel(c)) if c.channel_id == 710)
        );
        assert!(
            !td.dialog_manager
                .reload_video_chat_on_search_usernames
                .contains("vid")
        );

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
        assert!(
            td.dialog_manager.resolve_dialog_username_queries.is_empty(),
            "the resolve queue drained"
        );
    }

    #[test]
    fn search_public_dialogs_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(search_public_dialogs_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn search_public_dialogs_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-search-public-dialogs");
        let found_answer = || {
            let mut answer = Vec::new();
            telegram_api::contacts_Found {
                my_results: vec![telegram_api::Peer::peerUser(telegram_api::peerUser {
                    user_id: 42,
                })],
                results: vec![telegram_api::Peer::peerUser(telegram_api::peerUser {
                    user_id: 43,
                })],
                chats: Vec::new(),
                users: vec![
                    telegram_api::User::user(telegram_api::user {
                        id: 42,
                        flags: 1,
                        access_hash: 61,
                        first_name: "Mine".to_owned(),
                        ..telegram_api::user::default()
                    }),
                    telegram_api::User::user(telegram_api::user {
                        id: 43,
                        flags: 1,
                        access_hash: 62,
                        first_name: "Public".to_owned(),
                        ..telegram_api::user::default()
                    }),
                ],
            }
            .store_boxed(&mut answer);
            answer
        };
        let dialog_of = |user_id: i64| {
            crate::messages_manager::DialogId::from_user_id(crate::user_manager::UserId::new(
                user_id,
            ))
            .get()
        };

        // 1. the long query parks on the search family queue and sends
        //    contacts.search (limit 20, the unfiltered form)
        td.request(
            1,
            Function::searchPublicChats(td_api::searchPublicChats {
                query: "query".to_owned(),
                type_filter: None,
            }),
        );
        assert!(responses_of(&callback, 1).is_empty(), "the request parks");
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_search::ID,
        );
        let body = telegram_api::contacts_search::parse(sent.query()).expect("the sent body");
        assert_eq!(body.q, "query");
        assert_eq!(body.limit, 20);
        assert!(!body.broadcasts && !body.bots);

        // 2. the answer fills the caches; the parked request answers the
        //    public half (the results peers)
        net_complete(sent, found_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        match responses_of(&callback, 1).first() {
            Some(Object::chats(chats)) => {
                assert_eq!(chats.total_count, 1);
                assert_eq!(chats.chat_ids, vec![dialog_of(43)]);
            }
            other => panic!("request 1: wrong answer {other:?}"),
        }

        // 3. the cached public search answers locally (no new query)
        td.request(
            2,
            Function::searchPublicChats(td_api::searchPublicChats {
                query: "query".to_owned(),
                type_filter: None,
            }),
        );
        td.flush_deferred_results();
        match responses_of(&callback, 2).first() {
            Some(Object::chats(chats)) => assert_eq!(chats.chat_ids, vec![dialog_of(43)]),
            other => panic!("request 2: wrong answer {other:?}"),
        }
        assert_not_sent(&rec, telegram_api::contacts_search::ID, "the cache hit");

        // 4. the on-server search reads the my_results half with the
        //    limit truncation (still no new query)
        td.request(
            3,
            Function::searchChatsOnServer(td_api::searchChatsOnServer {
                query: "query".to_owned(),
                type_filter: None,
                limit: 1,
            }),
        );
        td.flush_deferred_results();
        match responses_of(&callback, 3).first() {
            Some(Object::chats(chats)) => {
                assert_eq!(chats.total_count, 1);
                assert_eq!(chats.chat_ids, vec![dialog_of(42)]);
            }
            other => panic!("request 3: wrong answer {other:?}"),
        }

        // 5. the QUERY_TOO_SHORT band answers the empty success
        td.request(
            4,
            Function::searchPublicChats(td_api::searchPublicChats {
                query: "toolongforshort".to_owned(),
                type_filter: None,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_search::ID,
        );
        net_fail(sent, 400, "QUERY_TOO_SHORT");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        match responses_of(&callback, 4).first() {
            Some(Object::chats(chats)) => assert!(chats.chat_ids.is_empty()),
            other => panic!("request 4: wrong answer {other:?}"),
        }

        // 6. the plain error band fails the parked request and leaves the
        //    negative cache (the next search answers locally, empty)
        td.request(
            6,
            Function::searchPublicChats(td_api::searchPublicChats {
                query: "failing".to_owned(),
                type_filter: None,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_search::ID,
        );
        net_fail(sent, 500, "Timeout");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 6);
        assert_eq!(error.code, 500);
        assert_eq!(error.message, "Timeout");
        td.request(
            7,
            Function::searchPublicChats(td_api::searchPublicChats {
                query: "failing".to_owned(),
                type_filter: None,
            }),
        );
        td.flush_deferred_results();
        match responses_of(&callback, 7).first() {
            Some(Object::chats(chats)) => assert!(chats.chat_ids.is_empty()),
            other => panic!("request 7: wrong answer {other:?}"),
        }
        assert_not_sent(
            &rec,
            telegram_api::contacts_search::ID,
            "the negative cache",
        );

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
        assert!(
            td.dialog_manager
                .search_public_dialogs_queries
                .iter()
                .all(|queue| queue.is_empty()),
            "the search queues drained"
        );
        assert!(
            td.dialog_manager.pending_search_dialogs_requests.is_empty(),
            "the parked requests drained"
        );
    }

    #[test]
    fn edit_dialog_photo_query_rides_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(edit_dialog_photo_query_rides_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn edit_dialog_photo_query_rides_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-edit-dialog-photo");
        seed_dialog_chats(&mut td);
        seed_dialog_user(&mut td);
        // a creator megagroup — the rights gate passes
        seed_dialog_channel(&mut td, 706, true, true);
        let channel_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(706),
        )
        .get();
        let member_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(703),
        )
        .get();
        let user_dialog = crate::messages_manager::DialogId::from_user_id(
            crate::user_manager::UserId::new(700000001),
        )
        .get();
        let updates_answer = || {
            let mut answer = Vec::new();
            telegram_api::Updates::updates(telegram_api::updates {
                updates: Vec::new(),
                users: Vec::new(),
                chats: Vec::new(),
                date: 0,
                seq: 0,
            })
            .store(&mut answer);
            answer
        };

        // 1. the null photo (the delete form) — channels.editPhoto with
        //    the inputChannel and inputChatPhotoEmpty
        td.request(
            1,
            Function::setChatPhoto(td_api::setChatPhoto {
                chat_id: channel_dialog,
                photo: None,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_editPhoto::ID,
        );
        let body = telegram_api::channels_editPhoto::parse(sent.query()).expect("the sent body");
        assert!(matches!(
            body.photo,
            Some(telegram_api::InputChatPhoto::inputChatPhotoEmpty(_))
        ));
        net_complete(sent, updates_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 2. the CHAT_NOT_MODIFIED !bot value band
        td.request(
            2,
            Function::setChatPhoto(td_api::setChatPhoto {
                chat_id: channel_dialog,
                photo: None,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_editPhoto::ID,
        );
        net_fail(sent, 400, "CHAT_NOT_MODIFIED");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::ok(_))
        ));

        // 3. the plain error band surfaces the error
        td.request(
            3,
            Function::setChatPhoto(td_api::setChatPhoto {
                chat_id: channel_dialog,
                photo: None,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_editPhoto::ID,
        );
        net_fail(sent, 400, "CHAT_ID_INVALID");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "CHAT_ID_INVALID");

        // 4. the rights band — a member channel answers the 400 before the
        //    query
        td.request(
            4,
            Function::setChatPhoto(td_api::setChatPhoto {
                chat_id: member_dialog,
                photo: None,
            }),
        );
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Not enough rights to change chat photo");

        // 5. the user band
        td.request(
            5,
            Function::setChatPhoto(td_api::setChatPhoto {
                chat_id: user_dialog,
                photo: None,
            }),
        );
        let error = error_of(&callback, 5);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Can't change private chat photo");

        // 6. the sticker form over a seeded custom emoji — the
        //    VIDEO_EMOJI_MARKUP wire (the videoSizeEmojiMarkup payload)
        td.stickers_manager.custom_emoji_to_sticker_id.insert(
            crate::stickers_manager::CustomEmojiId::new(7),
            Default::default(),
        );
        td.request(
            6,
            Function::setChatPhoto(td_api::setChatPhoto {
                chat_id: channel_dialog,
                photo: Some(td_api::InputChatPhoto::inputChatPhotoSticker(
                    td_api::inputChatPhotoSticker {
                        sticker: Some(td_api::ChatPhotoSticker {
                            r#type: Some(
                                td_api::ChatPhotoStickerType::chatPhotoStickerTypeCustomEmoji(
                                    td_api::chatPhotoStickerTypeCustomEmoji { custom_emoji_id: 7 },
                                ),
                            ),
                            background_fill: Some(td_api::BackgroundFill::backgroundFillSolid(
                                td_api::backgroundFillSolid { color: 0xFF0000 },
                            )),
                        }),
                    },
                )),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_editPhoto::ID,
        );
        let body = telegram_api::channels_editPhoto::parse(sent.query()).expect("the sent body");
        match body.photo {
            Some(telegram_api::InputChatPhoto::inputChatUploadedPhoto(uploaded)) => {
                assert_eq!(
                    uploaded.flags & (1 << 3),
                    1 << 3,
                    "the VIDEO_EMOJI_MARKUP bit"
                );
                match uploaded.video_emoji_markup {
                    Some(telegram_api::VideoSize::videoSizeEmojiMarkup(markup)) => {
                        assert_eq!(markup.emoji_id, 7);
                        assert_eq!(markup.background_colors, vec![0xFF0000]);
                    }
                    other => panic!("the emoji markup: {other:?}"),
                }
            }
            other => panic!("the uploaded photo form: {other:?}"),
        }
        net_complete(sent, updates_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 6).first(),
            Some(Object::ok(_))
        ));

        // 7. the unloaded stickers surface answers the local 400 (the
        //    custom emoji band)
        td.request(
            7,
            Function::setChatPhoto(td_api::setChatPhoto {
                chat_id: channel_dialog,
                photo: Some(td_api::InputChatPhoto::inputChatPhotoSticker(
                    td_api::inputChatPhotoSticker {
                        sticker: Some(td_api::ChatPhotoSticker {
                            r#type: Some(
                                td_api::ChatPhotoStickerType::chatPhotoStickerTypeCustomEmoji(
                                    td_api::chatPhotoStickerTypeCustomEmoji {
                                        custom_emoji_id: 999,
                                    },
                                ),
                            ),
                            background_fill: Some(td_api::BackgroundFill::backgroundFillSolid(
                                td_api::backgroundFillSolid { color: 0xFF0000 },
                            )),
                        }),
                    },
                )),
            }),
        );
        let error = error_of(&callback, 7);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Custom emoji not found");

        // 8. the static form parks at the Files upload tail (no query)
        td.request(
            8,
            Function::setChatPhoto(td_api::setChatPhoto {
                chat_id: channel_dialog,
                photo: Some(td_api::InputChatPhoto::inputChatPhotoStatic(
                    td_api::inputChatPhotoStatic {
                        photo: Some(td_api::InputFile::inputFileId(td_api::inputFileId {
                            id: 5,
                        })),
                    },
                )),
            }),
        );
        let error = error_of(&callback, 8);
        assert_eq!(error.code, 500);
        assert_eq!(error.message, "Network is not implemented yet");
        assert_not_sent(
            &rec,
            telegram_api::channels_editPhoto::ID,
            "the upload tail",
        );

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn chat_migration_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(chat_migration_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn chat_migration_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-migrate-chat");
        seed_dialog_chats(&mut td);
        // a member basic group — the creator-gate band
        seed_dialog_basic_group(&mut td, 711, false);
        let group_dialog =
            crate::messages_manager::DialogId::from_chat_id(crate::chat_manager::ChatId::new(701))
                .get();
        let member_group_dialog =
            crate::messages_manager::DialogId::from_chat_id(crate::chat_manager::ChatId::new(711))
                .get();
        let channel_dialog = crate::messages_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(702),
        )
        .get();
        let migrated_updates_answer = |with_channel: bool| {
            let mut chat = telegram_api::chat {
                creator: true,
                id: 701,
                title: "group".to_owned(),
                ..telegram_api::chat::default()
            };
            if with_channel {
                // the MIGRATED_TO_MASK flag bit gates the optional wire
                // field (the direct-struct seeds never serialize, so the
                // bit matters only on this stored answer)
                chat.flags |= 1 << 6;
                chat.migrated_to = Some(telegram_api::InputChannel::inputChannel(
                    telegram_api::inputChannel {
                        channel_id: 800,
                        access_hash: 999,
                    },
                ));
            }
            let mut answer = Vec::new();
            telegram_api::Updates::updates(telegram_api::updates {
                updates: Vec::new(),
                users: Vec::new(),
                chats: vec![telegram_api::Chat::chat(chat)],
                date: 0,
                seq: 0,
            })
            .store(&mut answer);
            answer
        };
        let empty_updates_answer = || {
            let mut answer = Vec::new();
            telegram_api::Updates::updates(telegram_api::updates {
                updates: Vec::new(),
                users: Vec::new(),
                chats: Vec::new(),
                date: 0,
                seq: 0,
            })
            .store(&mut answer);
            answer
        };

        // 1. the creator gate — a member basic group answers the 400
        //    BEFORE the park
        td.request(
            1,
            Function::upgradeBasicGroupChatToSupergroupChat(
                td_api::upgradeBasicGroupChatToSupergroupChat {
                    chat_id: member_group_dialog,
                },
            ),
        );
        let error = error_of(&callback, 1);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Need creator rights in the chat");
        assert_not_sent(
            &rec,
            telegram_api::messages_migrateChat::ID,
            "the creator band",
        );

        // 2. the type band — a channel can't be migrated
        td.request(
            2,
            Function::upgradeBasicGroupChatToSupergroupChat(
                td_api::upgradeBasicGroupChatToSupergroupChat {
                    chat_id: channel_dialog,
                },
            ),
        );
        let error = error_of(&callback, 2);
        assert_eq!(error.code, 400);
        assert_eq!(
            error.message,
            "Only basic group chats can be converted to supergroup"
        );

        // 3. the creator group — messages.migrateChat; a hard error
        //    forwards through the query promise
        td.request(
            3,
            Function::upgradeBasicGroupChatToSupergroupChat(
                td_api::upgradeBasicGroupChatToSupergroupChat {
                    chat_id: group_dialog,
                },
            ),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_migrateChat::ID,
        );
        let body = telegram_api::messages_migrateChat::parse(sent.query()).expect("the sent body");
        assert_eq!(body.chat_id, 701);
        net_fail(sent, 420, "FLOOD_WAIT_5");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "FLOOD_WAIT_5");

        // 4. the migration answer without the migrated chat — the
        //    on_migrate head answers the 500 "Supergroup not found"
        td.request(
            4,
            Function::upgradeBasicGroupChatToSupergroupChat(
                td_api::upgradeBasicGroupChatToSupergroupChat {
                    chat_id: group_dialog,
                },
            ),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_migrateChat::ID,
        );
        net_complete(sent, empty_updates_answer());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 500);
        assert_eq!(error.message, "Supergroup not found");

        // 5. the full migration answer — the intake sets the migrated-to
        //    channel and creates its record; the object tail parks at the
        //    M.10.20-22 chat-object residue
        td.request(
            5,
            Function::upgradeBasicGroupChatToSupergroupChat(
                td_api::upgradeBasicGroupChatToSupergroupChat {
                    chat_id: group_dialog,
                },
            ),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_migrateChat::ID,
        );
        net_complete(sent, migrated_updates_answer(true));
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 5);
        assert_eq!(error.code, 500);
        assert_eq!(error.message, "Network is not implemented yet");

        // 6. the migrated fast path — the record now carries the
        //    migrated-to channel, so the request takes the
        //    on_migrate_chat_to_megagroup arm with NO query out
        td.request(
            6,
            Function::upgradeBasicGroupChatToSupergroupChat(
                td_api::upgradeBasicGroupChatToSupergroupChat {
                    chat_id: group_dialog,
                },
            ),
        );
        td.flush_deferred_results();
        assert_not_sent(
            &rec,
            telegram_api::messages_migrateChat::ID,
            "the fast path",
        );
        let error = error_of(&callback, 6);
        assert_eq!(error.code, 500);
        assert_eq!(error.message, "Network is not implemented yet");

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn get_dialog_unread_marks_query_rides_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(get_dialog_unread_marks_query_rides_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn get_dialog_unread_marks_query_rides_the_dispatcher_impl() {
        let (mut td, rec) = netted_td("netfix-unread-marks");
        seed_dialog_user(&mut td);
        let user_dialog = crate::messages_manager::DialogId::from_user_id(
            crate::user_manager::UserId::new(700000001),
        );
        {
            let mut d = Box::new(crate::messages_manager::Dialog::default());
            d.dialog_id = user_dialog;
            d.is_update_new_chat_sent = true;
            td.messages_manager.dialogs.insert(user_dialog, d);
        }

        // 1. the load dispatches messages.getDialogUnreadMarks once
        crate::dialog_manager::load_dialog_marks_as_unread(&mut td);
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_getDialogUnreadMarks::ID,
        );
        // the answer — a vector of two dialog ids (the seeded user and an
        // unknown one); the unknown entry drops at the intake gates
        let mut answer = Vec::new();
        telegram_api::tl::__i32(&mut answer, telegram_api::tl::VECTOR_ID);
        telegram_api::tl::__i32(&mut answer, 2);
        telegram_api::tl::__i64(&mut answer, user_dialog.get());
        telegram_api::tl::__i64(&mut answer, 999999999);
        net_complete(sent, answer);
        td.dispatch_completed_dialog_net();
        assert!(
            td.messages_manager
                .get_dialog(user_dialog)
                .is_some_and(|d| d.is_marked_as_unread),
            "the marked entry flipped"
        );
        // the pmc flag settled — the next load is a no-op
        assert_eq!(td.global.binlog_pmc().get("fetched_marks_as_unread"), "1");
        crate::dialog_manager::load_dialog_marks_as_unread(&mut td);
        assert!(rec.sent.lock().is_empty(), "no re-fetch after the flag");

        // 2. the error band — expected errors log and the load re-arms
        let (mut td, rec) = netted_td("netfix-unread-marks-err");
        crate::dialog_manager::load_dialog_marks_as_unread(&mut td);
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_getDialogUnreadMarks::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_7");
        td.dispatch_completed_dialog_net();
        assert_eq!(
            td.global.binlog_pmc().get("fetched_marks_as_unread"),
            String::new(),
            "the flag stays unset on error"
        );
        // the retry dispatches again
        crate::dialog_manager::load_dialog_marks_as_unread(&mut td);
        assert_eq!(rec.sent.lock().len(), 1, "the load re-armed");
    }

    #[test]
    fn report_chat_query_rides_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(report_chat_query_rides_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn report_chat_query_rides_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-report-chat");
        seed_dialog_chats(&mut td);
        // a bot user — can_report_dialog admits only bot users
        {
            let crate::td::Td {
                global,
                option_manager,
                auth_manager,
                user_manager,
                ..
            } = &mut td;
            let mut env = crate::user_manager::UserEnv {
                global,
                options: option_manager
                    .as_mut()
                    .expect("option manager exists after init"),
                auth_is_bot: auth_manager.is_bot(),
            };
            user_manager.on_get_user(
                &mut env,
                telegram_api::User::user(telegram_api::user {
                    id: 700000002,
                    flags: 1,
                    access_hash: 6,
                    first_name: "Bot".to_owned(),
                    bot: true,
                    ..telegram_api::user::default()
                }),
                "test",
            );
        }
        let bot_dialog = crate::messages_manager::DialogId::from_user_id(
            crate::user_manager::UserId::new(700000002),
        )
        .get();
        let group_dialog =
            crate::messages_manager::DialogId::from_chat_id(crate::chat_manager::ChatId::new(701))
                .get();

        // 1. the happy path — messages.report with the Read peer, the
        //    server message ids and the raw option bytes; the reported
        //    answer maps to reportChatResultOk
        td.request(
            1,
            Function::reportChat(td_api::reportChat {
                chat_id: bot_dialog,
                option_id: b"spam".to_vec(),
                message_ids: vec![100 << 20, 250 << 20],
                text: "it is spam".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_report::ID,
        );
        let body = telegram_api::messages_report::parse(sent.query()).expect("the sent body");
        match body.peer.as_deref() {
            Some(telegram_api::InputPeer::inputPeerUser(peer)) => {
                assert_eq!(peer.user_id, 700000002);
                assert_eq!(peer.access_hash, 6);
            }
            other => panic!("the read peer: {other:?}"),
        }
        assert_eq!(body.id, vec![100, 250]);
        assert_eq!(body.option, b"spam".to_vec());
        assert_eq!(body.message, "it is spam");
        let mut answer = Vec::new();
        telegram_api::ReportResult::reportResultReported(telegram_api::reportResultReported)
            .store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::reportChatResultOk(_))
        ));

        // 2. the chooseOption answer — the option list maps (the empty
        //    options band answers Ok)
        td.request(
            2,
            Function::reportChat(td_api::reportChat {
                chat_id: bot_dialog,
                option_id: Vec::new(),
                message_ids: Vec::new(),
                text: String::new(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_report::ID,
        );
        let mut answer = Vec::new();
        telegram_api::ReportResult::reportResultChooseOption(
            telegram_api::reportResultChooseOption {
                title: "Choose".to_owned(),
                options: vec![telegram_api::MessageReportOption {
                    text: "Spam".to_owned(),
                    option: b"opt1".to_vec(),
                }],
            },
        )
        .store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        match responses_of(&callback, 2).first() {
            Some(Object::reportChatResultOptionRequired(result)) => {
                assert_eq!(result.title, "Choose");
                assert_eq!(result.options.len(), 1);
                assert_eq!(result.options[0].id, b"opt1".to_vec());
                assert_eq!(result.options[0].text, "Spam");
            }
            other => panic!("the choose-option result: {other:?}"),
        }

        // 3. the empty-options chooseOption answer answers Ok
        td.request(
            3,
            Function::reportChat(td_api::reportChat {
                chat_id: bot_dialog,
                option_id: Vec::new(),
                message_ids: Vec::new(),
                text: String::new(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_report::ID,
        );
        let mut answer = Vec::new();
        telegram_api::ReportResult::reportResultChooseOption(
            telegram_api::reportResultChooseOption {
                title: String::new(),
                options: Vec::new(),
            },
        )
        .store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 3).first(),
            Some(Object::reportChatResultOk(_))
        ));

        // 4. the addComment answer maps to the text-required result
        td.request(
            4,
            Function::reportChat(td_api::reportChat {
                chat_id: bot_dialog,
                option_id: Vec::new(),
                message_ids: Vec::new(),
                text: String::new(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_report::ID,
        );
        let mut answer = Vec::new();
        telegram_api::ReportResult::reportResultAddComment(telegram_api::reportResultAddComment {
            flags: 0,
            optional: true,
            option: b"spam".to_vec(),
        })
        .store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        match responses_of(&callback, 4).first() {
            Some(Object::reportChatResultTextRequired(result)) => {
                assert_eq!(result.option_id, b"spam".to_vec());
                assert!(result.is_optional);
            }
            other => panic!("the text-required result: {other:?}"),
        }

        // 5. the MESSAGE_ID_REQUIRED error maps to the messages-required
        //    VALUE (not an error)
        td.request(
            5,
            Function::reportChat(td_api::reportChat {
                chat_id: bot_dialog,
                option_id: Vec::new(),
                message_ids: Vec::new(),
                text: String::new(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_report::ID,
        );
        net_fail(sent, 400, "MESSAGE_ID_REQUIRED");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 5).first(),
            Some(Object::reportChatResultMessagesRequired(_))
        ));

        // 6. the plain error forwards
        td.request(
            6,
            Function::reportChat(td_api::reportChat {
                chat_id: bot_dialog,
                option_id: Vec::new(),
                message_ids: Vec::new(),
                text: String::new(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_report::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_9");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 6);
        assert_eq!(error.code, 420);
        assert_eq!(error.message, "FLOOD_WAIT_9");

        // 7. the basic-group band — can_report_dialog rejects it
        td.request(
            7,
            Function::reportChat(td_api::reportChat {
                chat_id: group_dialog,
                option_id: Vec::new(),
                message_ids: Vec::new(),
                text: String::new(),
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 7);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Chat can't be reported");

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn get_blocked_message_senders_query_rides_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(get_blocked_message_senders_query_rides_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn get_blocked_message_senders_query_rides_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-blocked-dialogs");
        seed_dialog_user(&mut td);
        let the_user = || {
            telegram_api::User::user(telegram_api::user {
                id: 700000001,
                flags: 1,
                access_hash: 5,
                first_name: "User".to_owned(),
                ..telegram_api::user::default()
            })
        };

        // 1. the main block list — contacts.getBlocked with the offset
        //    and limit; the contacts_blocked answer runs the users/chats
        //    intakes then the senders builder
        td.request(
            1,
            Function::getBlockedMessageSenders(td_api::getBlockedMessageSenders {
                block_list: Some(td_api::BlockList::blockListMain(td_api::blockListMain)),
                offset: 0,
                limit: 10,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getBlocked::ID,
        );
        let body = telegram_api::contacts_getBlocked::parse(sent.query()).expect("the sent body");
        assert!(!body.my_stories_from, "the main list flag");
        assert_eq!(body.offset, 0);
        assert_eq!(body.limit, 10);
        let mut answer = Vec::new();
        telegram_api::contacts_Blocked::contacts_blocked(telegram_api::contacts_blocked {
            blocked: vec![telegram_api::PeerBlocked {
                peer_id: Some(telegram_api::Peer::peerUser(telegram_api::peerUser {
                    user_id: 700000001,
                })),
                date: 100,
            }],
            chats: Vec::new(),
            users: vec![the_user()],
        })
        .store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        match responses_of(&callback, 1).first() {
            Some(Object::messageSenders(senders)) => {
                assert_eq!(senders.total_count, 1);
                assert_eq!(senders.senders.len(), 1);
                assert!(matches!(
                    senders.senders[0],
                    td_api::MessageSender::messageSenderUser(_)
                ));
            }
            other => panic!("the message senders: {other:?}"),
        }

        // 2. the slice form — the server count wins (and the
        //    count-repair band never triggers for a consistent answer)
        td.request(
            2,
            Function::getBlockedMessageSenders(td_api::getBlockedMessageSenders {
                block_list: Some(td_api::BlockList::blockListMain(td_api::blockListMain)),
                offset: 10,
                limit: 10,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getBlocked::ID,
        );
        let body = telegram_api::contacts_getBlocked::parse(sent.query()).expect("the sent body");
        assert_eq!(body.offset, 10);
        let mut answer = Vec::new();
        telegram_api::contacts_Blocked::contacts_blockedSlice(
            telegram_api::contacts_blockedSlice {
                count: 42,
                blocked: Vec::new(),
                chats: Vec::new(),
                users: Vec::new(),
            },
        )
        .store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        match responses_of(&callback, 2).first() {
            Some(Object::messageSenders(senders)) => {
                assert_eq!(senders.total_count, 42);
                assert!(senders.senders.is_empty());
            }
            other => panic!("the slice senders: {other:?}"),
        }

        // 3. the stories block list flag
        td.request(
            3,
            Function::getBlockedMessageSenders(td_api::getBlockedMessageSenders {
                block_list: Some(td_api::BlockList::blockListStories(
                    td_api::blockListStories,
                )),
                offset: 0,
                limit: 100,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_getBlocked::ID,
        );
        let body = telegram_api::contacts_getBlocked::parse(sent.query()).expect("the sent body");
        assert!(body.my_stories_from, "the stories list flag");
        net_fail(sent, 500, "Blocked flood");
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(error.code, 500);
        assert_eq!(error.message, "Blocked flood");

        // 4. the parameter bands — no query out
        td.request(
            4,
            Function::getBlockedMessageSenders(td_api::getBlockedMessageSenders {
                block_list: Some(td_api::BlockList::blockListMain(td_api::blockListMain)),
                offset: -1,
                limit: 10,
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Parameter offset must be non-negative");
        td.request(
            5,
            Function::getBlockedMessageSenders(td_api::getBlockedMessageSenders {
                block_list: None,
                offset: 0,
                limit: 10,
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 5);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Block list must be non-empty");
        assert!(rec.sent.lock().is_empty(), "no query on the bands");

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn toggle_dialog_report_spam_state_rides_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(toggle_dialog_report_spam_state_rides_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn toggle_dialog_report_spam_state_rides_the_dispatcher_impl() {
        let (mut td, rec) = netted_td("netfix-report-spam-state");
        const BOOL_TRUE: i32 = 0x9972_75b5u32 as i32;
        seed_dialog_user(&mut td);
        let user_dialog = crate::messages_manager::DialogId::from_user_id(
            crate::user_manager::UserId::new(700000001),
        );

        // 1. the report-spam form — messages.reportSpam with the Read
        //    peer; the ok answer completes the (erase-wrapped) promise
        let (promise, result) = record_ton_unit();
        crate::dialog_manager::toggle_dialog_report_spam_state_on_server(
            &mut td,
            user_dialog,
            true,
            0,
            promise,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_reportSpam::ID,
        );
        let body = telegram_api::messages_reportSpam::parse(sent.query()).expect("the sent body");
        match body.peer.as_deref() {
            Some(telegram_api::InputPeer::inputPeerUser(peer)) => {
                assert_eq!(peer.user_id, 700000001);
                assert_eq!(peer.access_hash, 5);
            }
            other => panic!("the read peer: {other:?}"),
        }
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();
        assert!(matches!(
            result.lock().unwrap().take(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 2. the hide-bar form — messages.hidePeerSettingsBar
        let (promise, result) = record_ton_unit();
        crate::dialog_manager::toggle_dialog_report_spam_state_on_server(
            &mut td,
            user_dialog,
            false,
            0,
            promise,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_hidePeerSettingsBar::ID,
        );
        drop(
            telegram_api::messages_hidePeerSettingsBar::parse(sent.query()).expect("the sent body"),
        );
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();
        assert!(matches!(
            result.lock().unwrap().take(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 3. the null input peer — the net-free SUCCESS band (no query)
        let (promise, result) = record_ton_unit();
        crate::dialog_manager::toggle_dialog_report_spam_state_on_server(
            &mut td,
            crate::messages_manager::DialogId::from_user_id(crate::user_manager::UserId::new(
                700000099,
            )),
            true,
            0,
            promise,
        );
        assert!(rec.sent.lock().is_empty(), "no query without a peer");
        assert!(matches!(
            result.lock().unwrap().take(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 4. the error band forwards (the action-bar reload is the
        //    MessagesManager step — documented drop)
        let (promise, result) = record_ton_unit();
        crate::dialog_manager::toggle_dialog_report_spam_state_on_server(
            &mut td,
            user_dialog,
            true,
            0,
            promise,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_reportSpam::ID,
        );
        net_fail(sent, 420, "PEER_ID_INVALID");
        td.dispatch_completed_dialog_net();
        match result.lock().unwrap().take() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.code(), 420);
                assert_eq!(status.message(), "PEER_ID_INVALID");
            }
            other => panic!("the error band: {other:?}"),
        }

        // 5. the secret-chat spam leg — messages.reportEncryptedSpam
        //    over the Read input encrypted chat
        {
            let crate::td::Td {
                global,
                option_manager,
                auth_manager,
                user_manager,
                ..
            } = &mut td;
            let mut env = crate::user_manager::UserEnv {
                global,
                options: option_manager
                    .as_mut()
                    .expect("option manager exists after init"),
                auth_is_bot: auth_manager.is_bot(),
            };
            user_manager.on_update_secret_chat(
                &mut env,
                crate::user_manager::SecretChatId::new(33),
                4321,
                crate::user_manager::UserId::new(700000001),
                crate::user_manager::SecretChatState::Active,
                true,
                -1,
                0,
                String::new(),
                0,
                0,
            );
        }
        let secret_dialog = crate::messages_manager::DialogId::from_secret_chat_id(
            crate::user_manager::SecretChatId::new(33),
        );
        let (promise, result) = record_ton_unit();
        crate::dialog_manager::toggle_dialog_report_spam_state_on_server(
            &mut td,
            secret_dialog,
            true,
            0,
            promise,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_reportEncryptedSpam::ID,
        );
        let body =
            telegram_api::messages_reportEncryptedSpam::parse(sent.query()).expect("the sent body");
        match body.peer {
            Some(telegram_api::InputEncryptedChat {
                chat_id,
                access_hash,
            }) => {
                assert_eq!(chat_id, 33);
                assert_eq!(access_hash, 4321);
            }
            other => panic!("the encrypted peer: {other:?}"),
        }
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();
        assert!(matches!(
            result.lock().unwrap().take(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 6. the secret-chat hide-bar leg — the user-not-found 400
        let (promise, result) = record_ton_unit();
        crate::dialog_manager::toggle_dialog_report_spam_state_on_server(
            &mut td,
            crate::messages_manager::DialogId::from_secret_chat_id(
                crate::user_manager::SecretChatId::new(77),
            ),
            false,
            0,
            promise,
        );
        assert!(rec.sent.lock().is_empty(), "no query for the unknown chat");
        match result.lock().unwrap().take() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.code(), 400);
                assert_eq!(status.message(), "Peer user not found");
            }
            other => panic!("the unknown-secret-chat band: {other:?}"),
        }

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn reorder_pinned_dialogs_query_rides_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(reorder_pinned_dialogs_query_rides_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn reorder_pinned_dialogs_query_rides_the_dispatcher_impl() {
        let (mut td, rec, _callback) = netted_td_with_files("netfix-reorder-pinned");
        const BOOL_TRUE: i32 = 0x9972_75b5u32 as i32;
        const BOOL_FALSE: i32 = 0xbc79_9737u32 as i32;
        seed_dialog_user(&mut td);
        let user_dialog = crate::messages_manager::DialogId::from_user_id(
            crate::user_manager::UserId::new(700000001),
        );

        // 1. the live send — force + the folder id + the Read input
        //    dialog peers; the binlog mirror is saved (use_message_database
        //    is on in the files form) and the answer resolves the
        //    erase-wrapped promise
        crate::dialog_manager::reorder_pinned_dialogs_on_server(&mut td, 1, &[user_dialog], 0);
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_reorderPinnedDialogs::ID,
        );
        let body = telegram_api::messages_reorderPinnedDialogs::parse(sent.query())
            .expect("the sent body");
        assert!(body.force);
        assert_eq!(body.folder_id, 1);
        match body.order.as_slice() {
            [telegram_api::InputDialogPeer::inputDialogPeer(peer)] => match peer.peer.as_deref() {
                Some(telegram_api::InputPeer::inputPeerUser(peer)) => {
                    assert_eq!(peer.user_id, 700000001);
                }
                other => panic!("the reorder peer: {other:?}"),
            },
            other => panic!("the reorder order: {other:?}"),
        }
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();

        // 2. the false answer is the C++ 400 ("Result is false") — the
        //    promise settles through the erase wrapper (the mirror
        //    retires either way)
        crate::dialog_manager::reorder_pinned_dialogs_on_server(&mut td, 0, &[user_dialog], 0);
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_reorderPinnedDialogs::ID,
        );
        net_complete(sent, BOOL_FALSE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();

        // 3. the error band (the on_update_pinned_dialogs refire is the
        //    dialog-list plane — documented drop)
        crate::dialog_manager::reorder_pinned_dialogs_on_server(&mut td, 0, &[user_dialog], 0);
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_reorderPinnedDialogs::ID,
        );
        net_fail(sent, 500, "FOLDER_SAVE_FAILED");
        td.dispatch_completed_dialog_net();

        // 4. the no-database form — no mirror, the same query
        crate::dialog_manager::reorder_pinned_dialogs_on_server(&mut td, 1, &[user_dialog], 12345);
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_reorderPinnedDialogs::ID,
        );
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn toggle_dialog_is_blocked_query_rides_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(toggle_dialog_is_blocked_query_rides_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn toggle_dialog_is_blocked_query_rides_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-toggle-blocked");
        const BOOL_TRUE: i32 = 0x9972_75b5u32 as i32;
        const BOOL_FALSE: i32 = 0xbc79_9737u32 as i32;
        seed_dialog_user(&mut td);
        seed_dialog_basic_group(&mut td, 701, true);
        let user_dialog = crate::messages_manager::DialogId::from_user_id(
            crate::user_manager::UserId::new(700000001),
        );
        let group_dialog =
            crate::messages_manager::DialogId::from_chat_id(crate::chat_manager::ChatId::new(701))
                .get();

        // 1. the block send — contacts.block with the stories flag off;
        //    the ok answer completes even for the false bool (the warning
        //    band)
        crate::dialog_manager::toggle_dialog_is_blocked_on_server(
            &mut td,
            user_dialog,
            true,
            false,
            0,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_block::ID,
        );
        let body = telegram_api::contacts_block::parse(sent.query()).expect("the sent body");
        assert!(!body.my_stories_from);
        match body.id.as_deref() {
            Some(telegram_api::InputPeer::inputPeerUser(peer)) => {
                assert_eq!(peer.user_id, 700000001);
            }
            other => panic!("the block peer: {other:?}"),
        }
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();

        // 2. the stories-only variant — the block twin still fires with
        //    the my_stories_from flag (the C++ twin choice is
        //    is_blocked || is_blocked_for_stories)
        crate::dialog_manager::toggle_dialog_is_blocked_on_server(
            &mut td,
            user_dialog,
            false,
            true,
            0,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_block::ID,
        );
        let body = telegram_api::contacts_block::parse(sent.query()).expect("the sent body");
        assert!(body.my_stories_from);
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();

        // 2b. the full unblock — contacts.unblock with the stories flag
        //     off
        crate::dialog_manager::toggle_dialog_is_blocked_on_server(
            &mut td,
            user_dialog,
            false,
            false,
            0,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_unblock::ID,
        );
        let body = telegram_api::contacts_unblock::parse(sent.query()).expect("the sent body");
        assert!(!body.my_stories_from);
        net_complete(sent, BOOL_FALSE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();

        // 3. the error band forwards (the reload refires are documented
        //    drops)
        crate::dialog_manager::toggle_dialog_is_blocked_on_server(
            &mut td,
            user_dialog,
            true,
            false,
            0,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_block::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_2");
        td.dispatch_completed_dialog_net();

        // 4. the live td_api arm — setMessageSenderBlockList on the
        //    bot-user sender: the local user-full fan-in (no dialog
        //    record) then the same net send
        td.request(
            1,
            Function::setMessageSenderBlockList(td_api::setMessageSenderBlockList {
                sender_id: Some(td_api::MessageSender::messageSenderUser(
                    td_api::messageSenderUser { user_id: 700000001 },
                )),
                block_list: Some(td_api::BlockList::blockListMain(td_api::blockListMain)),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::contacts_block::ID,
        );
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));

        // 5. the ladder bands — the basic group 400 and the self block
        td.request(
            2,
            Function::setMessageSenderBlockList(td_api::setMessageSenderBlockList {
                sender_id: Some(td_api::MessageSender::messageSenderChat(
                    td_api::messageSenderChat {
                        chat_id: group_dialog,
                    },
                )),
                block_list: Some(td_api::BlockList::blockListMain(td_api::blockListMain)),
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 2);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Basic group chats can't be blocked");

        tdactor::ActorMessage::dispatch(SeedMyId(700000001), &mut td);
        td.request(
            3,
            Function::setMessageSenderBlockList(td_api::setMessageSenderBlockList {
                sender_id: Some(td_api::MessageSender::messageSenderUser(
                    td_api::messageSenderUser { user_id: 700000001 },
                )),
                block_list: Some(td_api::BlockList::blockListStories(
                    td_api::blockListStories,
                )),
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Can't block self");

        // the unknown sender band
        td.request(
            4,
            Function::setMessageSenderBlockList(td_api::setMessageSenderBlockList {
                sender_id: Some(td_api::MessageSender::messageSenderUser(
                    td_api::messageSenderUser { user_id: 987654 },
                )),
                block_list: Some(td_api::BlockList::blockListMain(td_api::blockListMain)),
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 4);
        assert_eq!(error.code, 400);
        assert_eq!(error.message, "Unknown user identifier specified");

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn toggle_dialog_unread_mark_query_rides_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(toggle_dialog_unread_mark_query_rides_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn toggle_dialog_unread_mark_query_rides_the_dispatcher_impl() {
        let (mut td, rec) = netted_td("netfix-toggle-unread-mark");
        const BOOL_TRUE: i32 = 0x9972_75b5u32 as i32;
        const BOOL_FALSE: i32 = 0xbc79_9737u32 as i32;
        seed_dialog_user(&mut td);
        let user_dialog = crate::messages_manager::DialogId::from_user_id(
            crate::user_manager::UserId::new(700000001),
        );

        // 1. the send — messages.markDialogUnread with the Read input
        //    dialog peer (no PARENT_PEER flag; the topic leg rides the
        //    SavedMessagesManager plane)
        crate::dialog_manager::toggle_dialog_is_marked_as_unread_on_server(
            &mut td,
            user_dialog,
            0,
            true,
            0,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_markDialogUnread::ID,
        );
        let body =
            telegram_api::messages_markDialogUnread::parse(sent.query()).expect("the sent body");
        assert!(body.unread);
        assert!(body.parent_peer.is_none());
        match body.peer.as_ref() {
            Some(telegram_api::InputDialogPeer::inputDialogPeer(peer)) => {
                match peer.peer.as_deref() {
                    Some(telegram_api::InputPeer::inputPeerUser(peer)) => {
                        assert_eq!(peer.user_id, 700000001);
                    }
                    other => panic!("the mark peer: {other:?}"),
                }
            }
            other => panic!("the mark dialog peer: {other:?}"),
        }
        net_complete(sent, BOOL_TRUE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();

        // 2. the false answer is the C++ 400
        crate::dialog_manager::toggle_dialog_is_marked_as_unread_on_server(
            &mut td,
            user_dialog,
            0,
            true,
            0,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_markDialogUnread::ID,
        );
        net_complete(sent, BOOL_FALSE.to_le_bytes().to_vec());
        td.dispatch_completed_dialog_net();

        // 3. the error band — the local mark reverts (the seeded dialog
        //    record flips back)
        {
            let mut d = Box::new(crate::messages_manager::Dialog::default());
            d.dialog_id = user_dialog;
            d.is_update_new_chat_sent = true;
            td.messages_manager.dialogs.insert(user_dialog, d);
        }
        crate::dialog_manager::toggle_dialog_is_marked_as_unread_on_server(
            &mut td,
            user_dialog,
            0,
            true,
            0,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_markDialogUnread::ID,
        );
        net_fail(sent, 500, "mark failed");
        td.dispatch_completed_dialog_net();
        assert!(
            !td.messages_manager
                .get_dialog(user_dialog)
                .is_some_and(|d| d.is_marked_as_unread),
            "the revert intake ran"
        );

        // 4. the peer-less band — the send-site 400 with no query
        crate::dialog_manager::toggle_dialog_is_marked_as_unread_on_server(
            &mut td,
            crate::messages_manager::DialogId::from_user_id(crate::user_manager::UserId::new(
                700000099,
            )),
            0,
            true,
            0,
        );
        assert!(rec.sent.lock().is_empty(), "no query without a peer");

        assert!(td.dialog_net_completed.lock().is_empty(), "drained");
    }

