    // ---- the theme net slice: the four queries ride the dispatcher
    // (ThemeManager.cpp:44-170). ----

    type GiftThemesSlot =
        std::sync::Arc<std::sync::Mutex<Option<tdutils::status::Result<td_api::GiftChatThemes>>>>;

    fn record_gift_themes() -> (Promise<td_api::GiftChatThemes>, GiftThemesSlot) {
        struct Rec(GiftThemesSlot);
        impl tdutils::promise::PromiseInterface<td_api::GiftChatThemes> for Rec {
            fn set_value(&mut self, value: td_api::GiftChatThemes) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
            }
            fn set_error(&mut self, error: Status) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
            }
        }
        let slot: GiftThemesSlot = std::sync::Arc::new(std::sync::Mutex::new(None));
        (Promise::from_interface(Rec(slot.clone())), slot)
    }

    #[test]
    fn theme_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(theme_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn theme_queries_ride_the_dispatcher_impl() {
        let (mut td, rec) = netted_td("netfix-theme");

        // 1. reload_chat_themes — the account.themes answer lands in the
        //    intake (the update fires).
        {
            let theme_net = td.theme_net();
            let mut manager = std::mem::take(&mut td.theme_manager);
            let mut env = ThemeEnv {
                global: &mut td.global,
                options: td.option_manager.as_mut(),
                auth_is_authorized: td.auth_manager.is_authorized(),
                auth_is_bot: td.auth_manager.is_bot(),
                user_manager: &mut td.user_manager,
                chat_manager: &mut td.chat_manager,
                file_manager: std::sync::Arc::clone(&td.file_manager),
                updates: &mut td.theme_updates,
                file_load_manager: std::sync::Arc::clone(&td.file_load_manager),
                file_reference_manager: &mut td.file_reference_manager,
                documents_manager: &mut td.documents_manager,
                animations: &mut td.animations_manager,
                audios: &mut td.audios_manager,
                videos: &mut td.videos_manager,
                voice_notes: &mut td.voice_notes_manager,
                video_notes: &mut td.video_notes_manager,
                background_manager: &mut td.background_manager,
                background_updates: &mut td.background_updates,
                theme_net,
            };
            manager.reload_chat_themes(&mut env);
            td.theme_manager = manager;
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::account_getChatThemes::ID
        );
        let mut answer = Vec::new();
        telegram_api::account_Themes::account_themes(telegram_api::account_themes {
            hash: 7,
            themes: Vec::new(),
        })
        .store(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_theme_net();
        assert!(
            td.theme_updates
                .iter()
                .any(|u| matches!(u, td_api::Update::updateEmojiChatThemes(_))),
            "the intake fired the chat-themes update"
        );

        // 2. getUniqueGiftChatThemes — the pager promise resolves with
        //    the next offset.
        let (promise, slot) = record_gift_themes();
        {
            let theme_net = td.theme_net();
            let mut manager = std::mem::take(&mut td.theme_manager);
            let mut env = ThemeEnv {
                global: &mut td.global,
                options: td.option_manager.as_mut(),
                auth_is_authorized: td.auth_manager.is_authorized(),
                auth_is_bot: td.auth_manager.is_bot(),
                user_manager: &mut td.user_manager,
                chat_manager: &mut td.chat_manager,
                file_manager: std::sync::Arc::clone(&td.file_manager),
                updates: &mut td.theme_updates,
                file_load_manager: std::sync::Arc::clone(&td.file_load_manager),
                file_reference_manager: &mut td.file_reference_manager,
                documents_manager: &mut td.documents_manager,
                animations: &mut td.animations_manager,
                audios: &mut td.audios_manager,
                videos: &mut td.videos_manager,
                voice_notes: &mut td.voice_notes_manager,
                video_notes: &mut td.video_notes_manager,
                background_manager: &mut td.background_manager,
                background_updates: &mut td.background_updates,
                theme_net,
            };
            manager.get_unique_gift_chat_themes(&mut env, "off", 8, promise);
            td.theme_manager = manager;
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::account_getUniqueGiftChatThemes::ID
        );
        let mut answer = Vec::new();
        telegram_api::account_ChatThemes::account_chatThemes(telegram_api::account_chatThemes {
            flags: 1,
            hash: 0,
            themes: Vec::new(),
            chats: Vec::new(),
            users: Vec::new(),
            next_offset: "next".to_string(),
        })
        .store(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_theme_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(themes)) => {
                assert_eq!(themes.next_offset, "next");
                assert!(themes.themes.is_empty());
            }
            other => panic!("unexpected gift themes result: {other:?}"),
        }

        // 3. the peer-colors notModified arm — the intake returns
        //    without an update.
        let updates_before = td.theme_updates.len();
        {
            let theme_net = td.theme_net();
            let mut manager = std::mem::take(&mut td.theme_manager);
            let mut env = ThemeEnv {
                global: &mut td.global,
                options: td.option_manager.as_mut(),
                auth_is_authorized: td.auth_manager.is_authorized(),
                auth_is_bot: td.auth_manager.is_bot(),
                user_manager: &mut td.user_manager,
                chat_manager: &mut td.chat_manager,
                file_manager: std::sync::Arc::clone(&td.file_manager),
                updates: &mut td.theme_updates,
                file_load_manager: std::sync::Arc::clone(&td.file_load_manager),
                file_reference_manager: &mut td.file_reference_manager,
                documents_manager: &mut td.documents_manager,
                animations: &mut td.animations_manager,
                audios: &mut td.audios_manager,
                videos: &mut td.videos_manager,
                voice_notes: &mut td.voice_notes_manager,
                video_notes: &mut td.video_notes_manager,
                background_manager: &mut td.background_manager,
                background_updates: &mut td.background_updates,
                theme_net,
            };
            manager.reload_accent_colors(&mut env);
            td.theme_manager = manager;
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::help_getPeerColors::ID
        );
        let mut answer = Vec::new();
        telegram_api::help_PeerColors::help_peerColorsNotModified(
            telegram_api::help_peerColorsNotModified,
        )
        .store(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_theme_net();
        assert_eq!(td.theme_updates.len(), updates_before, "notModified no-ops");

        assert!(td.theme_net_completed.lock().is_empty(), "drained");
    }

    // ---- the quick-reply net slice: the four shortcut queries ride
    // the dispatcher (QuickReplyManager.cpp:91-240). ----

    #[test]
    fn quick_reply_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(quick_reply_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn quick_reply_queries_ride_the_dispatcher_impl() {
        let (mut td, rec) = netted_td("netfix-quick-reply");

        // Seed the shortcut map (the updateQuickReplyShortcut intake).
        {
            let (mut manager, mut env) = quick_reply_env_split(&mut td);
            manager.on_update_quick_reply_shortcut(&mut env, 1, "first".to_string());
            td.quick_reply_manager = manager;
        }

        // 1. editQuickReplyShortcut — answers Updates (the value drops).
        let (promise, slot) = record_translation_unit();
        {
            let (mut manager, mut env) = quick_reply_env_split(&mut td);
            manager.set_quick_reply_shortcut_name(&mut env, 1, "second", promise);
            td.quick_reply_manager = manager;
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::messages_editQuickReplyShortcut::ID
        );
        let mut answer = Vec::new();
        telegram_api::Updates::updatesTooLong(telegram_api::updatesTooLong).store(&mut answer);
        net_complete(sent.into_iter().next().unwrap(), answer);
        td.dispatch_completed_quick_reply_net();
        assert!(matches!(
            slot.lock().unwrap().take(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 2. deleteQuickReplyShortcut — answers Bool (the value drops).
        let (promise, slot) = record_translation_unit();
        {
            let (mut manager, mut env) = quick_reply_env_split(&mut td);
            manager.delete_quick_reply_shortcut(&mut env, 1, promise);
            td.quick_reply_manager = manager;
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::messages_deleteQuickReplyShortcut::ID
        );
        net_complete(sent.into_iter().next().unwrap(), bool_answer(false));
        td.dispatch_completed_quick_reply_net();
        assert!(matches!(
            slot.lock().unwrap().take(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 3. the delete-messages error tail — the promise errors and the
        //    reload re-entry parks at the messages plane (logged).
        {
            let (mut manager, mut env) = quick_reply_env_split(&mut td);
            manager.on_update_quick_reply_shortcut(&mut env, 2, "notes".to_string());
            td.quick_reply_manager = manager;
        }
        let (promise, slot) = record_translation_unit();
        {
            let (mut manager, mut env) = quick_reply_env_split(&mut td);
            manager.delete_quick_reply_shortcut_messages(&mut env, 2, &[100], promise);
            td.quick_reply_manager = manager;
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::messages_deleteQuickReplyMessages::ID
        );
        net_fail(sent.into_iter().next().unwrap(), 400, "MESSAGE_IDS_INVALID");
        td.dispatch_completed_quick_reply_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.message(), "MESSAGE_IDS_INVALID");
            }
            other => panic!("the error tail answers 400: {other:?}"),
        }

        // 3.5 the delete-messages ok tail (6aa26a95f) — the Updates
        //     answer re-enters `on_get_updates` carrying the promise; an
        //     empty umbrella settles it ok.
        {
            let (mut manager, mut env) = quick_reply_env_split(&mut td);
            manager.on_update_quick_reply_shortcut(&mut env, 2, "notes".to_string());
            td.quick_reply_manager = manager;
        }
        let (promise, slot) = record_translation_unit();
        {
            let (mut manager, mut env) = quick_reply_env_split(&mut td);
            manager.delete_quick_reply_shortcut_messages(&mut env, 2, &[100], promise);
            td.quick_reply_manager = manager;
        }
        // (the empty umbrella's state reconciliation may queue its own
        // query — pick the delete answer by constructor)
        let sent = std::mem::take(&mut *rec.sent.lock())
            .into_iter()
            .find(|q| q.tl_constructor() == telegram_api::messages_deleteQuickReplyMessages::ID)
            .expect("the delete-messages query rode the dispatcher");
        let mut answer = Vec::new();
        telegram_api::Updates::updates(telegram_api::updates {
            updates: Vec::new(),
            users: Vec::new(),
            chats: Vec::new(),
            seq: 0,
            date: 0,
        })
        .store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_quick_reply_net();
        assert!(
            matches!(
                slot.lock().unwrap().take(),
                Some(tdutils::status::Result::Ok(()))
            ),
            "the promise settles through on_get_updates"
        );

        // 4. reorderQuickReplies — answers Bool (the value drops).
        {
            let (mut manager, mut env) = quick_reply_env_split(&mut td);
            manager.on_update_quick_reply_shortcut(&mut env, 3, "third".to_string());
            td.quick_reply_manager = manager;
        }
        let (promise, slot) = record_translation_unit();
        {
            let (mut manager, mut env) = quick_reply_env_split(&mut td);
            manager.reorder_quick_reply_shortcuts(&mut env, &[3, 2], promise);
            td.quick_reply_manager = manager;
        }
        let sent = std::mem::take(&mut *rec.sent.lock())
            .into_iter()
            .find(|q| q.tl_constructor() == telegram_api::messages_reorderQuickReplies::ID)
            .expect("the reorder query rode the dispatcher");
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_quick_reply_net();
        assert!(matches!(
            slot.lock().unwrap().take(),
            Some(tdutils::status::Result::Ok(()))
        ));

        assert!(td.quick_reply_net_completed.lock().is_empty(), "drained");
        assert!(
            td.quick_reply_manager.net_promises.is_empty(),
            "all promises resolved"
        );
    }

    // ---- the autosave net slice (§3.9): the get/save settings pair rides
    // the dispatcher (AutosaveManager.cpp:32-95); the delete query stays
    // parked at its seam. ----

    /// A wire `autoSaveSettings` with the video-size flag (the
    /// manager-test helper shape).
    fn autosave_wire_settings(
        photos: bool,
        videos: bool,
        size: i64,
    ) -> telegram_api::AutoSaveSettings {
        telegram_api::AutoSaveSettings {
            flags: 1 << 2,
            photos,
            videos,
            video_max_size: size,
        }
    }

    /// A boxed `account.autoSaveSettings` answer.
    fn autosave_answer(
        users: telegram_api::AutoSaveSettings,
        chats: telegram_api::AutoSaveSettings,
        broadcasts: telegram_api::AutoSaveSettings,
    ) -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::account_AutoSaveSettings {
            users_settings: Some(users),
            chats_settings: Some(chats),
            broadcasts_settings: Some(broadcasts),
            exceptions: Vec::new(),
            chats: Vec::new(),
            users: Vec::new(),
        }
        .store_boxed(&mut answer);
        answer
    }

    fn autosave_private_scope() -> td_api::AutosaveSettingsScope {
        td_api::AutosaveSettingsScope::autosaveSettingsScopePrivateChats(
            td_api::autosaveSettingsScopePrivateChats,
        )
    }

    fn autosave_scope_chat(chat_id: i64) -> td_api::AutosaveSettingsScope {
        td_api::AutosaveSettingsScope::autosaveSettingsScopeChat(
            td_api::autosaveSettingsScopeChat { chat_id },
        )
    }

    #[test]
    fn autosave_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(autosave_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn autosave_queries_ride_the_dispatcher_impl() {
        let (mut td, rec) = netted_td("netfix-autosave");

        // seed a received user so the per-dialog save form resolves the
        // peer with its access hash (the C++ in-query build, cpp:72-75)
        with_user_manager(&mut td, |manager, env| {
            manager.on_get_users(env, vec![wire_user(7, "Bob")], "t");
        });

        // 1. the get leg: the reload query dispatches, the answer lands
        //    in the real intake and the parked request promise resolves.
        let (promise, slot) = record_bot_info_result::<td_api::AutosaveSettings>();
        {
            let (mut manager, mut env) = autosave_env_split(&mut td);
            manager.get_autosave_settings(&mut env, promise);
            td.autosave_manager = manager;
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::account_getAutoSaveSettings::ID
        );
        net_complete(
            sent.into_iter().next().unwrap(),
            autosave_answer(
                autosave_wire_settings(true, false, 10_000_000),
                autosave_wire_settings(false, false, 1),
                autosave_wire_settings(false, false, 1),
            ),
        );
        td.dispatch_completed_autosave_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Ok(settings)) => {
                let private = settings.private_chat_settings.expect("inited");
                assert!(private.autosave_photos && !private.autosave_videos);
                assert!(settings.exceptions.is_empty());
            }
            other => panic!("unexpected get result: {other:?}"),
        }
        assert_eq!(td.autosave_updates.len(), 3, "one update per scope");

        // 2. the save leg (the scope form): peer-less, the users flag
        //    rides, no PEER_MASK.
        let (promise, slot) = record_translation_unit();
        {
            let (mut manager, mut env) = autosave_env_split(&mut td);
            manager.set_autosave_settings(
                &mut env,
                Some(autosave_private_scope()),
                Some(td_api::ScopeAutosaveSettings {
                    autosave_photos: true,
                    autosave_videos: true,
                    max_video_file_size: 20_000_000,
                }),
                promise,
            );
            td.autosave_manager = manager;
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        let parsed = telegram_api::account_saveAutoSaveSettings::parse(sent[0].query()).unwrap();
        assert!(parsed.users && !parsed.chats && !parsed.broadcasts);
        assert_eq!(parsed.flags & (1 << 3), 0, "the scope form is peer-less");
        assert!(parsed.peer.is_none());
        assert_eq!(parsed.settings.as_ref().unwrap().video_max_size, 20_000_000);
        net_complete(sent.into_iter().next().unwrap(), bool_answer(true));
        td.dispatch_completed_autosave_net();
        assert!(matches!(
            slot.lock().unwrap().take(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 3. the per-dialog save form: the peer resolves with the access
        //    hash and PEER_MASK rides the flags.
        let (promise, slot) = record_translation_unit();
        {
            let (mut manager, mut env) = autosave_env_split(&mut td);
            manager.set_autosave_settings(
                &mut env,
                Some(autosave_scope_chat(7)),
                Some(td_api::ScopeAutosaveSettings {
                    autosave_photos: true,
                    autosave_videos: false,
                    max_video_file_size: 3_000_000,
                }),
                promise,
            );
            td.autosave_manager = manager;
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        let parsed = telegram_api::account_saveAutoSaveSettings::parse(sent[0].query()).unwrap();
        assert_eq!(
            parsed.flags & (1 << 3),
            1 << 3,
            "the peer form rides PEER_MASK"
        );
        match parsed.peer.as_deref() {
            Some(telegram_api::InputPeer::inputPeerUser(u)) => {
                assert_eq!(u.user_id, 7);
                assert_eq!(u.access_hash, 42);
            }
            other => panic!("the user peer rides the access hash: {other:?}"),
        }
        net_complete(sent.into_iter().next().unwrap(), bool_answer(true));
        td.dispatch_completed_autosave_net();
        assert!(matches!(
            slot.lock().unwrap().take(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 4. the unresolvable-peer band — the C++ in-query CHECK
        //    downgrades to the sibling access band; no query goes out.
        let (promise, slot) = record_translation_unit();
        {
            let (mut manager, mut env) = autosave_env_split(&mut td);
            manager.set_autosave_settings(
                &mut env,
                Some(autosave_scope_chat(999)),
                Some(td_api::ScopeAutosaveSettings {
                    autosave_photos: true,
                    autosave_videos: false,
                    max_video_file_size: 3_000_000,
                }),
                promise,
            );
            td.autosave_manager = manager;
        }
        assert!(rec.sent.lock().is_empty(), "no query for the banded save");
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.code(), 400);
                assert_eq!(status.message(), "Chat not found");
            }
            other => panic!("the peer band answers 400: {other:?}"),
        }

        // 5. the save error band: the promise fails and the reload tail
        //    re-fires the get query (the C++ on_error, cpp:91-94).
        let (promise, slot) = record_translation_unit();
        {
            let (mut manager, mut env) = autosave_env_split(&mut td);
            manager.set_autosave_settings(
                &mut env,
                Some(autosave_private_scope()),
                Some(td_api::ScopeAutosaveSettings {
                    autosave_photos: false,
                    autosave_videos: false,
                    max_video_file_size: 20_000_000,
                }),
                promise,
            );
            td.autosave_manager = manager;
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1);
        net_fail(sent.into_iter().next().unwrap(), 429, "Too Many Requests");
        td.dispatch_completed_autosave_net();
        match slot.lock().unwrap().take() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.code(), 429);
            }
            other => panic!("the error band fails the promise: {other:?}"),
        }
        let sent = std::mem::take(&mut *rec.sent.lock());
        assert_eq!(sent.len(), 1, "the reload re-fires");
        assert_eq!(
            sent[0].tl_constructor(),
            telegram_api::account_getAutoSaveSettings::ID
        );
        net_complete(
            sent.into_iter().next().unwrap(),
            autosave_answer(
                autosave_wire_settings(false, false, 10_000_000),
                autosave_wire_settings(false, false, 1),
                autosave_wire_settings(false, false, 1),
            ),
        );
        td.dispatch_completed_autosave_net();

        assert!(td.autosave_net_completed.lock().is_empty(), "drained");
        assert!(
            td.autosave_manager.pending_save_promises.is_empty(),
            "all save promises resolved"
        );
    }

    // ---- the bot_info net slice (§3.2): the twenty bot-administration
    // families ride the dispatcher. The bot-gated request arms' flows run
    // at the manager level (their CHECK_IS_BOT heads are the request
    // layer's — the with_bot_info_manager auth override); the user-gated
    // arms and the six-arm bot-info convergence go through the live
    // td_api requests. ----

    type BotInfoSlot<T> = std::sync::Arc<std::sync::Mutex<Option<tdutils::status::Result<T>>>>;

    /// The generic flow-level promise recorder (the M.40 RecordingPromise
    /// convention over any answer type).
    fn record_bot_info_result<T: Send + 'static>() -> (Promise<T>, BotInfoSlot<T>) {
        struct Rec<T: Send + 'static>(BotInfoSlot<T>);
        impl<T: Send + 'static> tdutils::promise::PromiseInterface<T> for Rec<T> {
            fn set_value(&mut self, value: T) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Ok(value));
            }
            fn set_error(&mut self, error: Status) {
                *self.0.lock().unwrap() = Some(tdutils::status::Result::Err(error));
            }
        }
        let slot: BotInfoSlot<T> = std::sync::Arc::new(std::sync::Mutex::new(None));
        (Promise::from_interface(Rec(slot.clone())), slot)
    }

    /// One wire bot record with an access hash, a first name and the
    /// editable-bot bits (`bot` flags.14, `bot_can_edit` flags2.1).
    fn bot_wire_user(id: i64, name: &str) -> telegram_api::User {
        telegram_api::User::user(telegram_api::user {
            flags: 1 | (1 << 1) | (1 << 14),
            flags2: 1 << 1,
            bot: true,
            bot_can_edit: true,
            access_hash: 43,
            id,
            first_name: name.to_owned(),
            ..telegram_api::user::default()
        })
    }

    /// A boxed `Vector<botCommand>` answer (the bots.getBotCommands
    /// result shape).
    fn bot_commands_vector_answer() -> Vec<u8> {
        let mut answer = Vec::new();
        answer.extend_from_slice(&telegram_api::tl::VECTOR_ID.to_le_bytes());
        answer.extend_from_slice(&1i32.to_le_bytes());
        telegram_api::BotCommand {
            flags: 0,
            ephemeral: false,
            command: "start".to_owned(),
            description: "Start".to_owned(),
        }
        .store_boxed(&mut answer);
        answer
    }

    /// A boxed `bots.botInfo` answer.
    fn bot_info_answer(name: &str, about: &str, description: &str) -> Vec<u8> {
        let mut answer = Vec::new();
        telegram_api::bots_BotInfo {
            name: name.to_owned(),
            about: about.to_owned(),
            description: description.to_owned(),
        }
        .store_boxed(&mut answer);
        answer
    }

    #[test]
    fn bot_commands_menu_and_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(bot_commands_menu_and_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn bot_commands_menu_and_queries_ride_the_dispatcher_impl() {
        let (mut td, rec) = netted_td("netfix-bot-commands");

        // 1. setCommands — the normalized command list rides the query
        //    (the leading slash stripped, the trim applied), the ok Bool
        //    answers ok.
        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |manager, env| {
            crate::bot_command::set_commands(
                manager,
                env,
                None,
                "en".to_owned(),
                vec![td_api::BotCommand {
                    command: " /start ".to_owned(),
                    description: " Start ".to_owned(),
                    is_ephemeral: false,
                }],
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_setBotCommands::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::bots_setBotCommands(payload) => {
                assert_eq!(payload.lang_code, "en");
                match &payload.commands[..] {
                    [command] => {
                        assert_eq!(command.command, "start");
                        assert_eq!(command.description, "Start");
                    }
                    other => panic!("the command list: {other:?}"),
                }
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_bot_info_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 2. deleteCommands — the reset twin.
        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |manager, env| {
            crate::bot_command::delete_commands(manager, env, None, "en".to_owned(), promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_resetBotCommands::ID,
        );
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_bot_info_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 3. getCommands — the answer converts over my id and the object
        //    builder.
        let (promise, slot) = record_bot_info_result::<td_api::BotCommands>();
        with_bot_info_manager(&mut td, true, |manager, env| {
            crate::bot_command::get_commands(manager, env, None, "en".to_owned(), promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_getBotCommands::ID,
        );
        net_complete(sent, bot_commands_vector_answer());
        td.dispatch_completed_bot_info_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Ok(commands)) => {
                assert_eq!(commands.bot_user_id, 0, "the un-set my id rides the object");
                match &commands.commands[..] {
                    [command] => assert_eq!(command.command, "start"),
                    other => panic!("the answer commands: {other:?}"),
                }
            }
            other => panic!("the commands answer: {other:?}"),
        }

        // 4. setMenuButton — the Web App button rides the query with the
        //    empty user id as inputUserEmpty.
        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |manager, env| {
            crate::bot_menu_button::set_menu_button(
                manager,
                env,
                crate::user_manager::UserId::default(),
                Some(td_api::BotMenuButton {
                    text: "Open".to_owned(),
                    url: "https://t.me/app".to_owned(),
                }),
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_setBotMenuButton::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::bots_setBotMenuButton(payload) => {
                assert!(matches!(
                    payload.user_id,
                    Some(telegram_api::InputUser::inputUserEmpty(_))
                ));
                match payload.button {
                    Some(telegram_api::BotMenuButton::botMenuButton(button)) => {
                        assert_eq!(button.text, "Open");
                        assert_eq!(button.url, "https://t.me/app");
                    }
                    other => panic!("the menu button: {other:?}"),
                }
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_bot_info_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 5. getMenuButton — the default answer converts over the
        //    user surface (the drain reads the real auth state —
        //    `td_->auth_manager_->is_bot()` — which this netted td
        //    keeps a user).
        let (promise, slot) = record_bot_info_result::<td_api::BotMenuButton>();
        with_bot_info_manager(&mut td, true, |manager, env| {
            crate::bot_menu_button::get_menu_button(
                manager,
                env,
                crate::user_manager::UserId::default(),
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_getBotMenuButton::ID,
        );
        let mut answer = Vec::new();
        telegram_api::BotMenuButton::botMenuButtonDefault(telegram_api::botMenuButtonDefault {})
            .store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_bot_info_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Ok(button)) => {
                assert_eq!(button.text, "");
                assert_eq!(button.url, "menu://default");
            }
            other => panic!("the default button: {other:?}"),
        }

        // 6. sendCustomRequest — the DataJSON answer rides the
        //    customRequestResult.
        let (promise, slot) = record_bot_info_result::<td_api::CustomRequestResult>();
        with_bot_info_manager(&mut td, true, |manager, env| {
            crate::bot_queries::send_bot_custom_query(
                manager,
                env,
                "getMe".to_owned(),
                "{}".to_owned(),
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_sendCustomRequest::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::bots_sendCustomRequest(payload) => {
                assert_eq!(payload.custom_method, "getMe");
                assert_eq!(payload.params.expect("the params ride").data, "{}");
            }
            other => panic!("the sent function: {other:?}"),
        }
        let mut answer = Vec::new();
        telegram_api::DataJSON {
            data: "{\"ok\":true}".to_owned(),
        }
        .store_boxed(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_bot_info_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Ok(result)) => {
                assert_eq!(result.result, "{\"ok\":true}");
            }
            other => panic!("the custom result: {other:?}"),
        }

        // 7. answerCustomQuery — the false Bool band logs and still
        //    answers ok (BotQueries.cpp:68-72).
        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |manager, env| {
            crate::bot_queries::answer_bot_custom_query(
                manager,
                env,
                7,
                "{\"x\":1}".to_owned(),
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_answerWebhookJSONQuery::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::bots_answerWebhookJSONQuery(payload) => {
                assert_eq!(payload.query_id, 7);
                assert_eq!(payload.data.expect("the data rides").data, "{\"x\":1}");
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(false));
        td.dispatch_completed_bot_info_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 8. setBotUpdatesStatus — the fire-and-forget family: the ok
        //    answer is immediate, nothing parks behind the query.
        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |_manager, env| {
            crate::bot_queries::set_bot_updates_status(
                env,
                3,
                "too many updates".to_owned(),
                promise,
            );
        });
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::help_setBotUpdatesStatus::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::help_setBotUpdatesStatus(payload) => {
                assert_eq!(payload.pending_updates_count, 3);
                assert_eq!(payload.message, "too many updates");
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(false));
        td.dispatch_completed_bot_info_net();

        // 9-15. the error bands — one per family (the §7 gate): the
        //     query error forwards to the parked promise (the C++
        //     on_error halves).
        for (what, drive) in [
            (
                "setCommands",
                Box::new(|td: &mut Td, promise| {
                    with_bot_info_manager(td, true, |manager, env| {
                        crate::bot_command::set_commands(
                            manager,
                            env,
                            None,
                            "en".to_owned(),
                            vec![td_api::BotCommand {
                                command: "x".to_owned(),
                                description: "Y".to_owned(),
                                is_ephemeral: false,
                            }],
                            promise,
                        );
                    });
                }) as Box<dyn FnOnce(&mut Td, Promise<()>)>,
            ),
            (
                "deleteCommands",
                Box::new(|td: &mut Td, promise| {
                    with_bot_info_manager(td, true, |manager, env| {
                        crate::bot_command::delete_commands(
                            manager,
                            env,
                            None,
                            "en".to_owned(),
                            promise,
                        );
                    });
                }) as Box<dyn FnOnce(&mut Td, Promise<()>)>,
            ),
            (
                "setMenuButton",
                Box::new(|td: &mut Td, promise| {
                    with_bot_info_manager(td, true, |manager, env| {
                        crate::bot_menu_button::set_menu_button(
                            manager,
                            env,
                            crate::user_manager::UserId::default(),
                            None,
                            promise,
                        );
                    });
                }) as Box<dyn FnOnce(&mut Td, Promise<()>)>,
            ),
        ] {
            let (promise, slot) = record_ton_unit();
            drive(&mut td, promise);
            let sent = std::mem::take(&mut *rec.sent.lock())
                .into_iter()
                .next()
                .unwrap_or_else(|| panic!("the {what} error-band query"));
            net_fail(sent, 420, "FLOOD_WAIT_3");
            td.dispatch_completed_bot_info_net();
            match &*slot.lock().unwrap() {
                Some(tdutils::status::Result::Err(status)) => {
                    assert_eq!(
                        (status.code(), status.message()),
                        (420, "FLOOD_WAIT_3"),
                        "{what}"
                    );
                }
                other => panic!("the {what} error band: {other:?}"),
            }
        }

        // getCommands / getMenuButton / sendCustomRequest carry typed
        // answers — the same error band over their own recorders
        {
            let (promise, slot) = record_bot_info_result::<td_api::BotCommands>();
            with_bot_info_manager(&mut td, true, |manager, env| {
                crate::bot_command::get_commands(manager, env, None, "en".to_owned(), promise);
            });
            let sent = take_sent(
                std::mem::take(&mut *rec.sent.lock()),
                telegram_api::bots_getBotCommands::ID,
            );
            net_fail(sent, 400, "BOT_COMMAND_INVALID");
            td.dispatch_completed_bot_info_net();
            match &*slot.lock().unwrap() {
                Some(tdutils::status::Result::Err(status)) => {
                    assert_eq!(status.message(), "BOT_COMMAND_INVALID");
                }
                other => panic!("the getCommands error band: {other:?}"),
            }
        }
        {
            let (promise, slot) = record_bot_info_result::<td_api::BotMenuButton>();
            with_bot_info_manager(&mut td, true, |manager, env| {
                crate::bot_menu_button::get_menu_button(
                    manager,
                    env,
                    crate::user_manager::UserId::default(),
                    promise,
                );
            });
            let sent = take_sent(
                std::mem::take(&mut *rec.sent.lock()),
                telegram_api::bots_getBotMenuButton::ID,
            );
            net_fail(sent, 400, "BUTTON_INVALID");
            td.dispatch_completed_bot_info_net();
            match &*slot.lock().unwrap() {
                Some(tdutils::status::Result::Err(status)) => {
                    assert_eq!(status.message(), "BUTTON_INVALID");
                }
                other => panic!("the getMenuButton error band: {other:?}"),
            }
        }
        {
            let (promise, slot) = record_bot_info_result::<td_api::CustomRequestResult>();
            with_bot_info_manager(&mut td, true, |manager, env| {
                crate::bot_queries::send_bot_custom_query(
                    manager,
                    env,
                    "getMe".to_owned(),
                    "{}".to_owned(),
                    promise,
                );
            });
            let sent = take_sent(
                std::mem::take(&mut *rec.sent.lock()),
                telegram_api::bots_sendCustomRequest::ID,
            );
            net_fail(sent, 400, "METHOD_INVALID");
            td.dispatch_completed_bot_info_net();
            match &*slot.lock().unwrap() {
                Some(tdutils::status::Result::Err(status)) => {
                    assert_eq!(status.message(), "METHOD_INVALID");
                }
                other => panic!("the sendCustomRequest error band: {other:?}"),
            }
        }

        assert!(td.bot_info_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn bot_administration_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(bot_administration_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn bot_administration_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-bot-admin");

        // me and an owned bot (the editable-bot bits set)
        with_user_manager(&mut td, |manager, env| {
            manager.set_my_id(env, crate::user_manager::UserId::new(700000001));
            manager.on_get_user(
                env,
                telegram_api::User::user(telegram_api::user {
                    flags: 1 | (1 << 1),
                    access_hash: 42,
                    id: 700000001,
                    first_name: "Me".to_owned(),
                    ..telegram_api::user::default()
                }),
                "t",
            );
            manager.on_get_user(env, bot_wire_user(8, "Bot"), "t");
        });

        // 1. createBot — the manager bot rides the query, the User
        //    answer registers the new bot and answers its object.
        td.request(
            1,
            Function::createBot(td_api::createBot {
                manager_bot_user_id: 8,
                name: "newbot".to_owned(),
                username: "newbot".to_owned(),
                via_link: true,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_createBot::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::bots_createBot(payload) => {
                assert_eq!(payload.flags, 1, "the via_deeplink bit");
                assert_eq!(payload.name, "newbot");
                assert_eq!(payload.username, "newbot");
                let telegram_api::InputUser::inputUser(input_user) =
                    payload.manager_id.expect("the manager rides the query")
                else {
                    panic!("the manager peer must be a concrete input user");
                };
                assert_eq!((input_user.user_id, input_user.access_hash), (8, 43));
            }
            other => panic!("the sent function: {other:?}"),
        }
        let mut answer = Vec::new();
        bot_wire_user(9, "Nine").store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        match responses_of(&callback, 1).first() {
            Some(Object::user(user)) => assert_eq!(user.id, 9),
            other => panic!("the created bot object: {other:?}"),
        }

        // 2. getOwnedBots — the Vector<User> answer intakes the users
        //    and answers the Users object.
        td.request(2, Function::getOwnedBots(td_api::getOwnedBots));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_getAdminedBots::ID,
        );
        net_complete(sent, users_vector_answer(bot_wire_user(10, "Ten")));
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        match responses_of(&callback, 2).first() {
            Some(Object::users(users)) => {
                assert_eq!(users.total_count, 1);
                assert_eq!(users.user_ids, vec![10]);
            }
            other => panic!("the owned bots object: {other:?}"),
        }

        // 3. canBotSendMessages — the false band answers the C++ 404.
        td.request(
            3,
            Function::canBotSendMessages(td_api::canBotSendMessages { bot_user_id: 8 }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_canSendMessage::ID,
        );
        net_complete(sent, bool_answer(false));
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 3) {
            Some((_, error)) => {
                assert_eq!(error.code, 404);
                assert_eq!(error.message, "Not Found");
            }
            None => panic!("the can-send false band never fired"),
        }

        // 4. canBotSendMessages — the true band answers ok.
        td.request(
            4,
            Function::canBotSendMessages(td_api::canBotSendMessages { bot_user_id: 8 }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_canSendMessage::ID,
        );
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 4).first(),
            Some(Object::ok(_))
        ));

        // 5. allowBotToSendMessages — the Updates answer re-enters
        //    on_get_updates and resolves ok.
        td.request(
            5,
            Function::allowBotToSendMessages(td_api::allowBotToSendMessages { bot_user_id: 8 }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_allowSendMessage::ID,
        );
        let mut answer = Vec::new();
        telegram_api::Updates::updates(telegram_api::updates {
            updates: Vec::new(),
            users: Vec::new(),
            chats: Vec::new(),
            date: 0,
            seq: 0,
        })
        .store(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 5).first(),
            Some(Object::ok(_))
        ));

        // 6. getManagedBotToken (the bot-gated flow at the manager level)
        //    — the exported token string answers.
        let (promise, slot) = record_star_url();
        with_bot_info_manager(&mut td, true, |manager, env| {
            manager.get_bot_token(env, crate::user_manager::UserId::new(8), true, promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_exportBotToken::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::bots_exportBotToken(payload) => {
                let telegram_api::InputUser::inputUser(input_user) =
                    payload.bot.expect("the bot rides the query")
                else {
                    panic!("the token peer must be a concrete input user");
                };
                assert_eq!(input_user.user_id, 8);
                assert!(payload.revoke);
            }
            other => panic!("the sent function: {other:?}"),
        }
        let mut answer = Vec::new();
        telegram_api::bots_ExportedBotToken {
            token: "12345:abc".to_owned(),
        }
        .store_boxed(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_bot_info_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Ok(token)) => assert_eq!(token, "12345:abc"),
            other => panic!("the token answer: {other:?}"),
        }

        // 7. getManagedBotAccessSettings — the answer converts through
        //    the users intake.
        let (promise, slot) = record_bot_info_result::<td_api::BotAccessSettings>();
        with_bot_info_manager(&mut td, true, |manager, env| {
            manager.get_bot_access_settings(env, crate::user_manager::UserId::new(8), promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_getAccessSettings::ID,
        );
        let mut answer = Vec::new();
        telegram_api::bots_AccessSettings {
            flags: 0,
            restricted: false,
            add_users: Vec::new(),
        }
        .store_boxed(&mut answer);
        net_complete(sent, answer);
        td.dispatch_completed_bot_info_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Ok(settings)) => {
                assert!(!settings.is_restricted);
                assert!(settings.added_user_ids.is_empty());
            }
            other => panic!("the access settings answer: {other:?}"),
        }

        // 8. setManagedBotAccessSettings — the added-user list rides the
        //    add_users wire bit.
        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |manager, env| {
            manager.set_bot_access_settings(
                env,
                crate::user_manager::UserId::new(8),
                Some(td_api::BotAccessSettings {
                    is_restricted: true,
                    added_user_ids: vec![700000001],
                }),
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_editAccessSettings::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::bots_editAccessSettings(payload) => {
                assert_eq!(
                    payload.flags,
                    1 | (1 << 1),
                    "the restricted + add_users bits"
                );
                assert!(payload.restricted);
                match &payload.add_users[..] {
                    [telegram_api::InputUser::inputUserSelf(_)] => {
                        // my own id takes the inputUserSelf force form
                    }
                    other => panic!("the added users: {other:?}"),
                }
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_bot_info_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 9. the default admin rights — the group family, the ok band
        //    (the invalidation of my full record).
        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |manager, env| {
            manager.set_default_group_administrator_rights(
                env,
                crate::chat_manager::AdministratorRights::default(),
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_setBotGroupDefaultAdminRights::ID,
        );
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_bot_info_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 10. the RIGHTS_NOT_MODIFIED error band answers ok.
        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |manager, env| {
            manager.set_default_group_administrator_rights(
                env,
                crate::chat_manager::AdministratorRights::default(),
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_setBotGroupDefaultAdminRights::ID,
        );
        net_fail(sent, 400, "RIGHTS_NOT_MODIFIED");
        td.dispatch_completed_bot_info_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 11. the broadcast twin — the false band logs and answers ok.
        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |manager, env| {
            manager.set_default_channel_administrator_rights(
                env,
                crate::chat_manager::AdministratorRights::default(),
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_setBotBroadcastDefaultAdminRights::ID,
        );
        net_complete(sent, bool_answer(false));
        td.dispatch_completed_bot_info_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 12. the plain error band forwards (the broadcast twin).
        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |manager, env| {
            manager.set_default_channel_administrator_rights(
                env,
                crate::chat_manager::AdministratorRights::default(),
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_setBotBroadcastDefaultAdminRights::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_5");
        td.dispatch_completed_bot_info_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.code(), 420);
                assert_eq!(status.message(), "FLOOD_WAIT_5");
            }
            other => panic!("the rights error band: {other:?}"),
        }

        // 13-17. the error bands — one per family (the §7 gate):
        //     createBot, getOwnedBots, allowBotToSendMessages,
        //     exportBotToken and get/editAccessSettings forward the
        //     query error to the request/parked promise.
        td.request(
            13,
            Function::createBot(td_api::createBot {
                manager_bot_user_id: 8,
                name: "newbot".to_owned(),
                username: "newbot".to_owned(),
                via_link: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_createBot::ID,
        );
        net_fail(sent, 400, "USERNAME_INVALID");
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 13) {
            Some((_, error)) => {
                assert_eq!(error.code, 400);
                assert_eq!(error.message, "USERNAME_INVALID");
            }
            None => panic!("the createBot error band never fired"),
        }

        td.request(14, Function::getOwnedBots(td_api::getOwnedBots));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_getAdminedBots::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_8");
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 14) {
            Some((_, error)) => {
                assert_eq!(error.code, 420);
                assert_eq!(error.message, "FLOOD_WAIT_8");
            }
            None => panic!("the getOwnedBots error band never fired"),
        }

        td.request(
            15,
            Function::allowBotToSendMessages(td_api::allowBotToSendMessages { bot_user_id: 8 }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_allowSendMessage::ID,
        );
        net_fail(sent, 400, "BOT_BLOCKED");
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 15) {
            Some((_, error)) => {
                assert_eq!(error.code, 400);
                assert_eq!(error.message, "BOT_BLOCKED");
            }
            None => panic!("the allowSendMessage error band never fired"),
        }

        let (promise, slot) = record_star_url();
        with_bot_info_manager(&mut td, true, |manager, env| {
            manager.get_bot_token(env, crate::user_manager::UserId::new(8), false, promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_exportBotToken::ID,
        );
        net_fail(sent, 400, "TOKEN_INVALID");
        td.dispatch_completed_bot_info_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.message(), "TOKEN_INVALID");
            }
            other => panic!("the exportBotToken error band: {other:?}"),
        }

        let (promise, slot) = record_bot_info_result::<td_api::BotAccessSettings>();
        with_bot_info_manager(&mut td, true, |manager, env| {
            manager.get_bot_access_settings(env, crate::user_manager::UserId::new(8), promise);
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_getAccessSettings::ID,
        );
        net_fail(sent, 400, "BOT_NOT_OWNED");
        td.dispatch_completed_bot_info_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.message(), "BOT_NOT_OWNED");
            }
            other => panic!("the getAccessSettings error band: {other:?}"),
        }

        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |manager, env| {
            manager.set_bot_access_settings(
                env,
                crate::user_manager::UserId::new(8),
                Some(td_api::BotAccessSettings {
                    is_restricted: false,
                    added_user_ids: Vec::new(),
                }),
                promise,
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_editAccessSettings::ID,
        );
        net_fail(sent, 400, "USERS_INVALID");
        td.dispatch_completed_bot_info_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.message(), "USERS_INVALID");
            }
            other => panic!("the editAccessSettings error band: {other:?}"),
        }

        assert!(td.bot_info_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn bot_info_convergence_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(bot_info_convergence_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn bot_info_convergence_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-bot-info");

        // me and an owned bot (the editable-bot bits set)
        with_user_manager(&mut td, |manager, env| {
            manager.set_my_id(env, crate::user_manager::UserId::new(700000001));
            manager.on_get_user(
                env,
                telegram_api::User::user(telegram_api::user {
                    flags: 1 | (1 << 1),
                    access_hash: 42,
                    id: 700000001,
                    first_name: "Me".to_owned(),
                    ..telegram_api::user::default()
                }),
                "t",
            );
            manager.on_get_user(env, bot_wire_user(8, "Bot"), "t");
        });

        // 1. setBotName parks behind the MAX_QUERY_DELAY fan-in; the
        //    timeout flush dispatches one bots.setBotInfo with the
        //    name + bot bits and the edited bot's input user.
        td.request(
            1,
            Function::setBotName(td_api::setBotName {
                bot_user_id: 8,
                language_code: "en".to_owned(),
                name: "NewName".to_owned(),
            }),
        );
        assert!(rec.sent.lock().is_empty(), "the fan-in holds the query");
        with_bot_info_manager(&mut td, false, |manager, env| manager.timeout_expired(env));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_setBotInfo::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::bots_setBotInfo(payload) => {
                assert_eq!(payload.flags, (1 << 3) | (1 << 2), "the name + bot bits");
                assert_eq!(payload.name, "NewName");
                assert_eq!(payload.lang_code, "en");
                assert_eq!(payload.about, "");
                assert_eq!(payload.description, "");
                let telegram_api::InputUser::inputUser(input_user) =
                    payload.bot.expect("the edited bot rides the query")
                else {
                    panic!("the bot peer must be a concrete input user");
                };
                assert_eq!((input_user.user_id, input_user.access_hash), (8, 43));
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        // the ok tail forwards the promise into reload_user — the real
        // UserManager reload now (the combiner's net-inert posture
        // outside the scheduler answers the C++ close-state 500, not a
        // lost promise — the users reload slice lifts it fully)
        match callback.errors.lock().iter().find(|(id, _)| *id == 1) {
            Some((_, error)) => {
                assert_eq!(error.code, 500);
                assert_eq!(error.message, "Request aborted");
            }
            None => panic!("the reload-tail forward never fired"),
        }
        assert!(td.bot_info_manager_pending_is_empty());

        // 2. the setBotInfo error band resolves (the invalidate head is
        //    a set_info-only band here)
        td.request(
            2,
            Function::setBotName(td_api::setBotName {
                bot_user_id: 8,
                language_code: "en".to_owned(),
                name: "Again".to_owned(),
            }),
        );
        with_bot_info_manager(&mut td, false, |manager, env| manager.timeout_expired(env));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_setBotInfo::ID,
        );
        net_fail(sent, 400, "BOT_INFO_INVALID");
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 2) {
            Some((_, error)) => {
                assert_eq!(error.code, 400);
                assert_eq!(error.message, "BOT_INFO_INVALID");
            }
            None => panic!("the setBotInfo error band never fired"),
        }

        // 3. getBotName rides the same fan-in; the answer fills the
        //    popped name promise (the three-vector reply).
        td.request(
            3,
            Function::getBotName(td_api::getBotName {
                bot_user_id: 8,
                language_code: "en".to_owned(),
            }),
        );
        with_bot_info_manager(&mut td, false, |manager, env| manager.timeout_expired(env));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_getBotInfo::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::bots_getBotInfo(payload) => {
                assert_eq!(payload.flags, 1, "the bot bit");
                assert_eq!(payload.lang_code, "en");
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bot_info_answer("The Name", "About", "Description"));
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        match responses_of(&callback, 3).first() {
            Some(Object::text(text)) => assert_eq!(text.text, "The Name"),
            other => panic!("the bot name answer: {other:?}"),
        }

        // 4. the bot-mode set arm (setBotInfoShortDescription shape, the
        //    my-id effective bot): the ok band answers without a reload —
        //    the invalidation is enough for bots (cpp:652-655)
        let (promise, slot) = record_ton_unit();
        with_bot_info_manager(&mut td, true, |manager, env| {
            manager.set_bot_info_about(
                env,
                crate::user_manager::UserId::default(),
                "en",
                "About text",
                promise,
            );
        });
        with_bot_info_manager(&mut td, true, |manager, env| manager.timeout_expired(env));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_setBotInfo::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::bots_setBotInfo(payload) => {
                assert_eq!(payload.flags, 1, "the about bit only");
                assert_eq!(payload.about, "About text");
                assert!(payload.bot.is_none(), "the my-id effective bot");
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(false));
        td.dispatch_completed_bot_info_net();
        // the drain reads the real auth state (a user td): the set_info
        // band forwards into reload_user_full — the same inert 500 as
        // the name leg (a bot client would answer ok here, cpp:652-655)
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(status.code(), 500);
                assert_eq!(status.message(), "Request aborted");
            }
            other => panic!("the bot-mode set band: {other:?}"),
        }

        // 5. setMessageSenderBotVerification — the user dialog rides the
        //    peer, the ok Bool answers ok.
        td.request(
            5,
            Function::setMessageSenderBotVerification(td_api::setMessageSenderBotVerification {
                verified_id: Some(td_api::MessageSender::messageSenderUser(
                    td_api::messageSenderUser { user_id: 8 },
                )),
                bot_user_id: 0,
                custom_description: Some(td_api::FormattedText {
                    text: "desc".to_owned(),
                    entities: Vec::new(),
                }),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_setCustomVerification::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::bots_setCustomVerification(payload) => {
                assert_eq!(
                    payload.flags,
                    (1 << 1) | (1 << 2),
                    "the enabled + description bits (no bot)"
                );
                assert!(payload.enabled);
                assert!(payload.bot.is_none());
                match *payload.peer.expect("the peer rides the query") {
                    telegram_api::InputPeer::inputPeerUser(peer) => {
                        assert_eq!(peer.user_id, 8);
                        assert_eq!(peer.access_hash, 43);
                    }
                    other => panic!("the verification peer: {other:?}"),
                }
                let description = payload.custom_description.expect("the description rides");
                assert_eq!(description.text, "desc");
            }
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 5).first(),
            Some(Object::ok(_))
        ));

        // 6. the verification error band forwards through the
        //    dialog-error head.
        td.request(
            6,
            Function::setMessageSenderBotVerification(td_api::setMessageSenderBotVerification {
                verified_id: Some(td_api::MessageSender::messageSenderUser(
                    td_api::messageSenderUser { user_id: 8 },
                )),
                bot_user_id: 0,
                custom_description: None,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_setCustomVerification::ID,
        );
        net_fail(sent, 420, "VERIFICATION_INVALID");
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 6) {
            Some((_, error)) => {
                assert_eq!(error.code, 420);
                assert_eq!(error.message, "VERIFICATION_INVALID");
            }
            None => panic!("the verification error band never fired"),
        }

        // 7. the getBotInfo error band — the popped reply's three
        //    promise vectors all fail with the query error.
        td.request(
            7,
            Function::getBotName(td_api::getBotName {
                bot_user_id: 8,
                language_code: "en".to_owned(),
            }),
        );
        with_bot_info_manager(&mut td, false, |manager, env| manager.timeout_expired(env));
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::bots_getBotInfo::ID,
        );
        net_fail(sent, 400, "LANG_INVALID");
        td.dispatch_completed_bot_info_net();
        td.flush_deferred_results();
        match callback.errors.lock().iter().find(|(id, _)| *id == 7) {
            Some((_, error)) => {
                assert_eq!(error.code, 400);
                assert_eq!(error.message, "LANG_INVALID");
            }
            None => panic!("the getBotInfo error band never fired"),
        }

        assert!(td.bot_info_net_completed.lock().is_empty(), "drained");
    }

    /// Seed one creator broadcast channel carrying the given username set
    /// (the `username`-vector form — the empty legacy first name); the
    /// access hash follows the seed_dialog_chats ladder.
    fn seed_channel_with_usernames(td: &mut Td, id: i64, usernames: &[(&str, bool, bool)]) {
        let crate::td::Td {
            global,
            option_manager,
            auth_manager,
            user_manager,
            chat_manager,
            ..
        } = td;
        let mut env = crate::user_manager::UserEnv {
            global,
            options: option_manager
                .as_mut()
                .expect("option manager exists after init"),
            auth_is_bot: auth_manager.is_bot(),
        };
        chat_manager.on_get_chat(
            &mut *user_manager,
            &mut env,
            telegram_api::Chat::channel(telegram_api::channel {
                creator: true,
                broadcast: true,
                id,
                access_hash: 777 + (id - 703).max(0),
                title: "named".to_owned(),
                usernames: usernames
                    .iter()
                    .map(|(username, editable, active)| telegram_api::Username {
                        flags: 0,
                        editable: *editable,
                        active: *active,
                        deletable: false,
                        expired: false,
                        username: username.to_string(),
                    })
                    .collect(),
                ..telegram_api::channel::default()
            }),
            "test",
        );
    }

    /// One wire `Username` record (the wire form needs no extra flags).
    fn wire_username(username: &str, editable: bool, active: bool) -> telegram_api::Username {
        telegram_api::Username {
            flags: 0,
            editable,
            active,
            deletable: false,
            expired: false,
            username: username.to_string(),
        }
    }

    #[test]
    fn channel_username_queries_ride_the_dispatcher() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(channel_username_queries_ride_the_dispatcher_impl)
            .unwrap()
            .join()
            .unwrap();
    }
    fn channel_username_queries_ride_the_dispatcher_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-channel-usernames");
        seed_dialog_chats(&mut td);
        // 705 — the editable-username family; 706 — the toggle family;
        // 707 — reorder + deactivate; 708 — the len<=1 band.
        seed_channel_with_usernames(
            &mut td,
            705,
            &[
                ("alpha", true, true),
                ("beta", false, true),
                ("gamma", false, false),
            ],
        );
        seed_channel_with_usernames(
            &mut td,
            706,
            &[("alpha", true, true), ("beta", false, true)],
        );
        seed_channel_with_usernames(
            &mut td,
            707,
            &[
                ("alpha", true, true),
                ("beta", false, true),
                ("gamma", false, true),
            ],
        );
        seed_channel_with_usernames(&mut td, 708, &[("solo", true, true)]);
        let usernames_object = |td: &Td, id: i64| {
            td.chat_manager
                .get_channel(crate::chat_manager::ChannelId::new(id))
                .unwrap()
                .usernames
                .get_usernames_object()
        };
        // 1. setSupergroupUsername — the live arm dispatches
        //    channels.updateUsername; the boolTrue answer runs the
        //    editable-username intake
        td.request(
            1,
            Function::setSupergroupUsername(td_api::setSupergroupUsername {
                supergroup_id: 705,
                username: "renamed".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_updateUsername::ID,
        );
        let body =
            telegram_api::channels_updateUsername::parse(sent.query()).expect("the sent body");
        match body.channel.as_ref() {
            Some(telegram_api::InputChannel::inputChannel(channel)) => {
                assert_eq!((channel.channel_id, channel.access_hash), (705, 779));
            }
            other => panic!("the input channel: {other:?}"),
        }
        assert_eq!(body.username, "renamed");
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 1).first(),
            Some(Object::ok(_))
        ));
        let object = usernames_object(&td, 705);
        assert_eq!(object.active_usernames, ["renamed", "beta"]);
        assert_eq!(object.editable_username, "renamed");
        // 2. the USERNAME_NOT_MODIFIED band — the intake runs, the !bot
        //    value answers
        td.request(
            2,
            Function::setSupergroupUsername(td_api::setSupergroupUsername {
                supergroup_id: 705,
                username: "renamed2".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_updateUsername::ID,
        );
        net_fail(sent, 400, "USERNAME_NOT_MODIFIED");
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 2).first(),
            Some(Object::ok(_))
        ));
        assert_eq!(usernames_object(&td, 705).editable_username, "renamed2");
        // 3. the hard error band — the channel-error head + the error
        td.request(
            3,
            Function::setSupergroupUsername(td_api::setSupergroupUsername {
                supergroup_id: 705,
                username: "third".to_owned(),
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_updateUsername::ID,
        );
        net_fail(sent, 400, "CHANNEL_PRIVATE");
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "CHANNEL_PRIVATE")
        );
        // 4. the invalid-username band — the C++ 400, no query
        td.request(
            4,
            Function::setSupergroupUsername(td_api::setSupergroupUsername {
                supergroup_id: 705,
                username: "bad name!".to_owned(),
            }),
        );
        let error = error_of(&callback, 4);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Username is invalid")
        );
        assert!(rec.sent.lock().is_empty(), "no query on the band");
        // 5. toggleSupergroupUsernameIsActive — the optimistic local
        //    toggle lands before the answer (cpp:3204-3205)
        td.request(
            5,
            Function::toggleSupergroupUsernameIsActive(td_api::toggleSupergroupUsernameIsActive {
                supergroup_id: 706,
                username: "beta".to_owned(),
                is_active: false,
            }),
        );
        let object = usernames_object(&td, 706);
        assert_eq!(object.active_usernames, ["alpha"], "the optimistic apply");
        assert_eq!(object.disabled_usernames, ["beta"], "the optimistic apply");
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_toggleUsername::ID,
        );
        let body =
            telegram_api::channels_toggleUsername::parse(sent.query()).expect("the sent body");
        match body.channel.as_ref() {
            Some(telegram_api::InputChannel::inputChannel(channel)) => {
                assert_eq!((channel.channel_id, channel.access_hash), (706, 780));
            }
            other => panic!("the input channel: {other:?}"),
        }
        assert_eq!(body.username, "beta");
        assert!(!body.active);
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 5).first(),
            Some(Object::ok(_))
        ));
        let object = usernames_object(&td, 706);
        assert_eq!(object.active_usernames, ["alpha"]);
        assert_eq!(object.disabled_usernames, ["beta"]);
        // 6. the toggle hard error band — the head + the error
        td.request(
            6,
            Function::toggleSupergroupUsernameIsActive(td_api::toggleSupergroupUsernameIsActive {
                supergroup_id: 706,
                username: "beta".to_owned(),
                is_active: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_toggleUsername::ID,
        );
        net_fail(sent, 400, "CHANNEL_PRIVATE");
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 6);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "CHANNEL_PRIVATE")
        );

        // the error tail's fire-and-forget reload (reload_channel for
        // 706) drains here over an empty answer, keeping the
        // GetChannels family queue FIFO-clean for the later bands
        let reload_index = rec
            .sent
            .lock()
            .iter()
            .position(|query| query.tl_constructor() == telegram_api::channels_getChannels::ID);
        if let Some(index) = reload_index {
            let reload_sent = rec.sent.lock().remove(index);
            let mut empty_answer = Vec::new();
            telegram_api::messages_Chats::messages_chats(telegram_api::messages_chats {
                chats: Vec::new(),
            })
            .store(&mut empty_answer);
            net_complete(reload_sent, empty_answer);
            td.dispatch_completed_chat_net();
        }

        // 7. reorderSupergroupActiveUsernames — the optimistic reorder +
        //    the round-trip
        td.request(
            7,
            Function::reorderSupergroupActiveUsernames(td_api::reorderSupergroupActiveUsernames {
                supergroup_id: 707,
                usernames: vec!["gamma".to_owned(), "alpha".to_owned(), "beta".to_owned()],
            }),
        );
        assert_eq!(
            usernames_object(&td, 707).active_usernames,
            ["gamma", "alpha", "beta"],
            "the optimistic apply"
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_reorderUsernames::ID,
        );
        let body =
            telegram_api::channels_reorderUsernames::parse(sent.query()).expect("the sent body");
        match body.channel.as_ref() {
            Some(telegram_api::InputChannel::inputChannel(channel)) => {
                assert_eq!((channel.channel_id, channel.access_hash), (707, 781));
            }
            other => panic!("the input channel: {other:?}"),
        }
        assert_eq!(body.order, ["gamma", "alpha", "beta"]);
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 7).first(),
            Some(Object::ok(_))
        ));
        // 8. the stale reorder — a toggle answer changes the active set
        //    between the send and the answer; the reorder intake rides
        //    the promise into the reload
        td.request(
            8,
            Function::reorderSupergroupActiveUsernames(td_api::reorderSupergroupActiveUsernames {
                supergroup_id: 707,
                usernames: vec!["alpha".to_owned(), "beta".to_owned(), "gamma".to_owned()],
            }),
        );
        let reorder_sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_reorderUsernames::ID,
        );
        // the interleaved toggle — its answer lands first
        td.request(
            9,
            Function::toggleSupergroupUsernameIsActive(td_api::toggleSupergroupUsernameIsActive {
                supergroup_id: 707,
                username: "gamma".to_owned(),
                is_active: false,
            }),
        );
        let toggle_sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_toggleUsername::ID,
        );
        net_complete(toggle_sent, bool_answer(true));
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 9).first(),
            Some(Object::ok(_))
        ));
        assert_eq!(
            usernames_object(&td, 707).active_usernames,
            ["alpha", "beta"]
        );
        // the reorder answer can no longer apply — the promise rides
        // the reload refire (net-drain 16: the GetChannelsQuery goes
        // out; the messages.chats answer completes the request; the
        // request-6 error tail's own reload already drained above)
        net_complete(reorder_sent, bool_answer(true));
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        let reload_sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_getChannels::ID,
        );
        match sent_function(&reload_sent) {
            telegram_api::Function::channels_getChannels(payload) => match &payload.id[..] {
                [telegram_api::InputChannel::inputChannel(input_channel)] => {
                    assert_eq!(input_channel.channel_id, 707, "the stale-reload target");
                }
                other => panic!("the single-id merger form: {other:?}"),
            },
            other => panic!("the reload refire: {other:?}"),
        }
        let mut reload_answer = Vec::new();
        telegram_api::messages_Chats::messages_chats(telegram_api::messages_chats {
            chats: vec![telegram_api::Chat::channel(telegram_api::channel {
                flags: (1 << 13) | (1 << 17), // access_hash + participants_count
                flags2: 1,                    // usernames present
                creator: true,
                broadcast: false,
                megagroup: true,
                id: 707,
                access_hash: 781,
                title: "named".to_owned(),
                usernames: vec![
                    wire_username("alpha", true, true),
                    wire_username("beta", false, true),
                    wire_username("gamma", false, false),
                ],
                ..telegram_api::channel::default()
            })],
        })
        .store(&mut reload_answer);
        net_complete(reload_sent, reload_answer);
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 8).first(),
            Some(Object::ok(_))
        ));
        // the reload intake re-applied the server's set (the toggle's
        // deactivated gamma stays disabled)
        assert_eq!(
            usernames_object(&td, 707).active_usernames,
            ["alpha", "beta"]
        );
        assert_eq!(usernames_object(&td, 707).disabled_usernames, ["gamma"]);

        // 9. the reorder hard error band — the head + the error
        td.request(
            10,
            Function::reorderSupergroupActiveUsernames(td_api::reorderSupergroupActiveUsernames {
                supergroup_id: 707,
                usernames: vec!["beta".to_owned(), "alpha".to_owned()],
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_reorderUsernames::ID,
        );
        net_fail(sent, 400, "CHANNEL_PRIVATE");
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 10);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "CHANNEL_PRIVATE")
        );

        // the error tail's fire-and-forget reload drains over an empty
        // answer (keeping the family queue FIFO-clean below)
        let reload_index = rec
            .sent
            .lock()
            .iter()
            .position(|query| query.tl_constructor() == telegram_api::channels_getChannels::ID);
        if let Some(index) = reload_index {
            let reload_sent = rec.sent.lock().remove(index);
            let mut empty_answer = Vec::new();
            telegram_api::messages_Chats::messages_chats(telegram_api::messages_chats {
                chats: Vec::new(),
            })
            .store(&mut empty_answer);
            net_complete(reload_sent, empty_answer);
            td.dispatch_completed_chat_net();
        }

        // 10. the invalid-order band — the C++ 400, no query
        td.request(
            11,
            Function::reorderSupergroupActiveUsernames(td_api::reorderSupergroupActiveUsernames {
                supergroup_id: 707,
                usernames: vec!["alpha".to_owned()],
            }),
        );
        let error = error_of(&callback, 11);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Invalid username order specified")
        );
        // 11. the len<=1 band — the value answers inline, no query
        td.request(
            12,
            Function::reorderSupergroupActiveUsernames(td_api::reorderSupergroupActiveUsernames {
                supergroup_id: 708,
                usernames: vec!["solo".to_owned()],
            }),
        );
        assert!(matches!(
            responses_of(&callback, 12).first(),
            Some(Object::ok(_))
        ));
        assert!(rec.sent.lock().is_empty(), "no query on the len band");
        // 12. disableAllSupergroupUsernames — the optimistic deactivate
        //     keeps the editable username active (the Usernames rule)
        td.request(
            13,
            Function::disableAllSupergroupUsernames(td_api::disableAllSupergroupUsernames {
                supergroup_id: 707,
            }),
        );
        let object = usernames_object(&td, 707);
        assert_eq!(object.active_usernames, ["alpha"], "the optimistic apply");
        assert_eq!(object.disabled_usernames, ["beta", "gamma"]);
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_deactivateAllUsernames::ID,
        );
        let body = telegram_api::channels_deactivateAllUsernames::parse(sent.query())
            .expect("the sent body");
        match body.channel.as_ref() {
            Some(telegram_api::InputChannel::inputChannel(channel)) => {
                assert_eq!((channel.channel_id, channel.access_hash), (707, 781));
            }
            other => panic!("the input channel: {other:?}"),
        }
        net_complete(sent, bool_answer(true));
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(matches!(
            responses_of(&callback, 13).first(),
            Some(Object::ok(_))
        ));
        // 13. the rights band — the member channel answers the C++ 400
        td.request(
            14,
            Function::setSupergroupUsername(td_api::setSupergroupUsername {
                supergroup_id: 703,
                username: "member".to_owned(),
            }),
        );
        let error = error_of(&callback, 14);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Not enough rights to change supergroup username")
        );
        assert!(rec.sent.lock().is_empty(), "no query on the bands");
        assert!(td.chat_net_completed.lock().is_empty(), "drained");
    }

    /// The chat/user managers out together (the netted chat-flow runner).
    fn with_chat_managers<R>(
        td: &mut Td,
        f: impl FnOnce(
            &mut crate::chat_manager::ChatManager,
            &mut crate::user_manager::UserManager,
            &mut crate::user_manager::UserEnv<'_>,
        ) -> R,
    ) -> R {
        let mut chat_manager = std::mem::take(&mut td.chat_manager);
        let mut user_manager = std::mem::take(&mut td.user_manager);
        let auth_is_bot = td.auth_manager.is_bot();
        let Some(options) = td.option_manager.as_mut() else {
            panic!("the option manager is set for the netted td");
        };
        let mut env = crate::user_manager::UserEnv {
            global: &mut td.global,
            options,
            auth_is_bot,
        };
        let result = f(&mut chat_manager, &mut user_manager, &mut env);
        td.user_manager = user_manager;
        td.chat_manager = chat_manager;
        result
    }

    /// One wire basic-group `chat` record (the bools ride their own
    /// flag bits).
    fn wire_basic_group_chat(id: i64, title: &str) -> telegram_api::Chat {
        telegram_api::Chat::chat(telegram_api::chat {
            creator: true,
            id,
            title: title.to_owned(),
            participants_count: 2,
            date: 10,
            version: 1,
            ..telegram_api::chat::default()
        })
    }

    /// A boxed `messages.chats` answer.
    fn messages_chats_answer(chats: Vec<telegram_api::Chat>) -> Vec<u8> {
        let mut out = Vec::new();
        telegram_api::messages_Chats::messages_chats(telegram_api::messages_chats { chats })
            .store(&mut out);
        out
    }

    /// A boxed `messages.chatFull` answer.
    fn messages_chat_full_answer(
        full_chat: telegram_api::ChatFull,
        chats: Vec<telegram_api::Chat>,
        users: Vec<telegram_api::User>,
    ) -> Vec<u8> {
        let mut out = Vec::new();
        telegram_api::messages_ChatFull {
            full_chat: Some(full_chat),
            chats,
            users,
        }
        .store_boxed(&mut out);
        out
    }

    #[test]
    fn chat_get_chats_merger_round_trips() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(chat_get_chats_merger_round_trips_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn chat_get_chats_merger_round_trips_impl() {
        let (mut td, rec) = netted_td("netfix-chat-get-chats");

        // 1. the merge-function half (cpp:1723-1726): the merged batch
        //    dispatches messages.getChats with the caller's ids
        let (promise, slot) = record_ton_unit();
        tdactor::ActorMessage::dispatch(
            MergeGetChatQueries {
                chat_ids: vec![91],
                promise,
            },
            &mut td,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_getChats::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::messages_getChats(payload) => {
                assert_eq!(payload.id, vec![91]);
            }
            other => panic!("the merged payload: {other:?}"),
        }

        // 2. the happy-path answer (cpp:1562-1583): on_get_chats caches
        //    the record, the merger's result promise flushes
        net_complete(
            sent,
            messages_chats_answer(vec![wire_basic_group_chat(91, "group")]),
        );
        td.dispatch_completed_chat_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));
        assert!(
            td.chat_manager
                .have_chat(crate::chat_manager::ChatId::new(91))
        );

        // 3. the error band forwards to the promise (cpp:1585-1588)
        let (promise, slot) = record_ton_unit();
        tdactor::ActorMessage::dispatch(
            MergeGetChatQueries {
                chat_ids: vec![91],
                promise,
            },
            &mut td,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_getChats::ID,
        );
        net_fail(sent, 420, "FLOOD_WAIT_5");
        td.dispatch_completed_chat_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!((status.code(), status.message()), (420, "FLOOD_WAIT_5"));
            }
            other => panic!("the error band: {other:?}"),
        }

        // 4. reload_chat through the real flow (cpp:8421-8429): the
        //    single-id merger ride over the actor-less collapse
        let (promise, slot) = record_ton_unit();
        with_chat_managers(&mut td, |chat_manager, _user_manager, env| {
            chat_manager.reload_chat(env, crate::chat_manager::ChatId::new(91), promise, "test");
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_getChats::ID,
        );
        net_complete(
            sent,
            messages_chats_answer(vec![wire_basic_group_chat(91, "group")]),
        );
        td.dispatch_completed_chat_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 5. the validation band — the validity gate answers before any
        //    query (cpp:8421-8426)
        let (promise, slot) = record_ton_unit();
        with_chat_managers(&mut td, |chat_manager, _user_manager, env| {
            chat_manager.reload_chat(env, crate::chat_manager::ChatId::new(0), promise, "test");
        });
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(
                    (status.code(), status.message()),
                    (400, "Invalid basic group identifier")
                );
            }
            other => panic!("the validity band: {other:?}"),
        }
        assert!(rec.sent.lock().is_empty(), "no query on the band");

        assert!(td.chat_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn chat_get_channels_and_migrated_round_trips() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(chat_get_channels_and_migrated_round_trips_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn chat_get_channels_and_migrated_round_trips_impl() {
        let (mut td, rec) = netted_td("netfix-chat-get-channels");
        seed_dialog_channel(&mut td, 802, true, false);

        // 1. the merge-function half (cpp:1727-1735): the input channel
        //    rides the seeded access hash
        let (promise, slot) = record_ton_unit();
        tdactor::ActorMessage::dispatch(
            MergeGetChannelQueries {
                channel_id: 802,
                promise,
            },
            &mut td,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_getChannels::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::channels_getChannels(payload) => match &payload.id[..] {
                [telegram_api::InputChannel::inputChannel(input_channel)] => {
                    assert_eq!(
                        (input_channel.channel_id, input_channel.access_hash),
                        (802, 876)
                    );
                }
                other => panic!("the single-id payload: {other:?}"),
            },
            other => panic!("the sent function: {other:?}"),
        }

        // 2. the happy-path answer (cpp:1650-1675): the intake applies
        //    the fresh record, the promise flushes
        net_complete(
            sent,
            messages_chats_answer(vec![telegram_api::Chat::channel(telegram_api::channel {
                flags: (1 << 13) | (1 << 17), // access_hash + participants_count
                flags2: 1,                    // usernames present
                creator: true,
                broadcast: true,
                megagroup: false,
                id: 802,
                access_hash: 876,
                title: "renamed".to_owned(),
                participants_count: 7,
                usernames: vec![wire_username("fresh", true, true)],
                ..telegram_api::channel::default()
            })]),
        );
        td.dispatch_completed_chat_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));
        assert!(
            td.chat_manager
                .get_channel(crate::chat_manager::ChannelId::new(802))
                .is_some_and(|c| c.title == "renamed")
        );

        // 3. the error band (cpp:1677-1680): the channel-error head +
        //    the error
        let (promise, slot) = record_ton_unit();
        tdactor::ActorMessage::dispatch(
            MergeGetChannelQueries {
                channel_id: 802,
                promise,
            },
            &mut td,
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_getChannels::ID,
        );
        net_fail(sent, 400, "CHANNEL_PRIVATE");
        td.dispatch_completed_chat_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!((status.code(), status.message()), (400, "CHANNEL_PRIVATE"));
            }
            other => panic!("the error band: {other:?}"),
        }
        // the CHANNEL_PRIVATE head ran (cpp:6405-6410: the member-leave
        // emulation is the invalidation tail — the record stays; the
        // forbidden emulation lands with on_get_channel_forbidden)
        assert!(
            td.chat_manager
                .have_channel(crate::chat_manager::ChannelId::new(802))
        );

        // 4. reload_channel's hash-0 arm (cpp:8949-8953): an unknown
        //    channel sends unmerged with access_hash 0
        let (promise, slot) = record_ton_unit();
        with_chat_managers(&mut td, |chat_manager, user_manager, env| {
            chat_manager.reload_channel(
                user_manager,
                env,
                crate::chat_manager::ChannelId::new(803),
                promise,
                "test",
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_getChannels::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::channels_getChannels(payload) => match &payload.id[..] {
                [telegram_api::InputChannel::inputChannel(input_channel)] => {
                    assert_eq!(
                        (input_channel.channel_id, input_channel.access_hash),
                        (803, 0)
                    );
                }
                other => panic!("the hash-0 payload: {other:?}"),
            },
            other => panic!("the sent function: {other:?}"),
        }
        net_complete(
            sent,
            messages_chats_answer(vec![telegram_api::Chat::channel(telegram_api::channel {
                flags: 1 << 13,
                creator: true,
                broadcast: true,
                megagroup: false,
                id: 803,
                access_hash: 42,
                title: "fresh".to_owned(),
                ..telegram_api::channel::default()
            })]),
        );
        td.dispatch_completed_chat_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));

        // 5. the migrated-to leg (cpp:9196-9210): a basic group with an
        //    unknown migrated-to channel refires the query through the
        //    merger (the promise-less park)
        with_chat_managers(&mut td, |chat_manager, user_manager, env| {
            chat_manager.on_get_chats(
                user_manager,
                env,
                vec![telegram_api::Chat::chat(telegram_api::chat {
                    creator: true,
                    id: 91,
                    title: "migrating".to_owned(),
                    migrated_to: Some(telegram_api::InputChannel::inputChannel(
                        telegram_api::inputChannel {
                            channel_id: 804,
                            access_hash: 55,
                        },
                    )),
                    participants_count: 2,
                    date: 10,
                    version: 1,
                    ..telegram_api::chat::default()
                })],
                "test",
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_getChannels::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::channels_getChannels(payload) => match &payload.id[..] {
                [telegram_api::InputChannel::inputChannel(input_channel)] => {
                    assert_eq!(
                        (input_channel.channel_id, input_channel.access_hash),
                        (804, 55)
                    );
                }
                other => panic!("the migrated-to payload: {other:?}"),
            },
            other => panic!("the sent function: {other:?}"),
        }
        // the temporarily-created channel record is visible to the client
        assert!(
            td.chat_manager
                .have_channel(crate::chat_manager::ChannelId::new(804))
        );
        net_complete(
            sent,
            messages_chats_answer(vec![telegram_api::Chat::channel(telegram_api::channel {
                flags: 1 << 13,
                creator: true,
                broadcast: false,
                megagroup: true,
                id: 804,
                access_hash: 55,
                title: "migrating".to_owned(),
                ..telegram_api::channel::default()
            })]),
        );
        td.dispatch_completed_chat_net();

        assert!(td.chat_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn chat_full_queries_round_trips() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(chat_full_queries_round_trips_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn chat_full_queries_round_trips_impl() {
        let (mut td, rec) = netted_td("netfix-chat-fulls");
        // a basic group with a record; a broadcast channel
        with_chat_managers(&mut td, |chat_manager, user_manager, env| {
            chat_manager.on_get_chats(
                user_manager,
                env,
                vec![wire_basic_group_chat(91, "group")],
                "test",
            );
        });
        seed_dialog_channel(&mut td, 803, true, false);

        // 1. GetFullChat through the real flow (load_chat_full over a
        //    known chat with no full, cpp:8479-8496 → 8513-8525): the
        //    combiner-collapse send goes out with the chat id
        let (promise, slot) = record_ton_unit();
        with_chat_managers(&mut td, |chat_manager, user_manager, env| {
            chat_manager.load_chat_full(
                user_manager,
                env,
                crate::chat_manager::ChatId::new(91),
                false,
                promise,
                "test",
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::messages_getFullChat::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::messages_getFullChat(payload) => {
                assert_eq!(payload.chat_id, 91);
            }
            other => panic!("the sent function: {other:?}"),
        }

        // 2. the answer (cpp:1602-1613): the users/chats pre-apply, the
        //    full record caches through on_get_chat_full, the promise
        //    flushes
        let chat_full = telegram_api::ChatFull::chatFull(telegram_api::chatFull {
            id: 91,
            about: "about".to_owned(),
            ..telegram_api::chatFull::default()
        });
        net_complete(
            sent,
            messages_chat_full_answer(
                chat_full,
                vec![wire_basic_group_chat(91, "group")],
                Vec::new(),
            ),
        );
        td.dispatch_completed_chat_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Ok(())) => {}
            other => panic!("the full-chat band: {other:?}"),
        }
        let has_full = with_chat_managers(&mut td, |chat_manager, _user_manager, _env| {
            chat_manager
                .get_chat_full(crate::chat_manager::ChatId::new(91))
                .is_some()
        });
        assert!(has_full, "the first full applies");

        // 3. GetFullChannel through the real flow (load_channel_full over
        //    a channel with no full): the first full applies — the
        //    missing-full repair check skips (cpp:5879-5894)
        let (promise, slot) = record_ton_unit();
        with_chat_managers(&mut td, |chat_manager, user_manager, env| {
            chat_manager.load_channel_full(
                user_manager,
                env,
                crate::chat_manager::ChannelId::new(803),
                false,
                promise,
                "test",
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_getFullChannel::ID,
        );
        match sent_function(&sent) {
            telegram_api::Function::channels_getFullChannel(payload) => {
                let telegram_api::InputChannel::inputChannel(input_channel) =
                    payload.channel.expect("the input channel rides the query")
                else {
                    panic!("the full query rides a concrete input channel");
                };
                assert_eq!(input_channel.channel_id, 803);
            }
            other => panic!("the sent function: {other:?}"),
        }
        let channel_full = telegram_api::ChatFull::channelFull(telegram_api::channelFull {
            flags: 1 << 12, // stats_dc present
            can_view_stats: true,
            id: 803,
            about: "about".to_owned(),
            stats_dc: 2,
            ..telegram_api::channelFull::default()
        });
        net_complete(
            sent,
            messages_chat_full_answer(channel_full, Vec::new(), Vec::new()),
        );
        td.dispatch_completed_chat_net();
        assert!(matches!(
            &*slot.lock().unwrap(),
            Some(tdutils::status::Result::Ok(()))
        ));
        let stats_dc = with_chat_managers(&mut td, |chat_manager, _user_manager, _env| {
            chat_manager
                .get_channel_full_const(crate::chat_manager::ChannelId::new(803))
                .map(|full| full.stats_dc_id)
        });
        assert_eq!(
            stats_dc.map(|dc| dc.get_value()),
            Some(2),
            "the first full applies"
        );

        // 4. the error band (cpp:1706-1712): the channel-error head, the
        //    on_get_channel_full_failed repair reset, the promise error
        //    (a fresh channel — 803's full is fresh and answers locally)
        seed_dialog_channel(&mut td, 807, true, false);
        let (promise, slot) = record_ton_unit();
        with_chat_managers(&mut td, |chat_manager, user_manager, env| {
            chat_manager.load_channel_full(
                user_manager,
                env,
                crate::chat_manager::ChannelId::new(807),
                true,
                promise,
                "test",
            );
        });
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_getFullChannel::ID,
        );
        net_fail(sent, 400, "CHANNEL_PRIVATE");
        td.dispatch_completed_chat_net();
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!((status.code(), status.message()), (400, "CHANNEL_PRIVATE"));
            }
            other => panic!("the error band: {other:?}"),
        }

        // 5. the validation bands — the missing-input/access gates answer
        //    before any query (cpp:9019-9025)
        let (promise, slot) = record_ton_unit();
        with_chat_managers(&mut td, |chat_manager, user_manager, env| {
            chat_manager.load_channel_full(
                user_manager,
                env,
                crate::chat_manager::ChannelId::new(0),
                false,
                promise,
                "test",
            );
        });
        match &*slot.lock().unwrap() {
            Some(tdutils::status::Result::Err(status)) => {
                assert_eq!(
                    (status.code(), status.message()),
                    (400, "Supergroup not found")
                );
            }
            other => panic!("the validity band: {other:?}"),
        }
        assert!(rec.sent.lock().is_empty(), "no query on the band");

        assert!(td.chat_net_completed.lock().is_empty(), "drained");
    }

    #[test]
    fn get_chat_statistics_dc_refire_rides_the_live_arm() {
        std::thread::Builder::new()
            .stack_size(16 * 1024 * 1024)
            .spawn(get_chat_statistics_dc_refire_rides_the_live_arm_impl)
            .unwrap()
            .join()
            .unwrap();
    }

    fn get_chat_statistics_dc_refire_rides_the_live_arm_impl() {
        let (mut td, rec, callback) = netted_td_with_callback("netfix-stats-dc");
        seed_dialog_channel(&mut td, 804, true, false);
        let chat_id = crate::chat_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(804),
        )
        .get();

        // 1. the §2 flip — the live arm runs the real
        //    get_channel_statistics_dc_id (cpp:746-758 + 3846-3876): a
        //    channel with no full refires GetFullChannelQuery; the
        //    request parks at the stats seam (net-drain 38)
        td.request(
            1,
            Function::getChatStatistics(td_api::getChatStatistics {
                chat_id,
                is_dark: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_getFullChannel::ID,
        );
        assert!(responses_of(&callback, 1).is_empty(), "the request parks");
        assert_eq!(td.statistics_manager.dc_parked.len(), 1);

        // 2. the refire answer — the full applies with the exact dc, the
        //    impl resolves it, the continuation runs the send leg over
        //    the net plane (cpp:3866-3876 + 753-764): the parked lot
        //    drains into `stats.getBroadcastStats`
        let channel_full = telegram_api::ChatFull::channelFull(telegram_api::channelFull {
            flags: 1 << 12, // stats_dc present
            can_view_stats: true,
            id: 804,
            about: "about".to_owned(),
            stats_dc: 2,
            ..telegram_api::channelFull::default()
        });
        net_complete(
            sent,
            messages_chat_full_answer(channel_full, Vec::new(), Vec::new()),
        );
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        assert!(
            td.statistics_manager.dc_parked.is_empty(),
            "the refire send leg ran"
        );
        take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::stats_getBroadcastStats::ID,
        );
        assert!(
            responses_of(&callback, 1).is_empty(),
            "the request waits on the stats answer"
        );
        let stats_dc = with_chat_managers(&mut td, |chat_manager, _user_manager, _env| {
            chat_manager
                .get_channel_full_const(crate::chat_manager::ChannelId::new(804))
                .map(|full| full.stats_dc_id)
        });
        assert_eq!(stats_dc.map(|dc| dc.get_value()), Some(2));

        // 3. the sync band — an exact cached dc skips the chain and the
        //    send leg fires directly (no new full query)
        td.request(
            2,
            Function::getChatStatistics(td_api::getChatStatistics {
                chat_id,
                is_dark: true,
            }),
        );
        assert!(
            td.statistics_manager.dc_parked.is_empty(),
            "the cached dc sends directly"
        );
        take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::stats_getBroadcastStats::ID,
        );

        // 4. the error band — the refire fails, the impl answers the
        //    "Chat full info not found" 400 to the request
        //    (cpp:3879-3886)
        seed_dialog_channel(&mut td, 805, true, false);
        td.request(
            3,
            Function::getChatStatistics(td_api::getChatStatistics {
                chat_id: crate::chat_manager::DialogId::from_channel_id(
                    crate::chat_manager::ChannelId::new(805),
                )
                .get(),
                is_dark: false,
            }),
        );
        let sent = take_sent(
            std::mem::take(&mut *rec.sent.lock()),
            telegram_api::channels_getFullChannel::ID,
        );
        net_fail(sent, 400, "CHANNEL_PRIVATE");
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        let error = error_of(&callback, 3);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Chat full info not found")
        );

        // 5. the gates — an unknown channel answers the C++ 400 before
        //    any query (cpp:3852-3858 over the have_dialog collapse)
        td.request(
            4,
            Function::getChatStatistics(td_api::getChatStatistics {
                chat_id: crate::chat_manager::DialogId::from_channel_id(
                    crate::chat_manager::ChannelId::new(807),
                )
                .get(),
                is_dark: false,
            }),
        );
        td.flush_deferred_results();
        let error = error_of(&callback, 4);
        assert_eq!(
            (error.code, error.message.as_str()),
            (400, "Chat not found")
        );
        assert!(rec.sent.lock().is_empty(), "no query on the band");

        // 6. the interleaving band — the channel-matched continuation
        //    drain: an answered full settles only its own channel's
        //    parked stats requests (never an unrelated channel's), and
        //    the same-channel join drains together. 805 still has no
        //    full (its case-4 refire failed), so both new requests
        //    refire
        let chat_id_805 = crate::chat_manager::DialogId::from_channel_id(
            crate::chat_manager::ChannelId::new(805),
        )
        .get();
        td.request(
            5,
            Function::getChatStatistics(td_api::getChatStatistics {
                chat_id: chat_id_805,
                is_dark: false,
            }),
        );
        td.request(
            6,
            Function::getChatStatistics(td_api::getChatStatistics {
                chat_id: chat_id_805,
                is_dark: false,
            }),
        );
        // both refires went out; the parked requests wait on them
        let mut stats_refires = std::mem::take(&mut *rec.sent.lock())
            .into_iter()
            .filter(|query| query.tl_constructor() == telegram_api::channels_getFullChannel::ID)
            .collect::<Vec<_>>();
        assert_eq!(stats_refires.len(), 2, "both 805 refires went out");
        let parked_before = td.statistics_manager.dc_parked.len();
        net_fail(stats_refires.remove(0), 400, "CHANNEL_PRIVATE");
        td.dispatch_completed_chat_net();
        td.flush_deferred_results();
        // the failed refire fails BOTH 805 requests (the same-channel
        // drain); the parked 804 seam entries stay untouched
        assert!(td.statistics_manager.dc_parked.len() < parked_before);
        assert_eq!(error_of(&callback, 5).code, 400);
        assert_eq!(error_of(&callback, 6).code, 400);

        assert!(td.chat_net_completed.lock().is_empty(), "drained");
    }

